const APP_FEATURE_FLAGS = Object.freeze({
  FEATURE_CAPTURE_UI: false,
  FEATURE_GAME_UI: false,
});

const LEGACY_GAME_UI_PAGES = new Set(["rating", "leaderboard", "tournament", "club", "games"]);

function isGameUiEnabled() {
  return APP_FEATURE_FLAGS.FEATURE_GAME_UI === true;
}

function isCaptureUiEnabled() {
  return isGameUiEnabled() && APP_FEATURE_FLAGS.FEATURE_CAPTURE_UI === true;
}

function isUiPageEnabled(page) {
  const normalized = String(page || "").trim().toLowerCase();
  if (normalized === "capture") return isCaptureUiEnabled();
  if (LEGACY_GAME_UI_PAGES.has(normalized)) return isGameUiEnabled();
  return true;
}

function getFeatureSafePage(page, fallback = "market") {
  const normalized = String(page || "").trim();
  return isUiPageEnabled(normalized) ? normalized : fallback;
}

function applyUiFeatureFlags(root = document) {
  const featureEnabled = {
    "capture-ui": isCaptureUiEnabled(),
    "game-ui": isGameUiEnabled(),
  };
  Object.entries(featureEnabled).forEach(([feature, enabled]) => {
    root.querySelectorAll(`[data-feature-ui="${feature}"]`).forEach((element) => {
      element.classList.toggle("feature-ui-hidden", !enabled);
      element.setAttribute("aria-hidden", enabled ? "false" : "true");
      if ("disabled" in element) element.disabled = !enabled;
    });
  });
  document.documentElement.dataset.captureUi = isCaptureUiEnabled() ? "on" : "off";
  document.documentElement.dataset.gameUi = isGameUiEnabled() ? "on" : "off";
}

window.__RP_MARKET_FEATURE_FLAGS__ = APP_FEATURE_FLAGS;
function escapeHtmlText(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function getSafeImageSrc(value, { allowBlob = false } = {}) {
  const raw = String(value ?? "").trim().replace(/\\\//g, "/");
  if (!raw) return "";
  if (/^data:image\/(?:png|jpe?g|gif|webp|avif);base64,/i.test(raw)) return raw;
  if (allowBlob && raw.startsWith("blob:")) return raw;
  try {
    const parsed = new URL(raw, window.location.origin);
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") return "";
    return parsed.href;
  } catch {
    return "";
  }
}

