let captureImagePreloadStarted = false;

/* Capture assets are large. Warm them only when the user opens Capture. */
function preloadCaptureImages() {
  if (captureImagePreloadStarted || window.__PERF_DIAG__?.skipImagePreload) return;
  captureImagePreloadStarted = true;
  Object.values(CAPTURE_MAP_BUILDING_BY_SLUG).forEach((src) => {
    const img = new Image();
    img.src = src;
  });
  Object.values(CAPTURE_BUSINESS_BY_CITY_SLUG).forEach((meta) => {
    const nodeSrc = String(meta?.nodeImage || "");
    const cardSrc = String(meta?.cardImage || "");
    if (nodeSrc) {
      const img = new Image();
      img.src = encodeURI(nodeSrc);
    }
    if (cardSrc && cardSrc !== nodeSrc) {
      const img = new Image();
      img.src = encodeURI(cardSrc);
    }
  });
}


