const applyRankBadge = (element, label) => {
  if (!element) return;
  const value = label || "Новичок";
  element.textContent = value;
  const normalized = String(value).toLowerCase().replace(/ё/g, "е");
  element.classList.remove(...RANK_CLASSES);
  const match = RANK_RULES.find((rule) => rule.matches.some((term) => normalized.includes(term)));
  if (match) {
    element.classList.add(match.className);
  }
};
