function syncInventoryCountFromServer(inventoryCounts = {}, coupons = [], cards = []) {
  const counts = inventoryCounts && typeof inventoryCounts === "object" ? inventoryCounts : {};
  const fromServerTotal = Number(counts.total);
  if (Number.isFinite(fromServerTotal)) {
    stateCoins.inventoryCount = Math.max(0, fromServerTotal);
    return;
  }
  const couponCount = Number.isFinite(Number(counts.coupons))
    ? Number(counts.coupons)
    : (Array.isArray(coupons)
        ? coupons.reduce((sum, item) => sum + Math.max(0, Number(item?.qty || 0)), 0)
        : 0);
  const cardCount = Number.isFinite(Number(counts.cards))
    ? Number(counts.cards)
    : (Array.isArray(cards)
        ? cards.reduce((sum, item) => sum + Math.max(0, Number(item?.qty || 0)), 0)
        : 0);
  stateCoins.inventoryCount = Math.max(0, couponCount + cardCount);
}
