// Website (non-Telegram browser) sign-in.
//
// Inside Telegram the app authenticates with X-Telegram-InitData. In a normal
// browser there is no initData, so the visitor signs in through the bot: the
// site starts a device-login attempt (/api/v2/auth/telegram/device/*), the user
// confirms it in Telegram, and the site exchanges the attempt for a session.
// The backend already accepts that session as `Authorization: Bearer <token>`
// on every /api/* route, so no other endpoint changes.
const WEB_AUTH_SESSION_KEY = "__rp_web_session__";
const WEB_AUTH_DEVICE_KEY = "__rp_web_device__";
const WEB_AUTH_REFRESH_SKEW_MS = 60 * 1000;
const WEB_AUTH_POLL_MS = 2000;
let webAuthRefreshInFlight = null;

function isWebBrowserMode() {
  const tg = window.Telegram && window.Telegram.WebApp;
  if (tg && String(tg.initData || "")) return false;
  const hash = String(window.location.hash || "");
  if (hash.indexOf("tgWebAppData") >= 0 || hash.indexOf("tgWebAppPlatform") >= 0) return false;
  const query = new URLSearchParams(window.location.search || "");
  if (String(query.get("_app") || "").trim().toLowerCase() === "android") return false;
  if (query.get("tgWebAppStartParam")) return false;
  return true;
}

function webAuthStorageGet(key) {
  try {
    return window.localStorage.getItem(key) || "";
  } catch (_) {
    return "";
  }
}

function webAuthStorageSet(key, value) {
  try {
    if (value === null) window.localStorage.removeItem(key);
    else window.localStorage.setItem(key, value);
  } catch (_) {}
}

function webAuthDeviceId() {
  let id = webAuthStorageGet(WEB_AUTH_DEVICE_KEY);
  if (!id) {
    const random = window.crypto && typeof window.crypto.randomUUID === "function"
      ? window.crypto.randomUUID()
      : `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 12)}`;
    id = `web-${random}`;
    webAuthStorageSet(WEB_AUTH_DEVICE_KEY, id);
  }
  return id;
}

function webAuthReadSession() {
  try {
    const parsed = JSON.parse(webAuthStorageGet(WEB_AUTH_SESSION_KEY) || "null");
    if (parsed && typeof parsed.access_token === "string" && parsed.access_token) return parsed;
  } catch (_) {}
  return null;
}

function webAuthWriteSession(session, telegramId) {
  const stored = {
    access_token: String(session.access_token || ""),
    refresh_token: String(session.refresh_token || ""),
    access_expires_at: String(session.access_expires_at || ""),
    refresh_expires_at: String(session.refresh_expires_at || ""),
    telegram_id: Number(telegramId || session.user?.telegram_id || 0),
  };
  webAuthStorageSet(WEB_AUTH_SESSION_KEY, JSON.stringify(stored));
  return stored;
}

function webAuthClearSession() {
  webAuthStorageSet(WEB_AUTH_SESSION_KEY, null);
}

function webAuthAccessToken() {
  if (!isWebBrowserMode()) return "";
  const session = webAuthReadSession();
  return session ? session.access_token : "";
}

// Extra request headers for raw fetch() calls outside apiRequest().
function webAuthHeaders() {
  const token = webAuthAccessToken();
  return token ? { Authorization: `Bearer ${token}` } : {};
}

function webAuthExpiresSoon(session) {
  const expires = Date.parse(session.access_expires_at ? `${session.access_expires_at}Z` : "");
  if (!Number.isFinite(expires)) return true;
  return expires - Date.now() < WEB_AUTH_REFRESH_SKEW_MS;
}

async function webAuthPostJson(path, body, headers = {}) {
  const response = await fetch(path, {
    method: "POST",
    headers: { "Content-Type": "application/json", ...headers },
    body: JSON.stringify(body || {}),
  });
  const payload = await response.json().catch(() => ({}));
  return { ok: response.ok, status: response.status, payload };
}

// Keeps the 15-minute access token fresh. A rejected refresh token ends the session.
async function webAuthEnsureFresh() {
  const session = webAuthReadSession();
  if (!session || !webAuthExpiresSoon(session)) return session;
  if (webAuthRefreshInFlight) return webAuthRefreshInFlight;
  webAuthRefreshInFlight = (async () => {
    try {
      const result = await webAuthPostJson("/api/v2/auth/refresh", {
        refresh_token: session.refresh_token,
        device_id: webAuthDeviceId(),
      });
      if (result.ok && result.payload.access_token) {
        return webAuthWriteSession(result.payload, result.payload.user?.telegram_id || session.telegram_id);
      }
      if (result.status === 401) webAuthClearSession();
      return result.status === 401 ? null : session;
    } catch (_) {
      return session;
    } finally {
      webAuthRefreshInFlight = null;
    }
  })();
  return webAuthRefreshInFlight;
}

async function webAuthStartLogin() {
  const result = await webAuthPostJson("/api/v2/auth/telegram/device/start", { device_id: webAuthDeviceId() });
  if (!result.ok || !result.payload.attempt_id) {
    throw new Error(String(result.payload.error || `http_${result.status}`));
  }
  const attemptId = String(result.payload.attempt_id);
  // Backend returns tg://resolve?domain=<bot>&startapp=..; a browser needs the https form.
  const deepLink = String(result.payload.telegram_url || "");
  const domain = (deepLink.match(/[?&]domain=([^&]+)/) || [])[1] || "";
  const startapp = (deepLink.match(/[?&]startapp=([^&]+)/) || [])[1] || "";
  // the sign-in goes through «Старт» in the bot (the server sends that link); the old Mini App link is only a fallback
  const webUrl = String(result.payload.bot_start_url || "") || (domain && startapp ? `https://t.me/${domain}?startapp=${startapp}` : "");
  return { attemptId, webUrl, deepLink, expiresAt: String(result.payload.expires_at || "") };
}

// Resolves with the stored session once the attempt is confirmed in Telegram.
async function webAuthWaitForLogin(attemptId, { signal } = {}) {
  for (;;) {
    if (signal && signal.aborted) throw new Error("aborted");
    const response = await fetch(`/api/v2/auth/telegram/device/status?attempt_id=${encodeURIComponent(attemptId)}`);
    const status = await response.json().catch(() => ({}));
    if (status.error) throw new Error(String(status.error));
    const value = String(status.status || "");
    if (value === "authorized") break;
    if (value === "expired" || value === "not_found" || value === "consumed") throw new Error(value);
    await new Promise((resolve) => setTimeout(resolve, WEB_AUTH_POLL_MS));
  }
  const exchange = await webAuthPostJson("/api/v2/auth/telegram/device/exchange", {
    attempt_id: attemptId,
    device_id: webAuthDeviceId(),
  });
  if (!exchange.ok || !exchange.payload.access_token) {
    throw new Error(String(exchange.payload.error || `http_${exchange.status}`));
  }
  return webAuthWriteSession(exchange.payload, exchange.payload.user?.telegram_id);
}

async function webAuthLogout() {
  const token = webAuthAccessToken();
  webAuthClearSession();
  if (token) {
    try {
      await webAuthPostJson("/api/v2/auth/logout-all", {}, { Authorization: `Bearer ${token}` });
    } catch (_) {}
  }
  window.location.reload();
}

// Called from init(): returns the session (or null) and mounts the sign-in control.
async function webAuthBoot() {
  const session = await webAuthEnsureFresh();
  webAuthMountChip(session);
  webTopBarMount(null);
  return session;
}

const WEB_AUTH_TG_ICON = '<svg class="web-auth-chip-icon" viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M21.9 4.3 18.7 19.5c-.2 1-.9 1.3-1.7.8l-4.7-3.5-2.3 2.2c-.3.3-.5.5-1 .5l.3-4.8 8.8-8c.4-.3-.1-.5-.6-.2L6.6 13 2 11.600c-1-.3-1-1 .2-1.500L20.100 3.200c.8-.3 1.600.2 1.800 1.100z"/></svg>';

// Guests on the website: screens that need an account explain it instead of showing a load error.
function webAuthIsGuest() {
  return Boolean(typeof state !== "undefined" && state.webMode && !webAuthReadSession());
}

function webAuthMountChip(session) {
  if (document.getElementById("webAuthChip") || document.getElementById("webLogoutRow")) return;
  if (session) {
    // signed in: no button in the top bar (it only wasted a strip of the screen); «Выйти» lives at the end of the profile
    webAuthMountLogout();
    return;
  }
  const chip = document.createElement("button");
  chip.id = "webAuthChip";
  chip.type = "button";
  chip.className = "web-auth-chip";
  chip.innerHTML = WEB_AUTH_TG_ICON + '<span class="web-auth-chip-text">Войти</span><span class="web-auth-chip-text web-auth-chip-text--wide">&nbsp;через Telegram</span>';
  chip.addEventListener("click", () => webAuthOpenDialog());
  webTopBarMount(chip);
}

function webAuthMountLogout() {
  const profile = document.querySelector('.page[data-page="profile"]');
  if (!profile || document.getElementById("webLogoutRow")) return;
  const row = document.createElement("div");
  row.id = "webLogoutRow";
  row.className = "web-logout-row";
  const button = document.createElement("button");
  button.type = "button";
  button.className = "web-logout-btn";
  button.textContent = "Выйти из аккаунта";
  button.addEventListener("click", async () => {
    const ok = typeof confirmDialog === "function"
      ? await confirmDialog("Выйти из аккаунта?", "Чтобы снова войти, понадобится подтверждение через Telegram.", "Выйти")
      : true;
    if (ok) webAuthLogout();
  });
  row.appendChild(button);
  profile.appendChild(row);
}

// Website on a phone: glass pills like the Telegram header — «‹ Назад» on inner screens and «Войти» for a guest. The bar
// exists only while it has something to show (no empty strip at the top), and it never carries a logo or a background.
function webTopBarMount(chip) {
  if (document.getElementById("webTopBar")) return;
  const bar = document.createElement("div");
  bar.id = "webTopBar";
  bar.className = "web-topbar";
  bar.innerHTML =
    '<button type="button" class="web-topbar-back" id="webTopBarBack" aria-label="Назад">' +
    '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" aria-hidden="true"><path d="m15 5-7 7 7 7" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>' +
    '<span>Назад</span></button>' +
    '<div class="web-topbar-right" id="webTopBarRight"></div>';
  if (chip) bar.querySelector("#webTopBarRight").appendChild(chip);
  bar.querySelector("#webTopBarBack").addEventListener("click", () => {
    if (typeof goBack === "function") goBack();
  });
  document.body.appendChild(bar);
  if (typeof syncWebTopBar === "function") syncWebTopBar();
}

function webAuthOpenDialog() {
  if (document.getElementById("webAuthDialog")) return;
  const overlay = document.createElement("div");
  overlay.id = "webAuthDialog";
  overlay.className = "web-auth-overlay";
  overlay.innerHTML = `
    <div class="web-auth-card" role="dialog" aria-modal="true" aria-label="Вход через Telegram">
      <div class="web-auth-grab" aria-hidden="true"></div>
      <div class="web-auth-title">Вход через Telegram</div>
      <ol class="web-auth-steps">
        <li><span>1</span>Нажмите «Открыть бота»</li>
        <li><span>2</span>В Telegram нажмите «Старт»</li>
        <li><span>3</span>Вернитесь сюда: вход выполнится сам</li>
      </ol>
      <div class="web-auth-text" id="webAuthText">Готовим ссылку для входа…</div>
      <a class="web-auth-primary" id="webAuthLink" target="_blank" rel="noopener" hidden>Открыть бота</a>
      <button class="web-auth-secondary" id="webAuthCancel" type="button">Отмена</button>
    </div>`;
  document.body.appendChild(overlay);
  const controller = new AbortController();
  const close = () => {
    controller.abort();
    overlay.remove();
  };
  overlay.querySelector("#webAuthCancel").addEventListener("click", close);
  overlay.addEventListener("click", (event) => {
    if (event.target === overlay) close();
  });
  const text = overlay.querySelector("#webAuthText");
  const link = overlay.querySelector("#webAuthLink");
  (async () => {
    try {
      const attempt = await webAuthStartLogin();
      if (attempt.webUrl) {
        link.href = attempt.webUrl;
        link.hidden = false;
        text.textContent = "Эта страница обновится сама после подтверждения.";
      } else {
        text.textContent = "Не удалось получить ссылку на бота. Попробуйте позже.";
        return;
      }
      await webAuthWaitForLogin(attempt.attemptId, { signal: controller.signal });
      window.location.reload();
    } catch (error) {
      if (controller.signal.aborted) return;
      const code = String((error && error.message) || error);
      text.textContent = code === "expired"
        ? "Время подтверждения вышло. Закройте окно и попробуйте снова."
        : code === "migration_required"
          ? "Вход на сайте пока не включён на этом сервере."
          : "Не получилось войти. Попробуйте ещё раз.";
      link.hidden = true;
    }
  })();
}
// Desktop website shell (browser only, width >= 1024px).
//
// One product, two layouts: phones (Telegram Mini App and the mobile browser)
// keep the bottom-bar UI untouched; on a wide browser window the same pages are
// framed by a left sidebar and a top bar. The shell owns no data: it proxies
// clicks to the existing navigation, filters and search, so every page keeps
// working exactly as in the Mini App.
const DESKTOP_SHELL_QUERY = "(min-width: 1024px)";
let desktopShellBuilt = false;
let desktopShellObserver = null;
let dkConversationsSeeded = false;

const DESKTOP_ICONS = {
  market: '<path d="M4 7h16l-1.4 11H5.4L4 7z"/><path d="M8 7a4 4 0 0 1 8 0"/>',
  favorites: '<path d="M12 20.3l-1.02-.92C7.3 16.1 4.8 13.9 4.8 11c0-2.2 1.7-3.9 3.8-3.9 1.2 0 2.4.6 3.4 1.6 1-1 2.2-1.6 3.4-1.6 2.1 0 3.8 1.7 3.8 3.9 0 2.9-2.5 5.1-6.2 8.4L12 20.3z"/>',
  conversations: '<path d="M5 6h14v9H9l-4 4V6z"/>',
  coins: '<circle cx="12" cy="12" r="8"/><path d="m12 8 1.2 2.6 2.8.3-2.1 1.9.6 2.8L12 14.2 9.5 15.6l.6-2.8L8 10.9l2.8-.3L12 8z"/>',
  profile: '<circle cx="12" cy="9" r="3.6"/><path d="M5 20c.8-3.6 3.6-5.4 7-5.4s6.2 1.8 7 5.4"/>',
  bell: '<path d="M6 9a6 6 0 0 1 12 0c0 6 2.5 7.5 2.5 7.5h-17S6 15 6 9z"/><path d="M10 20a2 2 0 0 0 4 0"/>',
  plus: '<path d="M12 5v14M5 12h14"/>',
  search: '<circle cx="11" cy="11" r="6"/><path d="m20 20-4.2-4.2"/>',
};

const DESKTOP_NAV = [
  { id: "market", label: "Рынок", auth: false },
  { id: "favorites", label: "Избранное", auth: true },
  { id: "conversations", label: "Чаты", auth: true },
  { id: "coins", label: "Активность", auth: true },
];

const DESKTOP_PAGE_TITLES = {
  market: "Рынок",
  listing: "Объявление",
  create: "Новое объявление",
  "coins-favorites": "Избранное",
  conversations: "Чаты",
  "deal-chat": "Чат",
  coins: "Активность",
  "coins-chests": "Кейсы",
  "case-open": "Открытие кейса",
  "coins-shop": "Магазин",
  "coins-vip": "VIP-подписка",
  "coins-packs": "Пополнение M-Coin",
  "coins-tasks": "Задания",
  "coins-inventory": "Инвентарь",
  "coins-referrals": "Рефералы",
  "coins-history": "История",
  "coins-promotion": "Продвижение",
  "coins-promocodes": "Промокоды",
  nickname: "Никнейм",
  profile: "Профиль",
  "profile-stats": "Статистика",
  "profile-report": "Бухгалтерия",
  "profile-edit": "Редактирование профиля",
  "public-profile": "Профиль продавца",
  admin: "Админ-панель",
};

function dkIcon(name) {
  return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${DESKTOP_ICONS[name] || ""}</svg>`;
}

function dkNavForPage(page) {
  const value = String(page || "");
  if (value === "market" || value === "listing" || value === "create") return "market";
  if (value === "coins-favorites") return "favorites";
  if (value === "conversations" || value === "deal-chat") return "conversations";
  if (value.indexOf("coins") === 0 || value === "case-open") return "coins";
  // profile pages are reached from the account card at the bottom of the sidebar, not from the nav list
  if (value === "profile" || value.indexOf("profile-") === 0 || value === "public-profile" || value === "admin") return "";
  return "market";
}

function dkHasSession() {
  return typeof webAuthReadSession === "function" && Boolean(webAuthReadSession());
}

function dkRequireSession() {
  if (dkHasSession()) return true;
  if (typeof webAuthOpenDialog === "function") webAuthOpenDialog();
  return false;
}

function dkGoNav(id) {
  const item = DESKTOP_NAV.find((entry) => entry.id === id);
  if (item && item.auth && !dkRequireSession()) return;
  if (id === "favorites") {
    resetNavTo("coins");
    navigateTo("coins-favorites");
    loadFavorites();
    return;
  }
  const button = document.querySelector(`#mainActionBar [data-nav="${id}"]`);
  if (button) button.click();
}

function dkSetCategory(category) {
  stateFilters.category = category;
  updateFiltersBar();
  if (state.page !== "market") dkGoNav("market");
  loadMarket();
  dkSync();
}

function dkBuild() {
  const root = document.createElement("div");
  root.id = "dkShell";
  root.className = "dk-shell";
  root.innerHTML = `
    <aside class="dk-side" aria-label="Навигация">
      <div class="dk-brand">RP MARKET</div>
      <nav class="dk-nav" id="dkNav">
        ${DESKTOP_NAV.map((item) => `
          <button class="dk-nav-item" type="button" data-dk-nav="${item.id}">
            ${dkIcon(item.id)}<span>${item.label}</span>
          </button>`).join("")}
      </nav>
      <div class="dk-section-title">Категории</div>
      <div class="dk-cats" id="dkCats"></div>
      <div class="dk-user" id="dkUser"></div>
    </aside>
    <header class="dk-top">
      <div class="dk-title" id="dkTitle">Рынок</div>
      <label class="dk-search">
        ${dkIcon("search")}
        <input id="dkSearch" type="search" placeholder="Поиск объявлений" autocomplete="off" />
      </label>
      <div class="dk-top-actions">
        <button class="dk-bell" id="dkBell" type="button" aria-label="Уведомления" hidden>${dkIcon("bell")}<span class="dk-bell-badge" id="dkBellBadge" hidden></span></button>
        <button class="dk-balance" id="dkBalance" type="button" aria-label="Баланс"><span class="dk-coin"></span><span id="dkBalanceValue">0</span></button>
        <button class="dk-topup" id="dkTopup" type="button">Пополнить</button>
        <button class="dk-create" id="dkCreate" type="button">${dkIcon("plus")}<span>Разместить</span></button>
      </div>
    </header>
    <div class="dk-chat-placeholder" id="dkChatPlaceholder" aria-hidden="true">
      ${dkIcon("conversations")}
      <div class="dk-chat-placeholder-title">Выберите диалог</div>
      <div class="dk-chat-placeholder-text">Переписка откроется здесь</div>
    </div>`;
  document.body.prepend(root);

  root.querySelector("#dkNav").addEventListener("click", (event) => {
    const button = event.target.closest("[data-dk-nav]");
    if (button) dkGoNav(button.getAttribute("data-dk-nav"));
  });
  root.querySelector("#dkCats").addEventListener("click", (event) => {
    const button = event.target.closest("[data-dk-cat]");
    if (button) dkSetCategory(button.getAttribute("data-dk-cat") || "");
  });
  root.querySelector("#dkBell").addEventListener("click", () => {
    const inbox = document.getElementById("conversationsInboxBtn");
    if (inbox) inbox.click();
  });
  root.querySelector("#dkTopup").addEventListener("click", () => dkGoNav("coins"));
  root.querySelector("#dkBalance").addEventListener("click", () => dkGoNav("coins"));
  root.querySelector("#dkCreate").addEventListener("click", () => {
    if (!dkRequireSession()) return;
    resetCreateForm();
    resetNavTo("market");
    navigateTo("create");
  });
  root.querySelector("#dkUser").addEventListener("click", (event) => {
    event.stopPropagation();
    const action = event.target.closest("[data-dk-user]");
    if (!action) return;
    const kind = action.getAttribute("data-dk-user");
    if (kind === "login") {
      webAuthOpenDialog();
      return;
    }
    if (kind === "toggle") {
      dkToggleUserMenu();
      return;
    }
    dkToggleUserMenu(false);
    if (kind === "logout") webAuthLogout();
    else if (kind === "profile") dkGoNav("profile");
    else if (kind === "stats") {
      resetNavTo("profile");
      navigateTo("profile-stats");
    } else if (kind === "settings") {
      dkGoNav("profile");
      if (stateProfile && stateProfile.data && typeof openEditProfileModal === "function") openEditProfileModal(stateProfile.data);
    } else if (kind === "referrals") {
      resetNavTo("coins");
      navigateTo("coins-referrals");
    }
  });
  document.addEventListener("click", () => dkToggleUserMenu(false));
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") dkToggleUserMenu(false);
  });
  const search = root.querySelector("#dkSearch");
  search.addEventListener("input", () => {
    const target = elements.marketSearch;
    if (!target) return;
    if (state.page !== "market") dkGoNav("market");
    target.value = search.value;
    target.dispatchEvent(new Event("input", { bubbles: true }));
  });
  dkRenderCategories();
}

function dkRenderCategories() {
  const host = document.getElementById("dkCats");
  if (!host) return;
  const categories = Array.isArray(state.categories) ? state.categories : [];
  host.innerHTML = [{ value: "", label: "Все категории" }]
    .concat(categories.map((name) => ({ value: name, label: name })))
    .map((entry) => `<button class="dk-cat" type="button" data-dk-cat="${escapeHtmlText(entry.value)}">${escapeHtmlText(entry.label)}</button>`)
    .join("");
}

function dkSync() {
  const shell = document.getElementById("dkShell");
  if (!shell) return;
  const page = (document.querySelector(".page.active") || {}).dataset?.page || state.page || "market";
  const activeNav = dkNavForPage(page);
  shell.querySelectorAll("[data-dk-nav]").forEach((button) => {
    button.classList.toggle("active", button.getAttribute("data-dk-nav") === activeNav);
  });
  shell.classList.toggle("dk-on-market", page === "market" || page === "listing");
  shell.classList.toggle("dk-chat-empty", page === "conversations");
  // Chats are a split view on desktop: the dialog list stays next to the open dialog.
  if (page === "deal-chat" && !dkConversationsSeeded && typeof loadConversations === "function") {
    dkConversationsSeeded = true;
    Promise.resolve(loadConversations())
      .catch(() => {})
      .then(() => {
        if (typeof renderConversations === "function") renderConversations();
      });
  } else if (page !== "deal-chat") {
    dkConversationsSeeded = false;
  }
  const title = shell.querySelector("#dkTitle");
  if (title) title.textContent = DESKTOP_PAGE_TITLES[page] || "Рынок";
  const category = String(stateFilters.category || "");
  shell.querySelectorAll("[data-dk-cat]").forEach((button) => {
    button.classList.toggle("active", (button.getAttribute("data-dk-cat") || "") === category);
  });
  const balance = (document.getElementById("coinsBalance") || {}).textContent || "0";
  const balanceValue = shell.querySelector("#dkBalanceValue");
  if (balanceValue) balanceValue.textContent = balance;
  const signedIn = dkHasSession();
  shell.querySelector("#dkBell").hidden = !signedIn;
  const unread = signedIn && typeof getSystemInboxUnreadCount === "function" ? Number(getSystemInboxUnreadCount() || 0) : 0;
  const bellBadge = shell.querySelector("#dkBellBadge");
  bellBadge.hidden = unread <= 0;
  bellBadge.textContent = unread > 99 ? "99+" : String(unread);
  shell.querySelector("#dkBalance").hidden = !dkHasSession();
  shell.querySelector("#dkTopup").hidden = !dkHasSession();
  dkRenderUser();
}

function dkToggleUserMenu(force) {
  const menu = document.getElementById("dkUserMenu");
  const card = document.getElementById("dkUserCard");
  if (!menu || !card) return;
  const open = typeof force === "boolean" ? force : menu.hidden;
  menu.hidden = !open;
  card.setAttribute("aria-expanded", open ? "true" : "false");
}

function dkRenderUser() {
  const host = document.getElementById("dkUser");
  if (!host) return;
  if (!dkHasSession()) {
    host.dataset.sig = "guest";
    host.innerHTML = '<button class="dk-login" type="button" data-dk-user="login">Войти через Telegram</button>';
    return;
  }
  const name = ((document.getElementById("profileName") || {}).textContent || "").trim() || "Профиль";
  const avatar = document.getElementById("navProfileAvatar");
  const avatarHtml = avatar ? avatar.innerHTML : "";
  const balance = (document.getElementById("coinsBalance") || {}).textContent || "0";
  const signature = `${name}|${balance}|${avatarHtml}`;
  if (host.dataset.sig === signature && host.querySelector("#dkUserCard")) return;
  host.dataset.sig = signature;
  const existingMenu = document.getElementById("dkUserMenu");
  const menuWasOpen = Boolean(existingMenu && !existingMenu.hidden);
  host.innerHTML = `
    <div class="dk-user-menu" id="dkUserMenu" role="menu" ${menuWasOpen ? "" : "hidden"}>
      <div class="dk-user-menu-head">
        <div class="dk-user-avatar">${avatarHtml}</div>
        <div class="dk-user-menu-name">${escapeHtmlText(name)}</div>
        <div class="dk-user-menu-balance"><span class="dk-coin"></span>${escapeHtmlText(balance)}</div>
      </div>
      <button type="button" role="menuitem" data-dk-user="profile">Мой профиль</button>
      <button type="button" role="menuitem" data-dk-user="stats">Статистика</button>
      <button type="button" role="menuitem" data-dk-user="settings">Настройки профиля</button>
      <button type="button" role="menuitem" data-dk-user="referrals">Реферальная ссылка</button>
      <div class="dk-user-menu-sep"></div>
      <button type="button" role="menuitem" class="is-danger" data-dk-user="logout">Выйти</button>
    </div>
    <button class="dk-user-card" id="dkUserCard" type="button" data-dk-user="toggle" aria-haspopup="menu" aria-expanded="${menuWasOpen ? "true" : "false"}">
      <span class="dk-user-avatar">${avatarHtml}</span>
      <span class="dk-user-text"><span class="dk-user-name">${escapeHtmlText(name)}</span><span class="dk-user-sub">Мой профиль</span></span>
      <span class="dk-user-dots" aria-hidden="true">⋯</span>
    </button>`;
}

function dkWatch() {
  if (desktopShellObserver) return;
  let queued = false;
  const schedule = () => {
    if (queued) return;
    queued = true;
    window.requestAnimationFrame(() => {
      queued = false;
      dkSync();
    });
  };
  desktopShellObserver = new MutationObserver(schedule);
  const shell = document.querySelector("main.shell");
  if (shell) desktopShellObserver.observe(shell, { attributes: true, attributeFilter: ["class"], subtree: true });
  [document.getElementById("coinsBalance"), document.getElementById("profileName"), document.getElementById("navProfileAvatar"), document.getElementById("conversationsInboxBadge")]
    .filter(Boolean)
    .forEach((node) => desktopShellObserver.observe(node, { childList: true, characterData: true, subtree: true, attributes: true }));
}

function dkApply(matches) {
  document.body.classList.toggle("web-desktop", matches);
  if (!matches) return;
  if (!desktopShellBuilt) {
    desktopShellBuilt = true;
    dkBuild();
    dkWatch();
  }
  dkRenderCategories();
  dkSync();
}

// Called from init() in plain-browser mode only.
function desktopShellInit() {
  if (typeof window.matchMedia !== "function") return;
  const query = window.matchMedia(DESKTOP_SHELL_QUERY);
  dkApply(query.matches);
  const onChange = (event) => dkApply(event.matches);
  if (typeof query.addEventListener === "function") query.addEventListener("change", onChange);
  else if (typeof query.addListener === "function") query.addListener(onChange);
}
function buildMarketListParams() {
  const params = new URLSearchParams();
  if (stateFilters.serverId) params.set("server_id", stateFilters.serverId);
  if (stateFilters.category) params.set("category", stateFilters.category);
  if (stateFilters.query) params.set("q", stateFilters.query);
  if (stateFilters.listingType && stateFilters.listingType !== "all") {
    params.set("listing_type", stateFilters.listingType);
  }
  return params;
}

function invalidateMarketCaches({ refreshNow = false } = {}) {
  stateMarket.items = [];
  stateMarket.loaded = false;
  stateMarket.total = 0;
  stateMarket.offset = 0;
  stateMarket.hasMore = false;
  stateMarket.loadingMore = false;
  stateMarket.queryKey = "";
  if (refreshNow && state.page === "market") {
    loadMarket();
  }
  if (refreshNow && state.page === "coins-favorites") {
    loadFavorites();
  }
}

async function refreshMarketIfUpdated() {
  if (state.page !== "market") return;
  if (document.hidden) return;
  if (stateMarket.loadingMore || marketLoadInFlight || stateCreate.submitting) return;
  if (marketRealtimeInFlight) return marketRealtimeInFlight;

  const params = buildMarketListParams();
  params.set("paged", "1");
  params.set("limit", "1");
  params.set("offset", "0");
  params.set("include_total", "0");

  const prevScrollY = window.scrollY || 0;
  const controller = new AbortController();
  marketRealtimeAbortController = controller;
  const request = (async () => {
    try {
      const payload = await apiRequest(`/api/listings?${params.toString()}`, {
        signal: controller.signal,
      });
      if (controller.signal.aborted || state.page !== "market") return;
      const nextItems = Array.isArray(payload?.items) ? payload.items : [];
      const nextTopId = Number(nextItems[0]?.id || 0);
      const hasRawTotal = Number.isFinite(Number(payload?.total));
      const nextTotal = hasRawTotal ? Number(payload.total) : null;
      // Some backends return total=0 when include_total=0; treat it as unreliable while items exist.
      const hasReliableTotal = hasRawTotal && (nextTotal > 0 || nextItems.length === 0);
      const currentTopId = Number(stateMarket.items[0]?.id || 0);
      const currentTotal = Number(stateMarket.total || stateMarket.items.length || 0);

      const topChanged = nextTopId !== currentTopId;
      if (topChanged || (hasReliableTotal && nextTotal !== currentTotal)) {
        await loadMarket();
        if (controller.signal.aborted || state.page !== "market") return;
        window.requestAnimationFrame(() => {
          if (state.page !== "market") return;
          const maxY = Math.max(0, document.body.scrollHeight - window.innerHeight);
          window.scrollTo({ top: Math.min(prevScrollY, maxY), behavior: "auto" });
        });
      }
    } catch (error) {
      if (isAbortError(error)) return;
      // Keep silent; next polling tick will retry.
    } finally {
      if (marketRealtimeInFlight === request) marketRealtimeInFlight = null;
      if (marketRealtimeAbortController === controller) marketRealtimeAbortController = null;
    }
  })();
  marketRealtimeInFlight = request;
  return request;
}

function handleMarketVisibilityRefresh() {
  if (!document.hidden && state.page === "market") refreshMarketIfUpdated();
}

function startMarketAutoRefresh() {
  if (marketRealtimeTimer) return;
  marketRealtimeTimer = setInterval(() => {
    refreshMarketIfUpdated();
  }, MARKET_AUTO_REFRESH_MS);
  document.addEventListener("visibilitychange", handleMarketVisibilityRefresh);
}

function stopMarketAutoRefresh() {
  if (marketRealtimeTimer) clearInterval(marketRealtimeTimer);
  marketRealtimeTimer = null;
  document.removeEventListener("visibilitychange", handleMarketVisibilityRefresh);
}

function leaveMarketReadLifecycle() {
  marketRequestToken += 1;
  if (marketSearchTimer) clearTimeout(marketSearchTimer);
  marketSearchTimer = null;
  if (marketLoadAbortController) marketLoadAbortController.abort();
  if (marketMoreAbortController) marketMoreAbortController.abort();
  if (marketTopStatusAbortController) marketTopStatusAbortController.abort();
  if (marketRealtimeAbortController) marketRealtimeAbortController.abort();
  marketLoadAbortController = null;
  marketMoreAbortController = null;
  marketTopStatusAbortController = null;
  marketRealtimeAbortController = null;
  marketLoadInFlight = null;
  marketLoadKeyInFlight = "";
  marketRealtimeInFlight = null;
  stateMarket.loadingMore = false;
  stopMarketAutoRefresh();
  if (typeof resetMarketPreviewPipeline === "function") {
    resetMarketPreviewPipeline({ abortRequests: true });
  }
}

function leaveListingReadLifecycle() {
  listingLoadToken += 1;
  if (listingLoadAbortController) listingLoadAbortController.abort();
  if (listingImagesAbortController) listingImagesAbortController.abort();
  listingLoadAbortController = null;
  listingImagesAbortController = null;
}

function resolveMarketTotal(payload, items) {
  const list = Array.isArray(items) ? items : [];
  const size = list.length;
  const parsedTotal = Number(payload?.total);
  if (Number.isFinite(parsedTotal)) {
    // Some responses use total=0 when include_total=0; prefer visible items count in that case.
    if (parsedTotal === 0 && size > 0) return size;
    return Math.max(0, parsedTotal);
  }
  // Fallback to currently visible items count when backend doesn't provide total.
  return size;
}
