function persistDailySubscriptionPending() {
  if (!state.tid) return;
  const storageKey = getDailySubPendingStorageKey();
  try {
    const pending = Object.fromEntries(
      Object.entries(stateCoins.dailySubscriptionPending || {}).filter(([taskKey, value]) => taskKey && Boolean(value)),
    );
    if (!Object.keys(pending).length) {
      localStorage.removeItem(storageKey);
      return;
    }
    localStorage.setItem(storageKey, JSON.stringify(pending));
  } catch {
    // ignore localStorage errors
  }
}

