async function fetchPaymentStatusByOperation(operationId) {
  const op = String(operationId || "").trim();
  if (!op) return null;
  try {
    return await apiRequest(withAuth(`/api/payments/status?operation_id=${encodeURIComponent(op)}`));
  } catch (error) {
    const code = String(error?.payload?.error || "");
    if (error?.status === 404 || code === "not_found") return null;
    throw error;
  }
}

async function syncVipPendingPaymentStatus(profile) {
  const pending = stateVip.checkoutPending;
  if (!pending || !pending.operationId) return;
  const tierKey = String(pending.tier || "vip_ultimate");
  const seenOp = getSeenVipOperationId(tierKey);
  const isTierActive = Boolean(getVipTierState(profile || stateProfile.data || {}, tierKey).active);
  if (isTierActive) return;
  if (vipPaymentStatusInFlight) return vipPaymentStatusInFlight;
  vipPaymentStatusInFlight = (async () => {
    try {
      const statusPayload = await fetchPaymentStatusByOperation(pending.operationId);
      const status = String(statusPayload?.status || "").trim().toLowerCase();
      if (!status) return;
      if (status === "failed" || status === "cancelled") {
        clearVipCheckoutPending();
        stateVip.paymentBanner = {
          title: "Оплата не завершена",
          text: "Платеж отменен или завершился ошибкой. Попробуйте снова.",
          pending: false,
          createdAtMs: Date.now(),
        };
        showToast("Платеж не завершен. Попробуйте снова.", "danger");
        return;
      }
      if (status === "processed" || status === "paid") {
        clearVipCheckoutPending();
        if (seenOp !== pending.operationId) {
          setSeenVipOperationId(tierKey, pending.operationId);
          stateVip.paymentBanner = {
            title: "Оплата подтверждена",
            text: "Платеж принят. Обновляем подписку и привилегии.",
            pending: false,
            createdAtMs: Date.now(),
          };
          showToast("✅ Оплата подтверждена. Подписка обновляется.", "success");
        }
      }
    } finally {
      vipPaymentStatusInFlight = null;
    }
  })();
  return vipPaymentStatusInFlight;
}

function applyMcoinBalance(nextBalance) {
  const numeric = Number(nextBalance);
  if (!Number.isFinite(numeric)) return;
  const safeBalance = Math.max(0, Math.round(numeric));
  state.mcoin = safeBalance;
  if (stateProfile.data && typeof stateProfile.data === "object") {
    stateProfile.data.mcoin = safeBalance;
  }
  if (elements.coinsBalance) {
    elements.coinsBalance.textContent = formatPrice(safeBalance);
    elements.coinsBalance.closest(".cn-cur")?.classList.toggle("is-zero", !(Number(safeBalance) > 0));
  }
  const shopBalance = document.getElementById("shopBalanceValue");
  if (shopBalance) {
    shopBalance.textContent = formatPrice(safeBalance);
  }
  if (elements.captureCoinValue) {
    elements.captureCoinValue.textContent = formatPrice(safeBalance);
  }
  syncCaseOpenHud();
}

function applyMatreshkaBalance(nextBalance) {
  const numeric = Number(nextBalance);
  const safeBalance = Number.isFinite(numeric) ? Math.max(0, Math.round(numeric)) : 0;
  if (stateProfile.data && typeof stateProfile.data === "object") {
    stateProfile.data.matreshka_balance = safeBalance;
  }
  if (elements.coinsMatreshkaBalance) {
    elements.coinsMatreshkaBalance.textContent = formatPrice(safeBalance);
    elements.coinsMatreshkaBalance.closest(".cn-cur")?.classList.toggle("is-zero", !(Number(safeBalance) > 0));
  }
}

async function requestMatreshkaWithdraw() {
  const balance = Number(stateProfile.data?.matreshka_balance || 0);
  if (!Number.isFinite(balance) || balance < 200) {
    showToast("Вывод доступен от 200 MATRESHKA.", "danger");
    return;
  }
  const confirmed = await telegramConfirmPopup({
    title: "Вывод MATRESHKA",
    message: `Отправить заявку на вывод?\n\nТекущий баланс: ${formatPrice(balance)} MATRESHKA`,
    okText: "Отправить",
    cancelText: "Отмена",
  });
  if (!confirmed) return;
  try {
    const response = await apiRequest(withAuth("/api/coins/withdraw"), { method: "POST" });
    const sentBalance = Number(response?.balance || balance || 0);
    showToast(`Заявка отправлена. Баланс: ${formatPrice(sentBalance)} MATRESHKA`, "success");
  } catch (err) {
    const code = String(err?.payload?.error || "").trim();
    if (code === "insufficient_matreshka_balance") {
      showToast("Вывод доступен от 200 MATRESHKA.", "danger");
      return;
    }
    if (code === "telegram_delivery_failed") {
      showToast("Не удалось отправить заявку. Попробуй ещё раз позже.", "danger");
      return;
    }
    showToast("Не удалось отправить заявку на вывод.", "danger");
  }
}

