function refreshLiveMcoinBalanceNow() {
  if (document.hidden || !state.tid || !isLiveMcoinPage() || mcoinBalanceInFlight) return;
  mcoinBalanceInFlight = true;
  Promise.resolve(apiRequest(withAuth("/api/mcoin/balance")))
    .then((payload) => {
      if (payload && payload.balance !== undefined && payload.balance !== null) {
        applyMcoinBalance(payload.balance);
      }
    })
    .catch(() => {})
    .finally(() => {
      mcoinBalanceInFlight = false;
    });
}

