function getReputationPercent(rawClosedDeals) {
  const closedDeals = Number(rawClosedDeals || 0);
  if (closedDeals >= 50) return 100;
  if (closedDeals >= 30) return 85;
  if (closedDeals >= 15) return 70;
  if (closedDeals >= 5) return 50;
  if (closedDeals >= 1) return 25;
  return 5;
}

function renderCompactReputation(targetEl, rawClosedDeals) {
  if (!targetEl) return;
  const reputationPct = getReputationPercent(rawClosedDeals);
  targetEl.classList.add("seller-meta--reputation");
  targetEl.innerHTML = `
    <div class="reputation-progress reputation-progress--mini">
      <div class="reputation-bar">
        <div class="reputation-fill" style="width: 0%"></div>
      </div>
      <span class="reputation-percent">${reputationPct}%</span>
    </div>
  `;
  const fillEl = targetEl.querySelector(".reputation-fill");
  if (fillEl) {
    requestAnimationFrame(() => {
      fillEl.style.width = `${reputationPct}%`;
    });
  }
}

function ensureShopUiState() {
  if (!stateShop.tryOnPreview) stateShop.tryOnPreview = {};
  if (!stateShop.selected) stateShop.selected = {};
  if (!stateShop.pending) stateShop.pending = {};
}

function isOwnerTelegramId(value) {
  return String(value || "").trim() === OWNER_TG_ID;
}

function isOwnerClient() {
  return isOwnerTelegramId(state.tid);
}

function isLocalOwnerDeveloperLabelItemId(itemId) {
  return false;
}

function getDevLabelStorageKey() {
  return `${OWNER_DEV_LABEL_STORAGE_KEY}:${String(state.tid || "anon")}`;
}

function isDeveloperLabelItem(item) {
  if (!item || String(item?.slot || "") !== "label") return false;
  const id = String(item?.id || "").trim().toLowerCase();
  const title = String(item?.title || "").trim().toLowerCase().replace(/ё/g, "е");
  if (!id && !title) return false;
  if (id === OWNER_DEV_LABEL_ITEM_ID) return true;
  if (title.includes("разработ") || title.includes("developer")) return true;
  // Keep ID matching strict enough to avoid false positives like "device".
  if (id.includes("label_developer") || id.includes("label_dev")) return true;
  return false;
}

function getDeveloperLabelItemId(data = stateShop.data) {
  const list = Array.isArray(data?.items) ? data.items : [];
  const normalizedOwnerId = String(OWNER_DEV_LABEL_ITEM_ID).trim();
  const ownerItem = list.find((item) => String(item?.id || "").trim() === normalizedOwnerId);
  if (isDeveloperLabelItem(ownerItem)) return normalizedOwnerId;
  const match = list.find((item) => isDeveloperLabelItem(item));
  if (match) return String(match?.id || "").trim();
  return "";
}

function isDeveloperLabelItemId(itemId, data = stateShop.data) {
  const normalizedItemId = String(itemId || "").trim();
  if (!normalizedItemId) return false;
  if (normalizedItemId === String(OWNER_DEV_LABEL_ITEM_ID).trim()) return true;
  const list = Array.isArray(data?.items) ? data.items : [];
  const item = list.find((entry) => String(entry?.id || "").trim() === normalizedItemId);
  if (item) return isDeveloperLabelItem(item);
  // Fallback when item list is stale but ID follows known naming.
  const normalizedId = normalizedItemId.toLowerCase();
  return normalizedId.includes("label_developer") || normalizedId.includes("label_dev");
}

function isOwnerDevLabelEnabled() {
  ownerDevLabelEnabledRuntime = false;
  return false;
}

function setOwnerDevLabelEnabled(value) {
  ownerDevLabelEnabledRuntime = false;
  try {
    localStorage.removeItem(getDevLabelStorageKey());
  } catch {
    // ignore localStorage failures
  }
}

function decorateShopDataForOwner(rawData) {
  const source = rawData && typeof rawData === "object" ? rawData : {};
  const next = {
    ...source,
    active: source.active && typeof source.active === "object" ? { ...source.active } : {},
    items: Array.isArray(source.items)
      ? source.items
        .map((item) => ({ ...item }))
        .filter((item) => !isDeveloperLabelItem(item))
      : [],
  };
  if (isDeveloperLabelItemId(next.active?.label, next)) {
    next.active.label = "";
  }
  return next;
}

function getOwnerDevLabelOverrideByTelegramId(value, labelId = "") {
  return null;
}

function getShopActiveSlotRawValue(slot) {
  if (!stateShop.data) return "";
  if (slot === "nick_color") {
    return String(stateShop.data.active_color || "").toUpperCase();
  }
  return String(stateShop.data.active?.[slot] || "").trim();
}

function normalizeShopSlotValue(slot, value) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  if (slot === "nick_color") return raw.toUpperCase();
  if (slot === "seller_bg") return normalizeSellerBgId(raw);
  if (slot === "seller_effect") return normalizeSellerEffectId(raw);
  return raw;
}

function isShopTryOnDirty(slot) {
  if (!stateShop.data) return false;
  const activeValue = normalizeShopSlotValue(slot, getShopActiveSlotRawValue(slot));
  const previewValue = normalizeShopSlotValue(slot, stateShop.tryOnPreview?.[slot]);
  return activeValue !== previewValue;
}

function buildShopPreviewCosmetics() {
  const data = stateShop.data || {};
  const profileCosmetics = stateProfile.data?.cosmetics || {};
  const active = data.active && typeof data.active === "object" ? data.active : {};
  const base = {
    badge: active.badge || "",
    label: active.label || "",
    label_text: profileCosmetics.label_text || "",
    label_style: active.label_style || "",
    label_style_staff: active.label_style_staff || profileCosmetics.label_style_staff || "",
    label_style_secondary: active.label_style_secondary || profileCosmetics.label_style_secondary || "",
    label_style_territory: active.label_style_territory || profileCosmetics.label_style_territory || "",
    label_style_vip: active.label_style_vip || profileCosmetics.label_style_vip || "",
    badge_style: active.badge_style || "",
    profile_frame: active.profile_frame || "",
    listing_frame: active.listing_frame || "",
    nick_color: data.active_color || "",
    seller_bg: active.seller_bg || "",
    seller_effect: active.seller_effect || "",
  };
  const overrides = stateShop.tryOnPreview || {};
  return {
    badge: overrides.badge ?? base.badge,
    label: overrides.label ?? base.label,
    label_text: overrides.label_text ?? base.label_text,
    label_style: overrides.label_style ?? base.label_style,
    label_style_staff: overrides.label_style_staff ?? base.label_style_staff,
    label_style_secondary: overrides.label_style_secondary ?? base.label_style_secondary,
    label_style_territory: overrides.label_style_territory ?? base.label_style_territory,
    label_style_vip: overrides.label_style_vip ?? base.label_style_vip,
    badge_style: overrides.badge_style ?? base.badge_style,
    profile_frame: overrides.profile_frame ?? base.profile_frame,
    listing_frame: overrides.listing_frame ?? base.listing_frame,
    nick_color: overrides.nick_color ?? base.nick_color,
    seller_bg: normalizeSellerBgId(overrides.seller_bg ?? base.seller_bg),
    seller_effect: normalizeSellerEffectId(overrides.seller_effect ?? base.seller_effect),
  };
}

function renderShopTryOnPreview() {
  if (!elements.shopPreviewProfileCard) return;
  if (!stateShop.data) return;
  ensureShopUiState();

  const profile = stateProfile.data || {};
  const displayName = getSafeProfileName(profile);
  const baseLabel = profile.rank || "Новичок";
  const previewCosmetics = buildShopPreviewCosmetics();
  const ownerLabelOverride = getOwnerDevLabelOverrideByTelegramId(
    profile.telegram_id || state.tid,
    previewCosmetics.label,
  );
  const photoUrl = getTelegramUserPhoto();
  const avatarUrl = profile.avatar_data || profile.avatar_url || photoUrl || "";

  const buildSellerPreview = () => {
    if (!elements.sellerCard) return null;
    const clone = elements.sellerCard.cloneNode(true);
    clone.classList.add("seller-card--preview");
    clone.removeAttribute("id");
    // Prevent one-frame flicker from inherited listing cosmetics on cloned node.
    clone.removeAttribute("data-listing-frame");
    clone.removeAttribute("data-seller-bg");
    clone.removeAttribute("data-seller-effect");
    clone.querySelectorAll("[id]").forEach((el) => el.removeAttribute("id"));
    clone.querySelectorAll("[data-listing-frame],[data-seller-bg],[data-seller-effect]").forEach((el) => {
      el.removeAttribute("data-listing-frame");
      el.removeAttribute("data-seller-bg");
      el.removeAttribute("data-seller-effect");
    });
    const title = clone.querySelector(".section-title");
    if (title) title.remove();
    // Remove actions (both old and new structure)
    const actions = clone.querySelector(".seller-actions, .seller-card-actions");
    if (actions) actions.remove();
    const staff = clone.querySelector(".seller-staff-side");
    if (staff) staff.remove();
    return clone;
  };

  let profileCard = elements.shopPreviewProfileCard.querySelector(".seller-card--preview");
  if (!profileCard) {
    profileCard = buildSellerPreview();
    if (profileCard) {
      elements.shopPreviewProfileCard.innerHTML = "";
      elements.shopPreviewProfileCard.appendChild(profileCard);
    }
  }
  if (profileCard) {
    // Updated selectors for new seller card structure
    const avatarEl = profileCard.querySelector(".avatar");
    const avatarWrapEl = profileCard.querySelector(".seller-avatar-wrap");
    const nameEl = profileCard.querySelector(".seller-name");
    const badgeEl = profileCard.querySelector(".cosmetic-badge");
    const labelEl = profileCard.querySelector(".uni-label, .role-badge");
    const familyEl = profileCard.querySelector(".family-inline-badge");
    const sinceEl = profileCard.querySelector(".seller-meta");
    const closedDeals = Number(profile.stats?.closed_deals || profile.closed_listings || 0);

    if (avatarEl) setAvatarPreview(avatarEl, avatarUrl, getInitials(displayName));
    applyProfileFrame(avatarWrapEl, previewCosmetics.profile_frame);
    if (nameEl) nameEl.textContent = displayName;
    if (familyEl) familyEl.remove();
    renderCompactReputation(sinceEl, closedDeals);

    applyCosmeticsToDisplay({
      nameEl,
      labelEl,
      badgeEl,
      sellerCardEl: profileCard,
      cosmetics: previewCosmetics,
      fallbackLabel: baseLabel,
      forceLabelText: ownerLabelOverride?.text || "",
      forceLabelStyle: ownerLabelOverride?.style || "",
    });
  }

  if (elements.shopPreviewProfileAvatar) {
    setAvatarPreview(elements.shopPreviewProfileAvatar, avatarUrl, getInitials(displayName));
  }
  applyProfileFrame(elements.shopPreviewProfileRing, previewCosmetics.profile_frame || "");
  applyProfileFrame(elements.shopPreviewProfileAvatarWrap, previewCosmetics.profile_frame || "");
  if (elements.shopPreviewProfileName) {
    elements.shopPreviewProfileName.textContent = displayName;
    applyNickColor(elements.shopPreviewProfileName, previewCosmetics.nick_color);
  }
  updateCosmeticBadge(elements.shopPreviewProfileBadge, previewCosmetics.badge);
  applyBadgeStyle(elements.shopPreviewProfileBadge, previewCosmetics.badge_style);
  renderBadgeSlotsForContext({
    profile,
    cosmetics: previewCosmetics,
    fallbackLabel: baseLabel,
    forceLabelText: ownerLabelOverride?.text || "",
    forceLabelStyle: ownerLabelOverride?.style || "",
    mainEl: elements.shopPreviewProfileMain,
    secondaryEl: elements.shopPreviewProfileSecondary,
    territoryEl: elements.shopPreviewProfileTerritory,
    vipEl: elements.shopPreviewProfileVip,
  });

  // Apply profile colors to shop preview gradient
  const previewSection = document.querySelector(".shop-preview-section");
  if (previewSection) {
    try {
      const saved = JSON.parse(localStorage.getItem("mancini_profile_colors"));
      if (saved && saved.c1 && saved.c2) {
        const rgb1 = hexToRgbStr(saved.c1);
        const rgb2 = hexToRgbStr(saved.c2);
        previewSection.style.setProperty("--shop-pc1", rgb1);
        previewSection.style.setProperty("--shop-pc2", rgb2);
      }
    } catch { /* ignore */ }
  }

  // Apply profile pattern to shop preview
  const shopPatternEl = document.getElementById("shopPreviewPattern");
  if (shopPatternEl) {
    try {
      const savedPattern = localStorage.getItem("mancini_profile_pattern");
      if (savedPattern) {
        shopPatternEl.setAttribute("data-pattern", savedPattern);
        shopPatternEl.classList.add("active");
      } else {
        shopPatternEl.classList.remove("active");
        shopPatternEl.removeAttribute("data-pattern");
      }
    } catch { /* ignore */ }
  }

}

const { CATEGORY_ICONS, CATEGORY_FALLBACK_COVERS, CATEGORY_COVER_IMAGE_CLASSES } = (window.__miniappStaticCatalogs || {});

function getTid() {
  const url = new URL(window.location.href);
  return url.searchParams.get("tid");
}

function getHashParams() {
  const hash = window.location.hash || "";
  if (!hash.startsWith("#")) return new URLSearchParams();
  return new URLSearchParams(hash.slice(1));
}

function getQueryParams() {
  const url = new URL(window.location.href);
  return url.searchParams;
}

function getListingParam() {
  const url = new URL(window.location.href);
  const direct = url.searchParams.get("listing");
  if (direct) return direct;
  // startapp=listing-<id>: a shared link opens this listing
  const match = String(getStartParam() || "").match(/^listing[:_-]?(\d+)$/i);
  return match ? match[1] : null;
}

function getStartParam() {
  if (window.Telegram && window.Telegram.WebApp) {
    const startParam = window.Telegram.WebApp.initDataUnsafe
      ? window.Telegram.WebApp.initDataUnsafe.start_param
      : null;
    if (startParam) return String(startParam);
  }
  const hashParams = getHashParams();
  const hashStart = hashParams.get("tgWebAppStartParam");
  if (hashStart) return String(hashStart);
  const queryParams = getQueryParams();
  const queryStart = queryParams.get("tgWebAppStartParam");
  if (queryStart) return String(queryStart);
  return "";
}

function getChatParam() {
  const url = new URL(window.location.href);
  const direct = url.searchParams.get("chat");
  if (direct) return direct;
  const startParam = getStartParam();
  if (!startParam) return null;
  const match = startParam.match(/^(?:deal-chat|chat)[:_-]?(\d+)(?:[:_-](\d+))?$/i);
  if (match) return match[1];
  return null;
}

function getChatThreadParam() {
  const url = new URL(window.location.href);
  const direct = url.searchParams.get("chat_id");
  if (direct) return direct;
  // startapp=deal-chat-<listing>-<thread> (Telegram notifications open one exact dialog)
  const match = getStartParam().match(/^(?:deal-chat|chat)[:_-]?\d+[:_-](\d+)$/i);
  if (match) return match[1];
  return null;
}

function getClubParam() {
  if (!isGameUiEnabled()) return null;
  const url = new URL(window.location.href);
  const direct = url.searchParams.get("club_id") || url.searchParams.get("club");
  if (direct) return direct;
  const startParam = getStartParam();
  if (!startParam) return null;
  const match = startParam.match(/^club[:_-]?(\d+)$/i);
  if (match) return match[1];
  return null;
}

function getPageParam() {
  const url = new URL(window.location.href);
  const page = url.searchParams.get("page");
  if (page) return page;
  const startParam = getStartParam();
  if (startParam) {
    if (/^(?:deal-chat|chat)[:_-]?\d+(?:[:_-]\d+)?$/i.test(startParam)) return "deal-chat";
    if (/^club[:_-]?\d+$/i.test(startParam)) return "club";
    const profileTab = startParam.match(/^profile-(hidden|active)(?:-\d+)?$/i);
    if (profileTab) return `profile-${profileTab[1].toLowerCase()}`;
    return startParam;
  }
  return null;
}

// startapp=profile-hidden-<listing> / profile-active-<listing> (Telegram expiry notices): the listing to show in the profile.
function getProfileListingParam() {
  const url = new URL(window.location.href);
  const direct = Number(url.searchParams.get("listing") || 0);
  if (direct > 0) return direct;
  const match = String(getStartParam() || "").match(/^profile-(?:hidden|active)-(\d+)$/i);
  return match ? Number(match[1]) : 0;
}

function readInitData() {
  if (window.Telegram && window.Telegram.WebApp) {
    window.Telegram.WebApp.ready();
    if (window.Telegram.WebApp.initData) {
      return window.Telegram.WebApp.initData;
    }
  }
  const hashParams = getHashParams();
  const hashData = hashParams.get("tgWebAppData");
  if (hashData) return decodeURIComponent(hashData);
  const queryParams = getQueryParams();
  const queryData = queryParams.get("tgWebAppData");
  if (queryData) return decodeURIComponent(queryData);
  return "";
}

function getInitData() {
  return readInitData();
}

async function waitForInitData(timeoutMs = 800) {
  const started = Date.now();
  while (Date.now() - started < timeoutMs) {
    const value = readInitData();
    if (value) return value;
    await new Promise((resolve) => setTimeout(resolve, 120));
  }
  return "";
}

async function ensureAuthContext(timeoutMs = 1500) {
  if (!state.initData) {
    state.initData = getInitData();
    if (!state.initData) {
      state.initData = await waitForInitData(timeoutMs);
    }
  }
  if (!state.tid) {
    state.tid = getTid();
    if (!state.tid) {
      state.tid = getTelegramUserId();
    }
    if (!state.tid) {
      state.tid = await waitForTelegramUserId(timeoutMs);
    }
  }
}

async function waitForTelegramUserId(timeoutMs = 1500) {
  const started = Date.now();
  while (Date.now() - started < timeoutMs) {
    const id = getTelegramUserId();
    if (id) return id;
    await new Promise((resolve) => setTimeout(resolve, 150));
  }
  return null;
}

function getTelegramUserId() {
  if (window.Telegram && window.Telegram.WebApp) {
    window.Telegram.WebApp.ready();
    const user = window.Telegram.WebApp.initDataUnsafe
      ? window.Telegram.WebApp.initDataUnsafe.user
      : null;
    if (user && user.id) return String(user.id);
  }
  return null;
}

function getTelegramUserPhoto() {
  if (window.Telegram && window.Telegram.WebApp) {
    const user = window.Telegram.WebApp.initDataUnsafe
      ? window.Telegram.WebApp.initDataUnsafe.user
      : null;
    return user && user.photo_url ? user.photo_url : "";
  }
  return "";
}

function isAndroidClient() {
  const platform = String(window.Telegram?.WebApp?.platform || "").toLowerCase();
  if (platform.includes("android")) return true;
  const ua = String(navigator.userAgent || "").toLowerCase();
  return ua.includes("android");
}

function getAndroidPerformanceTier() {
  if (!isAndroidClient()) return "non-android";
  const ua = String(navigator.userAgent || "").toUpperCase();
  const telegramTier = ua.match(/(?:^|[;\s(])(LOW|AVERAGE|HIGH)(?:$|[;\s)])/);
  if (telegramTier) return telegramTier[1].toLowerCase();

  // Standalone Android WebViews do not always expose Telegram's tier.
  // Use conservative browser hints when available and default to average.
  const memoryGb = Number(navigator.deviceMemory || 0);
  const cpuCores = Number(navigator.hardwareConcurrency || 0);
  if ((memoryGb > 0 && memoryGb <= 3) || (cpuCores > 0 && cpuCores <= 4)) return "low";
  if (memoryGb >= 6 && cpuCores >= 6) return "high";
  return "average";
}

function isIOSClient() {
  const platform = String(window.Telegram?.WebApp?.platform || "").toLowerCase();
  if (platform.includes("ios")) return true;
  const ua = String(navigator.userAgent || "").toLowerCase();
  return ua.includes("iphone") || ua.includes("ipad") || ua.includes("ipod");
}

function isAndroidLiteMode() {
  return document.documentElement.classList.contains("android-lite");
}

function applyViewportCssVars() {
  const root = document.documentElement;
  const visualViewportHeight = Number(window.visualViewport?.height || 0);
  const layoutViewportHeight = Math.max(
    Number(window.innerHeight || 0),
    Number(document.documentElement?.clientHeight || 0),
  );
  const viewportHeight = visualViewportHeight > 0 ? visualViewportHeight : layoutViewportHeight;
  const safeHeight = Number.isFinite(viewportHeight) && viewportHeight > 0 ? viewportHeight : 0;
  root.style.setProperty("--app-height", `${safeHeight}px`);
  root.style.setProperty("--app-vh", `${safeHeight / 100}px`);
}

function applyAndroidPerfMode() {
  const root = document.documentElement;
  const body = document.body;
  const isAndroid = isAndroidClient();
  const androidPerformanceTier = getAndroidPerformanceTier();
  const isTelegramWebView = Boolean(window.Telegram && window.Telegram.WebApp);
  root.classList.toggle("android-lite", isAndroid);
  root.classList.toggle("is-android-webview", isAndroid && isTelegramWebView);
  root.classList.toggle("android-perf-low", androidPerformanceTier === "low");
  root.classList.toggle("android-perf-average", androidPerformanceTier === "average");
  root.classList.toggle("android-perf-high", androidPerformanceTier === "high");
  if (isAndroid) root.dataset.androidPerformance = androidPerformanceTier;
  else delete root.dataset.androidPerformance;
  if (body) {
    body.classList.toggle("android-lite", isAndroid);
    body.classList.toggle("android-perf-low", androidPerformanceTier === "low");
    body.classList.toggle("android-perf-average", androidPerformanceTier === "average");
    body.classList.toggle("android-perf-high", androidPerformanceTier === "high");
  }
  console.info("perf: ANDROID device tier", { tier: androidPerformanceTier });
  return isAndroid;
}

function withAuth(path) {
  if (!state.tid) {
    return path;
  }
  return path.includes("?") ? `${path}&tid=${state.tid}` : `${path}?tid=${state.tid}`;
}

const { ROOT_TABS, COINS_PANE_TO_PAGE, preloadCaptureImages } = (window.__miniappStaticCatalogs || {});

const navStack = [];
let telegramBackBound = false;
let androidBackBound = false;
let pageTransitionDirection = "left";
let rootTransitionSequence = 0;
const pageAnimationTimers = new WeakMap();
const readyRootPages = new Set();
const coinsScrollByPage = new Map();
let gamesLastPage = "rating";
let gamesReturnRoot = "market";
let consumedClubStartTarget = "";

function getPageDomTarget(page) {
  return page === "tournament" ? "leaderboard" : page;
}

function isRootTab(page) {
  if (page === "games" && !isGameUiEnabled()) return false;
  return ROOT_TABS.has(page);
}

function isCoinsPage(page) {
  const value = String(page || "");
  return value === "coins" || value.startsWith("coins-");
}

function isGamesPage(page) {
  return isUiPageEnabled(page) && (page === "rating" || page === "capture" || page === "tournament" || page === "club");
}

function setPageDataState(page, status, message = "") {
  const pageEl = document.querySelector(`[data-page="${getPageDomTarget(page)}"]`);
  if (!pageEl) return;
  const normalizedStatus = String(status || "idle");
  pageEl.dataset.dataState = normalizedStatus;
  pageEl.setAttribute("aria-busy", normalizedStatus === "loading" || normalizedStatus === "refreshing" ? "true" : "false");
  const loader = pageEl.querySelector("[data-page-loader]");
  if (!loader) return;
  const showLoader = normalizedStatus === "loading" || normalizedStatus === "error";
  loader.classList.toggle("hidden", !showLoader);
  loader.classList.toggle("page-data-loader--error", normalizedStatus === "error");
  const textEl = loader.querySelector("[data-page-loader-text]");
  if (textEl && message) textEl.textContent = message;
}

async function loadGamesPageData(page) {
  const target = String(page || "").trim();
  if (target === "rating") return loadRatingPage();
  if (target === "capture") {
    let payload = null;
    try {
      payload = await loadCaptureState({ force: false, detail: true });
    } finally {
      if (state.page === "capture") {
        startCaptureStateAutoRefresh();
      }
    }
    if (state.page === "capture" && stateCapture.loaded) {
      scheduleCaptureTutorialOpen();
    }
    return payload;
  }
  if (target === "tournament") return loadTournamentPage();
  if (target === "club") return loadClubPage();
  return null;
}

function getActiveRootForPage(page) {
  if (isRootTab(page)) return page;
  if (page === "rating") return "games";
  if (page === "capture") return "games";
  if (page === "leaderboard") return "games";
  if (page === "tournament") return "games";
  if (page === "club") return "games";
  if (page === "deal-chat" || page === "conversations") return "conversations";
  if (page === "profile-stats" || page === "profile-report") return "profile";
  if (page === "case-open") return "coins";
  if (String(page || "").startsWith("coins-")) return "coins";
  for (let idx = navStack.length - 1; idx >= 0; idx -= 1) {
    const entry = navStack[idx];
    const candidate = entry ? entry.page : null;
    if (isRootTab(candidate)) return candidate;
  }
  return "market";
}

function runPageSwipeAnimation(page, direction) {
  const pageEl = document.querySelector(`[data-page="${getPageDomTarget(page)}"]`);
  if (!pageEl) return;
  const animationEl = page === "profile"
    ? (pageEl.querySelector("[data-profile-content-layer]") || pageEl)
    : pageEl;
  const cls = direction === "left" ? "swipe-enter-left" : "swipe-enter-right";
  const previousTimer = pageAnimationTimers.get(animationEl);
  if (previousTimer) clearTimeout(previousTimer);
  animationEl.classList.remove("swipe-enter-left", "swipe-enter-right");
  animationEl.classList.add(cls);
  const timer = setTimeout(() => {
    animationEl.classList.remove(cls);
    pageAnimationTimers.delete(animationEl);
  }, 320);
  pageAnimationTimers.set(animationEl, timer);
}

function hapticImpact(style = "light") {
  try {
    window.Telegram?.WebApp?.HapticFeedback?.impactOccurred(style);
  } catch {
    // ignore
  }
}

function getRootTransitionDirection(targetPage) {
  const rootOrder = ["racing", "market", "games", "coins", "conversations", "profile"].filter(isUiPageEnabled);
  const currentIndex = rootOrder.indexOf(getActiveRootForPage(state.page));
  const targetIndex = rootOrder.indexOf(targetPage);
  if (currentIndex < 0 || targetIndex < 0 || currentIndex === targetIndex) return "left";
  return targetIndex > currentIndex ? "left" : "right";
}

async function prepareRootPage(page) {
  if (page === "racing") {
    ensureRacingFrame();
    return true;
  }
  if (page === "market") {
    if (stateMarket.loaded) {
      await refreshTopStatusFromFilters();
      return true;
    }
    await loadMarket();
    return stateMarket.loaded;
  }
  if (page === "conversations") {
    await loadConversations({ silent: true });
    return stateConversations.loaded;
  }
  if (page === "profile") {
    const tasks = [loadProfile({ full: true, loadListings: true })];
    if (normalizeProfileSectionTab(stateProfile.sectionTab) === "referrals") {
      tasks.push(loadReferrals());
    }
    const results = await Promise.allSettled(tasks);
    const profileReady = results[0]?.status === "fulfilled" && stateProfile.appearanceLoaded;
    // First paint is atomic: the avatar images are part of it, not a late patch.
    if (profileReady) await settleProfileFirstPaintAssets();
    return profileReady;
  }
  if (page === "coins") {
    // The profile/balance is the only data required for the first complete
    // Activity frame. Cards below it own their loading/error states and should
    // hydrate in parallel without keeping the whole root page behind a loader.
    const profilePromise = loadProfile({ full: true });
    const secondaryPromise = Promise.allSettled([
      loadWeeklyTasks(),
      loadReferrals(),
      loadActivityHistoryPreview(),
      refreshTopStatusFromFilters(),
    ]);
    const profileResult = await Promise.allSettled([profilePromise]);
    void secondaryPromise.then(() => {
      updateCoinsTileBadges();
      updateVipPage();
    });
    updateCoinsTileBadges();
    updateVipPage();
    return profileResult[0]?.status === "fulfilled";
  }
  return true;
}

const PROFILE_ASSET_SETTLE_MAX_MS = 6000;

// Resolves when `promise` settles or after `ms`, whichever comes first. This is
// a failure bound for a dead image host, not a wait for rendering to catch up.
function settleWithDeadline(promise, ms) {
  return new Promise((resolve) => {
    promise.then(resolve, resolve);
    if (typeof AbortSignal !== "undefined" && typeof AbortSignal.timeout === "function") {
      AbortSignal.timeout(ms).addEventListener("abort", () => resolve(), { once: true });
    }
  });
}

function settleProfileFirstPaintAssets() {
  return settleWithDeadline(
    Promise.all([whenAvatarSettled(elements.profileAvatar), whenAvatarSettled(elements.navProfileAvatar)]),
    PROFILE_ASSET_SETTLE_MAX_MS,
  );
}

// The profile gradient belongs to the profile first paint: it may only be
// visible together with final profile content, never as a stale placeholder.
function syncProfileBackdrop() {
  const page = state.page;
  document.body.classList.toggle(
    "profile-bg-active",
    page === "public-profile" || (page === "profile" && isRootPageReady("profile")),
  );
}

function releaseProfileLoaderIfOwned() {
  const loader = document.querySelector("[data-root-page-loader]");
  if (loader && loader.dataset.loadingPage === "profile") setRootPageLoading("profile", false);
}

// Profile can be entered without the bottom bar (chat deep link, goBack,
// profile-stats back). Those entries get the same first-paint gate.
async function gateProfileEntryFirstPaint(options = {}) {
  const transitionSequence = ++rootTransitionSequence;
  const animate = options.animate !== false;
  const direction = options.direction || pageTransitionDirection || "left";
  setRootPageLoading("profile", true);
  let pageReady = true;
  try {
    pageReady = (await prepareRootPage("profile")) !== false;
  } catch (error) {
    pageReady = false;
    console.error("Failed to prepare Profile first paint:", error);
  }
  if (pageReady) readyRootPages.add("profile");
  if (transitionSequence !== rootTransitionSequence || state.page !== "profile") return;
  if (pageReady && animate) runPageSwipeAnimation("profile", direction);
  setRootPageLoading("profile", !pageReady, !pageReady);
  syncProfileBackdrop();
  window.requestAnimationFrame(() => window.scrollTo({ top: 0, behavior: "auto" }));
}

function isRootPageReady(page) {
  if (readyRootPages.has(page)) return true;
  if (page === "market") return stateMarket.loaded;
  if (page === "conversations") return stateConversations.loaded;
  if (page === "profile") {
    return stateProfile.appearanceLoaded && stateProfile.fullLoaded && stateMyListings.loaded;
  }
  return false;
}

function setRootPageLoading(page, loading, failed = false) {
  const pageEl = document.querySelector(`[data-page="${getPageDomTarget(page)}"]`);
  if (!pageEl) return;
  let loader = document.querySelector("[data-root-page-loader]");
  if (!loader) {
    loader = document.createElement("div");
    loader.className = "page-data-loader root-page-data-loader hidden";
    loader.dataset.rootPageLoader = "";
    loader.setAttribute("role", "status");
    loader.setAttribute("aria-live", "polite");
    loader.innerHTML = '<span class="page-data-loader-spinner" aria-hidden="true"></span><strong data-root-page-loader-text></strong>';
    document.body.appendChild(loader);
  }
  const text = loader.querySelector("[data-root-page-loader-text]");
  const guestGate = Boolean(failed && typeof webAuthIsGuest === "function" && webAuthIsGuest());
  if (text) text.textContent = failed ? (guestGate ? "Войдите, чтобы продолжить" : "Не удалось загрузить данные") : "Загружаем данные…";
  let guestBox = loader.querySelector("[data-guest-gate]");
  if (guestGate && !guestBox) {
    guestBox = document.createElement("div");
    guestBox.dataset.guestGate = "";
    guestBox.className = "guest-gate";
    guestBox.innerHTML = '<p class="guest-gate-text">Профиль, чаты и объявления доступны после входа через Telegram. Пароль не нужен.</p><button class="web-auth-primary guest-gate-btn" type="button">Войти через Telegram</button>';
    guestBox.querySelector("button").addEventListener("click", () => webAuthOpenDialog());
    loader.appendChild(guestBox);
  }
  if (guestBox) guestBox.hidden = !guestGate;
  loader.classList.toggle("page-data-loader--guest", loading && guestGate);
  loader.classList.toggle("hidden", !loading);
  loader.classList.toggle("page-data-loader--error", loading && failed && !guestGate);
  loader.dataset.loadingPage = loading ? page : "";
  pageEl.classList.toggle("root-page-loading", loading);
}

async function openRootTab(page, options = {}) {
  page = getFeatureSafePage(page);
  const transitionSequence = ++rootTransitionSequence;
  const direction = options.direction || getRootTransitionDirection(page);
  const resetViewportToTop = (targetPage) => {
    const pageEl = document.querySelector(`[data-page="${getPageDomTarget(targetPage)}"]`);
    if (pageEl) {
      pageEl.scrollTop = 0;
    }
    document.documentElement.scrollTop = 0;
    document.body.scrollTop = 0;
    window.scrollTo({ top: 0, behavior: "auto" });
  };
  if (page === "games" || page === "rating") {
    const currentRoot = getActiveRootForPage(state.page);
    if (currentRoot && currentRoot !== "games") {
      gamesReturnRoot = currentRoot;
    }
    const targetGamesPage = isGamesPage(gamesLastPage) ? gamesLastPage : "rating";
    resetNavTo(targetGamesPage, { direction });
    window.requestAnimationFrame(() => {
      window.scrollTo({ top: 0, behavior: "auto" });
    });
    if (isGamesPage(targetGamesPage)) {
      await loadGamesPageData(targetGamesPage);
    } else {
      await loadLeaderboardPage();
    }
    return;
  }
  const pageWasReady = isRootPageReady(page);
  setRootPageLoading(page, !pageWasReady);
  // A cold page stays behind the stable loader until its required data is
  // ready. Starting its transition now would spend the entire animation under
  // that overlay, making the eventual reveal look instantaneous.
  resetNavTo(page, { direction, skipPageLoad: true, animate: pageWasReady, rootGate: true });
  if (page === "profile") {
    window.requestAnimationFrame(() => {
      resetViewportToTop("profile");
    });
  }
  let pageReady = true;
  try {
    pageReady = (await prepareRootPage(page)) !== false;
  } catch (error) {
    pageReady = false;
    console.error(`Failed to prepare root page ${page}:`, error);
  }
  if (pageReady) readyRootPages.add(page);
  if (transitionSequence !== rootTransitionSequence) {
    if (page === "coins" && state.page !== "coins") {
      stopBloggerEventTimer();
      stopDailyTasksTimer();
      stopWeeklyTasksTimer();
    }
    return;
  }
  if (!pageWasReady && pageReady) {
    // Start the animation in the same render turn in which the loader is
    // removed. The first uncovered paint is therefore an actual transition
    // frame, not the already-settled final page.
    runPageSwipeAnimation(page, direction);
  }
  setRootPageLoading(page, !pageReady, !pageReady);
  if (page === "profile") {
    syncProfileBackdrop();
    resetViewportToTop("profile");
  } else {
    window.requestAnimationFrame(() => {
      window.scrollTo({ top: 0, behavior: "auto" });
    });
  }
  if (isGamesPage(page)) await loadGamesPageData(page);
  if (page === "admin") {
    if (stateAdmin.tab === "complaints") await loadAdminComplaints();
    if (stateAdmin.tab === "system") await loadAdminSystem();
    if (stateAdmin.tab === "promocodes") await loadAdminPromocodes();
    if (stateAdmin.tab === "broadcast") startAdminBroadcastPolling();
  }
}

function initRootSwipeGesture() {
  if (!elements.actionBar) return;
  const rootOrder = ["racing", "market", "games", "coins", "conversations", "profile"].filter(isUiPageEnabled);
  let pointerId = null;
  let startX = 0;
  let startY = 0;
  let dragging = false;
  let locked = false;
  let switched = false;

  const clearDragStyles = () => {
    if (elements.actionBar) {
      elements.actionBar.style.removeProperty("--swipe-dx");
      elements.actionBar.classList.remove("is-swiping");
    }
  };

  const switchBySwipe = async (deltaX) => {
    const root = getActiveRootForPage(state.page);
    const idx = rootOrder.indexOf(root);
    if (idx < 0) return;
    const targetIdx = deltaX < 0 ? idx + 1 : idx - 1;
    if (targetIdx < 0 || targetIdx >= rootOrder.length) return;
    const target = rootOrder[targetIdx];
    const dir = deltaX < 0 ? "left" : "right";
    switched = true;
    hapticImpact("medium");
    await openRootTab(target, { direction: dir });
  };

  elements.actionBar.addEventListener("pointerdown", (event) => {
    if (event.pointerType === "mouse" && event.button !== 0) return;
    pointerId = event.pointerId;
    startX = event.clientX;
    startY = event.clientY;
    dragging = true;
    locked = false;
    switched = false;
    if (elements.actionBar) {
      elements.actionBar.classList.add("is-swiping");
    }
  }, { passive: true });

  elements.actionBar.addEventListener("pointermove", async (event) => {
    if (!dragging || event.pointerId !== pointerId || switched) return;
    const dx = event.clientX - startX;
    const dy = event.clientY - startY;
    if (!locked) {
      if (Math.abs(dx) < 8) return;
      if (Math.abs(dx) > Math.abs(dy) * 1.25) {
        locked = true;
      } else {
        dragging = false;
        clearDragStyles();
        return;
      }
    }
    if (elements.actionBar) {
      const visualDx = Math.max(-34, Math.min(34, dx * 0.22));
      elements.actionBar.style.setProperty("--swipe-dx", `${visualDx}px`);
    }
    if (Math.abs(dx) >= 64) {
      dragging = false;
      clearDragStyles();
      await switchBySwipe(dx);
    }
  }, { passive: true });

  const finish = () => {
    dragging = false;
    pointerId = null;
    clearDragStyles();
  };

  elements.actionBar.addEventListener("pointerup", finish, { passive: true });
  elements.actionBar.addEventListener("pointercancel", finish, { passive: true });
  elements.actionBar.addEventListener("pointerleave", finish, { passive: true });
}

// ── App-wide swipes (Telegram-like): swipe right = back, on the main tabs left/right = neighbour tab ──────────────
// Conservative on purpose: one finger, clearly horizontal, long enough, and never on things that scroll or drag sideways.
function initGlobalSwipeGestures() {
  if (window.__rpGlobalSwipeInit) return;
  window.__rpGlobalSwipeInit = true;
  const NO_SWIPE_SELECTOR =
    "input, textarea, select, canvas, [contenteditable], [data-no-swipe], #imageZoomModal, .deal-chat-message-menu, " +
    ".server-drawer, .rp-confirm-overlay, .photo-grid, .market-filters-scroll";
  const MIN_DX = 88;          // px, a deliberate swipe
  const MAX_TIME_MS = 650;
  const RATIO = 2;            // |dx| must be at least twice |dy|
  let touch = null;

  const scrollsSideways = (node) => {
    for (let el = node; el && el !== document.body && el.nodeType === 1; el = el.parentElement) {
      if (el.scrollWidth > el.clientWidth + 4) {
        const overflowX = getComputedStyle(el).overflowX;
        if (overflowX === "auto" || overflowX === "scroll") return true;
      }
    }
    return false;
  };

  const canGoBack = () => {
    const page = String(state.page || "").trim();
    return Boolean(document.querySelector(".modal.show")) ||
      (page && !isRootTab(page) && page !== "nickname") || page === "racing";
  };

  const switchTab = async (deltaX) => {
    const rootOrder = ["racing", "market", "games", "coins", "conversations", "profile"].filter(isUiPageEnabled);
    const idx = rootOrder.indexOf(state.page);
    if (idx < 0) return;
    const targetIdx = deltaX < 0 ? idx + 1 : idx - 1;
    if (targetIdx < 0 || targetIdx >= rootOrder.length) return;
    hapticImpact("light");
    await openRootTab(rootOrder[targetIdx], { direction: deltaX < 0 ? "left" : "right" });
  };

  document.addEventListener("touchstart", (event) => {
    touch = null;
    if (!event.touches || event.touches.length !== 1) return;
    const target = event.target;
    if (!target || !target.closest) return;
    if (target.closest(NO_SWIPE_SELECTOR) || scrollsSideways(target)) return;
    if (document.body.classList.contains("level-path-open")) return;
    if (String(window.getSelection?.()?.toString() || "").length > 0) return;
    const point = event.touches[0];
    touch = { x: point.clientX, y: point.clientY, t: Date.now(), dead: false };
  }, { passive: true });

  document.addEventListener("touchmove", (event) => {
    if (!touch || touch.dead || !event.touches || event.touches.length !== 1) {
      if (touch && event.touches && event.touches.length > 1) touch.dead = true;
      return;
    }
    const point = event.touches[0];
    const dx = point.clientX - touch.x;
    const dy = point.clientY - touch.y;
    if (Math.abs(dy) > 16 && Math.abs(dy) > Math.abs(dx) * 0.6) touch.dead = true;  // it is a vertical scroll
  }, { passive: true });

  document.addEventListener("touchend", (event) => {
    const current = touch;
    touch = null;
    if (!current || current.dead || !event.changedTouches || !event.changedTouches.length) return;
    const point = event.changedTouches[0];
    const dx = point.clientX - current.x;
    const dy = point.clientY - current.y;
    if (Date.now() - current.t > MAX_TIME_MS) return;
    if (Math.abs(dx) < MIN_DX || Math.abs(dx) < Math.abs(dy) * RATIO) return;
    if (dx > 0 && canGoBack()) {
      hapticImpact("light");
      goBack();
      return;
    }
    const page = String(state.page || "").trim();
    if (isRootTab(page) && page !== "games" && !document.querySelector(".modal.show")) switchTab(dx);
  }, { passive: true });
}

// ── Website (outside the Mini App): the browser's Back button / edge swipe must walk back through our screens ──────
// The app is a single page, so without history entries Back leaves the site. history is kept in step with the screen
// stack: one entry per level (open screens + an open window); a popstate (browser Back) runs goBack(), and going back
// from inside the app pops the entry we pushed.
let webHistDepth = 0;
let webHistSuppress = 0;

function webHistoryWantedDepth() {
  const page = String(state.page || "").trim();
  const levels = isRootTab(page) || !page || page === "nickname" ? 0 : Math.max(1, navStack.length);
  // every open overlay is one more level to step back from: windows, the levels path screen and the level reward window
  return levels
    + (document.querySelector(".modal.show") ? 1 : 0)
    + (document.body.classList.contains("level-path-open") ? 1 : 0)
    + (document.getElementById("levelRewardModal") ? 1 : 0);
}

function syncWebHistory() {
  try {
    if (!isWebBrowserMode() || typeof history?.pushState !== "function") return;
    const wanted = webHistoryWantedDepth();
    while (webHistDepth < wanted) {
      webHistDepth += 1;
      history.pushState({ rpDepth: webHistDepth }, "");
    }
    if (webHistDepth > wanted) {
      const steps = webHistDepth - wanted;
      webHistDepth = wanted;
      webHistSuppress += 1;  // the popstate of this very jump is ours, not the person's Back press
      history.go(-steps);
    }
  } catch {
    // history is a convenience: never break navigation
  }
}

function initWebHistory() {
  if (window.__rpWebHistoryInit || !isWebBrowserMode()) return;
  window.__rpWebHistoryInit = true;
  try {
    history.replaceState({ rpDepth: 0 }, "");
  } catch {
    // ignore
  }
  window.addEventListener("popstate", (event) => {
    if (webHistSuppress > 0) {
      webHistSuppress -= 1;
      return;
    }
    webHistDepth = Number(event.state?.rpDepth || 0);
    if (webHistoryWantedDepth() > webHistDepth) goBack();  // goBack() re-syncs the history through syncTelegramBackButton()
  });
}

// the «‹ Назад» pill of the website top bar: shown on inner screens and over an open window
function syncWebTopBar() {
  const bar = document.getElementById("webTopBar");
  if (!bar) return;
  const showBack = webHistoryWantedDepth() > 0;
  const hasChip = Boolean(document.getElementById("webAuthChip"));  // a guest's «Войти»
  const active = showBack || hasChip;
  bar.classList.toggle("is-active", active);
  document.documentElement.classList.toggle("web-topbar-active", active);  // only then the content makes room for the bar
  document.getElementById("webTopBarBack")?.classList.toggle("is-visible", showBack);
}

function syncTelegramBackButton() {
  syncWebHistory();
  syncWebTopBar();
  try {
    if (!window.Telegram || !window.Telegram.WebApp || !window.Telegram.WebApp.BackButton) return;
    const webApp = window.Telegram.WebApp;
    if (!telegramBackBound) {
      webApp.BackButton.onClick(() => {
        goBack();
      });
      telegramBackBound = true;
    }
    const activePageFromDom = String(document.querySelector(".page.active[data-page]")?.getAttribute("data-page") || "").trim();
    const currentPage = String(state.page || "").trim() || activePageFromDom;
    const hasOpenModal = Boolean(document.querySelector(".modal.show")) || document.body.classList.contains("level-path-open");
    if (!hasOpenModal && (!currentPage || isRootTab(currentPage) || currentPage === "nickname")) {
      webApp.BackButton.hide();
    } else {
      webApp.BackButton.show();
    }
  } catch {
    // ignore
  }
}

function syncAndroidBackButton() {
  // Disabled: use only Telegram native BackButton / in-page back controls.
  return;
}

function initModalCornerCloseButtons() {
  document.querySelectorAll(".modal").forEach((modal) => {
    const card = modal.querySelector(".modal-card");
    if (!card) return;
    // Skip modals that already have any close control.
    if (card.querySelector(".icon-close, .image-zoom-close, .rules-close")) return;
    if (card.querySelector(".modal-corner-close")) return;
    const hasAnyCloseButton = Array.from(card.querySelectorAll("button")).some((button) => {
      const id = String(button.id || "");
      const aria = String(button.getAttribute("aria-label") || "").trim().toLowerCase();
      const text = String(button.textContent || "").trim().toLowerCase();
      return /close/i.test(id) || aria === "закрыть" || text === "закрыть";
    });
    if (hasAnyCloseButton) return;
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "modal-corner-close";
    btn.setAttribute("aria-label", "Закрыть");
    btn.textContent = "✕";
    card.appendChild(btn);
  });
}

function resetNavTo(page, options = {}) {
  navStack.length = 0;
  pageTransitionDirection = options.direction || "left";
  setActivePage(getFeatureSafePage(page), options);
}

function navigateTo(page) {
  page = getFeatureSafePage(page);
  if (!page || page === state.page) return;
  if (isCoinsPage(state.page)) {
    coinsScrollByPage.set(state.page, Math.max(0, Number(window.scrollY || 0)));
  }
  if (state.page) {
    navStack.push({ page: state.page });
  }
  pageTransitionDirection = "left";
  setActivePage(page);
  // A page opened from another one starts at its top (the previous page's scroll offset used to carry over,
  // so a long listing opened from the bottom of the market appeared scrolled to its bottom). Coins pages restore their own offset.
  if (!String(page).startsWith("coins-")) {
    window.scrollTo({ top: 0, behavior: "auto" });
    window.requestAnimationFrame(() => window.scrollTo({ top: 0, behavior: "auto" }));
  }
}

function closeImageZoomModal() {
  if (!elements.imageZoomModal) return false;
  if (!elements.imageZoomModal.classList.contains("show")) return false;
  elements.imageZoomModal.classList.remove("show");
  elements.imageZoomModal.classList.remove("is-dragging-down");
  elements.imageZoomModal.style.removeProperty("--iv-bg");
  imageViewer.images = [];
  return true;
}

// ── Photo viewer: pinch / double-tap / pan zoom, swipe between photos, swipe down to close ──────────────────────
// One <img> inside #imageZoomModal. State: scale + translation around the image's untransformed centre.
const imageViewer = { images: [], index: 0, scale: 1, x: 0, y: 0, base: null, pointers: new Map(), gesture: null, lastTap: null, bound: false };
const IMAGE_VIEWER_MAX_SCALE = 5;

function imageViewerImg() {
  return elements.imageZoomImg;
}

function imageViewerApply({ animate = false } = {}) {
  const img = imageViewerImg();
  if (!img) return;
  img.style.transition = animate ? "transform 0.22s cubic-bezier(0.22, 0.61, 0.36, 1)" : "none";
  img.style.transform = `translate3d(${imageViewer.x}px, ${imageViewer.y}px, 0) scale(${imageViewer.scale})`;
}

function imageViewerMeasure() {
  const img = imageViewerImg();
  const card = elements.imageZoomModal && elements.imageZoomModal.querySelector(".image-zoom-card");
  if (!img || !card) return null;
  const prev = img.style.transform;
  img.style.transition = "none";
  img.style.transform = "none";
  const rect = img.getBoundingClientRect();
  const cardRect = card.getBoundingClientRect();
  img.style.transform = prev;
  imageViewer.base = { cx: rect.left + rect.width / 2, cy: rect.top + rect.height / 2, w: rect.width, h: rect.height, vw: cardRect.width, vh: cardRect.height };
  return imageViewer.base;
}

function imageViewerBounds(scale) {
  const b = imageViewer.base || imageViewerMeasure();
  if (!b) return { x: 0, y: 0 };
  return { x: Math.max(0, (b.w * scale - b.vw) / 2), y: Math.max(0, (b.h * scale - b.vh) / 2) };
}

function imageViewerClamp({ animate = true } = {}) {
  imageViewer.scale = Math.min(IMAGE_VIEWER_MAX_SCALE, Math.max(1, imageViewer.scale));
  const bound = imageViewerBounds(imageViewer.scale);
  if (imageViewer.scale <= 1.001) {
    imageViewer.scale = 1;
    imageViewer.x = 0;
    imageViewer.y = 0;
  } else {
    imageViewer.x = Math.min(bound.x, Math.max(-bound.x, imageViewer.x));
    imageViewer.y = Math.min(bound.y, Math.max(-bound.y, imageViewer.y));
  }
  imageViewerApply({ animate });
}

// Zoom to `scale`, keeping the picture point under (clientX, clientY) where it is.
function imageViewerZoomAt(scale, clientX, clientY) {
  const b = imageViewer.base || imageViewerMeasure();
  if (!b) return;
  const next = Math.min(IMAGE_VIEWER_MAX_SCALE, Math.max(1, scale));
  const qx = (clientX - b.cx - imageViewer.x) / imageViewer.scale;
  const qy = (clientY - b.cy - imageViewer.y) / imageViewer.scale;
  imageViewer.scale = next;
  imageViewer.x = clientX - b.cx - qx * next;
  imageViewer.y = clientY - b.cy - qy * next;
}

function imageViewerRenderChrome() {
  const modal = elements.imageZoomModal;
  if (!modal) return;
  const total = imageViewer.images.length;
  let counter = modal.querySelector(".iv-counter");
  if (!counter) {
    counter = document.createElement("div");
    counter.className = "iv-counter";
    modal.querySelector(".image-zoom-card").appendChild(counter);
  }
  counter.hidden = total < 2;
  counter.textContent = `${imageViewer.index + 1} / ${total}`;
  ["prev", "next"].forEach((dir) => {
    let btn = modal.querySelector(`.iv-nav--${dir}`);
    if (!btn) {
      btn = document.createElement("button");
      btn.type = "button";
      btn.className = `iv-nav iv-nav--${dir}`;
      btn.setAttribute("aria-label", dir === "prev" ? "Предыдущее фото" : "Следующее фото");
      btn.textContent = dir === "prev" ? "‹" : "›";
      btn.addEventListener("click", (event) => {
        event.stopPropagation();
        imageViewerStep(dir === "prev" ? -1 : 1);
      });
      btn.addEventListener("pointerdown", (event) => event.stopPropagation());
      modal.querySelector(".image-zoom-card").appendChild(btn);
    }
    btn.hidden = total < 2;
    btn.disabled = dir === "prev" ? imageViewer.index <= 0 : imageViewer.index >= total - 1;
  });
}

function imageViewerShow(index, { fromDir = 0 } = {}) {
  const img = imageViewerImg();
  if (!img || !imageViewer.images.length) return;
  imageViewer.index = Math.min(imageViewer.images.length - 1, Math.max(0, index));
  imageViewer.scale = 1;
  imageViewer.x = fromDir * 48;
  imageViewer.y = 0;
  imageViewer.base = null;
  img.style.opacity = fromDir ? "0" : "1";
  img.onload = () => {
    imageViewerMeasure();
    img.style.transition = "transform 0.22s cubic-bezier(0.22, 0.61, 0.36, 1), opacity 0.22s ease";
    imageViewer.x = 0;
    imageViewerApply({ animate: true });
    img.style.opacity = "1";
  };
  img.src = imageViewer.images[imageViewer.index];
  imageViewerApply();
  if (img.complete) img.onload();
  imageViewerRenderChrome();
}

function imageViewerStep(dir) {
  const next = imageViewer.index + dir;
  if (next < 0 || next >= imageViewer.images.length) {
    imageViewerClamp();
    return;
  }
  imageViewerShow(next, { fromDir: dir });
}

function openImageViewer(images, startIndex = 0) {
  const list = (Array.isArray(images) ? images : [images]).filter(Boolean);
  if (!list.length || !elements.imageZoomModal || !elements.imageZoomImg) return;
  imageViewer.images = list;
  imageViewer.pointers.clear();
  imageViewer.gesture = null;
  imageViewer.lastTap = null;
  elements.imageZoomModal.classList.remove("is-dragging-down");
  elements.imageZoomModal.style.removeProperty("--iv-bg");
  elements.imageZoomModal.classList.add("show");
  stateZoom.scale = 1;
  imageViewerShow(startIndex);
  initImageViewerGestures();
}

function initImageViewerGestures() {
  if (imageViewer.bound) return;
  const modal = elements.imageZoomModal;
  const card = modal && modal.querySelector(".image-zoom-card");
  if (!card) return;
  imageViewer.bound = true;
  const pts = () => Array.from(imageViewer.pointers.values());
  const mid = (a, b) => ({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 });
  const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y) || 1;

  const beginPinch = () => {
    const [a, b] = pts();
    const m = mid(a, b);
    imageViewer.gesture = { type: "pinch", d0: dist(a, b), s0: imageViewer.scale, x0: imageViewer.x, y0: imageViewer.y, m0: m };
    modal.classList.remove("is-dragging-down");
  };

  card.addEventListener("pointerdown", (event) => {
    if (event.target.closest(".image-zoom-close, .iv-nav, .image-zoom-controls")) return;
    imageViewer.pointers.set(event.pointerId, { x: event.clientX, y: event.clientY, sx: event.clientX, sy: event.clientY, t: Date.now() });
    try { card.setPointerCapture(event.pointerId); } catch (_) {}
    if (!imageViewer.base) imageViewerMeasure();
    if (imageViewer.pointers.size === 2) {
      beginPinch();
    } else if (imageViewer.pointers.size === 1) {
      imageViewer.gesture = { type: "pending", x0: imageViewer.x, y0: imageViewer.y, sx: event.clientX, sy: event.clientY, moved: false };
    }
  });

  card.addEventListener("pointermove", (event) => {
    const p = imageViewer.pointers.get(event.pointerId);
    if (!p) return;
    p.x = event.clientX;
    p.y = event.clientY;
    const g = imageViewer.gesture;
    if (!g) return;
    if (g.type === "pinch" && imageViewer.pointers.size >= 2) {
      const [a, b] = pts();
      const m = mid(a, b);
      const base = imageViewer.base || imageViewerMeasure();
      const raw = g.s0 * (dist(a, b) / g.d0);
      // a little rubber band past the limits, settled on release
      const scale = raw < 1 ? 1 - (1 - raw) * 0.5 : Math.min(IMAGE_VIEWER_MAX_SCALE * 1.15, raw);
      const qx = (g.m0.x - base.cx - g.x0) / g.s0;
      const qy = (g.m0.y - base.cy - g.y0) / g.s0;
      imageViewer.scale = scale;
      imageViewer.x = m.x - base.cx - qx * scale;
      imageViewer.y = m.y - base.cy - qy * scale;
      imageViewerApply();
      return;
    }
    if (imageViewer.pointers.size !== 1) return;
    const dx = event.clientX - g.sx;
    const dy = event.clientY - g.sy;
    if (g.type === "pending") {
      if (Math.hypot(dx, dy) < 8) return;
      g.moved = true;
      if (imageViewer.scale > 1.01) g.type = "pan";
      else g.type = Math.abs(dx) > Math.abs(dy) ? "swipe-x" : "swipe-y";
    }
    if (g.type === "pan") {
      imageViewer.x = g.x0 + dx;
      imageViewer.y = g.y0 + dy;
      const bound = imageViewerBounds(imageViewer.scale);
      // resistance beyond the edges
      const soft = (v, lim) => (Math.abs(v) <= lim ? v : Math.sign(v) * (lim + (Math.abs(v) - lim) * 0.3));
      imageViewer.x = soft(imageViewer.x, bound.x);
      imageViewer.y = soft(imageViewer.y, bound.y);
      imageViewerApply();
    } else if (g.type === "swipe-x") {
      const atEdge = (dx > 0 && imageViewer.index === 0) || (dx < 0 && imageViewer.index >= imageViewer.images.length - 1);
      imageViewer.x = atEdge ? dx * 0.3 : dx;
      imageViewerApply();
    } else if (g.type === "swipe-y") {
      imageViewer.y = dy;
      imageViewerApply();
      modal.classList.add("is-dragging-down");
      modal.style.setProperty("--iv-bg", String(Math.max(0.25, 1 - Math.abs(dy) / 420)));
    }
  });

  const finish = (event) => {
    const p = imageViewer.pointers.get(event.pointerId);
    if (!p) return;
    imageViewer.pointers.delete(event.pointerId);
    try { card.releasePointerCapture(event.pointerId); } catch (_) {}
    const g = imageViewer.gesture;
    if (g && g.type === "pinch") {
      if (imageViewer.pointers.size === 1) {
        // one finger stays: continue as a pan from the current position
        const rest = pts()[0];
        imageViewer.gesture = { type: "pan", x0: imageViewer.x, y0: imageViewer.y, sx: rest.x, sy: rest.y, moved: true };
        imageViewerClamp();
      } else if (imageViewer.pointers.size === 0) {
        imageViewer.gesture = null;
        imageViewerClamp();
      }
      return;
    }
    if (imageViewer.pointers.size > 0 || !g) return;
    imageViewer.gesture = null;
    const dx = event.clientX - g.sx;
    const dy = event.clientY - g.sy;
    const fast = Date.now() - p.t < 280;
    if (g.type === "swipe-x") {
      const threshold = fast ? 36 : Math.min(120, window.innerWidth * 0.25);
      if (dx <= -threshold) imageViewerStep(1);
      else if (dx >= threshold) imageViewerStep(-1);
      else imageViewerClamp();
    } else if (g.type === "swipe-y") {
      modal.classList.remove("is-dragging-down");
      if (Math.abs(dy) > (fast ? 60 : 130)) {
        closeImageZoomModal();
        imageViewer.x = 0;
        imageViewer.y = 0;
        imageViewer.scale = 1;
      } else {
        modal.style.removeProperty("--iv-bg");
        imageViewerClamp();
      }
    } else if (g.type === "pan") {
      imageViewerClamp();
    } else if (g.type === "pending" && !g.moved) {
      // a tap: second tap within 280 ms and 30 px = double tap (zoom in at that point / back to fit)
      const now = Date.now();
      const last = imageViewer.lastTap;
      if (last && now - last.t < 280 && Math.hypot(event.clientX - last.x, event.clientY - last.y) < 30) {
        imageViewer.lastTap = null;
        if (imageViewer.scale > 1.05) imageViewer.scale = 1;
        else imageViewerZoomAt(2.5, event.clientX, event.clientY);
        imageViewerClamp();
      } else {
        imageViewer.lastTap = { t: now, x: event.clientX, y: event.clientY };
      }
    }
  };
  card.addEventListener("pointerup", finish);
  card.addEventListener("pointercancel", finish);

  // mouse / trackpad: wheel zooms around the cursor
  card.addEventListener("wheel", (event) => {
    event.preventDefault();
    const factor = Math.exp(-event.deltaY * (event.ctrlKey ? 0.01 : 0.0025));
    imageViewerZoomAt(imageViewer.scale * factor, event.clientX, event.clientY);
    imageViewerClamp({ animate: false });
  }, { passive: false });

  document.addEventListener("keydown", (event) => {
    if (!modal.classList.contains("show")) return;
    if (event.key === "ArrowLeft") imageViewerStep(-1);
    else if (event.key === "ArrowRight") imageViewerStep(1);
  });
}

function closeTopModal() {
  const openModals = Array.from(document.querySelectorAll(".modal.show"));
  const modal = openModals[openModals.length - 1];
  if (!modal) return false;
  const closeButton = modal.querySelector(
    ".modal-corner-close, .icon-close, .rules-close, button[id$='Close'], button[id$='Cancel']",
  );
  if (closeButton) closeButton.click();
  else modal.classList.remove("show");
  updateFabVisibility();
  syncTelegramBackButton();
  return true;
}

function goBack() {
  if (document.getElementById("levelRewardModal") && typeof closeLevelRewardModal === "function") {
    closeLevelRewardModal();
    return;
  }
  if (document.body.classList.contains("level-path-open") && typeof closeLevelPathScreen === "function") {
    closeLevelPathScreen();
    return;
  }
  if (closeImageZoomModal()) {
    return;
  }
  if (closeTopModal()) {
    return;
  }
  if (navStack.length) {
    const prev = navStack.pop();
    pageTransitionDirection = "right";
    setActivePage(prev.page);
    if (prev.page === "market") {
      if (!prev.skipReload) {
        loadMarket();
      }
      if (typeof prev.restoreScrollY === "number") {
        window.requestAnimationFrame(() => {
          window.scrollTo({ top: prev.restoreScrollY, behavior: "auto" });
        });
      }
    } else if (prev.page === "admin") {
      if (stateAdmin.tab === "listings") loadAdminListings();
      if (stateAdmin.tab === "complaints") loadAdminComplaints();
      if (stateAdmin.tab === "logs") loadAdminLogs();
      if (stateAdmin.tab === "system") loadAdminSystem();
      if (stateAdmin.tab === "promocodes") loadAdminPromocodes();
    }
    return;
  }
  if (String(state.page || "").startsWith("coins-")) {
    resetNavTo("coins");
    return;
  }
  if (isGamesPage(state.page)) {
    openRootTab(gamesReturnRoot || "market");
    return;
  }
  resetNavTo("market");
}

function setActivePage(page, options = {}) {
  page = getFeatureSafePage(page);
  const animate = options.animate !== false;
  const skipPageLoad = options.skipPageLoad === true;
  const prevPage = state.page;
  if (isCoinsPage(prevPage)) {
    coinsScrollByPage.set(prevPage, Math.max(0, Number(window.scrollY || 0)));
  }
  const pageEl = document.querySelector(`[data-page="${getPageDomTarget(page)}"]`);
  if (prevPage === page && pageEl && pageEl.classList.contains("active")) {
    syncTelegramBackButton();
    syncAndroidBackButton();
    return;
  }
  if (prevPage === "coins-shop" && stateShop.countdownTimer) {
    clearInterval(stateShop.countdownTimer);
    stateShop.countdownTimer = null;
  }
  if (prevPage === "deal-chat") {
    resetDealChatTransientState();
  }
  if (prevPage === "case-open") {
    stateChest.classicViewOpen = false;
    stopCaseRecentGlobalPolling();
  }
  if (prevPage === "market" && page !== "market") {
    leaveMarketReadLifecycle();
  }
  if (prevPage === "listing" && page !== "listing") {
    leaveListingReadLifecycle();
  }
  if (prevPage === "public-profile" && page !== "public-profile") {
    leavePublicProfileReadLifecycle();
  }

  state.page = page;
  if (page === "market" && !window.__PERF_DIAG__?.hardMarketIsolation) {
    startMarketAutoRefresh();
  }
  if (page === "market" && typeof resumeMarketPreviewLoads === "function") {
    resumeMarketPreviewLoads();
  }
  if (isGamesPage(page)) {
    gamesLastPage = page;
  }
  syncGamesTabUi(page);
  if (page === "conversations") {
    // Always release any stale open lock when user returns to dialogs list.
    stateConversations.openInFlight = false;
    stateConversations.openLockUntil = 0;
  }
  document.body.classList.toggle("deal-chat-active", page === "deal-chat");
  document.body.classList.toggle("capture-active", page === "capture");
  document.body.classList.toggle("tournament-active", page === "tournament");
  document.body.classList.toggle("mining-active", page === "rating");
  document.body.classList.toggle("club-active", page === "club");
  document.body.classList.toggle("admin-active", page === "admin");
  document.body.classList.toggle("case-open-active", page === "case-open");
  document.body.classList.toggle("conversations-bg-active", page === "conversations");
  document.body.classList.toggle("racing-active", page === "racing");
  if (page === "racing") ensureRacingFrame(); else setRacingImmersive(false);
  syncProfileBackdrop();
  if (page !== "profile") releaseProfileLoaderIfOwned();
  if (page !== "market") {
    fabScrollState.hiddenByScroll = false;
    fabScrollState.hiddenAnchorY = 0;
  }
  const activeRoot = getActiveRootForPage(page);
  const domTargetPage = getPageDomTarget(page);
  elements.pages.forEach((section) => {
    section.classList.toggle("active", section.dataset.page === domTargetPage);
  });
  elements.navButtons.forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.nav === activeRoot);
  });
  const mainActionBar = document.getElementById("mainActionBar");
  const gamesActionBar = document.getElementById("gamesActionBar");
  const hideAllActionBars =
    page === "nickname" || page === "deal-chat" || page === "admin" || page === "case-open";
  const racingActionBar = document.getElementById("racingActionBar");
  if (mainActionBar) {
    mainActionBar.classList.toggle("hidden", hideAllActionBars || isGamesPage(page) || page === "racing");
  }
  if (racingActionBar) {
    racingActionBar.classList.toggle("hidden", hideAllActionBars || page !== "racing");
  }
  if (gamesActionBar) {
    gamesActionBar.classList.toggle("hidden", hideAllActionBars || !isGamesPage(page));
  }
  syncActionBarMetrics(page);
  updateFabVisibility();
  if (page === "case-open") {
    startCaseRecentGlobalPolling();
  }
  if (page !== "market") {
    stopMarketEventBannerTimer();
  }
  if (page !== "capture" && stateCapture.timerId) {
    clearInterval(stateCapture.timerId);
    stateCapture.timerId = null;
  }
  if (page !== "tournament") {
    ensureLeaderboardTimer();
  }
  if (page !== "capture") {
    stopCaptureStateAutoRefresh();
    closeCaptureLbModal();
    stopCaptureScrollSound();
    stopCaptureAmbience();
    document.body.classList.remove("capture-online-scroll-hidden");
    setCaptureEnergyPopoverOpen(false);
    closeCaptureTutorial({ markSeen: false });
  }
  if (page !== "coins-tasks" && page !== "coins-referrals") {
    stopBloggerEventTimer();
    stopDailyTasksTimer();
    stopWeeklyTasksTimer();
  }
  if (page !== "admin") {
    stopAdminGamePanelTimer();
    stopAdminBroadcastPolling();
    stopAdminComplaintsPolling();
  }
  if (page === "coins" && !skipPageLoad) {
    updateCoinsTileBadges();
    refreshTopStatusFromFilters();
    loadWeeklyTasks();
    loadReferrals();
    updateVipPage();
    loadActivityHistoryPreview();
  }
  if (page === "coins-promotion") {
    refreshTopStatusFromFilters();
  }
  if (page === "coins-chests") {
    applyChestCaseUi(stateChest.caseType || "battle");
    loadChestsMeta();
    syncCaseOpenHud();
  }
  if (page === "coins-tasks") {
    loadWeeklyTasks();
  }
  if (page === "coins-vip") {
    updateVipPage();
  }
  if (page === "coins-referrals") {
    loadWeeklyTasks();
    loadReferrals();
  }
  if (page === "coins-favorites") {
    loadFavorites();
  }
  if (page === "capture") {
    if (typeof preloadCaptureImages === "function") preloadCaptureImages();
    if (prevPage !== "capture") {
      startCaptureAmbience();
    }
  }
  if (page === "profile") {
    setProfileSectionTab(stateProfile.sectionTab || "stats", {
      force: true,
      persist: false,
      triggerLoad: !skipPageLoad,
    });
    if (options.rootGate !== true && !isRootPageReady("profile")) {
      void gateProfileEntryFirstPaint(options);
    }
  }
  if (page === "coins-shop") {
    // a fresh visit starts with nothing tried on
    stateShop.pending = {};
    stateShop.selected = {};
    stateShop.tryOnPreview = {};
    stateShop.shopPreviewMode = "profile";
    if (elements.shopTabs) {
      elements.shopTabs.querySelectorAll(".shop-tab[data-shop-preview]").forEach((btn) => {
        btn.classList.toggle("active", String(btn.dataset.shopPreview || "") === "profile");
      });
    }
    if (elements.shopPreviewProfileView) {
      elements.shopPreviewProfileView.hidden = false;
    }
    if (elements.shopPreviewCardView) {
      elements.shopPreviewCardView.hidden = true;
    }
    const shopProfileCustomize = document.getElementById("shopProfileCustomize");
    if (shopProfileCustomize) {
      shopProfileCustomize.hidden = false;
    }
    try {
      localStorage.setItem(SHOP_PREVIEW_MODE_KEY, "profile");
    } catch {
      // ignore
    }
    returnShopSectionsToShopPage();
    loadShop();
  }
  if (page === "coins-history") {
    loadMcoinHistory();
  }
  if (page === "coins-packs") {
    loadMcoinPacks();
  }
  if (page === "coins-inventory") {
    renderInventoryPanel();
  }
  if (page === "coins-promocodes" && elements.promoCodeHint) {
    elements.promoCodeHint.textContent = "Код можно активировать только один раз.";
  }
  if (page === "leaderboard") {
    loadLeaderboardPage();
  }
  if (page === "deal-chat") {
    scheduleDealChatPolling();
  }
  if (page === "conversations" && !skipPageLoad) {
    loadConversations({ silent: true });
  }
  if (page === "profile-report") {
    openTradeReport();
  }
  if (!skipPageLoad && (
    page === "profile" ||
    page === "profile-stats" ||
    page === "edit-profile" ||
    page === "coins" ||
    String(page || "").startsWith("coins-")
  )) {
    Promise.resolve(loadProfile({ full: true })).catch(() => {});
  }
  if (page === "admin" && stateAdmin.tab === "complaints") {
    loadAdminComplaints();
    startAdminComplaintsPolling();
  }
  refreshLiveMcoinBalanceNow();
  if (animate) runPageSwipeAnimation(page, pageTransitionDirection);
  syncTelegramBackButton();
  syncAndroidBackButton();
  const shouldRestoreCoinsScroll =
    String(page || "").startsWith("coins-") || (isCoinsPage(prevPage) && page === "coins");
  if (shouldRestoreCoinsScroll) {
    const targetScrollY = Math.max(0, Number(coinsScrollByPage.get(page) || 0));
    window.requestAnimationFrame(() => {
      window.scrollTo({ top: targetScrollY, behavior: "auto" });
    });
  }
}

function syncGamesTabUi(page = state.page) {
  const current = String(page || "");
  document.querySelectorAll("[data-games-root]").forEach((button) => {
    button.classList.remove("active");
    button.setAttribute("aria-selected", "false");
  });
  document.querySelectorAll("[data-games-tab]").forEach((button) => {
    const isActive = String(button.getAttribute("data-games-tab") || "") === current;
    button.classList.toggle("active", isActive);
    button.setAttribute("aria-selected", isActive ? "true" : "false");
  });
  document.querySelectorAll("[data-games-nav]").forEach((button) => {
    const isActive = String(button.getAttribute("data-games-nav") || "") === current;
    button.classList.toggle("active", isActive);
    button.setAttribute("aria-selected", isActive ? "true" : "false");
  });
}

async function openGamesTab(page) {
  const target = String(page || "").trim();
  if (!isUiPageEnabled(target)) {
    await openRootTab("market");
    return;
  }
  if (!["rating", "capture", "tournament", "club"].includes(target)) return;
  gamesLastPage = target;
  setActivePage(target);
  window.requestAnimationFrame(() => {
    window.scrollTo({ top: 0, behavior: "auto" });
  });
  await loadGamesPageData(target);
}

function enableTapFeedback() {
  const activeClass = "tap-active";
  const pressableSelector = [
    "button",
    ".pill",
    ".server-btn",
    ".settings-item",
    ".nav-btn",
    ".listing-item",
    ".icon-btn",
    ".chip-btn",
    ".action-btn",
    ".ghost-btn",
  ].join(", ");

  const addActive = (target) => {
    if (!target || !target.classList) return;
    if (target.disabled) return;
    target.classList.add(activeClass);
  };

  const clearActive = (target) => {
    if (!target || !target.classList) return;
    target.classList.remove(activeClass);
  };

  document.addEventListener("pointerdown", (event) => {
    const target = event.target.closest(pressableSelector);
    addActive(target);
  });

  document.addEventListener("pointerup", (event) => {
    const target = event.target.closest(`.${activeClass}`);
    clearActive(target);
  });

  document.addEventListener("pointercancel", (event) => {
    const target = event.target.closest(`.${activeClass}`);
    clearActive(target);
  });

  document.addEventListener("touchmove", (event) => {
    const target = event.target.closest(`.${activeClass}`);
    clearActive(target);
  });
}

let fabScrollState = { lastScrollY: 0, hiddenByScroll: false, hiddenAnchorY: 0 };
let keyboardRestoreTimer = null;
const uiLoadingTokens = new Set();
let uiLoaderEl = null;
let uiLoaderHideTimer = null;

function isTextEntryElement(target) {
  if (!(target instanceof HTMLElement)) return false;
  if (target.isContentEditable) return true;
  const tag = target.tagName;
  if (tag === "TEXTAREA") return true;
  if (tag !== "INPUT") return false;
  const type = String(target.getAttribute("type") || "text").toLowerCase();
  const textTypes = new Set([
    "text",
    "search",
    "email",
    "url",
    "tel",
    "number",
    "password",
  ]);
  return textTypes.has(type);
}

function setKeyboardOpenState(isOpen) {
  document.body.classList.toggle("keyboard-open", Boolean(isOpen));
}

function ensureUiLoader() {
  if (uiLoaderEl) return uiLoaderEl;
  const booted = document.getElementById("uiBootLoader");
  if (booted) {
    uiLoaderEl = booted;
    return booted;
  }
  const el = document.createElement("div");
  el.className = "ui-loader-overlay";
  el.innerHTML = `
    <div class="ui-loader-card">
      <div class="ui-loader-spinner" aria-hidden="true"></div>
      <div class="ui-loader-title">Загружаем маркет...</div>
      <div class="ui-loader-sub">Почти готово</div>
    </div>
  `;
  document.body.appendChild(el);
  uiLoaderEl = el;
  return el;
}

function beginUiLoading(title = "Загружаем...", subtitle = "Почти готово") {
  const token = Symbol("ui-loading");
  uiLoadingTokens.add(token);
  const loader = ensureUiLoader();
  const titleEl = loader.querySelector(".ui-loader-title");
  const subEl = loader.querySelector(".ui-loader-sub");
  if (titleEl) titleEl.textContent = title;
  if (subEl) subEl.textContent = subtitle;
  if (uiLoaderHideTimer) {
    clearTimeout(uiLoaderHideTimer);
    uiLoaderHideTimer = null;
  }
  loader.classList.add("show");
  document.body.classList.remove("ui-loading-exit");
  document.body.classList.add("ui-loading");
  return token;
}

function endUiLoading(token) {
  if (token && uiLoadingTokens.has(token)) {
    uiLoadingTokens.delete(token);
  }
  if (uiLoadingTokens.size > 0) return;
  const loader = uiLoaderEl;
  if (!loader) return;
  if (uiLoaderHideTimer) clearTimeout(uiLoaderHideTimer);
  uiLoaderHideTimer = setTimeout(() => {
    // The navbar returns instantly underneath the still-opaque overlay, so the
    // overlay fade reveals a finished glass bar instead of a half-faded one.
    document.body.classList.add("ui-loading-exit");
    loader.classList.remove("show");
    document.body.classList.remove("ui-loading");
    const onFadeEnd = (event) => {
      if (event.target !== loader) return;
      loader.removeEventListener("transitionend", onFadeEnd);
      document.body.classList.remove("ui-loading-exit");
    };
    loader.addEventListener("transitionend", onFadeEnd);
  }, 120);
}

function syncKeyboardOpenStateFromActiveElement() {
  setKeyboardOpenState(isTextEntryElement(document.activeElement));
}

function initKeyboardAwareBottomBar() {
  document.addEventListener(
    "focusin",
    (event) => {
      if (isTextEntryElement(event.target)) {
        if (keyboardRestoreTimer) {
          clearTimeout(keyboardRestoreTimer);
          keyboardRestoreTimer = null;
        }
        setKeyboardOpenState(true);
      }
    },
    true,
  );

  document.addEventListener(
    "focusout",
    () => {
      if (keyboardRestoreTimer) clearTimeout(keyboardRestoreTimer);
      keyboardRestoreTimer = setTimeout(() => {
        syncKeyboardOpenStateFromActiveElement();
      }, 120);
    },
    true,
  );

  if (window.visualViewport) {
    window.visualViewport.addEventListener("resize", () => {
      const activeIsText = isTextEntryElement(document.activeElement);
      if (activeIsText) {
        setKeyboardOpenState(true);
        return;
      }
      const ratio = window.visualViewport.height / Math.max(window.innerHeight, 1);
      if (ratio > 0.9) setKeyboardOpenState(false);
    });
  }
}

function syncActionBarMetrics(page = state.page) {
  const mainActionBar = document.getElementById("mainActionBar");
  const gamesActionBar = document.getElementById("gamesActionBar");

  // Always seed --nav-count on both bars (even the hidden one) so the
  // .action-bar:not([style*="--nav-count"]) ~ #createFab rule doesn't
  // hide the floating "Меню" button when the user hasn't visited the
  // games tab yet.
  if (mainActionBar && !mainActionBar.style.getPropertyValue("--nav-count")) {
    const initialMainGroup = mainActionBar.querySelectorAll(".nav-group [data-nav]:not(.feature-ui-hidden)").length;
    mainActionBar.style.setProperty("--nav-count", String(initialMainGroup || 3));
    mainActionBar.style.setProperty("--nav-index", "0");
  }
  if (gamesActionBar && !gamesActionBar.style.getPropertyValue("--nav-count")) {
    const initialGamesGroup = gamesActionBar.querySelectorAll(".nav-group [data-games-nav]:not(.feature-ui-hidden)").length;
    gamesActionBar.style.setProperty("--nav-count", String(initialGamesGroup || 3));
    gamesActionBar.style.setProperty("--nav-index", "0");
  }

  if (isGamesPage(page)) {
    if (!gamesActionBar) return;
    const groupButtons = Array.from(
      gamesActionBar.querySelectorAll(".nav-group [data-games-nav]:not(.feature-ui-hidden), .nav-group [data-games-root]:not(.feature-ui-hidden)"),
    );
    if (!groupButtons.length) return;
    const activeIndex = groupButtons.findIndex((btn) => btn.dataset.gamesNav === page);
    gamesActionBar.style.setProperty("--nav-count", String(groupButtons.length));
    gamesActionBar.style.setProperty("--nav-index", String(activeIndex >= 0 ? activeIndex : 0));
    gamesActionBar.classList.toggle("nav-side-active", activeIndex < 0);
    return;
  }
  if (!mainActionBar) return;
  const groupButtons = Array.from(mainActionBar.querySelectorAll(".nav-group [data-nav]:not(.feature-ui-hidden)"));
  const fallbackButtons = Array.from(elements.navButtons || []).filter((button) => !button.classList.contains("feature-ui-hidden"));
  const buttons = groupButtons.length ? groupButtons : fallbackButtons;
  if (!buttons.length) return;
  const activeRoot = getActiveRootForPage(page);
  const activeIndex = buttons.findIndex((btn) => btn.dataset.nav === activeRoot);
  mainActionBar.style.setProperty("--nav-count", String(buttons.length));
  mainActionBar.style.setProperty("--nav-index", String(activeIndex >= 0 ? activeIndex : 0));
  mainActionBar.classList.toggle("nav-side-active", groupButtons.length ? activeIndex < 0 : false);
}

function updateFabVisibility() {
  const isProfileSupport = state.page === "profile";
  const modalOpen = Boolean(document.querySelector(".modal.show"));
  const isCoins = state.page === "coins" || String(state.page || "").startsWith("coins-");
  const isChatPage = state.page === "deal-chat" || state.page === "conversations";
  const scrollHiddenOnMarket = state.page === "market" && fabScrollState.hiddenByScroll;
  const shouldHide =
    state.page === "capture" ||
    state.page === "rating" ||
    state.page === "tournament" ||
    state.page === "club" ||
    state.page === "leaderboard" ||
    state.page === "listing" ||
    state.page === "create" ||
    state.page === "admin" ||
    state.page === "case-open" ||
    state.page === "nickname" ||
    state.page === "public-profile" ||
    isChatPage ||
    modalOpen ||
    isCoins ||
    scrollHiddenOnMarket;
  if (elements.createFab) {
    elements.createFab.classList.toggle("is-hidden", shouldHide);
    elements.createFab.setAttribute("aria-label", isProfileSupport ? "Поддержка" : "Создать объявление");
  }
  if (elements.chatFab) {
    elements.chatFab.classList.toggle("is-hidden", shouldHide || isProfileSupport);
  }
  if (elements.createFabPlus) {
    elements.createFabPlus.classList.toggle("hidden", isProfileSupport);
  }
  if (elements.createFabSupport) {
    elements.createFabSupport.classList.toggle("hidden", !isProfileSupport);
  }
  if (elements.createFabSupportBadge) {
    elements.createFabSupportBadge.classList.toggle("hidden", !isProfileSupport || elements.createFabSupportBadge.hidden);
  }
  document.body.classList.toggle("modal-open", modalOpen);
  updateMarketScrollChrome();
}

function updateMarketScrollChrome() {
  const onMarket = state.page === "market";
  const scrollY = window.scrollY || 0;
  const hideOnCreate = state.page === "create";
  const hideBottomBar = hideOnCreate || (onMarket && fabScrollState.hiddenByScroll && scrollY > 100);
  const showScrollTop = onMarket && fabScrollState.hiddenByScroll && scrollY > 260;
  if (elements.actionBar) {
    elements.actionBar.classList.toggle("is-scroll-hidden", hideBottomBar);
  }
  if (elements.marketScrollTop) {
    elements.marketScrollTop.classList.toggle("is-visible", showScrollTop);
  }
}

function initFabScrollBehavior() {
  if (!elements.createFab && !elements.actionBar && !elements.marketScrollTop) return;
  let ticking = false;
  window.addEventListener("scroll", () => {
    if (!ticking) {
      window.requestAnimationFrame(() => {
        const currentScrollY = window.scrollY;
        const delta = currentScrollY - fabScrollState.lastScrollY;
        if (delta > 10 && currentScrollY > 100) {
          if (!fabScrollState.hiddenByScroll) {
            fabScrollState.hiddenByScroll = true;
            fabScrollState.hiddenAnchorY = currentScrollY;
            updateFabVisibility();
          } else {
            fabScrollState.hiddenAnchorY = Math.max(fabScrollState.hiddenAnchorY || 0, currentScrollY);
          }
        } else if (delta < -10 || currentScrollY < 50) {
          if (fabScrollState.hiddenByScroll) {
            const anchorY = Math.max(fabScrollState.hiddenAnchorY || 0, currentScrollY);
            const revealDistance = Math.max(0, anchorY - currentScrollY);
            if (currentScrollY < 60 || revealDistance > 220) {
              fabScrollState.hiddenByScroll = false;
              fabScrollState.hiddenAnchorY = currentScrollY;
              updateFabVisibility();
            }
          } else if (currentScrollY < 50) {
            fabScrollState.hiddenByScroll = false;
            fabScrollState.hiddenAnchorY = currentScrollY;
            updateFabVisibility();
          }
        }
        updateMarketScrollChrome();
        fabScrollState.lastScrollY = currentScrollY;
        ticking = false;
      });
      ticking = true;
    }
  }, { passive: true });
}

function updateCoinsTileBadges() {
  if (elements.coinChestBadge) {
    elements.coinChestBadge.textContent = String(stateCoins.chestCost || 60);
  }
  if (elements.coinPromoBadge) {
    const slotsText = stateCoins.topSlotsText || "—/5";
    // "0/5" alone says nothing: name the unit once the number is known.
    elements.coinPromoBadge.textContent = /^\d/.test(slotsText) ? `${slotsText} слотов` : slotsText;
  }
  if (elements.coinTasksBadge) {
    const value = Number(stateCoins.tasksClaimableSum || 0);
    elements.coinTasksBadge.textContent = value > 0 ? `+${value}` : "0";
    elements.coinTasksBadge.hidden = value <= 0;
  }
  if (elements.coinReferralsBadge) {
    const pending = stateCoins.referralsPending;
    elements.coinReferralsBadge.textContent =
      pending === null || pending === undefined ? "—" : String(pending);
  }
  if (elements.coinFavoritesBadge) {
    const count = Number(stateCoins.favoritesCount || 0);
    elements.coinFavoritesBadge.textContent = String(count);
    elements.coinFavoritesBadge.hidden = count <= 0;
  }
  if (elements.coinInventoryBadge) {
    const count = Number(stateCoins.inventoryCount || 0);
    elements.coinInventoryBadge.textContent = `${count} шт.`;
    elements.coinInventoryBadge.hidden = count <= 0;
  }
}

function renderInventoryPanel() {
  const activeTab = stateCoins.inventoryTab === "coupons" ? "coupons" : "cards";
  stateCoins.inventoryTab = activeTab;
  if (elements.inventoryTabCoupons) {
    const active = activeTab === "coupons";
    elements.inventoryTabCoupons.classList.toggle("active", active);
    elements.inventoryTabCoupons.setAttribute("aria-selected", active ? "true" : "false");
  }
  if (elements.inventoryTabCards) {
    const active = activeTab === "cards";
    elements.inventoryTabCards.classList.toggle("active", active);
    elements.inventoryTabCards.setAttribute("aria-selected", active ? "true" : "false");
  }
  if (elements.inventoryEmptyTitle) {
    elements.inventoryEmptyTitle.textContent =
      activeTab === "coupons"
        ? "Пока нет купонов в инвентаре"
        : "Пока нет карточек в инвентаре";
  }
  if (elements.inventoryEmptySubtitle) {
    elements.inventoryEmptySubtitle.textContent =
      activeTab === "coupons"
        ? "Забирай купоны в активностях и специальных событиях."
        : "Открывай кейсы и выполняй активности, чтобы пополнить инвентарь.";
  }
  const listEl = elements.inventoryItemsList;
  const emptyEl = elements.inventoryEmptyState;
  if (!listEl || !emptyEl) return;
  listEl.innerHTML = "";
  const coupons = Array.isArray(stateCoins.couponInventory)
    ? stateCoins.couponInventory.filter((item) => Math.max(0, Number(item?.qty || 0)) > 0)
    : [];
  const cards = Array.isArray(stateCoins.cardInventory)
    ? stateCoins.cardInventory.filter((item) => Math.max(0, Number(item?.qty || 0)) > 0)
    : [];
  if (activeTab === "cards" && !cards.length && coupons.length) {
    stateCoins.inventoryTab = "coupons";
    return renderInventoryPanel();
  }
  if (activeTab === "coupons" && !coupons.length && cards.length) {
    stateCoins.inventoryTab = "cards";
    return renderInventoryPanel();
  }
  const list = activeTab === "coupons" ? coupons : cards;
  if (!list.length) {
    if (!stateProfile.fullLoaded && Number(stateCoins.inventoryCount || 0) > 0) {
      if (elements.inventoryEmptyTitle) {
        elements.inventoryEmptyTitle.textContent = "Загружаем инвентарь";
      }
      if (elements.inventoryEmptySubtitle) {
        elements.inventoryEmptySubtitle.textContent = "Предметы найдены, подгружаем содержимое.";
      }
    }
    emptyEl.hidden = false;
    listEl.hidden = true;
    return;
  }
  emptyEl.hidden = true;
  listEl.hidden = false;
  if (activeTab === "coupons") {
    listEl.className = "inventory-list is-coupons";
    list.forEach((item) => {
      const qty = Math.max(0, Number(item?.qty || 0));
      const active = Boolean(item?.active);
      const canUse = Boolean(item?.can_use) && qty > 0;
      const activeText = getInventoryCouponActiveText(item);
      const effect = getCouponEffectByCouponId(item?.id);
      const effectExpiresMsk = String(effect?.expires_at_msk || "");
      const iconMarkup = rewardVisualMarkup(item) || "🎟️";
      const card = document.createElement("div");
      card.className = `inv-coupon-card${active ? " is-active" : ""}`;
      card.innerHTML = `
        <div class="inv-coupon-qty">×${qty}</div>
        <div class="inv-coupon-icon">${iconMarkup}</div>
        <div class="inv-coupon-title">${item?.title || "Купон"}</div>
        <div class="inv-coupon-desc">${item?.subtitle || ""}</div>
        ${activeText ? `<div class="inv-coupon-active-text"${effectExpiresMsk ? ` data-coupon-active-text data-coupon-id="${String(item?.id || "").replace(/"/g, "&quot;")}" data-expires-msk="${String(effectExpiresMsk).replace(/"/g, "&quot;")}"` : ""}>${activeText}</div>` : ""}
        <button class="inv-coupon-btn${active ? " is-active" : ""}" type="button" data-coupon-use="${item?.id || ""}" ${canUse && !active ? "" : "disabled"}>
          ${active ? "Активен" : "Активировать"}
        </button>
      `;
      listEl.appendChild(card);
    });
  } else {
    listEl.className = "inventory-list is-cards";
    list.forEach((item) => {
      const qty = Math.max(0, Number(item?.qty || 0));
      const iconMarkup = rewardVisualMarkup(item) || "🎴";
      const rarityClass = rewardRarityClass(item);
      const rarityLabel =
        rarityClass === "is-legend"
          ? "Легендарная"
          : rarityClass === "is-epic"
            ? "Эпическая"
            : rarityClass === "is-rare"
              ? "Редкая"
              : "Обычная";
      const card = document.createElement("div");
      card.className = `inv-coupon-card inv-card-card ${rarityClass}`;
      card.innerHTML = `
        <div class="inv-coupon-qty">×${qty}</div>
        <div class="inv-coupon-icon">${iconMarkup}</div>
        <div class="inv-coupon-title">${item?.title || "Карточка"}</div>
        <div class="inv-coupon-desc inv-card-desc">${item?.subtitle || "Выпало из кейса"}</div>
        <div class="inv-card-meta">
          <span class="inv-card-rarity-chip">${rarityLabel}</span>
          <span class="inv-card-source">Кейс</span>
        </div>
      `;
      listEl.appendChild(card);
    });
  }
  syncInventoryCouponLiveTimer();
}
function parseMskIsoToMs(value) {
  const raw = String(value || "").trim();
  const m = raw.match(/^(\d{4})-(\d{2})-(\d{2})[T\s](\d{2}):(\d{2})(?::(\d{2}))?$/);
  if (!m) return NaN;
  const y = Number(m[1]);
  const mo = Number(m[2]) - 1;
  const d = Number(m[3]);
  const hMsk = Number(m[4]);
  const mi = Number(m[5]);
  const s = Number(m[6] || 0);
  return Date.UTC(y, mo, d, hMsk - 3, mi, s);
}

function formatCouponCountdown(msLeft) {
  const total = Math.max(0, Math.floor(msLeft / 1000));
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  if (h > 0) return `Активен еще ${h}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
  return `Активен еще ${m}:${String(s).padStart(2, "0")}`;
}

function getCouponEffectByCouponId(couponId) {
  const id = String(couponId || "").trim();
  if (!id) return null;
  const effects = Array.isArray(stateCoins.couponEffects) ? stateCoins.couponEffects : [];
  return effects.find((e) => String(e?.effect_key || "").trim() === id) || null;
}

function getInventoryCouponActiveText(item) {
  const fallback = String(item?.active_text || "");
  if (!item?.active) return fallback;
  const effect = getCouponEffectByCouponId(item?.id);
  if (!effect) return fallback;
  const expiresMsk = String(effect?.expires_at_msk || "");
  if (expiresMsk) {
    const endsMs = parseMskIsoToMs(expiresMsk);
    if (Number.isFinite(endsMs)) {
      const left = endsMs - Date.now();
      if (left > 0) return formatCouponCountdown(left);
    }
  }
  const chargesLeft = Number(effect?.charges_left || 0);
  if (chargesLeft > 0) return `Зарядов: ${chargesLeft}`;
  return fallback || "Активен";
}

function updateInventoryCouponLiveTimers() {
  const listEl = elements.inventoryItemsList;
  if (!listEl || listEl.hidden) return;
  if (stateCoins.inventoryTab !== "coupons") return;
  const nodes = listEl.querySelectorAll("[data-coupon-active-text][data-expires-msk]");
  if (!nodes.length) return;
  const nowMs = Date.now();
  nodes.forEach((node) => {
    const expiresMsk = String(node.getAttribute("data-expires-msk") || "");
    const endsMs = parseMskIsoToMs(expiresMsk);
    if (!Number.isFinite(endsMs)) return;
    const left = endsMs - nowMs;
    if (left <= 0) {
      node.textContent = "Истекает...";
      return;
    }
    node.textContent = formatCouponCountdown(left);
  });
}

function syncInventoryCouponLiveTimer() {
  const shouldRun = Boolean(
    elements.inventoryItemsList &&
    !elements.inventoryItemsList.hidden &&
    stateCoins.inventoryTab === "coupons" &&
    elements.inventoryItemsList.querySelector("[data-coupon-active-text][data-expires-msk]")
  );
  if (shouldRun) {
    updateInventoryCouponLiveTimers();
    if (!inventoryCouponLiveTimer) {
      inventoryCouponLiveTimer = setInterval(updateInventoryCouponLiveTimers, 1000);
    }
    return;
  }
  if (inventoryCouponLiveTimer) {
    clearInterval(inventoryCouponLiveTimer);
    inventoryCouponLiveTimer = null;
  }
}

function setInventoryTab(tab) {
  stateCoins.inventoryTab = tab === "coupons" ? "coupons" : "cards";
  renderInventoryPanel();
}

