function showError(message) {
  console.error(message);
}

function guardRapidClicks(event) {
  const pressable = event.target.closest("button, .conversations-item[role='button']");
  if (!pressable) return;
  // Root navigation is an idempotent state change and must remain responsive
  // while the user switches tabs quickly. Keep the debounce for mutating and
  // dialog actions, where a duplicate click can submit the same action twice.
  if (pressable.matches("[data-nav], [data-games-root], [data-games-nav]")) return;
  const now = Date.now();
  const last = Number(pressable.dataset.lastClickAt || 0);
  if (now - last < 450) {
    event.preventDefault();
    event.stopPropagation();
    return;
  }
  pressable.dataset.lastClickAt = String(now);
}

