async function copyListingLinkById(listingId) {
  let link = `${window.location.origin}/?listing=${Number(listingId)}`;
  try {
    const detail = await apiRequest(withAuth(`/api/listings/${Number(listingId)}`));
    if (detail && detail.share_url) link = String(detail.share_url);
  } catch {
    // the plain link still works
  }
  await copyListingLink(link);
}

function buildMarketCard(item, favorites, onToggleFavorite) {
  const topScopeActive = Boolean(stateFilters.serverId);
  const showTop =
    topScopeActive &&
    Boolean(item.is_top) &&
    String(item.server_id || "") === String(stateFilters.serverId || "");
  const createdAtMs = parseTopUntilMs(item.created_at);
  const isNew = Number.isFinite(createdAtMs) && Date.now() - createdAtMs <= 24 * 60 * 60 * 1000;
  const listingType = item?.listing_type === "buy" ? "buy" : "sell";
  const listingTypeLabel = listingType === "buy" ? "Куплю" : "Продам";
  const card = document.createElement("div");
  card.className = `market-card market-card--compact market-card--${listingType}${showTop ? " market-card--top" : ""}`;
  card.dataset.listingId = String(item.id);
  
  const topRemaining = showTop ? (item.top_remaining || formatTopRemaining(item.top_until)) : "";
  const topBadge = showTop ? `<div class="market-card-top-badge">TOP${topRemaining ? ` · ${topRemaining}` : ""}</div>` : "";
  const newBadge = !showTop && isNew ? `<div class="market-card-top-badge market-card-top-badge--new">NEW</div>` : "";
  
  const isFavorite = favorites.has(Number(item.id));
  const categoryLabel = String(item.category || "—");
  const serverNum = Number(item.server_id);
  const serverLabel = Number.isFinite(serverNum) && serverNum > 0 ? String(serverNum) : "—";
  const listingHasImage = Number(item.has_image || 0) > 0;
  // own photo first; no photo at all: the picture of the catalog entry (car / skin); else the category cover below
  const previewImage = getSafeImageSrc(item.preview_image) || (!listingHasImage ? getSafeImageSrc(catalogPhotoUrl(item.catalog_item_id)) : "");
  const hasPreviewImage = Boolean(previewImage);
  const coverImage = CATEGORY_FALLBACK_COVERS[item.category] || "";
  const coverImageClass = !hasPreviewImage ? (CATEGORY_COVER_IMAGE_CLASSES[item.category] || "") : "";
  const imageSrc = hasPreviewImage ? previewImage : coverImage;
  const hasImage = Boolean(imageSrc);
  const shouldLazyLoadListingImage = listingHasImage && !hasPreviewImage;
  card.innerHTML = `
    <div class="market-card-thumb">
      <div class="market-card-thumb-skeleton"></div>
      ${
        hasImage
          ? `<img class="market-card-thumb-img${hasPreviewImage ? "" : " is-cover"}${coverImageClass ? ` ${coverImageClass}` : ""}"${
              hasImage ? ` src="${imageSrc}"` : ""
            } alt="" loading="lazy" decoding="async" />`
          : ""
      }
      <div class="market-card-thumb-fallback${!hasImage ? " is-visible" : ""}">
        <span class="market-card-thumb-fallback-label">${escapeHtmlText(categoryLabel)}</span>
      </div>
      ${topBadge || newBadge}
      <div class="market-card-type-badge market-card-type-badge--${listingType}">${listingTypeLabel}</div>
      <button class="market-card-fav market-card-thumb-fav${isFavorite ? " active" : ""}" data-action="favorite" type="button" aria-label="В избранное">
        <svg viewBox="0 0 24 24" fill="none">
          <path class="fav-heart-fill" d="M12 20.3l-1.02-.92c-3.7-3.26-6.16-5.43-6.16-8.45 0-2.24 1.76-3.9 3.92-3.9 1.22 0 2.4.57 3.26 1.56.86-.99 2.04-1.56 3.26-1.56 2.16 0 3.92 1.66 3.92 3.9 0 3.02-2.46 5.19-6.16 8.45L12 20.3z" fill="currentColor"/>
          <path class="fav-heart-outline" d="M12 20.3l-1.02-.92c-3.7-3.26-6.16-5.43-6.16-8.45 0-2.24 1.76-3.9 3.92-3.9 1.22 0 2.4.57 3.26 1.56.86-.99 2.04-1.56 3.26-1.56 2.16 0 3.92 1.66 3.92 3.9 0 3.02-2.46 5.19-6.16 8.45L12 20.3z" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/>
          <path d="M14.2 8.3c.62 0 1.12.12 1.58.4" stroke="rgba(255,255,255,0.75)" stroke-width="1.2" stroke-linecap="round"/>
        </svg>
      </button>
    </div>
    <div class="market-card-content">
      <div class="market-card-title">${escapeHtmlText(item.title)}</div>
      <div class="market-card-meta-line">Сервер ${serverLabel}${categoryLabel && categoryLabel !== "—" ? ` · ${escapeHtmlText(categoryLabel)}` : ""}</div>
      <div class="market-card-price-row">
        <div class="market-card-price-chip">
          <span class="market-card-price">${formatPrice(item.price)} ₽</span>
        </div>
      </div>
    </div>
  `;
  const thumb = card.querySelector(".market-card-thumb");
  const thumbImage = card.querySelector(".market-card-thumb-img");
  const thumbFallback = card.querySelector(".market-card-thumb-fallback");
  if (thumb && thumbImage) {
    const resolveThumb = (ok) => {
      if (!ok && thumbFallback) thumbFallback.classList.add("is-visible");
    };
    if (thumbImage.complete) {
      resolveThumb(Boolean(thumbImage.naturalWidth));
    } else {
      thumbImage.addEventListener("load", () => resolveThumb(true), { once: true });
      thumbImage.addEventListener("error", () => resolveThumb(false), { once: true });
    }
  }
  if (shouldLazyLoadListingImage && thumb && thumbImage) {
    let started = false;
    let settled = false;
    const startPreviewLoad = () => {
      if (started) return;
      started = true;
      enqueuePreviewLoad(async () => {
      let rawImage;
      try {
        rawImage = await getListingPreviewImage(item.id);
      } catch (error) {
        // Aborted (left Market): let the card be resumed when Market is shown again.
        started = false;
        throw error;
      }
      if (rawImage === null) {
        started = false;
        return;
      }
      settled = true;
      const realImage = getSafeImageSrc(rawImage);
      if (!realImage) {
        if (coverImage) {
          thumbImage.src = coverImage;
          thumbImage.classList.add("is-cover");
          if (thumbFallback) thumbFallback.classList.remove("is-visible");
          return;
        }
        if (thumbFallback) thumbFallback.classList.add("is-visible");
        return;
      }
      thumbImage.src = realImage;
      thumbImage.classList.remove("is-cover");
      thumbImage.addEventListener(
        "load",
        () => {
          if (thumbFallback) thumbFallback.classList.remove("is-visible");
        },
        { once: true }
      );
      thumbImage.addEventListener(
        "error",
        () => {
          if (coverImage) {
            thumbImage.src = coverImage;
            thumbImage.classList.add("is-cover");
            if (thumbFallback) thumbFallback.classList.remove("is-visible");
          } else if (thumbFallback) {
            thumbFallback.classList.add("is-visible");
          }
        },
        { once: true }
      );
      });
    };
    // Leaving Market resets the preview pipeline while its cards stay in the DOM;
    // resumeMarketPreviewLoads() re-arms every card that has not resolved yet.
    card.__marketPreviewResume = () => {
      if (settled) return;
      started = false;
      scheduleCardPreviewLoad(card, startPreviewLoad);
    };
    scheduleCardPreviewLoad(card, startPreviewLoad);
  }
  
  const favoriteBtn = card.querySelector("[data-action='favorite']");
  const toggleFavorite = () => {
    const id = Number(item.id);
    // Always toggle the CURRENT list: a background sync may have changed it since this card was built.
    const current = getFavoritesSet();
    if (current.has(id)) {
      current.delete(id);
      favoriteBtn?.classList.remove("active");
    } else {
      current.add(id);
      favoriteBtn?.classList.add("active");
    }
    saveFavoritesSet(current);
    if (typeof onToggleFavorite === "function") {
      onToggleFavorite(current);
    }
  };
  if (favoriteBtn) {
    favoriteBtn.addEventListener("click", (event) => {
      event.stopPropagation();
      toggleFavorite();
    });
  }
  // hold / right click on a card: the floating menu (never inside the listing page)
  attachLongPressMenu(card, () => {
    const id = Number(item.id);
    const isFavorite = getFavoritesSet().has(id);
    const isOwn = Number(item.seller_id || 0) > 0 && Number(item.seller_id) === Number(state.tid || 0);
    return [
      { label: "Поделиться", icon: ACTION_ICONS.share, run: () => shareListing(item) },
      { label: isFavorite ? "Убрать из избранного" : "В избранное", icon: ACTION_ICONS.heart, run: toggleFavorite },
      { label: "Скопировать ссылку", icon: ACTION_ICONS.link, run: () => copyListingLinkById(id) },
      isOwn ? null : { label: "Пожаловаться", icon: ACTION_ICONS.flag, run: () => openReportModal({ targetType: "listing", targetId: id, title: "Жалоба на объявление" }) },
    ];
  });
  card.addEventListener("click", () => {
    const backPage = state.page === "coins-favorites" ? "coins-favorites" : "market";
    loadListing(item.id, backPage, item);
  });
  return card;
}

function formatDateTime(value) {
  return formatDateTimeMsk(value);
}

function parseApiDate(value) {
  if (!value) return null;
  const raw = String(value).trim();
  if (!raw) return null;
  const normalized = /(?:Z|[+-]\d{2}:\d{2})$/.test(raw) ? raw : `${raw}Z`;
  const date = new Date(normalized);
  if (Number.isNaN(date.getTime())) return null;
  return date;
}

function formatDateTimeMsk(value) {
  if (!value) return "—";
  const date = parseApiDate(value);
  if (!date) return value;
  return date.toLocaleString("ru-RU", {
    timeZone: "Europe/Moscow",
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });
}

function formatConversationTime(value) {
  if (!value) return "—";
  const date = parseApiDate(value);
  if (!date) return "—";
  const now = new Date();
  const dayFmt = new Intl.DateTimeFormat("ru-RU", {
    timeZone: "Europe/Moscow",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  });
  const timeFmt = new Intl.DateTimeFormat("ru-RU", {
    timeZone: "Europe/Moscow",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });
  const dateKey = dayFmt.format(date);
  const nowKey = dayFmt.format(now);
  if (dateKey === nowKey) {
    return timeFmt.format(date);
  }
  const yesterday = new Date(now.getTime() - 86400000);
  if (dateKey === dayFmt.format(yesterday)) {
    return "Вчера";
  }
  const weekdayFmt = new Intl.DateTimeFormat("ru-RU", {
    timeZone: "Europe/Moscow",
    weekday: "short",
  });
  const dateParts = dayFmt.formatToParts(date);
  const nowParts = dayFmt.formatToParts(now);
  const dateUtc = Date.UTC(
    Number(dateParts.find((part) => part.type === "year")?.value || 0),
    Number(dateParts.find((part) => part.type === "month")?.value || 1) - 1,
    Number(dateParts.find((part) => part.type === "day")?.value || 1),
  );
  const nowUtc = Date.UTC(
    Number(nowParts.find((part) => part.type === "year")?.value || 0),
    Number(nowParts.find((part) => part.type === "month")?.value || 1) - 1,
    Number(nowParts.find((part) => part.type === "day")?.value || 1),
  );
  const diffDays = Math.floor((nowUtc - dateUtc) / 86400000);
  if (diffDays > 1 && diffDays < 7) {
    const weekday = weekdayFmt.format(date).replace(".", "");
    return weekday ? weekday.charAt(0).toUpperCase() + weekday.slice(1) : "—";
  }
  return date.toLocaleDateString("ru-RU", {
    timeZone: "Europe/Moscow",
    day: "2-digit",
    month: "2-digit",
  });
}

function appendConversationUnread(container, item) {
  if (!container) return;
  const unreadCount = Math.max(0, getChatUnreadCount(item));
  if (!unreadCount) return;
  const badge = document.createElement("span");
  badge.className = "conversations-item-unread";
  badge.textContent = unreadCount > 99 ? "99+" : String(unreadCount);
  container.appendChild(badge);
}

function applyConversationReadStateLocally(options = {}) {
  const items = Array.isArray(stateConversations.items) ? stateConversations.items : [];
  if (!items.length) return;
  const chatType = String(options.chatType || "");
  const listingId = Number(options.listingId || 0) || 0;
  const chatId = Number(options.chatId || 0) || 0;
  const roomId = Number(options.roomId || 0) || 0;
  let changed = false;
  stateConversations.items = items.map((item) => {
    if (!item || typeof item !== "object") return item;
    const itemType = String(item.chat_type || "");
    let match = false;
    if (chatType === "server_room") {
      match = itemType === "server_room" && Number(item.room_id || 0) === roomId;
    } else if (chatType === "listing") {
      match =
        itemType === "listing" &&
        (
          (chatId > 0 && Number(item.chat_id || 0) === chatId) ||
          (chatId <= 0 && listingId > 0 && Number(item.listing_id || 0) === listingId)
        );
    }
    if (!match) return item;
    if (getChatUnreadCount(item) <= 0) return item;
    changed = true;
    return { ...item, unread_count: 0, unread_messages: 0, unread: 0, has_unread: false, is_read: 1 };
  });
  if (!changed) return;
  stateConversations.chatUnread = getConversationsBadgeCount(stateConversations.items);
  syncConversationsBadge();
  if (state.page === "conversations") renderConversations();
}

function buildConversationPreviewText(item, options = {}) {
  const isSystemChat = Boolean(options.isSystemChat);
  const isServerRoomChat = Boolean(options.isServerRoomChat);
  const isSupportHubChat = Boolean(options.isSupportHubChat);
  const preview = String(item.last_message || "").trim();
  if (preview) return preview;
  if (isSystemChat) return "Системные сообщения появятся здесь.";
  if (isSupportHubChat) return "Свяжитесь с поддержкой RP Market";
  if (isServerRoomChat) return "Общий чат вашего сервера.";
  return "Сообщений пока нет.";
}

function formatConversationStatus(status) {
  switch (String(status || "").toLowerCase()) {
    case "pending":
      return "На проверке";
    case "in_review":
      return "В работе";
    case "accepted":
      return "Принято";
    case "rejected":
      return "Отклонено";
    case "pending_confirm":
      return "Ожидает подтверждения";
    case "confirmed":
      return "Подтверждена";
    case "cancelled":
      return "Отменена";
    case "expired":
      return "Просрочена";
    default:
      return "Открыта";
  }
}

function getConversationStatusClass(status) {
  switch (String(status || "").toLowerCase()) {
    case "pending":
      return "pending";
    case "in_review":
      return "open";
    case "accepted":
      return "confirmed";
    case "rejected":
      return "cancelled";
    case "pending_confirm":
      return "pending";
    case "confirmed":
      return "confirmed";
    case "cancelled":
      return "cancelled";
    case "expired":
      return "expired";
    default:
      return "open";
  }
}

// Unread counter on the "Чаты" tab of the bottom bar (absolutely positioned: the bar itself does not change).
let lastNavChatsBadgeCount = 0;
function updateNavChatsBadge(count) {
  const badge = document.getElementById("navChatsBadge");
  if (!badge) return;
  const safe = Math.max(0, Math.round(Number(count) || 0));
  const text = safe > 99 ? "99+" : String(safe);
  if (badge.textContent !== text) badge.textContent = text;
  badge.hidden = safe <= 0;
  const tab = badge.closest(".nav-btn");
  if (tab) tab.setAttribute("aria-label", safe > 0 ? `Чаты, непрочитанных: ${text}` : "Чаты");
  if (safe > lastNavChatsBadgeCount) {
    // a short pop when a new message arrives, not on every refresh
    badge.classList.remove("is-bump");
    void badge.offsetWidth;
    badge.classList.add("is-bump");
  }
  lastNavChatsBadgeCount = safe;
}

function updateConversationsBadge(count) {
  updateNavChatsBadge(count);
  // the same number sits on the "Сообщения" button of the radial menu
  const menuBadge = document.getElementById("settingsDialogsBadge");
  if (menuBadge) {
    const menuCount = Number(count || 0);
    menuBadge.textContent = menuCount > 99 ? "99+" : String(menuCount);
    menuBadge.hidden = menuCount <= 0;
  }
  if (!elements.profileDialogsCount) return;
  const safe = Number(count || 0);
  if (safe > 0) {
    elements.profileDialogsCount.textContent = safe > 99 ? "99+" : String(safe);
    elements.profileDialogsCount.classList.remove("hidden");
  } else {
    elements.profileDialogsCount.textContent = "0";
    elements.profileDialogsCount.classList.add("hidden");
  }
}

function getChatUnreadCount(item) {
  if (!item || typeof item !== "object") return 0;
  const numericKeys = [
    "unread_count",
    "unread_messages",
    "unread_messages_count",
    "unread_total",
    "unread_chats",
    "unread_dialogs",
    "dialogs_unread",
    "messages_unread",
    "new_messages_count",
    "new_messages",
    "unread",
  ];
  for (const key of numericKeys) {
    const raw = Number(item[key]);
    if (Number.isFinite(raw) && raw > 0) {
      return Math.max(0, Math.floor(raw));
    }
  }
  const boolKeys = ["has_unread", "is_unread", "has_new_messages", "new_message"];
  for (const key of boolKeys) {
    if (item[key] === true || item[key] === 1 || item[key] === "1") {
      return 1;
    }
  }
  const isReadValue = item.is_read;
  if (isReadValue === false || isReadValue === 0 || isReadValue === "0") {
    return 1;
  }
  return 0;
}

function getConversationsBadgeCount(items) {
  const rows = Array.isArray(items) ? items : [];
  return rows.reduce((sum, item) => {
    if (!item || String(item.chat_type || "") === "support") return sum;
    return sum + getChatUnreadCount(item);
  }, 0);
}

function getNotificationsUnreadCount(items) {
  const rows = Array.isArray(items) ? items : [];
  return rows.reduce((sum, item) => {
    if (!item || typeof item !== "object") return sum;
    if (item.is_read === 0 || item.is_read === false || String(item.status || "").toLowerCase() === "unread") {
      return sum + 1;
    }
    return sum;
  }, 0);
}

function resolveSystemInboxLatestNotification(items) {
  const rows = Array.isArray(items) ? items : [];
  if (!rows.length) return null;
  let latest = rows[0];
  let latestTs = parseApiDate(rows[0]?.created_at || rows[0]?.updated_at)?.getTime() || 0;
  rows.forEach((item) => {
    const ts = parseApiDate(item?.created_at || item?.updated_at)?.getTime() || 0;
    if (ts > latestTs) {
      latest = item;
      latestTs = ts;
    }
  });
  return latest || null;
}

function getSystemInboxUnreadCount() {
  return Math.max(0, Number(stateSystemInbox.unread || 0));
}

function getSupportHubUnreadCount() {
  return supportModeratorUnread ? 1 : 0;
}

function syncConversationsBadge() {
  const chatsUnread = Math.max(0, Number(stateConversations.chatUnread || 0));
  updateConversationsBadge(chatsUnread + getSystemInboxUnreadCount());
  _syncInboxBellBadge();
}

function formatSystemNotificationMessage(item) {
  const title = String(item?.title || "").trim();
  const text = String(item?.message || "").trim();
  if (title && text) return `${title}\n${text}`;
  return title || text || "Системное сообщение";
}

function buildSystemConversationItem() {
  const latest = resolveSystemInboxLatestNotification(stateSystemInbox.items) || stateSystemInbox.latest || null;
  const unread = getSystemInboxUnreadCount();
  return {
    chat_type: "system",
    title: "RP Market",
    counterpart_name: "RP Market",
    last_message: latest ? formatSystemNotificationMessage(latest).replace(/\s+/g, " ").trim() : "Системные сообщения от RP Market",
    last_message_at: latest?.created_at || latest?.updated_at || null,
    unread_count: unread,
    chat_status: unread > 0 ? "open" : "confirmed",
  };
}

function buildSupportConversationItem() {
  return {
    chat_type: "support_hub",
    title: "Техподдержка",
    counterpart_name: "Техподдержка",
    last_message: supportModeratorUnread ? "Есть новый ответ от модерации" : "Свяжитесь с поддержкой RP Market",
    last_message_at: null,
    unread_count: supportModeratorUnread ? 1 : 0,
    chat_status: supportModeratorUnread ? "open" : "confirmed",
  };
}

function resolveConversationsItems(payload) {
  if (Array.isArray(payload)) return payload;
  if (!payload || typeof payload !== "object") return [];
  if (Array.isArray(payload.items)) return payload.items;
  if (Array.isArray(payload.chats)) return payload.chats;
  if (Array.isArray(payload.rows)) return payload.rows;
  if (Array.isArray(payload.data?.items)) return payload.data.items;
  if (Array.isArray(payload.data?.chats)) return payload.data.chats;
  return [];
}

function generateOperationId() {
  return `op_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
}

function getRestrictionLabel(type) {
  switch (type) {
    case "publish_ban":
      return "Публикации";
    case "top_ban":
      return "ТОП";
    case "market_ban":
      return "Рынок";
    default:
      return "Ограничение";
  }
}

function getActiveRestriction(restrictions, types) {
  if (!Array.isArray(restrictions)) return null;
  return restrictions.find((item) => types.includes(item.type)) || null;
}

function restrictionNoticeText(restriction) {
  if (!restriction) return "";
  const until = restriction.expires_at ? `До ${formatDateTimeMsk(restriction.expires_at)}` : "Навсегда";
  return `Ограничение: ${getRestrictionLabel(restriction.type)}. ${until}. Причина: ${restriction.reason || "—"}`;
}

function getStatusView(status) {
  switch (status) {
    case "pending":
      return { text: "На модерации", className: "status-pending" };
    case "active":
      return { text: "Активно", className: "status-active" };
    case "awaiting_confirmation":
      return { text: "Ожидает подтверждения", className: "status-awaiting" };
    case "rejected":
      return { text: "Отклонено", className: "status-rejected" };
    case "hidden":
      return { text: "Скрыто", className: "status-archived" };
    case "expired":
      return { text: "Истёк срок", className: "status-archived" };
    case "sold":
      return { text: "Продано", className: "status-sold" };
    default:
      return { text: "Архив", className: "status-archived" };
  }
}

function getHiddenStatusText(item) {
  const role = normalizeStaffRoleKey(item?.hidden_by_role);
  if (role === "moderator" || role === "head_moderator" || role === "cofounder" || role === "developer") {
    return "Скрыто модератором";
  }
  if (role === "user") {
    return "Скрыто вами";
  }
  return "Скрыто";
}

function normalizeStaffRoleKey(role) {
  const normalized = String(role || "").trim().toLowerCase().replace(/[\s-]+/g, "_");
  if (!normalized) return "";
  if (normalized === "owner" || normalized === "superadmin" || normalized === "developer") return "developer";
  if (normalized === "cofounder" || normalized === "co_founder" || normalized === "founder" || normalized === "vice" || normalized === "deputy" || normalized === "сооснователь") return "cofounder";
  if (normalized === "head_moderator" || normalized === "chief_moderator" || normalized === "lead_moderator" || normalized === "senior_moderator" || normalized === "market_admin" || normalized === "gl_moderator" || normalized === "главный_модератор") return "head_moderator";
  if (normalized === "moderator" || normalized === "admin" || normalized === "administrator" || normalized === "mod") return "moderator";
  return normalized;
}

function isDeveloperRole(role) {
  return normalizeStaffRoleKey(role) === "developer";
}

function isCofounderRole(role) {
  return normalizeStaffRoleKey(role) === "cofounder";
}

function isHeadModeratorRole(role) {
  return normalizeStaffRoleKey(role) === "head_moderator";
}

function isModeratorRole(role) {
  const normalized = normalizeStaffRoleKey(role);
  return normalized === "moderator" || normalized === "head_moderator" || normalized === "cofounder" || normalized === "developer";
}

function canAccessAdminSystemTabs(role) {
  const normalized = normalizeStaffRoleKey(role);
  return normalized === "cofounder" || normalized === "developer";
}

function getStaffRoleLabel(role) {
  const normalized = normalizeStaffRoleKey(role);
  if (normalized === "developer") return "Разработчик";
  if (normalized === "cofounder") return "Сооснователь";
  if (normalized === "head_moderator") return "Администратор";
  if (normalized === "moderator") return "Модератор";
  return "";
}

function getStaffRoleSlotMeta(role, styleOverride = "") {
  const normalized = normalizeStaffRoleKey(role);
  const style = String(styleOverride || "").trim();
  if (normalized === "developer") {
    return { text: "РАЗРАБОТЧИК", style: style || "label_style_midnight", kind: "system-developer", system: true };
  }
  if (normalized === "cofounder") {
    return { text: "СООСНОВАТЕЛЬ", style: style || "label_style_ruby", kind: "system-cofounder", system: true };
  }
  if (normalized === "head_moderator") {
    return { text: "АДМИНИСТРАТОР", style: style || "label_style_ocean", kind: "system-head-moderator", system: true };
  }
  if (normalized === "moderator") {
    return { text: "МОДЕРАТОР", style: style || "label_style_ocean", kind: "system-moderator", system: true };
  }
  return null;
}

function firstNonEmptyString(...values) {
  for (const value of values) {
    const text = String(value ?? "").trim();
    if (text) return text;
  }
  return "";
}

function firstTruthyBool(...values) {
  for (const value of values) {
    if (value === true || value === 1) return true;
    if (typeof value === "string") {
      const normalized = value.trim().toLowerCase();
      if (normalized === "1" || normalized === "true" || normalized === "yes" || normalized === "on" || normalized === "active") {
        return true;
      }
    }
  }
  return false;
}

function normalizeSlotPayloadEntry(value) {
  if (value === null || value === undefined || value === false) return null;
  if (typeof value === "string") {
    const text = value.trim();
    return text ? { text } : null;
  }
  if (typeof value !== "object") return null;
  const text = firstNonEmptyString(value.text, value.title, value.label, value.value, value.name);
  const style = firstNonEmptyString(
    value.style,
    value.label_style,
    value.color_style,
    value.style_id,
    value.style_item,
    value.item_style,
    value.item_id
  );
  const active =
    value.active === undefined &&
    value.enabled === undefined &&
    value.visible === undefined &&
    value.unlocked === undefined
      ? true
      : firstTruthyBool(value.active, value.enabled, value.visible, value.unlocked);
  if (!text && !style) return null;
  return {
    text,
    style,
    active,
    kind: firstNonEmptyString(value.kind, value.type),
    system: firstTruthyBool(value.system, value.is_system),
  };
}

function resolveBadgeSlotsPayload(profile, cosmetics) {
  const slotBag = [
    profile?.badge_slots,
    profile?.label_slots,
    profile?.status_slots,
    profile?.slots,
    cosmetics?.badge_slots,
    cosmetics?.slots,
  ].find((entry) => entry && typeof entry === "object") || {};
  const main = normalizeSlotPayloadEntry(slotBag.main || slotBag.primary || slotBag.top || null);
  const secondary = normalizeSlotPayloadEntry(slotBag.secondary || slotBag.service || slotBag.lower || null);
  const territory = normalizeSlotPayloadEntry(slotBag.territory || slotBag.right || null);
  const vip = normalizeSlotPayloadEntry(slotBag.vip || slotBag.subscription || null);
  return { main, secondary, territory, vip };
}

function resolveVipSlot(profile, cosmetics, slotPayload = null) {
  return null;
}

function resolveBadgeSlotsForProfile(profile, cosmetics, options = {}) {
  const data = profile || {};
  const safeCosmetics = cosmetics || {};
  const payload = resolveBadgeSlotsPayload(data, safeCosmetics);

  const labelFromItem =
    getCosmeticLabelText(safeCosmetics.label) ||
    getShopLabelTextByItemId(safeCosmetics.label);
  const mainSlot = {
    text: firstNonEmptyString(
      payload.main?.text,
      options.forceLabelText,
      labelFromItem,
      safeCosmetics.label_text,
      options.fallbackLabel,
      "Новичок"
    ),
    style: firstNonEmptyString(
      options.forceLabelStyle,
      safeCosmetics.label_style,
      safeCosmetics.main_label_style,
      safeCosmetics.label_style_main,
      payload.main?.style,
      "default"
    ),
    kind: payload.main?.kind || "main",
    system: Boolean(payload.main?.system),
  };

  const staffStyleOverride = firstNonEmptyString(
    safeCosmetics.staff_label_style,
    safeCosmetics.label_style_staff
  );
  const staffSlot = getStaffRoleSlotMeta(data.staff_role, staffStyleOverride);
  const userSecondarySlot = {
    text: firstNonEmptyString(
      payload.secondary?.text,
      safeCosmetics.secondary_label_text,
      safeCosmetics.label_secondary_text,
      safeCosmetics.service_label_text,
      data.secondary_label,
      data.service_label
    ),
    style: firstNonEmptyString(
      safeCosmetics.secondary_label_style,
      safeCosmetics.service_label_style,
      safeCosmetics.label_style_secondary,
      safeCosmetics.label_style_2,
      payload.secondary?.style,
      "label_style_ocean"
    ),
    kind: payload.secondary?.kind || "secondary",
    system: Boolean(payload.secondary?.system),
  };

  const territorySystemText = isCaptureUiEnabled()
    ? firstNonEmptyString(data.capture_title, data.territory_title)
    : "";
  const territorySlot = {
    text: isCaptureUiEnabled()
      ? firstNonEmptyString(territorySystemText, payload.territory?.text)
      : "",
    style: firstNonEmptyString(
      safeCosmetics.territory_label_style,
      safeCosmetics.label_style_territory,
      payload.territory?.style,
      "label_style_goldrush"
    ),
    kind: payload.territory?.kind || "territory",
    system: isCaptureUiEnabled() && (Boolean(territorySystemText) || Boolean(payload.territory?.system)),
  };

  const vipSlot = resolveVipSlot(data, safeCosmetics, payload.vip);

  return {
    main: mainSlot,
    secondary: staffSlot || (userSecondarySlot.text ? userSecondarySlot : null),
    territory: territorySlot.text ? territorySlot : null,
    vip: vipSlot,
  };
}

function renderBadgeSlot(el, slot, defaultStyle = "default") {
  if (!el) return;
  const text = firstNonEmptyString(slot?.text);
  if (!text) {
    el.textContent = "";
    el.classList.add("hidden");
    el.removeAttribute("data-slot-kind");
    applyLabelStyle(el, defaultStyle);
    return;
  }
  el.classList.remove("hidden");
  applyRankBadge(el, text);
  applyLabelStyle(el, firstNonEmptyString(slot?.style, defaultStyle));
  if (slot?.kind) {
    el.setAttribute("data-slot-kind", String(slot.kind));
  } else {
    el.removeAttribute("data-slot-kind");
  }
  el.classList.toggle("badge-slot-system", Boolean(slot?.system));
}

function renderBadgeSlotsForContext({
  profile,
  cosmetics,
  fallbackLabel,
  forceLabelText,
  forceLabelStyle,
  mainEl,
  secondaryEl,
  territoryEl,
  vipEl,
} = {}) {
  const slots = resolveBadgeSlotsForProfile(profile, cosmetics, {
    fallbackLabel,
    forceLabelText,
    forceLabelStyle,
  });
  renderBadgeSlot(mainEl, slots.main, "default");
  renderBadgeSlot(secondaryEl, slots.secondary, "label_style_ocean");
  renderBadgeSlot(territoryEl, slots.territory, "label_style_goldrush");
  renderBadgeSlot(vipEl, slots.vip, "label_style_goldrush");

  const mainRow = mainEl?.closest?.(".profile-badge-slot-row");
  if (mainRow) {
    const hasVisible = [mainEl, territoryEl].some((el) => el && !el.classList.contains("hidden"));
    mainRow.classList.toggle("hidden", !hasVisible);
  }
  const extraRow = secondaryEl?.closest?.(".profile-badge-slot-row") || vipEl?.closest?.(".profile-badge-slot-row");
  if (extraRow) {
    const hasVisible = [secondaryEl, vipEl].some((el) => el && !el.classList.contains("hidden"));
    extraRow.classList.toggle("hidden", !hasVisible);
  }

  // Shop preview rows use a dedicated structure; keep empty rows collapsed.
  const shopMainRow = mainEl?.closest?.(".shop-profile-preview-badge-row--main");
  if (shopMainRow) {
    const hasTerritory = Boolean(territoryEl && !territoryEl.classList.contains("hidden"));
    shopMainRow.classList.toggle("is-single", !hasTerritory);
    const hasVisible = [mainEl, territoryEl].some((el) => el && !el.classList.contains("hidden"));
    shopMainRow.classList.toggle("hidden", !hasVisible);
  }
  const shopExtraRow = secondaryEl?.closest?.(".shop-profile-preview-badge-row--extra") || vipEl?.closest?.(".shop-profile-preview-badge-row--extra");
  if (shopExtraRow) {
    const hasVisible = [secondaryEl, vipEl].some((el) => el && !el.classList.contains("hidden"));
    shopExtraRow.classList.toggle("hidden", !hasVisible);
  }
}

function renderPremiumVipInlineBadge(el, profile, cosmetics = null) {
  if (!el) return;
  const isPremium = firstTruthyBool(
    profile?.vip_ultimate,
    profile?.vip_ultimate_active,
    profile?.subscription_ultimate?.active
  );
  if (!isPremium) {
    el.textContent = "";
    el.classList.add("hidden");
    el.classList.remove("uni-label--vip-crown");
    el.classList.remove("uni-label--vip-crown-only");
    el.removeAttribute("data-slot-kind");
    return;
  }
  el.classList.remove("hidden");
  el.classList.add("uni-label--vip-crown");
  el.classList.add("uni-label--vip-crown-only");
  el.innerHTML = '<span class="vip-inline-crown" aria-hidden="true"></span>';
  el.setAttribute("aria-label", "Премиум");
  applyLabelStyle(el, firstNonEmptyString(cosmetics?.label_style_vip, "label_style_goldrush"));
  el.setAttribute("data-slot-kind", "vip");
}

function updateStaffBadge(el, role) {
  if (!el) return;
  const label = getStaffRoleLabel(role);
  if (label) {
    el.classList.remove("hidden");
    el.setAttribute("data-role", role);
    el.setAttribute("data-role-label", label);
  } else {
    el.classList.add("hidden");
    el.removeAttribute("data-role");
    el.removeAttribute("data-role-label");
  }
  if (el.dataset.tooltipBound) return;
  el.dataset.tooltipBound = "true";
  el.addEventListener("click", (event) => {
    event.stopPropagation();
    const text = el.getAttribute("data-role-label");
    if (text) showToast(text, "info");
  });
}

