function isLabelStyleSlot(slot) {
  const normalized = String(slot || "").trim();
  return normalized === "label_style" || normalized.startsWith("label_style_");
}

function getSlotHumanTitle(slot) {
  const normalized = String(slot || "").trim();
  const suffix = normalized.replace(/^label_style_/, "");
  if (suffix === "secondary") return "Второй лейбл";
  if (suffix === "territory") return "Территория";
  if (suffix === "vip") return "VIP";
  if (suffix === "main") return "Основной";
  return normalized;
}

function getShopSlotMeta(slot) {
  const normalized = String(slot || "").trim();
  const known = SHOP_UI_SLOTS.find((item) => item.slot === normalized);
  if (known) return known;
  if (isLabelStyleSlot(normalized)) {
    return {
      slot: normalized,
      title: `Стиль: ${getSlotHumanTitle(normalized)}`,
      subtitle: "Градиент и оформление слота",
    };
  }
  return {
    slot: normalized,
    title: normalized,
    subtitle: "Настройка слота",
  };
}

function getShopTabMeta(slot) {
  const normalized = String(slot || "").trim();
  const known = SHOP_UI_TABS.find((item) => item.slot === normalized);
  if (known) return known;
  if (isLabelStyleSlot(normalized)) {
    return {
      slot: normalized,
      title: getSlotHumanTitle(normalized),
      icon: `<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="8" width="18" height="8" rx="4" stroke="currentColor" stroke-width="1.8" fill="none"/><circle cx="8" cy="12" r="1.3" fill="currentColor"/><circle cx="12" cy="12" r="1.3" fill="currentColor" opacity="0.55"/><circle cx="16" cy="12" r="1.3" fill="currentColor" opacity="0.35"/></svg>`,
    };
  }
  return {
    slot: normalized,
    title: normalized,
    icon: `<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="5" width="16" height="14" rx="3" stroke="currentColor" stroke-width="1.8" fill="none"/><path d="M8 12h8" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>`,
  };
}

const NICK_COLOR_PALETTES = [
  {
    id: "neon",
    title: "Неон",
    colors: ["#7C5CFF", "#4DA3FF", "#1FE6D1", "#FF4D8D", "#FFB340", "#B6FF3B", "#FF5C5C", "#8D5CFF", "#00D1FF", "#FFFFFF"],
  },
  {
    id: "pastel",
    title: "Пастель",
    colors: ["#F3D1FF", "#C7D6FF", "#BFF4FF", "#C7FFD6", "#FFF1B6", "#FFD1D1", "#E7C7FF", "#B6E3FF", "#D8FFC7", "#F7F3E6"],
  },
];

function nickColorItemId(hex) {
  const normalized = String(hex || "").trim().toUpperCase();
  if (!/^#[0-9A-F]{6}$/.test(normalized)) return "";
  return `nick_color_${normalized.slice(1)}`;
}

function shopShortName(item) {
  const raw = String(item?.title || "").trim();
  const idx = raw.indexOf(":");
  return idx >= 0 ? raw.slice(idx + 1).trim() : raw;
}

function ensureShopDefaults() {
  ensureShopUiState();
  if (!stateShop.selected.palette) stateShop.selected.palette = "neon";
}
function renderShopFlat(options = {}) {
  if (!elements.shopSections || !stateShop.data) return;
  const preserveScroll = Boolean(options?.preserveScroll);
  const scrollX = preserveScroll ? window.scrollX : 0;
  const scrollY = preserveScroll ? window.scrollY : 0;
  if (preserveScroll && document.activeElement instanceof HTMLElement) {
    document.activeElement.blur();
  }
  ensureShopDefaults();

  const data = stateShop.data;
  const list = Array.isArray(data.items) ? data.items : [];
  const active = data.active || {};
  const closedDeals = Number(data.closed_deals || 0);

  const itemsBySlot = new Map();
  list.forEach((item) => {
    const slot = String(item?.slot || "");
    if (!slot) return;
    if (!itemsBySlot.has(slot)) itemsBySlot.set(slot, []);
    itemsBySlot.get(slot).push(item);
  });

  const buildSection = (meta, bodyEl) => {
    const section = document.createElement("div");
    section.className = "store-section";
    section.dataset.shopSection = meta.slot;

    const head = document.createElement("div");
    head.className = "store-section-head";
    const headText = document.createElement("div");
    const title = document.createElement("div");
    title.className = "store-section-title";
    title.textContent = meta.title;
    const note = document.createElement("div");
    note.className = "store-section-note";
    note.textContent = meta.subtitle;
    headText.appendChild(title);
    headText.appendChild(note);

    const actions = document.createElement("div");
    actions.className = "store-section-head-actions";

    const removeBtn = document.createElement("button");
    removeBtn.type = "button";
    removeBtn.className = "store-reset-btn";
    removeBtn.textContent = "Снять";
    removeBtn.dataset.shopAction = "deactivate-slot";
    removeBtn.dataset.shopSlot = meta.slot;
    removeBtn.hidden = meta.slot === "nick_color"
      ? !String(data.active_color || "").trim()
      : !active[meta.slot];
    actions.appendChild(removeBtn);

    head.appendChild(headText);
    head.appendChild(actions);
    section.appendChild(head);
    section.appendChild(bodyEl);

    return section;
  };

  const buildNickColorSection = () => {
    const meta = getShopSlotMeta("nick_color");
    const wrap = document.createElement("div");

    const palette = String(stateShop.selected.palette || "neon");
    const paletteDef = NICK_COLOR_PALETTES.find((p) => p.id === palette) || NICK_COLOR_PALETTES[0];

    const palettePicker = document.createElement("div");
    palettePicker.className = "store-palette-tabs";
    NICK_COLOR_PALETTES.forEach((p) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = `pill store-palette-tab${p.id === paletteDef.id ? " active" : ""}`;
      btn.textContent = p.title;
      btn.dataset.shopSelect = "palette";
      btn.dataset.palette = p.id;
      palettePicker.appendChild(btn);
    });
    wrap.appendChild(palettePicker);

    const items = itemsBySlot.get("nick_color") || [];
    const statusByColor = new Map();
    const priceByColor = new Map();
    items.forEach((it) => {
      const color = String(it?.color || "").toUpperCase();
      if (!color) return;
      statusByColor.set(color, String(it?.status || "locked"));
      priceByColor.set(color, Number(it?.price || 0));
    });

    // highlight what is tried on (or worn); nothing is picked for the player and nothing is applied by a tap
    const selectedColor =
      String(stateShop.selected.nick_color || "").toUpperCase() ||
      String(data.active_color || "").toUpperCase();

    const vipShopAccess = canUseVipFreeShopAccess();
    const grid = document.createElement("div");
    grid.className = "store-color-grid";
    paletteDef.colors.forEach((hex) => {
      const normalized = String(hex).toUpperCase();
      const rawStatus = statusByColor.get(normalized) || "locked";
      const status = vipShopAccess && rawStatus === "locked" ? "owned" : rawStatus;
      const swatch = document.createElement("button");
      swatch.type = "button";
      swatch.className = `color-swatch${normalized === selectedColor ? " is-selected" : ""}${status === "locked" ? " is-locked" : ""}`;
      swatch.style.background = normalized;
      swatch.dataset.shopSelect = "nick_color";
      swatch.dataset.color = normalized;
      swatch.dataset.itemId = nickColorItemId(normalized);
      swatch.dataset.status = status;
      swatch.dataset.itemPrice = String(priceByColor.get(normalized) || 0);
      swatch.setAttribute("aria-label", `Цвет ${normalized}`);
      grid.appendChild(swatch);
    });
    wrap.appendChild(grid);

    return buildSection(meta, wrap);
  };

  const buildSlotSection = (slot) => {
    const meta = getShopSlotMeta(slot);
    const wrap = document.createElement("div");

    const items = (itemsBySlot.get(slot) || [])
      .filter((item) => {
        if (slot !== "seller_effect") return true;
        const id = String(item?.id || "").toLowerCase();
        const title = String(item?.title || "").toLowerCase();
        // Temporarily hide problematic effects from shop UI.
        if (id.includes("glow") || id.includes("hologram") || id.includes("prism")) return false;
        if (title.includes("неон") || title.includes("призм")) return false;
        return true;
      })
      .slice();
    items.sort((a, b) => Number(a?.price || 0) - Number(b?.price || 0));
    if (!items.length) {
      const empty = document.createElement("div");
      empty.className = "store-row-hint";
      empty.textContent = "Скоро появится";
      wrap.appendChild(empty);
      return buildSection(meta, wrap);
    }

    // the tile that is tried on (a tap) or worn is highlighted; nothing is picked for the player
    const currentActive = String(active[slot] || "").trim();
    let selected = String(stateShop.selected[slot] || "").trim();
    if (!selected) selected = currentActive;
    const selectedCustomGradient = isLabelStyleSlot(slot) ? parseCustomGradientStyleId(selected) : null;

    const vipShopAccess = canUseVipFreeShopAccess();
    const usesGradientSwatches = isLabelStyleSlot(slot) || slot === "profile_frame";
    const grid = document.createElement("div");
    grid.className = usesGradientSwatches ? "store-color-grid" : "store-grid";
    items.forEach((item) => {
      const rawStatus = String(item?.status || "locked");
      // VIP opens the store, but never a reward that needs confirmed deals
      const dealLocked = Number(item?.requires_deals || 0) > Number(data.closed_deals || 0);
      const status = vipShopAccess && rawStatus === "locked" && !dealLocked ? "owned" : rawStatus;
      const card = document.createElement("button");
      card.type = "button";
      card.dataset.shopSelect = "item";
      card.dataset.shopSlot = slot;
      card.dataset.itemId = item.id || "";
      card.dataset.status = status;
      card.dataset.itemPrice = String(item?.price || 0);
      card.dataset.requiresDeals = String(item?.requires_deals || 0);
      if (slot === "seller_bg") {
        card.dataset.previewValue = normalizeSellerBgId(item?.id, item);
      } else if (slot === "seller_effect") {
        card.dataset.previewValue = normalizeSellerEffectId(item?.id, item);
      }
      if (usesGradientSwatches) {
        card.className = `color-swatch${item.id === selected ? " is-selected" : ""}${status === "locked" ? " is-locked" : ""}`;
        card.style.background = String(item?.swatch || "transparent");
        card.setAttribute("aria-label", String(item?.title || "Градиент"));
      } else {
        card.className = `store-item${item.id === selected ? " is-selected" : ""}${status === "locked" ? " is-locked" : ""}${status === "active" ? " is-active" : ""}`;
        if (slot === "badge") {
          card.classList.add("store-item--icon-only");
          const iconPreview = document.createElement("div");
          iconPreview.className = "store-item-badge-preview";
          const badge = document.createElement("span");
          badge.className = "cosmetic-badge";
          updateCosmeticBadge(badge, item.id || "");
          iconPreview.appendChild(badge);
          card.appendChild(iconPreview);
        } else {
          const title = document.createElement("div");
          title.className = "store-item-title";
          title.textContent = shopShortName(item) || "—";
          card.appendChild(title);
        }
        const chip = document.createElement("div");
        chip.className = `store-chip${status === "active" ? " store-chip--active" : ""}${status === "owned" ? " store-chip--owned" : ""}${status === "locked" ? " store-chip--locked" : ""}`;
        const tileRequires = Number(item?.requires_deals || 0);
        if (status === "active") chip.textContent = "Активно";
        else if (status === "owned") {
          // a real purchase / earned reward vs. «open because of VIP»
          chip.textContent = rawStatus === "owned" ? (tileRequires > 0 && Number(item?.price || 0) === 0 ? "Получено" : "Куплено") : "Доступно с VIP";
        } else if (tileRequires > 0 && dealLocked) {
          chip.textContent = `${Math.min(Number(data.closed_deals || 0), tileRequires)} / ${tileRequires} ${data.levels_enabled ? "ур." : "сделок"}`;
        } else chip.textContent = `${formatPrice(item?.price || 0)} M‑Coin`;
        card.appendChild(chip);
      }
      grid.appendChild(card);
    });
    wrap.appendChild(grid);

    if (isLabelStyleSlot(slot)) {
      const activeCustomGradient = parseCustomGradientStyleId(currentActive) || selectedCustomGradient;
      const customColor1 = activeCustomGradient?.color1 || "#7C5CFF";
      const customColor2 = activeCustomGradient?.color2 || "#1FE6D1";

      const customBox = document.createElement("div");
      customBox.className = "store-custom-gradient";

      const customTitle = document.createElement("div");
      customTitle.className = "store-custom-gradient-title";
      customTitle.textContent = "Свой градиент (2 цвета)";
      customBox.appendChild(customTitle);

      const customRow = document.createElement("div");
      customRow.className = "store-custom-gradient-row";

      const inputWrap1 = document.createElement("label");
      inputWrap1.className = "store-custom-gradient-input";
      const input1 = document.createElement("input");
      input1.type = "color";
      input1.value = customColor1;
      input1.setAttribute("data-custom-gradient-color", "1");
      inputWrap1.appendChild(input1);

      const inputWrap2 = document.createElement("label");
      inputWrap2.className = "store-custom-gradient-input";
      const input2 = document.createElement("input");
      input2.type = "color";
      input2.value = customColor2;
      input2.setAttribute("data-custom-gradient-color", "2");
      inputWrap2.appendChild(input2);

      const applyCustomBtn = document.createElement("button");
      applyCustomBtn.type = "button";
      applyCustomBtn.className = "store-row-action";
      applyCustomBtn.dataset.shopAction = "apply-custom-gradient";
      applyCustomBtn.dataset.shopSlot = slot;
      applyCustomBtn.textContent = "Применить свои цвета";

      customRow.appendChild(inputWrap1);
      customRow.appendChild(inputWrap2);
      customRow.appendChild(applyCustomBtn);
      customBox.appendChild(customRow);
      wrap.appendChild(customBox);
    }

    // only a reason that blocks the item is explained here; buying / wearing is done by the bottom bar
    const selectedItem = selectedCustomGradient ? null : (items.find((it) => String(it?.id || "") === selected) || null);
    const requiresDeals = Number(selectedItem?.requires_deals || 0);
    const selectedStatusRaw = String(selectedItem?.status || "");
    const lockedByDeals = Boolean(selectedItem) && selectedStatusRaw === "locked" && requiresDeals > 0 && closedDeals < requiresDeals;
    if (lockedByDeals) {
      const hint = document.createElement("div");
      hint.className = "store-row-hint";
      hint.textContent = data.levels_enabled ? `Откроется на ${requiresDeals} уровне (сейчас: ${closedDeals})` : `Откроется после ${requiresDeals} подтверждённых сделок (сейчас: ${closedDeals})`;
      wrap.appendChild(hint);
    }

    return buildSection(meta, wrap);
  };

  const root = document.createElement("div");
  root.className = "store-list";

  const availableSlots = new Set();
  availableSlots.add("nick_color");
  Array.from(itemsBySlot.keys()).forEach((slot) => availableSlots.add(slot));
  // Mirror main label_style palette into dedicated style slots.
  // Backend now supports slot-specific activation for these targets.
  const labelStyleItems = itemsBySlot.get("label_style");
  if (labelStyleItems && labelStyleItems.length) {
    const staffRole = normalizeStaffRoleKey(stateProfile.data?.staff_role);
    const hasStaffRole = isModeratorRole(staffRole);
    const mirrorSlots = [
      ...(hasStaffRole ? ["label_style_staff"] : []),
      "label_style_secondary",
      // territories belong to the hidden game: no tab for them while it is off
      ...(typeof isGameUiEnabled === "function" && isGameUiEnabled() ? ["label_style_territory"] : []),
    ];
    mirrorSlots.forEach((slotName) => {
      if (!itemsBySlot.has(slotName)) {
        const activeItemId = String(stateShop.data?.active?.[slotName] || "");
        const cloned = labelStyleItems.map((item) => {
          const itemId = String(item?.id || "");
          const baseStatus = String(item?.status || "locked");
          const ownedStatus = baseStatus === "locked" ? "locked" : "owned";
          const status = activeItemId && itemId === activeItemId ? "active" : ownedStatus;
          return { ...item, slot: slotName, status };
        });
        itemsBySlot.set(slotName, cloned);
      }
      availableSlots.add(slotName);
    });
  }

  const preferredOrder = [
    "nick_color",
    "badge",
    "label",
    "label_style",
    "label_style_staff",
    "label_style_secondary",
    "label_style_territory",
    "badge_style",
    "profile_frame",
    "seller_bg",
    "seller_effect",
    "listing_frame",
  ];
  const allOrderedSlots = preferredOrder.filter((slot) => availableSlots.has(slot));

  // One screen, a few groups (chips): every group shows all of its sections one under another; the preview above follows.
  const groups = SHOP_GROUPS
    .map((g) => ({ ...g, slots: g.slots.filter((slot) => allOrderedSlots.includes(slot)) }))
    .filter((g) => g.slots.length || g.id === "look");
  if (!stateShop.shopGroup || !groups.some((g) => g.id === stateShop.shopGroup)) {
    stateShop.shopGroup = groups[0]?.id || "nick";
  }
  const group = groups.find((g) => g.id === stateShop.shopGroup) || groups[0];
  stateShop.shopPreviewMode = group.id === "card" ? "card" : "profile";
  syncShopPreviewModeUi();

  const chips = document.createElement("div");
  chips.className = "store-groups";
  groups.forEach((g) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = `store-group${g.id === group.id ? " active" : ""}`;
    btn.dataset.shopGroup = g.id;
    btn.textContent = g.title;
    chips.appendChild(btn);
  });
  root.appendChild(chips);

  // «Профиль»: background photo / pattern / colours live right here (they used to hide in a folded row)
  const customize = document.getElementById("shopProfileCustomize");
  if (customize) {
    customize.hidden = group.id !== "look";
    const fold = document.getElementById("shopCustomizeFold");
    if (fold) fold.open = true;
    root.appendChild(customize);
  }

  const panels = document.createElement("div");
  panels.className = "store-tab-panels";

  group.slots.forEach((slot) => {
    const panel = document.createElement("div");
    panel.className = "store-tab-panel";
    panel.dataset.shopTab = slot;
    panel.appendChild(slot === "nick_color" ? buildNickColorSection() : buildSlotSection(slot));
    panels.appendChild(panel);
  });

  root.appendChild(panels);
  const actionBar = buildShopActionBar();
  if (actionBar) root.appendChild(actionBar);

  elements.shopSections.innerHTML = "";
  elements.shopSections.appendChild(root);
  if (preserveScroll) {
    requestAnimationFrame(() => {
      window.scrollTo({ left: scrollX, top: scrollY, behavior: "auto" });
    });
  }
}

// What the bottom bar will do: everything the player tried on (a tap on a tile) and has not applied yet.
function getShopPendingChanges() {
  const out = { list: [], total: 0, blocked: "" };
  const data = stateShop.data;
  if (!data) return out;
  const pending = stateShop.pending || {};
  const items = Array.isArray(data.items) ? data.items : [];
  const vip = canUseVipFreeShopAccess();
  const closed = Number(data.closed_deals || 0);
  Object.keys(pending).forEach((slot) => {
    const value = String(pending[slot] || "").trim();
    if (!value) return;
    let item = null;
    let color = "";
    if (slot === "nick_color") {
      color = value.toUpperCase();
      if (color === String(data.active_color || "").toUpperCase()) return;
      item = items.find((it) => String(it?.slot || "") === "nick_color" && String(it?.color || "").toUpperCase() === color) || null;
    } else {
      if (value === String(data.active?.[slot] || "")) return;
      item = items.find((it) => String(it?.id || "") === value) || null;
    }
    if (!item) return;
    const price = Number(item.price || 0);
    const need = Number(item.requires_deals || 0);
    const raw = String(item.status || "locked");
    let needsBuy = false;
    if (raw === "locked") {
      if (need > closed) {
        out.blocked = out.blocked || (data.levels_enabled ? `Нужен ${need} уровень` : `Нужно ${need} сделок`);
        return;
      }
      if (vip) needsBuy = false;
      else if (price > 0) needsBuy = true;
      else {
        out.blocked = out.blocked || "Недоступно";
        return;
      }
    }
    out.list.push({ slot, itemId: String(item.id || value), title: String(item.title || "Предмет"), price: needsBuy ? price : 0, needsBuy, color });
    if (needsBuy) out.total += price;
  });
  return out;
}

function buildShopActionBar() {
  const plan = getShopPendingChanges();
  if (!plan.list.length && !plan.blocked) return null;
  const bar = document.createElement("div");
  bar.className = "store-cta";
  const reset = document.createElement("button");
  reset.type = "button";
  reset.className = "store-cta-reset";
  reset.dataset.shopAction = "cta-reset";
  reset.textContent = "Сбросить";
  const main = document.createElement("button");
  main.type = "button";
  main.className = `store-cta-main${plan.total > 0 ? "" : " is-free"}`;
  main.dataset.shopAction = "cta-apply";
  if (plan.blocked && !plan.list.length) {
    main.disabled = true;
    main.textContent = plan.blocked;
  } else {
    main.textContent = plan.total > 0 ? `Купить и надеть · ${formatPrice(plan.total)} M‑Coin` : "Надеть";
  }
  bar.appendChild(reset);
  bar.appendChild(main);
  return bar;
}

function syncShopPreviewModeUi() {
  const mode = stateShop.shopPreviewMode === "card" ? "card" : "profile";
  if (elements.shopPreviewProfileView) elements.shopPreviewProfileView.hidden = mode !== "profile";
  if (elements.shopPreviewCardView) elements.shopPreviewCardView.hidden = mode !== "card";
  elements.shopTabs?.querySelectorAll(".shop-tab[data-shop-preview]").forEach((btn) => {
    btn.classList.toggle("active", String(btn.dataset.shopPreview || "") === mode);
  });
}

async function loadShop(options = {}) {
  const { renderPreview = true, renderStore = true } = options;
  try {
    await ensureAuthContext(2500);
  } catch {
    // ignore
  }

  let data = null;
  try {
    data = await apiRequest(withAuth("/api/shop"));
  } catch {
    showToast("Не удалось загрузить магазин.", "danger");
    return;
  }

  stateShop.data = decorateShopDataForOwner(data);
  ensureShopDefaults();
  if (renderPreview) renderShopTryOnPreview();
  if (renderStore) renderShopFlat();

  const balanceValue = document.getElementById("shopBalanceValue");
  if (balanceValue) {
    balanceValue.textContent = formatPrice(stateShop.data?.balance || 0);
  }

  // Load sets in parallel (non-blocking)
  loadShopSets();
  initShopTabs();
}

// ── Shop Sets ────────────────────────────────────────────────────────────
let _shopSetsLoaded = false;
let _shopTabsInitialized = false;
let _shopSetsData = null;

function initShopTabs() {
  if (_shopTabsInitialized) return;
  _shopTabsInitialized = true;
  const tabsEl = elements.shopTabs;
  if (!tabsEl) return;
  const shopProfileCustomize = document.getElementById("shopProfileCustomize");
  const setPreviewMode = (mode, skipRender) => {
    const normalized = mode === "card" ? "card" : "profile";
    stateShop.shopPreviewMode = normalized;
    tabsEl.querySelectorAll(".shop-tab[data-shop-preview]").forEach((btn) => {
      btn.classList.toggle("active", String(btn.dataset.shopPreview || "") === normalized);
    });
    if (elements.shopPreviewProfileView) {
      elements.shopPreviewProfileView.hidden = normalized !== "profile";
    }
    if (elements.shopPreviewCardView) {
      elements.shopPreviewCardView.hidden = normalized !== "card";
    }
    if (shopProfileCustomize) {
      shopProfileCustomize.hidden = normalized !== "profile";
    }
    try {
      localStorage.setItem(SHOP_PREVIEW_MODE_KEY, normalized);
    } catch {
      // ignore
    }
    if (!skipRender && stateShop.data) {
      renderShopFlat({ preserveScroll: true });
    }
  };

  tabsEl.addEventListener("click", (e) => {
    const btn = e.target.closest("[data-shop-preview]");
    if (!btn) return;
    setPreviewMode(String(btn.dataset.shopPreview || "profile"));
  });

  // Always default to profile tab when opening shop.
  setPreviewMode("profile", true);
  if (elements.shopSections) elements.shopSections.hidden = false;
  if (elements.shopSetsContent) elements.shopSetsContent.hidden = true;
}

async function loadShopSets() {
  if (_shopSetsLoaded) return;
  try {
    const data = await apiRequest(withAuth("/api/shop/sets"));
    _shopSetsData = data;
    _shopSetsLoaded = true;
    renderShopSets(data.sets || []);
  } catch {
    // silent fail — sets tab just stays empty
  }
}

function renderShopSets(sets) {
  const container = elements.shopSetsContent;
  if (!container) return;
  container.innerHTML = "";

  if (!sets.length) {
    container.innerHTML = '<div style="text-align:center;color:rgba(255,255,255,0.4);padding:24px 0;font-size:13px;">Нет доступных стилей</div>';
    return;
  }

  sets.forEach(s => {
    const card = document.createElement("div");
    card.className = "set-card";
    const [c1, c2] = s.colors || ["124,92,255", "31,230,209"];
    card.style.background = `linear-gradient(135deg, rgba(${c1},0.15), rgba(${c2},0.1))`;
    card.style.border = `1px solid rgba(${c1},0.2)`;

    const preview = `background: linear-gradient(135deg, rgba(${c1},0.6), rgba(${c2},0.4));`;

    let actionHtml = "";
    if (s.status === "active") {
      actionHtml = '<span class="set-card-status set-card-status--active">Активен</span>';
    } else if (s.status === "owned") {
      actionHtml = `<button class="set-card-price" data-set-activate="${s.id}">Применить</button>`;
    } else {
      actionHtml = `<button class="set-card-price" data-set-buy="${s.id}" data-set-price="${s.price}">${formatPrice(s.price)} MC</button>`;
    }

    card.innerHTML = `
      <div class="set-card-inner">
        <div class="set-card-preview" style="${preview}"></div>
        <div class="set-card-info">
          <div class="set-card-title"></div>
          <div class="set-card-subtitle"></div>
        </div>
        <div class="set-card-action">${actionHtml}</div>
      </div>
    `;
    card.querySelector(".set-card-title").textContent = s.title;
    card.querySelector(".set-card-subtitle").textContent = s.subtitle;
    container.appendChild(card);
  });

  // Event delegation for buy/activate
  container.addEventListener("click", async (e) => {
    const buyBtn = e.target.closest("[data-set-buy]");
    const actBtn = e.target.closest("[data-set-activate]");
    if (buyBtn) {
      const setId = buyBtn.dataset.setBuy;
      const price = Number(buyBtn.dataset.setPrice || 0);
      const balance = _shopSetsData?.balance || stateShop.data?.balance || 0;
      if (price > balance) {
        showToast("Недостаточно M-Coin", "danger");
        return;
      }
      buyBtn.disabled = true;
      buyBtn.textContent = "...";
      try {
        await apiRequest(withAuth("/api/shop/buy-set"), {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ set_id: setId, operation_id: `buyset_${setId}_${Date.now()}` }),
        });
        showToast("Набор активирован!", "success");
        _shopSetsLoaded = false;
        await Promise.all([loadShopSets(), loadShop({ renderPreview: true }), loadProfile({ force: true })]);
      } catch (error) {
        if (error?.payload?.error === "vip_required") {
          showToast("Нужна активная VIP подписка.", "danger");
          buyBtn.disabled = false;
          buyBtn.textContent = `${formatPrice(price)} MC`;
          return;
        }
        showToast("Ошибка покупки набора", "danger");
        buyBtn.disabled = false;
        buyBtn.textContent = `${formatPrice(price)} MC`;
      }
      return;
    }
    if (actBtn) {
      const setId = actBtn.dataset.setActivate;
      actBtn.disabled = true;
      actBtn.textContent = "...";
      try {
        await apiRequest(withAuth("/api/shop/buy-set"), {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ set_id: setId, operation_id: `actset_${setId}_${Date.now()}` }),
        });
        showToast("Набор применён!", "success");
        _shopSetsLoaded = false;
        await Promise.all([loadShopSets(), loadShop({ renderPreview: true }), loadProfile({ force: true })]);
      } catch (error) {
        if (error?.payload?.error === "vip_required") {
          showToast("Нужна активная VIP подписка.", "danger");
          actBtn.disabled = false;
          actBtn.textContent = "Применить";
          return;
        }
        showToast("Ошибка активации набора", "danger");
        actBtn.disabled = false;
        actBtn.textContent = "Применить";
      }
    }
  });
}

async function loadShopLegacy() {
  if (elements.shopSections) {
    try {
      await ensureAuthContext(2500);
    } catch {
      // ignore
    }

    const balanceValue = document.getElementById("shopBalanceValue");
    if (balanceValue) {
      balanceValue.textContent = formatPrice(state.mcoin || 0);
    }

    let data = null;
    try {
      data = await apiRequest(withAuth("/api/shop"));
    } catch {
      showToast("Не удалось загрузить магазин.", "danger");
      return;
    }
    stateShop.data = decorateShopDataForOwner(data);
    if (balanceValue) {
      balanceValue.textContent = formatPrice(stateShop.data?.balance || 0);
    }

    const cosmetics = {
      badge: data.active?.badge || "",
      label: data.active?.label || "",
      label_style: data.active?.label_style || "",
      badge_style: data.active?.badge_style || "",
      listing_frame: data.active?.listing_frame || "",
      nick_color: data.active_color || "",
    };

    const ensureShopTryOnState = () => {
      if (!stateShop.tryOn) stateShop.tryOn = {};
      if (!stateShop.tryOnPreview) stateShop.tryOnPreview = {};
      if (!stateShop.selectedColorItemId) stateShop.selectedColorItemId = "";
      if (!stateShop.selectedLabelStyleItemId) stateShop.selectedLabelStyleItemId = "";
    };
    ensureShopTryOnState();

    const buildPreviewCosmetics = () => {
      const base = {
        badge: cosmetics.badge || "",
        label: cosmetics.label || "",
        label_style: cosmetics.label_style || "",
        badge_style: cosmetics.badge_style || "",
        listing_frame: cosmetics.listing_frame || "",
        nick_color: cosmetics.nick_color || "",
      };
      const overrides = stateShop.tryOnPreview || {};
      return {
        badge: overrides.badge ?? base.badge,
        label: overrides.label ?? base.label,
        label_style: overrides.label_style ?? base.label_style,
        badge_style: overrides.badge_style ?? base.badge_style,
        listing_frame: overrides.listing_frame ?? base.listing_frame,
        nick_color: overrides.nick_color ?? base.nick_color,
      };
    };

	    const updateShopPreview = () => {
	      const profile = stateProfile.data || {};
	      const displayName = profile.game_nick || profile.display_name || "Без имени";
	      const baseLabel = profile.rank || "Новичок";
	      const previewCosmetics = buildPreviewCosmetics();

	      if (elements.shopPreviewName) elements.shopPreviewName.textContent = displayName;
	      if (elements.shopPreviewLabel) applyRankBadge(elements.shopPreviewLabel, baseLabel);
	      if (elements.shopPreviewAvatar) {
	        const photoUrl = getTelegramUserPhoto();
	        const avatarUrl = profile.avatar_data || profile.avatar_url || photoUrl || "";
	        setAvatarPreview(elements.shopPreviewAvatar, avatarUrl, getInitials(displayName));
	      }

	      applyCosmeticsToDisplay({
	        nameEl: elements.shopPreviewName,
	        labelEl: elements.shopPreviewLabel,
	        badgeEl: elements.shopPreviewBadge,
	        sellerCardEl: null,
	        cosmetics: previewCosmetics,
	        fallbackLabel: baseLabel,
	      });

	      if (elements.shopPreviewListingTitle) {
	        elements.shopPreviewListingTitle.textContent = "Пример объявления";
	      }
	      if (elements.shopPreviewListingPrice) {
	        elements.shopPreviewListingPrice.innerHTML = formatPriceWithGame(1000000);
	      }
	      if (elements.shopPreviewListingMeta) {
	        elements.shopPreviewListingMeta.textContent = "Сервер 2 • Недвижимость";
	      }
	      if (elements.shopPreviewSellerAvatar) {
	        const photoUrl = getTelegramUserPhoto();
	        const avatarUrl = profile.avatar_data || profile.avatar_url || photoUrl || "";
	        setAvatarPreview(elements.shopPreviewSellerAvatar, avatarUrl, getInitials(displayName));
	      }
	      if (elements.shopPreviewSellerName) {
	        elements.shopPreviewSellerName.textContent = displayName;
	      }
	      applyCosmeticsToDisplay({
	        nameEl: elements.shopPreviewSellerName,
	        labelEl: elements.shopPreviewSellerLabel,
	        badgeEl: elements.shopPreviewSellerBadge,
	        sellerCardEl: elements.shopPreviewListingFrame,
	        cosmetics: previewCosmetics,
	        fallbackLabel: baseLabel,
	      });
	    };
    updateShopPreview();

    const items = Array.isArray(data.items) ? data.items : [];
    const itemsBySlot = items.reduce((acc, item) => {
      const slot = item?.slot || "";
      if (!slot) return acc;
      if (!acc[slot]) acc[slot] = [];
      acc[slot].push(item);
      return acc;
    }, {});

    const previewCosmeticsForSections = buildPreviewCosmetics();
    const orderedSections = [
      { slot: "nick_color", title: "Цвет ника", note: "Каждый цвет покупается отдельно (120 M‑Coin)" },
      { slot: "badge", title: "Иконка", note: "⚡ / 💎 / 👑 / ▶ рядом с ником" },
      { slot: "badge_style", title: "Стиль иконки", note: "Градиент/свечение/обводка для иконки" },
      { slot: "label", title: "Лейбл", note: "Текст в плашке под ником" },
      ...(previewCosmeticsForSections.label || previewCosmeticsForSections.label_style
        ? [{ slot: "label_style", title: "Цвет лейбла", note: "Градиенты для плашки (200 M‑Coin)" }]
        : []),
      { slot: "listing_frame", title: "Рамка продавца", note: "Обводка/свечение блока продавца в объявлении" },
    ];

    const statusLabel = (status) => {
      if (status === "active") return "Активно";
      if (status === "owned") return "Куплено";
      return "Закрыто";
    };

    const cardVariantForSlot = (slot, itemId) => {
      if (slot === "badge") return itemId?.includes("crown") ? "gold" : "violet";
      if (slot === "label") return itemId?.includes("legend") ? "gold" : "blue";
      if (slot === "badge_style") return itemId?.includes("gold") ? "gold" : itemId?.includes("ultra") ? "blue" : "violet";
      if (slot === "listing_frame") return "violet";
      return "violet";
    };

    const canBuyByDeals = (requiresDeals) => {
      const req = Number(requiresDeals || 0);
      if (!req) return true;
      const have = Number(data.closed_deals || 0);
      return have >= req;
    };

    const renderPaletteColors = (palette) => {
      const colors = Array.isArray(palette?.colors) ? palette.colors : [];
      const isOwned = palette.status === "owned" || palette.status === "active";
      const grid = document.createElement("div");
      grid.className = "color-grid";
      colors.forEach((hex) => {
        const swatch = document.createElement("button");
        swatch.type = "button";
        swatch.className = "color-swatch";
        swatch.style.background = hex;
        swatch.setAttribute("aria-label", `Цвет ${hex}`);
        swatch.dataset.shopColor = hex;
        swatch.dataset.paletteOwned = isOwned ? "1" : "0";
        if (!isOwned) swatch.classList.add("is-locked");
        if (String(hex).toUpperCase() === String(data.active_color || "").toUpperCase()) {
          swatch.classList.add("is-selected");
        }
        grid.appendChild(swatch);
      });
      return grid;
    };

    const buildCard = (item) => {
      const slot = item.slot || "";
      const status = item.status || "locked";
      const variant = cardVariantForSlot(slot, item.id);
      const requiresDeals = Number(item.requires_deals || 0);
      const lockedByDeals = status === "locked" && requiresDeals > 0 && !canBuyByDeals(requiresDeals);
      const haveDeals = Number(data.closed_deals || 0);
      const previewCosmetics = buildPreviewCosmetics();

      const wrapper = document.createElement("div");
      wrapper.className = `store-item store-item--${variant} ${status}`;
      wrapper.dataset.itemId = item.id || "";
      wrapper.dataset.shopSlot = slot;

      const top = document.createElement("div");
      top.className = "store-item-top";

      const titleWrap = document.createElement("div");
      titleWrap.className = "store-item-title-wrap";

      const title = document.createElement("div");
      title.className = "store-item-title";
      title.textContent = item.title || "Предмет";
      titleWrap.appendChild(title);

      const subtitle = document.createElement("div");
      subtitle.className = "store-item-subtitle";
      subtitle.textContent = item.subtitle || "";
      if (subtitle.textContent.trim()) titleWrap.appendChild(subtitle);

      const statusEl = document.createElement("div");
      statusEl.className = `store-chip store-chip--${status}`;
      statusEl.textContent = statusLabel(status);

      top.appendChild(titleWrap);
      top.appendChild(statusEl);
      wrapper.appendChild(top);

      const desc = document.createElement("div");
      desc.className = "store-item-desc";
      if (lockedByDeals) {
        desc.textContent = `Нужно сделок: ${requiresDeals}. У тебя: ${haveDeals}.`;
      } else if (slot === "nick_color") {
        desc.textContent = item.description || "Убирает выбранный цвет ника.";
      } else if (slot === "listing_frame") {
        desc.textContent = "Видно в карточке продавца";
      } else if (slot === "label" || slot === "badge" || slot === "badge_style") {
        desc.textContent = "Видно в профиле и у продавца";
      } else if (slot === "nick_palette") {
        desc.textContent = "Выбирай активный цвет прямо в карточке";
      } else {
        desc.textContent = String(item.description || "").trim();
      }
      if (desc.textContent) wrapper.appendChild(desc);

      if (slot === "listing_frame") {
        const preview = document.createElement("div");
        preview.className = "store-listing-preview";

        const listing = document.createElement("div");
        listing.className = "store-listing-preview-text";
        listing.innerHTML = `
          <div class="store-listing-title">Продам дом</div>
          <div class="store-listing-meta">Сервер 2 • Недвижимость</div>
        `;

        const seller = document.createElement("div");
        seller.className = "store-listing-seller listing-frame-target";
        applyListingFrame(seller, item.id || "");

        const avatar = document.createElement("div");
        avatar.className = "avatar store-listing-avatar";
        const profile = stateProfile.data || {};
        const displayName = profile.game_nick || profile.display_name || "—";
        const photoUrl = getTelegramUserPhoto();
        const avatarUrl = profile.avatar_data || profile.avatar_url || photoUrl || "";
        setAvatarPreview(avatar, avatarUrl, getInitials(displayName));

        const nameRow = document.createElement("div");
        nameRow.className = "name-row store-listing-name-row";
        const name = document.createElement("span");
        name.className = "store-listing-name";
        name.textContent = displayName;
        applyNickColor(name, previewCosmetics.nick_color);
        const badge = document.createElement("span");
        badge.className = "cosmetic-badge hidden";
        updateCosmeticBadge(badge, previewCosmetics.badge);
        applyBadgeStyle(badge, previewCosmetics.badge_style);
        nameRow.appendChild(name);
        nameRow.appendChild(badge);

        seller.appendChild(avatar);
        seller.appendChild(nameRow);
        preview.appendChild(listing);
        preview.appendChild(seller);
        wrapper.appendChild(preview);
      }

      const bottom = document.createElement("div");
      bottom.className = "store-item-bottom";

      const price = document.createElement("div");
      price.className = "store-item-price";
      if (slot === "nick_color") {
        price.textContent = data.active_color ? `Сейчас: ${data.active_color}` : "Цвет не выбран";
      } else {
        const rawPrice = Number(item.price || 0);
        price.textContent = rawPrice
          ? `${formatPrice(rawPrice)} M‑Coin`
          : requiresDeals > 0 ? (data.levels_enabled ? `Награда за ${requiresDeals} уровень` : `Награда за ${requiresDeals} сделок`) : "Бесплатно";
      }
      bottom.appendChild(price);

      const actionBtn = document.createElement("button");
      actionBtn.type = "button";
      actionBtn.className = "store-item-action";
      const vipShopAccess = canUseVipFreeShopAccess();
      if (status === "active") {
        actionBtn.textContent = "Активно";
        actionBtn.disabled = true;
      } else if (status === "locked" && requiresDeals > 0 && lockedByDeals) {
        // reward label: not for sale, opens by deals
        actionBtn.textContent = `${Math.min(haveDeals, requiresDeals)} / ${requiresDeals} ${data.levels_enabled ? "ур." : "сделок"}`;
        actionBtn.disabled = true;
      } else if (status === "owned" || (status === "locked" && vipShopAccess)) {
        actionBtn.textContent = "Применить";
        actionBtn.dataset.shopAction = "activate";
        actionBtn.dataset.itemId = item.id || "";
      } else {
        actionBtn.textContent = "Купить";
        actionBtn.dataset.shopAction = "buy";
        actionBtn.dataset.itemId = item.id || "";
        actionBtn.dataset.itemTitle = item.title || "Предмет";
        actionBtn.dataset.itemPrice = String(item.price || 0);
        actionBtn.disabled = lockedByDeals;
      }
      bottom.appendChild(actionBtn);

      wrapper.appendChild(bottom);
      return wrapper;
    };

    const openSlots = new Set(
      Array.from(elements.shopSections.querySelectorAll("details[open][data-shop-section]")).map((el) => el.dataset.shopSection),
    );
    elements.shopSections.innerHTML = "";
    orderedSections.forEach((sectionDef) => {
      const list = itemsBySlot[sectionDef.slot] || [];
      if (!list.length) return;

      const section = document.createElement("details");
      section.className = "store-section";
      section.dataset.shopSection = sectionDef.slot;
      section.open = openSlots.has(sectionDef.slot);

      const summary = document.createElement("summary");
      const head = document.createElement("div");
      head.className = "store-section-head";
      const title = document.createElement("div");
      title.className = "store-section-title";
      title.textContent = sectionDef.title;
      const note = document.createElement("div");
      note.className = "store-section-note";
      note.textContent = sectionDef.note;
      head.appendChild(title);
      head.appendChild(note);
      summary.appendChild(head);
      section.appendChild(summary);

      if (sectionDef.slot === "nick_color") {
        const panel = document.createElement("div");
        panel.className = "store-color-panel";

        const grid = document.createElement("div");
        grid.className = "store-color-grid";
        list.forEach((item) => {
          const swatch = document.createElement("button");
          swatch.type = "button";
          swatch.className = "color-swatch";
          const colorHex = String(item.color || "").trim();
          swatch.style.background = colorHex || "transparent";
          swatch.setAttribute("aria-label", colorHex ? `Цвет ${colorHex}` : "Цвет");
          swatch.dataset.colorItemId = String(item.id || "");
          swatch.dataset.owned = item.status === "owned" || item.status === "active" ? "1" : "0";
          swatch.dataset.status = String(item.status || "locked");
          swatch.dataset.colorHex = colorHex;
          swatch.dataset.price = String(item.price || 120);
          if (item.status === "active") swatch.classList.add("is-selected");
          if (item.status === "locked") swatch.classList.add("is-locked");
          grid.appendChild(swatch);
        });

        const actions = document.createElement("div");
        actions.className = "store-color-actions";
        const reset = document.createElement("button");
        reset.type = "button";
        reset.className = "store-reset-btn";
        reset.textContent = "Сбросить цвет";
        reset.dataset.shopAction = "deactivate";
        reset.dataset.shopSlot = "nick_color";
        reset.disabled = !String(data.active_color || "").trim();
        actions.appendChild(reset);

        const picked = list.find((it) => String(it?.id || "") === String(stateShop.selectedColorItemId || "")) || null;
        const pickedStatus = String(picked?.status || "");
        const pickedId = String(picked?.id || "");
        const pickedPrice = Number(picked?.price || 120);
        const pickedColor = String(picked?.color || "");
        if (pickedId) {
          const actionBtn = document.createElement("button");
          actionBtn.type = "button";
          actionBtn.className = "store-item-action";
          actionBtn.dataset.colorAction = "1";
          actionBtn.dataset.itemId = pickedId;
          actionBtn.dataset.itemTitle = `Цвет ника ${pickedColor}`;
          actionBtn.dataset.itemPrice = String(pickedPrice);
          if (pickedStatus === "active") {
            actionBtn.textContent = "Активно";
            actionBtn.disabled = true;
          } else if (pickedStatus === "owned") {
            actionBtn.textContent = "Применить";
            actionBtn.dataset.shopAction = "activate";
          } else {
            actionBtn.textContent = "Купить";
            actionBtn.dataset.shopAction = "buy";
          }
          actions.appendChild(actionBtn);
        }

        panel.appendChild(grid);
        panel.appendChild(actions);
        section.appendChild(panel);
      } else if (sectionDef.slot === "label_style") {
        const panel = document.createElement("div");
        panel.className = "store-color-panel";

        const grid = document.createElement("div");
        grid.className = "store-color-grid";
        list.forEach((item) => {
          const swatch = document.createElement("button");
          swatch.type = "button";
          swatch.className = "color-swatch";
          const gradient = String(item.swatch || "").trim();
          swatch.style.background = gradient || "transparent";
          swatch.setAttribute("aria-label", item.title ? String(item.title) : "Градиент");
          swatch.dataset.labelStyleItemId = String(item.id || "");
          swatch.dataset.owned = item.status === "owned" || item.status === "active" ? "1" : "0";
          swatch.dataset.status = String(item.status || "locked");
          swatch.dataset.price = String(item.price || 200);
          if (item.status === "active") swatch.classList.add("is-selected");
          if (item.status === "locked") swatch.classList.add("is-locked");
          grid.appendChild(swatch);
        });

        const actions = document.createElement("div");
        actions.className = "store-color-actions";
        const reset = document.createElement("button");
        reset.type = "button";
        reset.className = "store-reset-btn";
        reset.textContent = "Сбросить цвет лейбла";
        reset.dataset.shopAction = "deactivate";
        reset.dataset.shopSlot = "label_style";
        reset.disabled = !String(data.active?.label_style || "").trim();
        actions.appendChild(reset);

        const picked =
          list.find((it) => String(it?.id || "") === String(stateShop.selectedLabelStyleItemId || "")) ||
          list.find((it) => String(it?.id || "") === String(stateShop.tryOnPreview?.label_style || "")) ||
          null;
        const pickedStatus = String(picked?.status || "");
        const pickedId = String(picked?.id || "");
        const pickedPrice = Number(picked?.price || 200);
        const pickedTitle = String(picked?.title || "Цвет лейбла");
        if (pickedId) {
          const actionBtn = document.createElement("button");
          actionBtn.type = "button";
          actionBtn.className = "store-item-action";
          actionBtn.dataset.itemId = pickedId;
          actionBtn.dataset.itemTitle = pickedTitle;
          actionBtn.dataset.itemPrice = String(pickedPrice);
          actionBtn.dataset.shopSlot = "label_style";
          if (pickedStatus === "active") {
            actionBtn.textContent = "Активно";
            actionBtn.disabled = true;
          } else if (pickedStatus === "owned") {
            actionBtn.textContent = "Применить";
            actionBtn.dataset.shopAction = "activate";
          } else {
            actionBtn.textContent = "Купить";
            actionBtn.dataset.shopAction = "buy";
          }
          actions.appendChild(actionBtn);
        }

        panel.appendChild(grid);
        panel.appendChild(actions);
        section.appendChild(panel);
      } else if (sectionDef.slot === "label") {
        const grid = document.createElement("div");
        grid.className = "store-grid";
        list.forEach((item) => grid.appendChild(buildCard(item)));
        section.appendChild(grid);

        const actions = document.createElement("div");
        actions.className = "store-section-actions";
        const reset = document.createElement("button");
        reset.type = "button";
        reset.className = "store-reset-btn";
        reset.textContent = "Сбросить лейбл";
        reset.dataset.shopAction = "deactivate";
        reset.dataset.shopSlot = "label";
        reset.disabled = !String(data.active?.label || "").trim();
        actions.appendChild(reset);
        section.appendChild(actions);
      } else {
        const grid = document.createElement("div");
        grid.className = "store-grid";
        list.forEach((item) => grid.appendChild(buildCard(item)));
        section.appendChild(grid);
      }

      elements.shopSections.appendChild(section);
    });

    return;
  }

  if (!elements.shopFeed) return;
  try {
    await ensureAuthContext(2500);
  } catch {
    // ignore
  }

  if (elements.shopTabs) {
    elements.shopTabs.style.display = "";
  }

  let data = null;
  try {
    data = await apiRequest(withAuth("/api/shop"));
  } catch {
    showToast("Не удалось загрузить магазин.", "danger");
    return;
  }

  const balanceValue = document.getElementById("shopBalanceValue");
  if (balanceValue) {
    balanceValue.textContent = formatPrice(data.balance || 0);
  }

  const savedTab = localStorage.getItem(SHOP_TAB_STORAGE_KEY);
  if (savedTab && stateShop.tab !== savedTab) {
    stateShop.tab = savedTab;
  }

  const setTabsActive = () => {
    if (!elements.shopTabs) return;
    elements.shopTabs.querySelectorAll("[data-shop-tab]").forEach((btn) => {
      btn.classList.toggle("active", btn.getAttribute("data-shop-tab") === stateShop.tab);
      btn.setAttribute("aria-selected", btn.classList.contains("active") ? "true" : "false");
    });
  };
  setTabsActive();

  const items = Array.isArray(data.items) ? data.items : [];
  const itemsById = new Map(items.filter(Boolean).map((item) => [item.id, item]));
  const userName =
    stateProfile?.data?.game_nick ||
    stateProfile?.data?.display_name ||
    "Вы";

  const createCountdownText = (mode) => {
    if (mode !== "week") return "";
    const now = new Date(Date.now() + 3 * 60 * 60 * 1000);
    const day = now.getUTCDay(); // 0..6 (UTC), but now already shifted to MSK in UTC frame
    const rawDaysToMonday = (8 - (day || 7)) % 7; // Mon=1..Sun=7, Monday -> 0
    const daysToMonday = rawDaysToMonday === 0 ? 7 : rawDaysToMonday;
    const end = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), 0, 0, 0));
    end.setUTCDate(end.getUTCDate() + daysToMonday);
    const secondsLeft = Math.max(0, Math.floor((end.getTime() - now.getTime()) / 1000));
    return formatTaskTimer(secondsLeft);
  };

  const splitOfferTitle = (title) => {
    const raw = String(title || "").trim();
    const parts = raw.split(":");
    if (parts.length >= 2) {
      return { type: parts[0].trim(), name: parts.slice(1).join(":").trim() };
    }
    return { type: raw, name: "" };
  };

  const renderOffer = (offer) => {
    const slide = document.createElement("div");
    slide.className = "shop-slide";

    if (offer.kind === "item") {
      const item = itemsById.get(offer.itemId);
      const status = item ? item.status : "locked";
      const price = item ? Number(item.price || 0) : 0;
      const canAfford = Number(data.balance || 0) >= price;
      const isLocked = status === "locked";
      const isOwned = status === "owned";
      const isActive = status === "active";

      const tone = offer.tone || "violet";
      const pillText = isActive ? "АКТИВНО" : isOwned ? "КУПЛЕНО" : "НОВОЕ";
      const pillClass = isActive || isOwned ? "shop-style-pill--owned" : "shop-style-pill--new";

      const { type, name } = splitOfferTitle(offer.title);
      const displayType = type || "Оффер";
      const displayName = name || "";

      const priceLabel = canAfford ? `${formatPrice(price)} M‑Coin` : `Нужно ${formatPrice(price)} M‑Coin`;
      const showBuy = isLocked;
      const buyDisabled = !canAfford;

      const showActivate = isOwned || isActive;
      const action = isActive ? "deactivate" : "activate";
      const activateDisabled = false;
      const activateText = isActive ? "Убрать" : "Активировать";

      slide.innerHTML = `
        <div class="shop-style-card shop-style-card--${tone} ${isActive ? "is-active" : ""} ${isOwned ? "is-owned" : ""} ${isLocked ? "is-locked" : ""}">
          <div class="shop-style-pill ${pillClass}">${pillText}</div>

          <button class="shop-style-arrow shop-style-arrow--prev" type="button" aria-label="Предыдущий" data-carousel-nav="prev">‹</button>
          <button class="shop-style-arrow shop-style-arrow--next" type="button" aria-label="Следующий" data-carousel-nav="next">›</button>

          <div class="shop-style-icon" aria-hidden="true">
            <div class="shop-style-icon-ring">${SHOP_BADGE_SVG}</div>
          </div>

          <div class="shop-style-title">
            <div class="shop-style-title-type">${displayType}</div>
            ${displayName ? `<div class="shop-style-title-name">${displayName}</div>` : ""}
          </div>

          <div class="shop-style-subtitle">${offer.subtitle || ""}</div>
          <div class="shop-style-desc">${offer.description || ""}</div>

          <div class="shop-style-preview">
            <div class="shop-preview-name">${userName}</div>
            <span class="shop-preview-badge" aria-hidden="true">${SHOP_BADGE_SVG}</span>
          </div>

          ${
            showBuy
              ? `<button class="shop-style-price" type="button" data-shop-action="buy" data-item-id="${offer.itemId}" data-shop-slot="${item?.slot || "badge"}" data-item-title="${offer.title}" data-item-price="${price}" ${buyDisabled ? "disabled" : ""}>${priceLabel}</button>`
              : `<div class="shop-style-price shop-style-price--static">${formatPrice(price)} M‑Coin</div>`
          }

          ${
            showActivate
              ? `<button class="shop-style-action" type="button" data-shop-action="${action}" data-item-id="${offer.itemId}" data-shop-slot="${item?.slot || "badge"}" ${activateDisabled ? "disabled" : ""}>${activateText}</button>`
              : ""
          }
        </div>
      `;
      return slide;
    }

    const card = document.createElement("div");
    card.className = `shop-offer shop-offer--${offer.tone || "violet"} is-soon`;
    const countdown = offer.countdownMode ? createCountdownText(offer.countdownMode) : "";
    const priceLine = offer.priceText ? `<div class="shop-offer-price-plain">${offer.priceText}</div>` : "";
    const topLabel = offer.label ? `<span class="shop-offer-label shop-offer-label--${offer.labelTone || "new"}">${offer.label}</span>` : "";
    card.innerHTML = `
      <div class="shop-offer-top">
        <div class="shop-offer-top-left">
          ${topLabel}
          <span class="shop-offer-status">СКОРО</span>
        </div>
        <div class="shop-offer-top-right">${offer.visibility || ""}</div>
      </div>
      <div class="shop-offer-center">
        <div class="shop-offer-title">${offer.title}</div>
        <div class="shop-offer-subtitle">${offer.subtitle || ""}</div>
        <div class="shop-offer-preview">
          <div class="shop-preview-name">${userName}</div>
          <div class="shop-preview-pill">${offer.subtitle || "Оффер"}</div>
        </div>
        <div class="shop-offer-desc">${offer.description || ""}</div>
        ${countdown ? `<div class="shop-offer-countdown" data-countdown-mode="${offer.countdownMode}">${countdown}</div>` : ""}
      </div>
      <div class="shop-offer-bottom">
        ${priceLine || `<div class="shop-offer-price"><span class="shop-offer-price-value">—</span><span class="shop-offer-price-currency"></span></div>`}
        <button class="action-btn shop-offer-btn disabled" type="button" disabled>${offer.cta || "Скоро"}</button>
      </div>
    `;
    slide.appendChild(card);
    return slide;
  };

  const visibleOffers = SHOP_OFFERS.filter((offer) => {
    const tabs = offer.tab || [];
    return tabs.includes(stateShop.tab);
  });

  elements.shopFeed.innerHTML = "";
  elements.shopFeed.classList.add("is-carousel");
  if (!visibleOffers.length) {
    elements.shopFeed.innerHTML = "<div class='empty-state' style='display:block'>Раздел скоро появится.</div>";
    return;
  }

  elements.shopFeed.innerHTML = `
    <div class="shop-carousel">
      <button class="shop-nav shop-nav--prev" type="button" aria-label="Предыдущий оффер">‹</button>
      <div class="shop-track" aria-label="Офферы магазина"></div>
      <button class="shop-nav shop-nav--next" type="button" aria-label="Следующий оффер">›</button>
    </div>
  `;

  const track = elements.shopFeed.querySelector(".shop-track");
  const prevBtn = elements.shopFeed.querySelector(".shop-nav--prev");
  const nextBtn = elements.shopFeed.querySelector(".shop-nav--next");
  if (!track || !prevBtn || !nextBtn) return;

  visibleOffers.forEach((offer) => {
    track.appendChild(renderOffer(offer));
  });

  const getScrollStep = () => {
    const first = track.querySelector(".shop-slide");
    if (!first) return Math.max(240, Math.floor(track.clientWidth * 0.8));
    const gap = 14;
    return first.getBoundingClientRect().width + gap;
  };

  const updateNav = () => {
    const maxScroll = track.scrollWidth - track.clientWidth;
    prevBtn.disabled = track.scrollLeft <= 6;
    nextBtn.disabled = track.scrollLeft >= maxScroll - 6;
  };

  prevBtn.addEventListener("click", () => {
    track.scrollBy({ left: -getScrollStep(), behavior: "smooth" });
  });
  nextBtn.addEventListener("click", () => {
    track.scrollBy({ left: getScrollStep(), behavior: "smooth" });
  });

  let navRaf = null;
  track.addEventListener(
    "scroll",
    () => {
      if (navRaf) cancelAnimationFrame(navRaf);
      navRaf = requestAnimationFrame(() => {
        navRaf = null;
        updateNav();
      });
    },
    { passive: true },
  );

  track.scrollLeft = 0;
  updateNav();

  if (stateShop.countdownTimer) {
    clearInterval(stateShop.countdownTimer);
    stateShop.countdownTimer = null;
  }
  if (visibleOffers.some((offer) => Boolean(offer.countdownMode))) {
    stateShop.countdownTimer = setInterval(() => {
      elements.shopFeed.querySelectorAll("[data-countdown-mode]").forEach((node) => {
        const mode = node.getAttribute("data-countdown-mode");
        node.textContent = createCountdownText(mode);
      });
    }, 1000);
  }
}

// UI tabs group DB statuses; the statuses themselves are never merged or rewritten.
//   Активные = active · Скрытые = hidden + expired + sold + rejected · Ожидает = awaiting_confirmation (+ pending moderation)
const MY_LISTINGS_TAB_STATUSES = {
  active: ["active"],
  hidden: ["hidden", "expired", "sold", "rejected"],
  awaiting_confirmation: ["awaiting_confirmation", "pending"],
};

function matchesMyListingsTab(status, tab) {
  const allowed = MY_LISTINGS_TAB_STATUSES[tab];
  return allowed ? allowed.includes(String(status || "")) : String(status || "") === tab;
}

function setMyListingsTab(tab) {
  stateMyListings.tab = MY_LISTINGS_TAB_STATUSES[tab] ? tab : "active";
  stateMyListings.expanded = false;
  if (elements.myListingsTabs) {
    elements.myListingsTabs.querySelectorAll(".pill, .profile-tab").forEach((pill) => {
      pill.classList.toggle("active", pill.dataset.tab === stateMyListings.tab);
    });
  }
}

function focusMyListingFromLink() {
  // Deep link target (see getProfileListingParam). One shot: the tab follows the listing's real status.
  const id = Number(stateMyListings.focusId || 0);
  stateMyListings.focusId = 0;
  if (!id) return 0;
  const target = stateMyListings.items.find((item) => Number(item.id) === id);
  if (!target) return 0;
  const tab = Object.keys(MY_LISTINGS_TAB_STATUSES).find((key) => matchesMyListingsTab(target.status, key));
  if (tab) setMyListingsTab(tab);
  stateMyListings.expanded = true;
  return id;
}

function renderMyListings() {
  const focusId = focusMyListingFromLink();
  const items = stateMyListings.items.filter((item) => matchesMyListingsTab(item.status, stateMyListings.tab));
  elements.myListingsList.innerHTML = "";
  if (!items.length) {
    elements.myListingsEmpty.style.display = "grid";
    elements.myListingsToggle.textContent = "";
    return;
  }
  elements.myListingsEmpty.style.display = "none";

  // a horizontal carousel: every listing is in reach with a swipe, so there is no «Показать все»
  const visible = items;
  elements.myListingsToggle.textContent = "";

  visible.forEach((item) => {
    const card = document.createElement("div");
    card.className = `listing-item${item.is_top ? " listing-top" : ""}`;
    card.dataset.listingId = String(Number(item.id || 0) || "");
    const statusView = getStatusView(item.status);
    const topRemaining = item.is_top ? formatTopRemaining(item.top_until) : "";
    const topBadgeText = item.is_top ? `ТОП${topRemaining ? ` · осталось ${topRemaining}` : ""}` : "";
    const canPromote = item.status === "active" && !item.is_top && (state.mcoin >= TOP_MIN_COST || Number(state.promoCredits || 0) > 0);
    let actionsHtml = "";
    let statusHtml = `<div class="chip-stack listing-status-stack">
      <div class="listing-meta"><span class="status-badge ${statusView.className}">${statusView.text}</span></div>
      ${topBadgeText ? `<div class="listing-meta"><span class="top-badge">${topBadgeText}</span></div>` : ""}
    </div>`;
    if (item.status === "hidden") {
      statusHtml = `<div class="listing-meta"><span class="status-badge ${statusView.className}">${getHiddenStatusText(item)}</span></div>`;
    }
    if (item.status === "pending") {
      statusHtml = `<div class="chip-stack">
        <div class="chip-btn muted" role="status">На модерации</div>
        <div class="chip-note">Проверка займёт до 1–2 часов</div>
      </div>`;
      actionsHtml = "";
    } else if (item.status === "awaiting_confirmation") {
      actionsHtml = `<div class="chip-stack">
        <div class="chip-btn muted" role="status">Ожидает подтверждения</div>
        <div class="chip-note">Ждём ответ покупателя</div>
      </div>`;
    } else if (item.status === "rejected") {
      actionsHtml = '<button class="chip-btn" data-action="resubmit" type="button">Отправить снова</button>';
    } else if (item.status === "sold") {
      // sold stays read-only: no actions are defined for it (deleting a sold listing touches deal/chat history)
      actionsHtml = "";
    } else {
      const menuButtonsHtml = `
        ${item.status === "active" ? '<button class="chip-btn listing-action-btn" data-action="sold" title="Продано">✅ Продано</button>' : ""}
        ${item.status === "active" ? '<button class="chip-btn listing-action-btn" data-action="hide" title="Скрыть">👁️ Скрыть</button>' : ""}
        ${item.status === "active" ? '<button class="chip-btn listing-action-btn" data-action="edit" title="Редактировать">✏️ Редактировать</button>' : ""}
        ${item.status === "active" ? `<button class="chip-btn listing-action-btn${item.is_top ? " glow" : ""}${canPromote ? "" : " disabled"}" data-action="promo" title="Продвижение">🔥 В ТОП</button>` : ""}
        ${item.status === "hidden" && !isModeratorRole(item.hidden_by_role) ? '<button class="chip-btn listing-action-btn" data-action="restore" title="Вернуть в активные">↩️ Вернуть</button>' : ""}
        ${item.status === "expired" ? `<button class="chip-btn listing-action-btn" data-action="renew" title="Продлить на 30 дней"><svg class="listing-action-icon" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 12a8 8 0 1 1-2.6-5.9"/><path d="M20 4v5h-5"/></svg>Продлить · 50 M‑Coin</button>` : ""}
        ${item.status === "hidden" || item.status === "expired" ? '<button class="chip-btn listing-action-btn danger" data-action="delete" title="Удалить">🗑 Удалить</button>' : ""}
      `;
      actionsHtml = `
        <details class="listing-actions-menu">
          <summary class="icon-btn listing-actions-trigger" title="Действия">⋯</summary>
          <div class="listing-actions-popup">
            ${menuButtonsHtml}
          </div>
        </details>
      `;
    }
    card.classList.add("listing-item--card");
    card.innerHTML = `
      <span class="listing-thumb" aria-hidden="true"></span>
      <div class="listing-main">
        <div class="listing-title">${escapeHtmlText(item.title)}</div>
        <div class="listing-item-price">${formatPriceWithGame(item.price)}</div>
        <div class="listing-meta">${escapeHtmlText(formatServer(item.server_id))} • ${escapeHtmlText(item.category)}</div>
        ${statusHtml}
      </div>
      <div class="listing-actions">
        ${actionsHtml}
      </div>
    `;
    applyListingThumb(card.querySelector(".listing-thumb"), item.id, item.category, item.has_image, "", item.catalog_item_id);
    const cardMenu = card.querySelector(".listing-actions-menu");
    if (cardMenu) {
      // the old dropdown would be clipped by the scrolling strip: its buttons stay (their handlers are bound below), a «⋯» on the cover opens them as a floating menu
      const moreBtn = document.createElement("button");
      moreBtn.type = "button";
      moreBtn.className = "listing-card-more";
      moreBtn.setAttribute("aria-label", "Действия");
      moreBtn.textContent = "⋯";
      moreBtn.addEventListener("click", (event) => {
        event.stopPropagation();
        const rect = moreBtn.getBoundingClientRect();
        openActionMenu(rect.right - 20, rect.bottom, [...cardMenu.querySelectorAll(".listing-actions-popup button")].map((btn) => ({
          label: btn.textContent.replace(/\s+/g, " ").trim(),
          danger: btn.classList.contains("danger"),
          run: () => btn.click(),
        })));
      });
      card.querySelector(".listing-thumb").appendChild(moreBtn);
      cardMenu.classList.add("is-proxied");
    }
    card.addEventListener("click", (event) => {
      // the card opens the listing page; its own buttons / the «⋯» menu keep their actions
      if (event.target.closest("button, summary, details, a, .listing-actions-menu, .listing-card-more")) return;
      const id = Number(item.id || 0);
      if (id > 0) loadListing(id, "profile", item);
    });
    card.style.cursor = "pointer";
    const closeCardMenu = () => {
      if (cardMenu) {
        cardMenu.removeAttribute("open");
        cardMenu.classList.remove("open-up");
        card.classList.remove("menu-open");
      }
    };
    if (cardMenu) {
      cardMenu.addEventListener("click", (event) => {
        event.stopPropagation();
      });
      cardMenu.addEventListener("toggle", () => {
        if (!cardMenu.open) {
          cardMenu.classList.remove("open-up");
          card.classList.remove("menu-open");
          return;
        }
        card.classList.add("menu-open");
        closeOpenListingActionMenus(cardMenu);
        const alignMenuDirection = () => {
          const trigger = cardMenu.querySelector(".listing-actions-trigger");
          const popup = cardMenu.querySelector(".listing-actions-popup");
          if (!trigger || !popup) return;
          cardMenu.classList.remove("open-up");
          const triggerRect = trigger.getBoundingClientRect();
          const popupRect = popup.getBoundingClientRect();
          const popupHeight = Math.max(
            popupRect.height || 0,
            popup.offsetHeight || 0,
            popup.scrollHeight || 0,
          );
          const safeBottom = 148;
          const spaceBelow = window.innerHeight - triggerRect.bottom - safeBottom;
          const spaceAbove = triggerRect.top - 12;
          let shouldOpenUp = popupHeight > 0 && spaceBelow < popupHeight && spaceAbove >= Math.min(popupHeight, 140);
          // In "my listings", avoid dropping the popup over the next card's content.
          if (!shouldOpenUp && popupHeight > 0) {
            const nextCard = card.nextElementSibling;
            if (nextCard && nextCard.classList.contains("listing-item")) {
              const nextTop = nextCard.getBoundingClientRect().top;
              const projectedBottom = triggerRect.bottom + 6 + popupHeight;
              if (projectedBottom > nextTop - 6) {
                shouldOpenUp = spaceAbove >= Math.min(popupHeight, 140);
              }
            }
          }
          if (shouldOpenUp) {
            cardMenu.classList.add("open-up");
          }
        };
        alignMenuDirection();
        requestAnimationFrame(alignMenuDirection);
      });
    }
    const resubmitBtn = card.querySelector("[data-action='resubmit']");
    if (resubmitBtn) {
      resubmitBtn.addEventListener("click", () => {
        startEditListing(item);
      });
    }
    const soldBtn = card.querySelector("[data-action='sold']");
    if (soldBtn) {
      soldBtn.addEventListener("click", () => {
        closeCardMenu();
        stateDeal.listingId = item.id;
        if (elements.dealBuyerNick) {
          elements.dealBuyerNick.value = "";
        }
        hideDealNickSuggest();
        if (elements.dealModal) {
          elements.dealModal.classList.add("show");
        }
      });
    }
    const hideBtn = card.querySelector("[data-action='hide']");
    if (hideBtn) {
      hideBtn.addEventListener("click", () => {
        closeCardMenu();
        stateMyListings.statusId = item.id;
        stateMyListings.statusValue = "hidden";
        elements.statusTitle.textContent = "Скрыть объявление?";
        elements.statusText.textContent = "Оно исчезнет из рынка, но останется в профиле.";
        elements.statusConfirm.textContent = "Скрыть";
        elements.statusModal.classList.add("show");
      });
    }
    const editBtn = card.querySelector("[data-action='edit']");
    if (editBtn) {
      editBtn.addEventListener("click", () => {
        closeCardMenu();
        startEditListing(item);
      });
    }
    const promoBtn = card.querySelector("[data-action='promo']");
    if (promoBtn && item.status === "active" && !item.is_top) {
      promoBtn.addEventListener("click", () => {
        closeCardMenu();
        openPromotionModal(item);
      });
    }
    const restoreBtn = card.querySelector("[data-action='restore']");
    if (restoreBtn) {
      restoreBtn.addEventListener("click", () => {
        closeCardMenu();
        stateMyListings.statusId = item.id;
        stateMyListings.statusValue = "active";
        elements.statusTitle.textContent = "Вернуть объявление в активные?";
        elements.statusText.textContent = "Оно снова появится в рынке.";
        elements.statusConfirm.textContent = "Вернуть";
        elements.statusModal.classList.add("show");
      });
    }
    const deleteBtn = card.querySelector("[data-action='delete']");
    if (deleteBtn) {
      deleteBtn.addEventListener("click", () => {
        closeCardMenu();
        stateMyListings.deleteId = item.id;
        elements.deleteModal.classList.add("show");
      });
    }
    const renewBtn = card.querySelector("[data-action='renew']");
    if (renewBtn) {
      renewBtn.addEventListener("click", async () => {
        closeCardMenu();
        const confirmed = await telegramConfirmPopup({
          title: "Продлить объявление?",
          message: "Объявление снова появится в Market на 30 дней. Стоимость: 50 M‑Coin.",
          cancelText: "Нет",
          okText: "Продлить",
        });
        if (!confirmed) return;
        renewBtn.disabled = true;
        try {
          await apiRequest(withAuth(`/api/listings/${item.id}/renew`), {
            method: "POST",
            body: JSON.stringify({ operation_id: generateOperationId() }),
          });
          showToast("Объявление продлено на 30 дней.", "success");
          invalidateMarketCaches({ refreshNow: true });
          await loadProfile({ force: true });
        } catch (error) {
          const code = error?.payload?.error;
          showToast(code === "insufficient_funds" ? "Недостаточно M‑Coin." : "Не удалось продлить объявление.", "danger");
          renewBtn.disabled = false;
        }
      });
    }
    elements.myListingsList.appendChild(card);
    if (focusId && Number(item.id) === focusId) {
      card.classList.add("listing-focus");
      requestAnimationFrame(() => card.scrollIntoView({ block: "center", behavior: "smooth" }));
    }
  });
}

async function openPromotionModal(item) {
  statePromotion.listingId = item.id;
  statePromotion.option = "2h";
  if (elements.promoListingTitle) {
    elements.promoListingTitle.textContent = item.title;
  }
  const remaining = formatTopRemaining(item.top_until);
  const topStatus = await requestTopStatus(item.server_id);
  // free promotions (a prize of the referral program) pay for the 2-hour tariff
  let freePromos = 0;
  try {
    freePromos = Number((await apiRequest(withAuth("/api/referrals/rewards")))?.promotion_credits || 0);
    state.promoCredits = freePromos;
  } catch {
    freePromos = Number(state.promoCredits || 0);
  }
  const isFree = () => statePromotion.option === "2h" && freePromos > 0;
  const slotsLine = topStatus ? `Слоты: ${topStatus.active_slots}/${topStatus.slot_limit}` : "";
  const queueLine = topStatus ? `Очередь: ${topStatus.queue_size}/${topStatus.queue_limit}` : "";

  const renderOptions = () => {
    if (!elements.promoOptions) return;
    elements.promoOptions.innerHTML = "";
    TOP_TARIFFS.forEach((tariff) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = `promo-option${tariff.key === statePromotion.option ? " active" : ""}`;
      btn.dataset.option = tariff.key;
      btn.textContent = tariff.key === "2h" && freePromos > 0 ? `ТОП на ${tariff.label} — бесплатно (осталось ${freePromos})` : `ТОП на ${tariff.label} — ${tariff.cost} M‑Coin`;
      btn.addEventListener("click", () => {
        statePromotion.option = tariff.key;
        renderOptions();
        renderHint();
      });
      elements.promoOptions.appendChild(btn);
    });
  };

  const renderHint = () => {
    const tariff = TOP_TARIFFS.find((entry) => entry.key === statePromotion.option) || TOP_TARIFFS[0];
    let hint = isFree() ? `Бесплатное продвижение (останется ${freePromos - 1}). Длительность: ${tariff.label}.` : `Списание: ${tariff.cost} M‑Coin. Длительность: ${tariff.label}.`;
    let disable = false;

    if (item.is_top && remaining) {
      hint = `Уже в ТОПе: осталось ${remaining}.`;
      disable = true;
    } else if (!isFree() && state.mcoin < tariff.cost) {
      hint = `Недостаточно M‑Coin. Нужно ${tariff.cost}, у вас ${state.mcoin}.`;
      disable = true;
    } else if (topStatus && topStatus.queue_size >= topStatus.queue_limit) {
      hint = "Очередь заполнена. Попробуйте позже.";
      disable = true;
    } else if (topStatus) {
      const freeNote = isFree() ? ` Бесплатное продвижение (останется ${freePromos - 1}).` : "";
      if (topStatus.active_slots >= topStatus.slot_limit) {
        hint = `${slotsLine}. Объявление встанет в очередь. ${queueLine}.${freeNote}`;
      } else {
        hint = `${slotsLine}. ${queueLine}.${freeNote}`;
      }
    }

    if (elements.promoHint) {
      elements.promoHint.textContent = hint;
    }
    if (elements.promoConfirm) {
      elements.promoConfirm.disabled = disable;
      elements.promoConfirm.classList.toggle("disabled", disable);
    }
  };

  renderOptions();
  renderHint();
  elements.promoModal.classList.add("show");
}

async function openPromotionSelect() {
  const collectActiveItems = () =>
    (Array.isArray(stateMyListings.items) ? stateMyListings.items : []).filter((item) => item.status === "active");
  const fallbackItems = collectActiveItems();
  let items = fallbackItems;
  try {
    await loadMyListings();
    items = collectActiveItems();
  } catch (error) {
    console.warn("Failed to refresh my listings for promotion select", error);
    items = fallbackItems;
  }
  elements.promoSelectList.innerHTML = "";
  if (!items.length) {
    const empty = document.createElement("div");
    empty.className = "promo-select-empty";
    empty.innerHTML = `
      <div class="promo-select-empty-icon" aria-hidden="true">📭</div>
      <div class="promo-select-empty-title">Нет активных объявлений</div>
      <div class="promo-select-empty-text">В ТОП можно поднять только активное объявление. Создай его и вернись сюда.</div>
      <button class="action-btn primary" id="promoSelectCreate" type="button">Создать объявление</button>
    `;
    empty.querySelector("#promoSelectCreate").addEventListener("click", () => {
      elements.promoSelectModal.classList.remove("show");
      navigateTo("create");
    });
    elements.promoSelectList.appendChild(empty);
  } else {
    items.forEach((item) => {
      const inTop = Boolean(item.is_top);
      const btn = document.createElement("button");
      btn.className = `promo-pick${inTop ? " is-in-top" : ""}`;
      btn.type = "button";
      btn.disabled = inTop;
      const cover = CATEGORY_FALLBACK_COVERS[item.category] || "";
      const remaining = inTop ? formatTopRemaining(item.top_until) : "";
      const metaParts = [formatServer(item.server_id), item.category].filter((part) => part && part !== "—");
      btn.innerHTML = `
        <span class="promo-pick-thumb">${cover ? `<img src="${cover}" alt="" loading="lazy" />` : `<span>${escapeHtmlText((String(item.title || "").replace(/^[^\p{L}\p{N}]+/u, "").charAt(0) || "?").toUpperCase())}</span>`}</span>
        <span class="promo-pick-body">
          <span class="promo-pick-title">${escapeHtmlText(item.title || "Объявление")}${inTop ? `<span class="promo-pick-tag">уже в ТОПе${remaining ? ` · ${escapeHtmlText(remaining)}` : ""}</span>` : ""}</span>
          <span class="promo-pick-meta">${escapeHtmlText(metaParts.join(" · "))}</span>
          <span class="promo-pick-price">${formatPrice(item.price)} ₽</span>
        </span>
        <span class="promo-pick-go" aria-hidden="true">${inTop ? "" : "›"}</span>
      `;
      if (!inTop) {
        btn.addEventListener("click", () => {
          elements.promoSelectModal.classList.remove("show");
          openPromotionModal(item);
        });
      }
      elements.promoSelectList.appendChild(btn);
    });
  }
  elements.promoSelectModal.classList.add("show");
}

function formatDurationCompact(seconds) {
  const value = Math.max(0, Number(seconds || 0));
  const days = Math.floor(value / 86400);
  const hours = Math.floor((value % 86400) / 3600);
  const minutes = Math.floor((value % 3600) / 60);
  if (days > 0) return `${days}д ${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}`;
  return `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}`;
}

function formatTaskTimer(seconds) {
  const value = Math.max(0, Number(seconds || 0));
  const days = Math.floor(value / 86400);
  const hours = Math.floor((value % 86400) / 3600);
  const minutes = Math.floor((value % 3600) / 60);
  const secs = value % 60;
  const hms = `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}:${String(secs).padStart(2, "0")}`;
  if (days > 0) return `${days} д ${hms}`;
  return hms;
}

function stopMarketEventBannerTimer() {
  if (marketEventTimer) {
    clearInterval(marketEventTimer);
    marketEventTimer = null;
  }
}

function renderMarketEventBanner(event) {
  if (!elements.marketEventBanner) return;
  const visible = Boolean(event?.visible) && String(event?.status || "") !== "ended";
  if (!visible) {
    elements.marketEventBanner.hidden = true;
    stopMarketEventBannerTimer();
    return;
  }

  const target = Math.max(1, Number(event?.target || 1));
  const progress = Math.max(0, Math.min(target, Number(event?.progress || 0)));
  const title = String(event?.title || "Ивент");
  const status = String(event?.status || "");

  elements.marketEventBanner.hidden = false;
  elements.marketEventBanner.classList.toggle("is-ready", Boolean(event?.can_claim));
  elements.marketEventBanner.classList.toggle("is-submitted", status === "submitted");
  if (elements.marketEventTitle) {
    elements.marketEventTitle.textContent = title;
  }
  if (elements.marketEventProgress) {
    elements.marketEventProgress.textContent = `Прогресс: ${progress}/${target}`;
  }

  stopMarketEventBannerTimer();
  if (!elements.marketEventTimer) return;
  let secondsLeft = Math.max(0, Number(event?.seconds_left || 0));
  const render = () => {
    if (status === "submitted") {
      elements.marketEventTimer.textContent = "Заявка отправлена";
      return;
    }
    elements.marketEventTimer.textContent = `До конца: ${formatDurationDetailed(secondsLeft)} (МСК)`;
  };
  render();
  marketEventTimer = setInterval(() => {
    secondsLeft = Math.max(0, secondsLeft - 1);
    render();
    if (secondsLeft <= 0) {
      stopMarketEventBannerTimer();
      loadMarketEventBanner();
    }
  }, 1000);
}

async function loadMarketEventBanner() {
  if (!elements.marketEventBanner) return;
  try {
    const data = await apiRequest(withAuth("/api/tasks"));
    renderMarketEventBanner(data?.blogger_event || null);
  } catch {
    elements.marketEventBanner.hidden = true;
    stopMarketEventBannerTimer();
  }
}

function formatDurationDetailed(seconds) {
  const value = Math.max(0, Number(seconds || 0));
  const days = Math.floor(value / 86400);
  const hours = Math.floor((value % 86400) / 3600);
  const minutes = Math.floor((value % 3600) / 60);
  const secs = Math.floor(value % 60);
  if (days > 0) {
    return `${days}д ${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}:${String(secs).padStart(2, "0")}`;
  }
  return `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}:${String(secs).padStart(2, "0")}`;
}

function stopBloggerEventTimer() {
  if (bloggerEventTimer) {
    clearInterval(bloggerEventTimer);
    bloggerEventTimer = null;
  }
}

function renderBloggerEventCard(data) {
  if (!elements.bloggerEventCard) return;
  const event = data?.blogger_event || null;
  if (!event || !event.visible) {
    elements.bloggerEventCard.classList.add("hidden");
    stopBloggerEventTimer();
    stateCoins.bloggerEventReady = false;
    updateCoinsTileBadges();
    return;
  }

  elements.bloggerEventCard.classList.remove("hidden");
  const target = Math.max(1, Number(event.target || 5));
  stateCoins.bloggerEventTarget = target;
  const progress = Math.max(0, Math.min(target, Number(event.progress || 0)));
  const progressPct = Math.max(0, Math.min(100, Math.round((progress / target) * 100)));
  const status = String(event.status || "in_progress");
  const canClaim = Boolean(event.can_claim);
  const isSubmitted = Boolean(event.submitted);
  const isEnded = status === "ended";
  const countdownEnabled = status !== "ended" && status !== "submitted";

  if (elements.bloggerEventProgressFill) {
    elements.bloggerEventProgressFill.style.width = `${progressPct}%`;
  }
  if (elements.bloggerEventProgressText) {
    elements.bloggerEventProgressText.textContent = `Прогресс: ${progress}/${target}`;
  }
  if (elements.bloggerEventClaimBtn) {
    elements.bloggerEventClaimBtn.disabled = !canClaim;
    elements.bloggerEventClaimBtn.classList.toggle("is-glow", canClaim);
    elements.bloggerEventClaimBtn.textContent = isSubmitted ? "Заявка отправлена" : "Забрать награду";
  }
  if (elements.bloggerEventHint) {
    const hint = String(event.hint || "");
    elements.bloggerEventHint.textContent = hint || (isEnded ? "Ивент завершён." : `Когда наберёшь ${target}/${target} — нажми «Забрать награду»`);
  }

  elements.bloggerEventCard.classList.toggle("is-ready", canClaim);
  elements.bloggerEventCard.classList.toggle("is-submitted", isSubmitted);
  elements.bloggerEventCard.classList.toggle("is-ended", isEnded);

  stopBloggerEventTimer();
  if (!elements.bloggerEventTimer) return;
  let secondsLeft = Math.max(0, Number(event.seconds_left || 0));
  const renderTimer = () => {
    if (status === "submitted") {
      elements.bloggerEventTimer.textContent = "Заявка отправлена в проверку";
      return;
    }
    if (status === "ended" || secondsLeft <= 0) {
      elements.bloggerEventTimer.textContent = "Ивент завершён";
      return;
    }
    elements.bloggerEventTimer.textContent = `До конца ивента: ${formatDurationDetailed(secondsLeft)} (МСК)`;
  };

  renderTimer();
  if (!countdownEnabled) return;
  bloggerEventTimer = setInterval(() => {
    secondsLeft = Math.max(0, secondsLeft - 1);
    renderTimer();
    if (secondsLeft <= 0) {
      stopBloggerEventTimer();
      loadWeeklyTasks({ force: true });
    }
  }, 1000);

  stateCoins.bloggerEventReady = canClaim;
  updateCoinsTileBadges();
}

function openTelegramUrl(url) {
  const target = String(url || "").trim();
  if (!target) return;
  try {
    if (window.Telegram?.WebApp?.openTelegramLink && target.startsWith("https://t.me/")) {
      window.Telegram.WebApp.openTelegramLink(target);
      return;
    }
  } catch {
    // fall through
  }
  try {
    window.open(target, "_blank", "noopener");
  } catch {
    // ignore
  }
}

function stopDailyTasksTimer() {
  if (dailyTasksTimer) {
    clearInterval(dailyTasksTimer);
    dailyTasksTimer = null;
  }
}

function stopWeeklyTasksTimer() {
  if (weeklyTasksTimer) {
    clearInterval(weeklyTasksTimer);
    weeklyTasksTimer = null;
  }
}

const TASK_CHECK_ERROR_TEXT = "Не удалось проверить подписку: Telegram не ответил. Нажмите ещё раз.";

function renderDailyTasks(data) {
  if (!elements.dailyTaskList || !elements.dailyTaskTimer) return;
  const dailyTasks = data?.daily_tasks || {};
  const visibleTaskKeys = new Set(["subscribe_market_news", "subscribe_market_chat", "subscribe_kuz1111"]);
  const tasks = Array.isArray(dailyTasks?.tasks)
    ? dailyTasks.tasks.filter((task) => visibleTaskKeys.has(String(task?.key || "")))
    : [];
  let secondsLeft = Math.max(0, Number(dailyTasks?.seconds_left || 0));
  const timerMain = elements.dailyTaskTimer.querySelector(".tasks-timer-main");
  const renderTimer = () => {
    const text = formatTaskTimer(secondsLeft);
    if (timerMain) timerMain.textContent = text;
    else elements.dailyTaskTimer.textContent = text;
  };

  stopDailyTasksTimer();
  renderTimer();
  dailyTasksTimer = setInterval(() => {
    secondsLeft = Math.max(0, secondsLeft - 1);
    renderTimer();
    if (secondsLeft <= 0) {
      stopDailyTasksTimer();
      loadWeeklyTasks({ force: true });
    }
  }, 1000);

  elements.dailyTaskList.innerHTML = "";
  if (!tasks.length) {
    elements.dailyTaskList.innerHTML = "<div class='empty-state' style='display:block'>Задания появятся позже.</div>";
    stateCoins.dailyTasksClaimableSum = 0;
    return;
  }

  const claimable = tasks.filter((task) => (task?.status || "") === "claimable");
  stateCoins.dailyTasksClaimableSum = claimable.reduce((sum, task) => sum + Number(task?.reward || 0), 0);
  tasks.forEach((task) => {
    const taskKey = String(task?.key || "");
    const progress = Number(task?.progress || 0);
    const target = Math.max(1, Number(task?.target || 1));
    const reward = Number(task?.reward || 0);
    const progressPct = Math.max(0, Math.min(100, Math.round((progress / target) * 100)));
    const status = String(task?.status || "available");
    const kind = String(task?.kind || "");
    const isSubscriptionTask = kind === "telegram_subscription";
    const isLinkOpenTask = kind === "telegram_link_open";
    const isClaimable = status === "claimable";
    const isClaimed = status === "claimed";
    if (isClaimed) {
      setDailySubscriptionPending(taskKey, false);
    }
    const pendingVerify = Boolean(stateCoins.dailySubscriptionPending[taskKey]);
    const canClaim = isClaimable && !isClaimed;
    const canLinkOpen = isLinkOpenTask && !canClaim && !isClaimed && !pendingVerify;
    const canLinkVerify = isLinkOpenTask && !canClaim && !isClaimed && pendingVerify;
    const canSubscribe = isSubscriptionTask && !canClaim && !isClaimed && !pendingVerify;
    const canVerify = isSubscriptionTask && !canClaim && !isClaimed && pendingVerify;
    const statusText = isClaimed
      ? "Получено"
      : canLinkOpen
          ? "Открыть"
          : canSubscribe
            ? "Подписаться"
            : canLinkVerify || canVerify
              ? "Проверить"
              : isClaimable
                ? "Забрать"
                : "Забрать";
    const linkUrl = String(task?.link_url || "").trim();
    const linkBtn = linkUrl && !isClaimed && !isSubscriptionTask && !isLinkOpenTask
      ? `<button class="task-link-btn" type="button" data-link-url="${linkUrl}">${task?.link_label || "Открыть"}</button>`
      : "";
    const card = document.createElement("div");
    card.className = `task-card task-card--compact${isClaimed ? " done" : ""}${isClaimable ? " ready" : ""}`;
    card.innerHTML = `
      <div class="task-check${isClaimed ? " is-done" : ""}" aria-hidden="true">${isClaimed ? "✓" : ""}</div>
      <div class="task-main">
        <div class="task-title">${task?.title || "Задание"}</div>
        <div class="task-meta">+${reward} <span class="task-coin-icon" aria-hidden="true"></span>${target > 1 && !isClaimed ? `<span class="task-prog">${Math.min(progress, target)}/${target}</span>` : ""}</div>
        <div class="task-progress task-progress--compact">
          <div class="task-progress-track">
            <div class="task-progress-fill" style="width:${progressPct}%"></div>
          </div>
        </div>
      </div>
      <div class="task-actions-right">
        <button class="task-row-claim-btn" type="button" ${(canClaim || canVerify || canSubscribe || canLinkOpen || canLinkVerify) ? "" : "disabled"} data-task-key="${taskKey}">
          ${statusText}
        </button>
        <div class="task-link-wrap">
          ${linkBtn}
        </div>
      </div>
    `;
    const claimButton = card.querySelector(".task-row-claim-btn");
    if (claimButton && (canClaim || canVerify || canSubscribe || canLinkOpen || canLinkVerify)) {
      claimButton.addEventListener("click", async () => {
        claimButton.disabled = true;
        try {
          if (canClaim) {
            if (isSubscriptionTask || isLinkOpenTask) {
              const checkResult = await apiRequest(withAuth("/api/tasks/daily-task/check"), {
                method: "POST",
                body: JSON.stringify({ task_key: taskKey }),
              });
              const checkedStatus = String(checkResult?.task?.status || "");
              if (checkedStatus === "claimed") {
                setDailySubscriptionPending(taskKey, false);
                showToast("Награда уже получена.", "info");
                return;
              }
              if (checkResult?.task?.check_error) {
                showToast(TASK_CHECK_ERROR_TEXT, "info");
                return;
              }
              if (checkedStatus !== "claimable") {
                showToast("Задание пока не выполнено.", "info");
                return;
              }
            }
            await apiRequest(withAuth("/api/tasks/daily-task/claim"), {
              method: "POST",
              body: JSON.stringify({ task_key: taskKey }),
            });
            setDailySubscriptionPending(taskKey, false);
            showToast(`✅ +${formatPrice(reward)} M‑Coin`, "success");
            await loadProfile();
          } else if (canLinkOpen) {
            setDailySubscriptionPending(taskKey, true);
            if (linkUrl) openTelegramUrl(linkUrl);
            showToast("После открытия ссылки нажмите «Проверить».", "info");
          } else if (canLinkVerify) {
            const checkResult = await apiRequest(withAuth("/api/tasks/daily-task/check"), {
              method: "POST",
              body: JSON.stringify({ task_key: taskKey }),
            });
            const checkedStatus = String(checkResult?.task?.status || "");
            if (checkedStatus === "claimed") {
              setDailySubscriptionPending(taskKey, false);
              showToast("Награда уже получена.", "info");
              return;
            }
            if (checkedStatus !== "claimable") {
              showToast("Задание пока не выполнено.", "info");
              return;
            }
            await apiRequest(withAuth("/api/tasks/daily-task/claim"), {
              method: "POST",
              body: JSON.stringify({ task_key: taskKey }),
            });
            setDailySubscriptionPending(taskKey, false);
            showToast(`✅ +${formatPrice(reward)} M‑Coin`, "success");
            await loadProfile();
          } else if (canSubscribe) {
            setDailySubscriptionPending(taskKey, true);
            if (linkUrl) openTelegramUrl(linkUrl);
            showToast("После вступления нажмите «Проверить».", "info");
          } else if (canVerify) {
            const checkResult = await apiRequest(withAuth("/api/tasks/daily-task/check"), {
              method: "POST",
              body: JSON.stringify({ task_key: taskKey }),
            });
            const checkedStatus = String(checkResult?.task?.status || "");
            if (checkedStatus === "claimed") {
              setDailySubscriptionPending(taskKey, false);
              showToast("Награда уже получена.", "info");
              return;
            }
            if (checkResult?.task?.check_error) {
              // Telegram did not answer: it does NOT mean «не подписан». Stay on «Проверить» so the person just presses it again.
              showToast(TASK_CHECK_ERROR_TEXT, "info");
              return;
            }
            if (checkedStatus !== "claimable") {
              setDailySubscriptionPending(taskKey, false); // reset → button returns to "Подписаться"
              showToast("Подписка не найдена. Вступите в канал и нажмите «Проверить» ещё раз.", "info");
              return;
            }
            await apiRequest(withAuth("/api/tasks/daily-task/claim"), {
              method: "POST",
              body: JSON.stringify({ task_key: taskKey }),
            });
            setDailySubscriptionPending(taskKey, false);
            showToast(`✅ +${formatPrice(reward)} M‑Coin`, "success");
            await loadProfile();
          } else {
            showToast("Сначала откройте задание и вернитесь для проверки.", "info");
          }
        } catch (error) {
          const code = error?.payload?.error;
          if (code === "already_claimed") {
            setDailySubscriptionPending(taskKey, false);
            showToast("Награда уже получена.", "info");
          } else if (code === "not_ready") {
            showToast("Задание пока не выполнено.", "info");
          } else if (code === "check_failed") {
            showToast(TASK_CHECK_ERROR_TEXT, "info");
          } else {
            showToast(canClaim ? "Не удалось получить награду." : "Не удалось проверить выполнение задания.", "danger");
          }
        } finally {
          await loadWeeklyTasks({ force: true });
        }
      });
    }
    const linkButton = card.querySelector(".task-link-btn");
    if (linkButton) {
      linkButton.addEventListener("click", () => {
        openTelegramUrl(linkUrl);
      });
    }
    elements.dailyTaskList.appendChild(card);
  });
}

function renderDailyLogin(data) {
  if (!elements.dailyLoginCard || !elements.dailyLoginDays || !elements.dailyLoginHint || !elements.dailyLoginClaimBtn) return;
  const daily = data?.daily_login || {};
  const days = Array.isArray(daily.days) ? daily.days : [];
  const claimedToday = Boolean(daily.claimed_today);
  const canClaim = Boolean(daily.can_claim);
  const currentClaimDay = Math.max(1, Math.min(7, Number(daily.current_claim_day || 1)));
  const currentStreak = Math.max(0, Number(daily.streak_day || 0));
  const rewardTitle = String(daily.reward_title || "");
  const weekdayLabels = ["Пн", "Вт", "Ср", "Чт", "Пт", "Сб", "Вс"];
  const totalClaims = Math.max(0, Number(daily.total_claims || 0));
  const showCard = true;

  elements.dailyLoginCard.style.display = showCard ? "" : "none";
  if (!showCard) return;

  if (elements.dailyLoginStreakValue) {
    elements.dailyLoginStreakValue.textContent = String(totalClaims);
  }

  elements.dailyLoginDays.innerHTML = "";
  if (!days.length) {
    const fallback = document.createElement("div");
    fallback.className = "daily-login-empty";
    fallback.textContent = "Ежедневные награды скоро появятся";
    elements.dailyLoginDays.appendChild(fallback);
  } else {
    days.forEach((item) => {
      const day = Number(item?.day || 0);
      const cell = document.createElement("div");
      const isDone = claimedToday ? day <= currentStreak : day <= currentStreak;
      const isCurrent = day === currentClaimDay;
      const isLabelDay = String(item?.kind || "") === "label";
      cell.className = `daily-login-day${isDone ? " is-done" : ""}${isCurrent ? " is-current" : ""}${isLabelDay ? " is-label" : ""}`;
      const labelIndex = Math.max(0, (day || 1) - 1) % weekdayLabels.length;
      const value = isDone ? "✦" : isCurrent ? "◉" : "·";
      cell.innerHTML = `
        <div class="daily-login-day-index">${weekdayLabels[labelIndex]}</div>
        <div class="daily-login-day-value">${value}</div>
      `;
      elements.dailyLoginDays.appendChild(cell);
    });
  }

  if (claimedToday) {
    elements.dailyLoginHint.textContent = `Получено \u2022 всего ${totalClaims} входов`;
    elements.dailyLoginClaimBtn.disabled = true;
    elements.dailyLoginClaimBtn.textContent = "Получено";
    return;
  }
  elements.dailyLoginHint.textContent = rewardTitle
    ? `Сегодня: ${rewardTitle}`
    : "Награда готова";
  elements.dailyLoginClaimBtn.disabled = !canClaim;
  elements.dailyLoginClaimBtn.textContent = canClaim ? "Забрать" : "Недоступно";
}

function closeDailyLoginModal() {
  if (!elements.dailyLoginModal) return;
  clearInterval(dailyLoginModalTimer);
  elements.dailyLoginModal.classList.remove("show");
  maybeOpenTournamentRewardModal();
  if (typeof maybeOpenSeasonPromo === "function") setTimeout(maybeOpenSeasonPromo, 350);
}

let dailyLoginModalTimer = null;

// time to the next 00:00 Moscow time (the day the daily reward is counted by)
function dailyLoginTimeLeftText() {
  const nowMs = Date.now();
  const msk = new Date(nowMs + 3 * 3600 * 1000);
  const nextMidnightMsk = Date.UTC(msk.getUTCFullYear(), msk.getUTCMonth(), msk.getUTCDate() + 1) - 3 * 3600 * 1000;
  const mins = Math.max(1, Math.ceil((nextMidnightMsk - nowMs) / 60000));
  return `${Math.floor(mins / 60)}ч ${String(mins % 60).padStart(2, "0")}м`;
}

function renderDailyLoginModal(daily, options = {}) {
  if (!elements.dailyLoginModalDays || !elements.dailyLoginModalHint || !elements.dailyLoginModalClaimBtn) return;
  const days = Array.isArray(daily?.days) ? daily.days : [];
  const claimedToday = Boolean(daily?.claimed_today);
  const canClaim = Boolean(daily?.can_claim);
  const currentClaimDay = Math.max(1, Math.min(7, Number(daily?.current_claim_day || 1)));
  const doneUpTo = Math.max(0, Number(daily?.streak_day || 0));
  const labelGranted = Boolean(daily?.label_granted);
  const labelTitle = String(daily?.label_title || "Маэстро");
  const rewardKind = String(daily?.reward_kind || "mcoin");
  const rewardAmount = Math.max(0, Number(daily?.reward_amount || 0));

  elements.dailyLoginModalStreakValue.textContent = String(currentClaimDay);
  const ring = document.getElementById("dailyLoginModalRing");
  if (ring) ring.style.setProperty("--p", `${Math.round((Math.min(7, doneUpTo) / 7) * 100)}%`);
  const sub = document.getElementById("dailyLoginModalSub");
  if (sub) {
    sub.textContent = `${currentClaimDay}-й день подряд${currentClaimDay < 7 && !labelGranted ? ` · 7-й день: лейбл «${labelTitle}»` : ""}`;
  }

  elements.dailyLoginModalDays.innerHTML = "";
  days.forEach((item) => {
    const day = Number(item?.day || 0);
    const isDone = day <= doneUpTo;
    const isToday = !claimedToday && day === currentClaimDay;
    const isNext = claimedToday && day === currentClaimDay + 1;
    const isLabelDay = String(item?.kind || "") === "label";
    const cell = document.createElement("div");
    cell.className = `dlm2-day${isDone ? " is-done" : ""}${isToday ? " is-today" : ""}${isNext ? " is-next" : ""}${isLabelDay ? " is-wide" : ""}${options.justClaimed && claimedToday && day === currentClaimDay ? " is-just-claimed" : ""}`;
    cell.dataset.day = String(day);
    if (isLabelDay) {
      cell.innerHTML = `<span class="dlm2-day-tag" aria-hidden="true">🏷️</span><div class="dlm2-day-text"><small>ДЕНЬ ${day}</small><b>Лейбл «${labelTitle}»</b><em>${labelGranted ? "уже получен, теперь" : "потом"} +${formatPrice(Number(String(item?.title || "").match(/\+(\d+)/)?.[1] || 30))} M‑Coin</em></div>`;
    } else {
      cell.innerHTML = `<small>ДЕНЬ ${day}</small><span class="dlm2-coin" aria-hidden="true">M</span><b>+${formatPrice(Number(item?.amount || 0))}</b>`;
    }
    elements.dailyLoginModalDays.appendChild(cell);
  });

  const btn = elements.dailyLoginModalClaimBtn;
  elements.dailyLoginModalHint.textContent = "";
  clearInterval(dailyLoginModalTimer);
  if (claimedToday) {
    btn.disabled = true;
    btn.classList.add("is-off");
    const setText = () => { btn.textContent = `Следующая награда через ${dailyLoginTimeLeftText()}`; };
    setText();
    dailyLoginModalTimer = setInterval(setText, 30000);
  } else {
    btn.disabled = !canClaim;
    btn.classList.remove("is-off");
    btn.textContent = rewardKind === "label" ? `Забрать лейбл «${labelTitle}»` : `Забрать +${formatPrice(rewardAmount)} M‑Coin`;
  }
}

function renderTournamentRewardItems(rewardData) {
  if (!elements.tournamentRewardModalRewards) return;
  const rewards = Array.isArray(rewardData?.rewards) ? rewardData.rewards : [];
  if (!rewards.length) {
    elements.tournamentRewardModalRewards.innerHTML = "";
    return;
  }
  elements.tournamentRewardModalRewards.innerHTML = rewards.map((item) => {
    const kind = String(item?.kind || "");
    const status = String(item?.status || "");
    const amount = Math.max(0, Number(item?.amount || 0));
    const isMarket = kind === "market_coin";
    const icon = isMarket ? "🪙" : "🎁";
    const itemClass = isMarket ? "tournament-reward-item tournament-reward-item--market" : "tournament-reward-item tournament-reward-item--matreshka";
    const title = isMarket
      ? `+${formatPrice(amount)} Market-Coin`
      : status === "granted"
        ? `+${formatPrice(amount)} MATRESHKA`
        : `${formatPrice(amount)} MATRESHKA`;
    const subtitle = isMarket
      ? "Начислено на баланс"
      : status === "granted"
        ? "Награда начислена на баланс"
        : "Заявка на выдачу доната оформлена";
    return `
      <div class="${itemClass}">
        <div class="tournament-reward-item__icon">${icon}</div>
        <div class="tournament-reward-item__content">
          <div class="tournament-reward-item__title">${escapeHtml(title)}</div>
          <div class="tournament-reward-item__subtitle">${escapeHtml(subtitle)}</div>
        </div>
      </div>
    `;
  }).join("");
}

function renderTournamentRewardModal(rewardData) {
  if (!elements.tournamentRewardModal) return;
  const place = Math.max(0, Number(rewardData?.place || 0));
  const pointsFinal = Math.max(0, Number(rewardData?.points_final || 0));
  const marketReward = Math.max(0, Number(rewardData?.reward_mcoin || 0));
  const matreshkaReward = Math.max(0, Number(rewardData?.reward_matreshka || 0));
  const pendingMatreshka = Math.max(0, Number(rewardData?.pending_matreshka || 0));
  if (elements.tournamentRewardModalPlace) {
    elements.tournamentRewardModalPlace.textContent = place > 0 ? `#${place}` : "—";
  }
  if (elements.tournamentRewardModalTitle) {
    elements.tournamentRewardModalTitle.textContent = "Награда турнира";
  }
  if (elements.tournamentRewardModalPoints) {
    elements.tournamentRewardModalPoints.textContent = `${formatPrice(pointsFinal)} Point`;
  }
  if (elements.tournamentRewardModalHint) {
    const parts = [];
    if (marketReward > 0) parts.push(`+${formatPrice(marketReward)} Market-Coin`);
    if (matreshkaReward > 0) parts.push(`+${formatPrice(matreshkaReward)} MATRESHKA`);
    if (pendingMatreshka > 0) parts.push(`${formatPrice(pendingMatreshka)} MATRESHKA ожидает выдачи`);
    const intro = place > 0 ? `Ты занял ${place} место.` : "Турнир завершён.";
    elements.tournamentRewardModalHint.textContent = parts.length ? `${intro} ${parts.join(" • ")}` : intro;
  }
  renderTournamentRewardItems(rewardData || {});
}

function closeTournamentRewardModal(options = {}) {
  const { defer = false } = options || {};
  if (!elements.tournamentRewardModal) return;
  elements.tournamentRewardModal.classList.remove("show");
  if (defer && activeTournamentRewardBanner) {
    pendingTournamentRewardBanner = activeTournamentRewardBanner;
  }
  activeTournamentRewardBanner = null;
  if (!defer && typeof maybeOpenSeasonPromo === "function") setTimeout(maybeOpenSeasonPromo, 350);
}

function openTournamentRewardModal(rewardData) {
  if (!elements.tournamentRewardModal || !rewardData) return;
  activeTournamentRewardBanner = rewardData;
  pendingTournamentRewardBanner = null;
  if (typeof closeSeasonPromo === "function") closeSeasonPromo(true);
  renderTournamentRewardModal(rewardData);
  elements.tournamentRewardModal.classList.add("show");
}

function maybeOpenTournamentRewardModal() {
  if (!pendingTournamentRewardBanner || !elements.tournamentRewardModal) return;
  if (elements.dailyLoginModal && elements.dailyLoginModal.classList.contains("show")) return;
  if (elements.tournamentRewardModal.classList.contains("show")) return;
  const rewardData = pendingTournamentRewardBanner;
  openTournamentRewardModal(rewardData);
}

function queueTournamentRewardModal(rewardData) {
  if (!rewardData || typeof rewardData !== "object") return;
  pendingTournamentRewardBanner = rewardData;
  if (tournamentRewardModalTimer) {
    window.clearTimeout(tournamentRewardModalTimer);
  }
  tournamentRewardModalTimer = window.setTimeout(() => {
    tournamentRewardModalTimer = null;
    maybeOpenTournamentRewardModal();
  }, 250);
}

function openDailyLoginModal(daily) {
  if (!elements.dailyLoginModal) return;
  if (elements.tournamentRewardModal && elements.tournamentRewardModal.classList.contains("show")) {
    closeTournamentRewardModal({ defer: true });
  }
  if (typeof closeSeasonPromo === "function") closeSeasonPromo(true);
  renderDailyLoginModal(daily || {});
  elements.dailyLoginModal.classList.add("show");
}

async function loadTasksPayload(options = {}) {
  const force = Boolean(options?.force);
  const now = Date.now();
  if (!force && tasksLoadInFlight) {
    return tasksLoadInFlight;
  }
  if (!force && tasksPayloadCache && now - tasksLoadedAtMs < TASKS_CACHE_TTL_MS) {
    return tasksPayloadCache;
  }
  const currentLoadPromise = apiRequest(withAuth("/api/tasks"));
  tasksLoadInFlight = currentLoadPromise;
  try {
    const data = await currentLoadPromise;
    tasksPayloadCache = data;
    tasksLoadedAtMs = Date.now();
    return data;
  } finally {
    if (tasksLoadInFlight === currentLoadPromise) {
      tasksLoadInFlight = null;
    }
  }
}

let dailyLoginPromptDone = false;

// The prompt must not appear under the boot loader or over the nickname screen, and a failed startup request must not lose it for the day
async function waitUntilDailyPromptAllowed() {
  for (let i = 0; i < 25; i += 1) {
    const busy = document.body.classList.contains("ui-loading") || state.page === "nickname" || document.querySelector(".modal.show");
    if (!busy) return true;
    await new Promise((resolve) => setTimeout(resolve, 600));
  }
  return false;
}

async function loadDailyLoginStatus(options = {}) {
  const { openModalIfClaimable = false } = options;
  try {
    const data = await loadTasksPayload();
    renderDailyLogin(data);
    const daily = data?.daily_login || {};
    if (openModalIfClaimable && daily?.can_claim && !dailyLoginPromptDone) {
      dailyLoginPromptDone = true;
      if (await waitUntilDailyPromptAllowed()) {
        openDailyLoginModal(daily);
      } else {
        dailyLoginPromptDone = false; // try again on the next start-up step
      }
    }
  } catch {
    // ignore at startup; app.js asks again once the profile is loaded
  }
}

function renderWeeklyTasks(data) {
  if (!elements.taskList || !elements.taskWeekTimer) return;
  let secondsLeft = Math.max(0, Number(data?.seconds_left || 0));
  const timerSpan = elements.taskWeekTimer.querySelector(".tasks-timer-main");
  const renderTimer = () => {
    const text = formatTaskTimer(secondsLeft);
    if (timerSpan) timerSpan.textContent = text;
    else elements.taskWeekTimer.textContent = text;
  };
  stopWeeklyTasksTimer();
  renderTimer();
  weeklyTasksTimer = setInterval(() => {
    secondsLeft = Math.max(0, secondsLeft - 1);
    renderTimer();
    if (secondsLeft <= 0) {
      stopWeeklyTasksTimer();
      loadWeeklyTasks({ force: true });
    }
  }, 1000);

  renderBloggerEventCard(data);
  renderDailyTasks(data);
  renderDailyLogin(data);

  const tasks = Array.isArray(data?.tasks) ? data.tasks : [];
  if (!tasks.length) {
    elements.taskList.innerHTML = "<div class='empty-state' style='display:block'>Задания появятся позже.</div>";
    return;
  }

  elements.taskList.innerHTML = "";
  const claimable = tasks.filter((task) => (task?.status || "") === "claimable");
  stateCoins.tasksClaimableSum = claimable.reduce((sum, task) => sum + Number(task?.reward || 0), 0);
  updateCoinsTileBadges();
  tasks.forEach((task) => {
    const progress = Number(task.progress || 0);
    const target = Number(task.target || 0);
    const reward = Number(task.reward || 0);
    const safeTarget = Math.max(1, target);
    const progressPct = Math.max(0, Math.min(100, Math.round((progress / safeTarget) * 100)));
    const status = task.status || "available";
    const isClaimable = status === "claimable";
    const isClaimed = status === "claimed";
    const card = document.createElement("div");
    card.className = `task-card task-card--compact${isClaimed ? " done" : ""}${isClaimable ? " ready" : ""}`;
    const statusText = isClaimed ? "Получено" : isClaimable ? "Забрать" : "Забрать";
    card.innerHTML = `
      <div class="task-check${isClaimed ? " is-done" : ""}" aria-hidden="true">${isClaimed ? "✓" : ""}</div>
      <div class="task-main">
        <div class="task-title">${task.title}</div>
        <div class="task-meta">+${reward} <span class="task-coin-icon" aria-hidden="true"></span>${safeTarget > 1 && !isClaimed ? `<span class="task-prog">${Math.min(progress, safeTarget)}/${safeTarget}</span>` : ""}</div>
        <div class="task-progress task-progress--compact">
          <div class="task-progress-track">
            <div class="task-progress-fill" style="width:${progressPct}%"></div>
          </div>
        </div>
      </div>
      <div class="task-actions-right">
        <button class="task-row-claim-btn" type="button" ${isClaimable ? "" : "disabled"} data-task-key="${task.key}">
          ${statusText}
        </button>
      </div>
    `;
    const claimButton = card.querySelector(".task-row-claim-btn");
    if (claimButton && isClaimable) {
      claimButton.addEventListener("click", async () => {
        claimButton.disabled = true;
        try {
          await apiRequest(withAuth("/api/tasks/claim"), {
            method: "POST",
            body: JSON.stringify({ task_key: task.key }),
          });
          showToast(`✅ +${formatPrice(reward)} M‑Coin`, "success");
          await loadProfile();
        } catch {
          showToast("Не удалось получить награду.", "danger");
        } finally {
          await loadWeeklyTasks({ force: true });
        }
      });
    }
    elements.taskList.appendChild(card);
  });
}

async function loadWeeklyTasks(options = {}) {
  if (!elements.taskList) return;
  try {
    const data = await loadTasksPayload(options);
    renderWeeklyTasks(data);
    maybeOpenTournamentRewardModal();
  } catch (error) {
    elements.taskList.innerHTML = "<div class='empty-state' style='display:block'>Не удалось загрузить задания.</div>";
    if (elements.dailyTaskList) {
      elements.dailyTaskList.innerHTML = "<div class='empty-state' style='display:block'>Не удалось загрузить ежедневные задания.</div>";
    }
    stateCoins.tasksClaimableSum = 0;
    stateCoins.dailyTasksClaimableSum = 0;
    stateCoins.bloggerEventReady = false;
    updateCoinsTileBadges();
    renderBloggerEventCard(null);
    stopDailyTasksTimer();
    stopWeeklyTasksTimer();
    if (elements.dailyTaskTimer) {
      const dailyTimerSpan = elements.dailyTaskTimer.querySelector(".tasks-timer-main");
      if (dailyTimerSpan) {
        dailyTimerSpan.textContent = "До конца дня: — (МСК)";
      } else {
        elements.dailyTaskTimer.textContent = "До конца дня: — (МСК)";
      }
    }
    if (elements.dailyTasksClaimBtn && elements.dailyTasksClaimHint) {
      elements.dailyTasksClaimBtn.disabled = true;
      elements.dailyTasksClaimHint.textContent = "Не удалось загрузить ежедневные задания";
    }
    if (elements.taskWeekTimer) {
      const timerSpan = elements.taskWeekTimer.querySelector(".tasks-timer-main");
      if (timerSpan) {
        timerSpan.textContent = "До конца недели: — (МСК)";
      } else {
        elements.taskWeekTimer.textContent = "До конца недели: — (МСК)";
      }
    }
    if (elements.tasksClaimBtn && elements.tasksClaimHint) {
      elements.tasksClaimBtn.disabled = true;
      elements.tasksClaimHint.textContent = "Не удалось загрузить задания";
    }
    maybeOpenTournamentRewardModal();
  }
}

async function claimDailyLogin(options = {}) {
  const { silentAlready = false, skipProfileReload = false } = options;
  const response = await apiRequest(withAuth("/api/tasks/daily/claim"), {
    method: "POST",
    body: JSON.stringify({}),
  });
  if (response?.daily_login) {
    renderDailyLogin(response.daily_login);
  }
  if (!response?.claimed) {
    if (!silentAlready && !response?.already_claimed) {
      showToast("Сегодняшнюю награду забрать не удалось.", "danger");
    }
    if (response?.daily_login) {
      renderDailyLoginModal(response.daily_login);
    }
    return response;
  }
  if (!skipProfileReload) {
    await loadProfile();
  } else if (typeof response?.balance === "number") {
    applyMcoinBalance(Number(response.balance));
  }
  const toastText =
    response.reward_kind === "label"
      ? "Ежедневный вход: получен лейбл «Маэстро»"
      : `✅ Ежедневный вход: +${formatPrice(Number(response.reward_amount || 0))} M-Coin`;
  showToast(toastText, "success");
  if (response?.daily_login) {
    renderDailyLoginModal(response.daily_login, { justClaimed: true });
  }
  return response;
}

function startEditListing(item, options = {}) {
  const scope = String(options && options.scope ? options.scope : "owner");
  const canEditPriceAndDescription = !(scope === "moderation" && !isDeveloperRole(stateAdmin.role));
  const editingId = Number(item?.id || 0) || 0;
  const sourcePage = String((options && options.returnPage) || state.page || "profile");
  const listingType = item?.listing_type === "buy" ? "buy" : "sell";
  stateMyListings.editing = item.id;
  stateMyListings.editingStatus = item.status;
  stateMyListings.editingScope = scope;
  stateMyListings.editingReadOnlyFields = !canEditPriceAndDescription;
  stateMyListings.editingReturnPage = sourcePage;
  stateMyListings.editingReturnScrollY = Math.max(0, Number(window.scrollY || 0));
  stateMyListings.editingReturnListingId = editingId > 0 ? editingId : null;
  stateCreate.category = item.category;
  stateCreate.listingType = listingType;
  elements.createCategoryInput.value = item.category;
  setCreateListingType(listingType);
  setActivePill(elements.createCategoryPills, item.category);
  elements.createCategoryPills.dataset.locked = "false";
  elements.createCategoryPills.classList.remove("locked");
  elements.createForm.querySelector("input[name='title']").value = item.title;
  elements.priceInput.value = formatPrice(item.price);
  elements.priceInput.dataset.raw = String(item.price);
  const descriptionEl = elements.createForm.querySelector("textarea[name='description']");
  if (descriptionEl) {
    descriptionEl.value = item.description || "";
    descriptionEl.disabled = !canEditPriceAndDescription;
  }
  if (elements.priceInput) {
    elements.priceInput.disabled = !canEditPriceAndDescription;
  }
  if (elements.createServerInput) {
    elements.createServerInput.value = String(item.server_id || "");
  }
  if (elements.createServerPicker) {
    elements.createServerPicker.disabled = true;
  }
  updateCreateServerPicker();
  if (scope === "moderation") {
    elements.createSubmit.textContent = "Сохранить правки";
  } else {
    elements.createSubmit.textContent = item.status === "rejected" ? "Опубликовать снова" : "Сохранить";
  }
  stateCreate.editPhotosLoadId = Number(stateCreate.editPhotosLoadId || 0) + 1;
  const photosLoadId = stateCreate.editPhotosLoadId;
  createPhotos.length = 0;
  renderPhotoGrid();
  if (editingId > 0) {
    void (async () => {
      try {
        const response = await apiRequest(withAuth(`/api/listings/${editingId}/images`));
        if (stateCreate.editPhotosLoadId !== photosLoadId || Number(stateMyListings.editing || 0) !== editingId) return;
        const images = Array.isArray(response?.images) ? response.images : [];
        createPhotos.length = 0;
        images.slice(0, MAX_PHOTOS).forEach((src) => {
          if (typeof src === "string" && src.trim()) {
            createPhotos.push(src.trim());
          }
        });
        renderPhotoGrid();
      } catch (error) {
        // Keep editor usable even if images endpoint is temporarily unavailable.
        console.warn("Failed to load listing images for edit", error);
      }
    })();
  }
  navigateTo("create");
}

function resetCreateForm() {
  document.dispatchEvent(new Event("rp-create-reset"));
  stateCreate.editPhotosLoadId = Number(stateCreate.editPhotosLoadId || 0) + 1;
  stateMyListings.editing = null;
  stateMyListings.editingStatus = null;
  stateMyListings.editingScope = "owner";
  stateMyListings.editingReadOnlyFields = false;
  stateMyListings.editingReturnPage = "profile";
  stateMyListings.editingReturnScrollY = 0;
  stateMyListings.editingReturnListingId = null;
  stateCreate.category = "";
  stateCreate.listingType = "sell";
  elements.createCategoryInput.value = "";
  elements.createCategoryPills.dataset.locked = "false";
  elements.createCategoryPills.classList.remove("locked");
  setActivePill(elements.createCategoryPills, "");
  setCreateListingType("sell");
  if (elements.createServerPicker) {
    elements.createServerPicker.disabled = false;
  }
  if (elements.priceInput) {
    elements.priceInput.disabled = false;
  }
  const descriptionEl = elements.createForm ? elements.createForm.querySelector("textarea[name='description']") : null;
  if (descriptionEl) {
    descriptionEl.disabled = false;
  }
  updateCreateServerPicker();
  elements.createSubmit.textContent = "Опубликовать";
  createPhotos.length = 0;
  renderPhotoGrid();
}

function restoreListingPositionAfterEdit(page, listingId, scrollY) {
  const targetPage = String(page || "");
  const targetListingId = Number(listingId || 0) || 0;
  const targetScrollY = Math.max(0, Number(scrollY || 0));
  let tries = 0;
  const maxTries = 8;

  const attemptRestore = () => {
    tries += 1;
    if ((targetPage === "profile" || targetPage === "admin") && targetListingId > 0) {
      const card = document.querySelector(`.listing-item[data-listing-id="${targetListingId}"]`);
      if (card) {
        card.scrollIntoView({ block: "center", behavior: "auto" });
        return;
      }
      if (tries < maxTries) {
        requestAnimationFrame(attemptRestore);
        return;
      }
    }
    window.scrollTo({ top: targetScrollY, behavior: "auto" });
  };

  requestAnimationFrame(() => {
    requestAnimationFrame(attemptRestore);
  });
}

function getFiltersSummary() {
  const serverLabel = stateFilters.serverId ? `Сервер ${stateFilters.serverId}` : "Все серверы";
  const categoryLabel = stateFilters.category || "Все категории";
  const typeLabel =
    stateFilters.listingType === "buy"
      ? "Покупка"
      : stateFilters.listingType === "sell"
        ? "Продажа"
        : "Все типы";
  return `Фильтры: ${serverLabel} · ${categoryLabel} · ${typeLabel}`;
}

function setMarketListingTypeFilter(listingType) {
  const normalized = listingType === "buy" || listingType === "sell" ? listingType : "all";
  stateFilters.listingType = normalized;
  if (!elements.marketTypeSwitch) return;
  elements.marketTypeSwitch.querySelectorAll("[data-market-type]").forEach((button) => {
    button.classList.toggle("active", button.dataset.marketType === normalized);
  });
  syncMarketTypeIndicator();
}

// The active chip's pill slides to the new chip (mini-app only; on the desktop site the chips are separate buttons).
let marketTypeIndicatorObserver = null;
function syncMarketTypeIndicator() {
  const seg = elements.marketTypeSwitch && elements.marketTypeSwitch.querySelector(".market-type-seg");
  if (!seg) return;
  if (!marketTypeIndicatorObserver && typeof ResizeObserver === "function") {
    // the page may be hidden when the filter is set: measure again as soon as the control gets a size
    marketTypeIndicatorObserver = new ResizeObserver(() => syncMarketTypeIndicator());
    marketTypeIndicatorObserver.observe(seg);
  }
  const active = seg.querySelector(".market-type-chip.active");
  if (!active || getComputedStyle(seg).display === "contents" || !active.offsetWidth) return;
  seg.style.setProperty("--seg-x", `${active.offsetLeft}px`);
  seg.style.setProperty("--seg-w", `${active.offsetWidth}px`);
  const first = !seg.classList.contains("has-indicator");
  seg.classList.add("has-indicator");
  // no slide from the left edge on the first measurement
  if (first) requestAnimationFrame(() => requestAnimationFrame(() => seg.classList.add("is-ready")));
}

// Switching Все / Купить / Продать (or any filter): keep the old list on screen, dim it, hold its height, then cross-fade
// into the new one instead of a hard swap.
let marketSwitchTimer = null;
let marketSwitchDimTimer = null;
function marketListBeginSwitch() {
  const list = elements.marketList;
  if (!list || !list.childElementCount) return;
  clearTimeout(marketSwitchTimer);
  clearTimeout(marketSwitchDimTimer);
  list.style.minHeight = `${Math.round(list.getBoundingClientRect().height)}px`;
  // a fast answer swaps the list with no dimming at all; only a slow one shows the "loading" dim
  marketSwitchDimTimer = setTimeout(() => list.classList.add("is-switching"), 380);
}

function marketListEndSwitch() {
  const list = elements.marketList;
  if (!list) return;
  clearTimeout(marketSwitchDimTimer);
  list.classList.remove("is-switching");
  clearTimeout(marketSwitchTimer);
  marketSwitchTimer = setTimeout(() => {
    list.style.minHeight = "";
  }, 260);
}

function setCreateListingType(listingType) {
  const normalized = listingType === "buy" ? "buy" : "sell";
  stateCreate.listingType = normalized;
  if (elements.createListingTypeInput) {
    elements.createListingTypeInput.value = normalized;
  }
  // «Куплю» only (and only for a new listing): the checkbox «tell me when someone posts a matching «Продам»»
  const watchRow = document.getElementById("createWatchRow");
  if (watchRow) watchRow.hidden = !(normalized === "buy" && !stateMyListings.editing);
  if (!elements.createTypeSwitch) return;
  elements.createTypeSwitch.querySelectorAll("[data-create-type]").forEach((button) => {
    button.classList.toggle("active", button.dataset.createType === normalized);
  });
}

function parseServerId(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
}

function persistMarketServerFilter() {
  if (stateFilters.serverId) {
    localStorage.setItem(MARKET_SERVER_FILTER_KEY, String(stateFilters.serverId));
    return;
  }
  localStorage.setItem(MARKET_SERVER_FILTER_KEY, "__all__");
}

function setMarketServerFilter(serverId, options = {}) {
  stateFilters.serverId = parseServerId(serverId);
  if (options.persist !== false) {
    persistMarketServerFilter();
  }
}

function restoreMarketServerFilter() {
  const raw = localStorage.getItem(MARKET_SERVER_FILTER_KEY);
  if (raw === null) return false;
  if (raw === "__all__") {
    stateFilters.serverId = null;
    return true;
  }
  const parsed = parseServerId(raw);
  if (parsed) {
    stateFilters.serverId = parsed;
    return true;
  }
  localStorage.removeItem(MARKET_SERVER_FILTER_KEY);
  return false;
}

function ensureDefaultMarketServerFilter() {
  if (localStorage.getItem(MARKET_SERVER_FILTER_KEY) !== null) return;
  if (state.serverId) {
    setMarketServerFilter(state.serverId);
  }
  setMarketListingTypeFilter(stateFilters.listingType);
}

function updateFiltersBar() {
  if (!elements.marketFiltersBar || !elements.marketFiltersText) return;
  setMarketListingTypeFilter(stateFilters.listingType);
  elements.marketFiltersText.textContent = getFiltersSummary();
  
  // Update filter badge count
  const badge = document.getElementById("marketFilterBadge");
  if (badge) {
    let activeCount = 0;
    if (stateFilters.category) activeCount++;
    if (stateFilters.listingType && stateFilters.listingType !== "all") activeCount++;
    // Server is always selected, so we don't count it
    badge.textContent = activeCount > 0 ? activeCount : "";
  }
}

function showServerModal(source = null) {
  stateServerPicker.source = source;
  elements.serverModal.classList.add("show");
}

function hideServerModal() {
  stateServerPicker.source = null;
  elements.serverModal.classList.remove("show");
}

function formatFiltersApplyLabel(total) {
  const n = Math.max(0, Number(total) || 0);
  if (n === 0) return "Нет объявлений";
  const mod10 = n % 10;
  const mod100 = n % 100;
  const word = mod10 === 1 && mod100 !== 11 ? "объявление" : (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14) ? "объявления" : "объявлений");
  return `Показать ${n} ${word}`;
}

let filtersCountTimer = null;
let filtersCountController = null;
function scheduleFiltersApplyCount() {
  const btn = elements.filtersApply;
  if (!btn) return;
  clearTimeout(filtersCountTimer);
  filtersCountTimer = setTimeout(async () => {
    if (filtersCountController) filtersCountController.abort();
    const controller = new AbortController();
    filtersCountController = controller;
    try {
      const params = buildMarketListParams();
      params.set("paged", "1");
      params.set("limit", "1");
      params.set("offset", "0");
      params.set("include_total", "1");
      const payload = await apiRequest(`/api/listings?${params.toString()}`, { signal: controller.signal });
      if (controller.signal.aborted || !elements.filtersModal.classList.contains("show")) return;
      const items = Array.isArray(payload?.items) ? payload.items : [];
      btn.textContent = formatFiltersApplyLabel(resolveMarketTotal(payload, items));
    } catch (error) {
      // the count is a hint only: keep a plain label when it cannot be loaded
      if (!isAbortError(error)) btn.textContent = "Применить";
    }
  }, 220);
}

function openFiltersModal() {
  if (!elements.filtersModal) return;
  updateFilterServerButtons();
  setActivePill(elements.filterCategoryPills, stateFilters.category);
  elements.filtersModal.classList.add("show");
  scheduleFiltersApplyCount();
}

function closeFiltersModal() {
  if (!elements.filtersModal) return;
  elements.filtersModal.classList.remove("show");
}

function updateFilterServerButtons() {
  if (!elements.filterServerGrid) return;
  elements.filterServerGrid.querySelectorAll(".server-btn").forEach((btn) => {
    if (btn.dataset.value === "my") {
      btn.classList.toggle(
        "active",
        Boolean(state.serverId) && Number(stateFilters.serverId || 0) === Number(state.serverId || 0)
      );
      return;
    }
    btn.classList.toggle("active", Number(btn.dataset.value) === Number(stateFilters.serverId || 0));
  });
}

function updateCreateServerPicker() {
  if (!elements.createServerInput || !elements.createServerPicker) return;
  const selected = parseServerId(elements.createServerInput.value) || state.serverId || null;
  elements.createServerInput.value = selected ? String(selected) : "";
  elements.createServerPicker.textContent = selected ? `Сервер ${selected}` : "Сервер по умолчанию";
}

function updateNicknameServerPicker() {
  if (!elements.nicknameServerInput || !elements.nicknameServerPicker) return;
  const selected = parseServerId(elements.nicknameServerInput.value) || state.serverId || null;
  elements.nicknameServerInput.value = selected ? String(selected) : "";
  elements.nicknameServerPicker.textContent = selected ? `Сервер ${selected}` : "Выбери сервер";
  renderNicknameServerTiles(selected);
}

function renderNicknameServerTiles(selected) {
  const grid = document.getElementById("nicknameServerGrid");
  if (!grid) return;
  const servers = Array.isArray(state.servers) ? state.servers : [];
  const key = `${servers.join(",")}|${selected || ""}`;
  if (grid.dataset.key === key) return;
  grid.dataset.key = key;
  grid.innerHTML = "";
  servers.forEach((serverId) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = `nickname-server-btn${Number(serverId) === Number(selected) ? " active" : ""}`;
    btn.dataset.value = String(serverId);
    btn.textContent = String(serverId);
    btn.addEventListener("click", () => {
      if (elements.nicknameServerInput) elements.nicknameServerInput.value = String(serverId);
      updateNicknameServerPicker();
      if (typeof scheduleNicknamePageCheck === "function") scheduleNicknamePageCheck();
    });
    grid.appendChild(btn);
  });
}

function updateEditProfileServerPicker() {
  if (!elements.editServerInput || !elements.editServerPicker) return;
  const selected = parseServerId(elements.editServerInput.value) || state.serverId || null;
  elements.editServerInput.value = selected ? String(selected) : "";
  elements.editServerPicker.textContent = selected ? `Сервер ${selected}` : "Выбери сервер";
}

function populateFilterServers(servers) {
  if (!elements.filterServerGrid) return;
  elements.filterServerGrid.innerHTML = "";
  const allBtn = document.createElement("button");
  allBtn.className = "server-btn";
  allBtn.type = "button";
  allBtn.dataset.value = "0";
  allBtn.textContent = "Все серверы";
  allBtn.addEventListener("click", () => {
    setMarketServerFilter(null);
    updateFilterServerButtons();
  });
  elements.filterServerGrid.appendChild(allBtn);
  const myBtn = document.createElement("button");
  myBtn.className = "server-btn";
  myBtn.type = "button";
  myBtn.dataset.value = "my";
  myBtn.textContent = "Мой сервер";
  myBtn.addEventListener("click", () => {
    if (!state.serverId) {
      alert("Сначала выберите сервер по умолчанию в профиле.");
      return;
    }
    setMarketServerFilter(state.serverId);
    updateFilterServerButtons();
  });
  elements.filterServerGrid.appendChild(myBtn);
  servers.forEach((serverId) => {
    const btn = document.createElement("button");
    btn.className = "server-btn";
    btn.type = "button";
    btn.dataset.value = String(serverId);
    btn.textContent = String(serverId); // the "Сервер" label sits above the row
    btn.addEventListener("click", () => {
      setMarketServerFilter(serverId);
      updateFilterServerButtons();
    });
    elements.filterServerGrid.appendChild(btn);
  });
  updateFilterServerButtons();
}

async function loadServers() {
  const servers = await apiRequest("/api/servers");
  state.servers = Array.isArray(servers) ? servers : [];
  elements.serverGrid.innerHTML = "";
  populateFilterServers(state.servers);
  updateCreateServerPicker();
  updateNicknameServerPicker();
  updateEditProfileServerPicker();
  state.servers.forEach((serverId) => {
    const btn = document.createElement("button");
    btn.className = "server-btn";
    btn.textContent = `Сервер ${serverId}`;
    btn.addEventListener("click", async () => {
      if (stateServerPicker.source === "create") {
        if (elements.createServerInput) {
          elements.createServerInput.value = String(serverId);
        }
        updateCreateServerPicker();
        hideServerModal();
        return;
      }
      if (stateServerPicker.source === "nickname") {
        if (elements.nicknameServerInput) {
          elements.nicknameServerInput.value = String(serverId);
        }
        updateNicknameServerPicker();
        hideServerModal();
        return;
      }
      if (stateServerPicker.source === "profile-edit") {
        if (elements.editServerInput) {
          elements.editServerInput.value = String(serverId);
        }
        updateEditProfileServerPicker();
        hideServerModal();
        return;
      }
      await apiRequest(withAuth("/api/server"), {
        method: "POST",
        body: JSON.stringify({ server_id: serverId }),
      });
      state.serverId = serverId;
      setMarketServerFilter(serverId);
      updateCreateServerPicker();
      updateNicknameServerPicker();
      updateEditProfileServerPicker();
      updateFilterServerButtons();
      updateFiltersBar();
      updateServerButton();
      hideServerModal();
      if (state.page === "market") {
        await loadMarket();
      }
    });
    elements.serverGrid.appendChild(btn);
  });
}

async function loadMarket(options = {}) {
  const allowInactive = options.allowInactive === true;
  const loadingToken = null;
  const params = buildMarketListParams();
  const key = params.toString();
  // Prevent double refresh flicker when loadMarket() is called twice in quick succession
  // (e.g. nav click + delayed marketSearchTimer).
  if (marketLoadInFlight && marketLoadKeyInFlight === key) {
    return marketLoadInFlight;
  }
  if (marketLoadAbortController) marketLoadAbortController.abort();
  const controller = new AbortController();
  marketLoadAbortController = controller;
  marketLoadKeyInFlight = key;
  if (stateMarket.loaded && key !== stateMarket.queryKey) marketListBeginSwitch();
  const requestToken = ++marketRequestToken;
  const request = (async () => {
    try {
      params.set("paged", "1");
      params.set("limit", String(stateMarket.limit));
      params.set("offset", "0");
      params.set("include_total", "1");
      const payload = await apiRequest(`/api/listings?${params.toString()}`, {
        signal: controller.signal,
      });
      if (requestToken !== marketRequestToken || controller.signal.aborted || (!allowInactive && state.page !== "market")) return;
      const items = Array.isArray(payload?.items) ? payload.items : [];
      stateMarket.items = items;
      stateMarket.loaded = true;
      stateMarket.total = resolveMarketTotal(payload, items);
      stateMarket.offset = items.length;
      stateMarket.hasMore = Boolean(payload?.has_more);
      stateMarket.loadingMore = false;
      stateMarket.queryKey = key;
      elements.marketCount.textContent = `Найдено: ${stateMarket.total}`;
      if (!items.length) {
        elements.marketList.innerHTML = "";
        const emptyTitle = elements.marketEmpty?.querySelector(".market-empty-text");
        const emptySubtitle = elements.marketEmpty?.querySelector(".market-empty-sub");
        if (emptyTitle) emptyTitle.textContent = "Нет объявлений";
        if (emptySubtitle) emptySubtitle.textContent = "Попробуйте изменить фильтры";
        elements.marketEmpty.style.display = "block";
        renderPlaceholders();
        if (elements.marketMore) elements.marketMore.style.display = "none";
        marketListEndSwitch();
        await refreshTopStatusFromFilters();
        return;
      }
      elements.marketEmpty.style.display = "none";
      renderMarketPage({ append: false, items });
      if (elements.marketMore) {
        elements.marketMore.style.display = stateMarket.hasMore ? "block" : "none";
      }
      marketListEndSwitch();
      await refreshTopStatusFromFilters();
    } catch (error) {
      if (isAbortError(error) || requestToken !== marketRequestToken || controller.signal.aborted) return;
      console.error("Failed to load market:", error);
      if (!stateMarket.items.length) {
        elements.marketList.innerHTML = "";
        const emptyTitle = elements.marketEmpty?.querySelector(".market-empty-text");
        const emptySubtitle = elements.marketEmpty?.querySelector(".market-empty-sub");
        if (emptyTitle) emptyTitle.textContent = "Ошибка загрузки маркета";
        if (emptySubtitle) emptySubtitle.textContent = "Проверьте соединение и попробуйте ещё раз";
        elements.marketEmpty.style.display = "block";
      }
    }
  })();
  marketLoadInFlight = request;
  try {
    return await request;
  } finally {
    // a newer request keeps the dimmed state until it finishes
    if (marketLoadAbortController === controller || !marketLoadAbortController) marketListEndSwitch();
    if (marketLoadInFlight === request) {
      marketLoadInFlight = null;
      marketLoadKeyInFlight = "";
    }
    if (marketLoadAbortController === controller) marketLoadAbortController = null;
    if (loadingToken) endUiLoading(loadingToken);
  }
}

async function loadMoreMarketListings() {
  if (window.__PERF_DIAG__?.hardMarketIsolation) return;
  if (stateMarket.loadingMore || !stateMarket.hasMore) return;
  const params = buildMarketListParams();
  const key = params.toString();
  if (key !== stateMarket.queryKey) {
    return;
  }
  const requestToken = marketRequestToken;
  if (marketMoreAbortController) marketMoreAbortController.abort();
  const controller = new AbortController();
  marketMoreAbortController = controller;
  stateMarket.loadingMore = true;
  params.set("paged", "1");
  params.set("limit", String(stateMarket.limit));
  params.set("offset", String(stateMarket.offset));
  // Don't count total on pagination - we already know it from first request
  // params.set("include_total", "1");
  try {
    const payload = await apiRequest(`/api/listings?${params.toString()}`, {
      signal: controller.signal,
    });
    if (requestToken !== marketRequestToken || controller.signal.aborted || state.page !== "market") return;
    if (key !== stateMarket.queryKey) return;
    const nextItems = Array.isArray(payload?.items) ? payload.items : [];
    if (!nextItems.length) {
      stateMarket.hasMore = false;
      if (elements.marketMore) elements.marketMore.style.display = "none";
      return;
    }
    const seen = new Set(stateMarket.items.map((item) => Number(item.id)));
    const freshItems = nextItems.filter((item) => !seen.has(Number(item.id)));
    if (!freshItems.length) {
      stateMarket.hasMore = false;
      if (elements.marketMore) elements.marketMore.style.display = "none";
      return;
    }
    stateMarket.items = stateMarket.items.concat(freshItems);
    stateMarket.offset += freshItems.length;
    stateMarket.total = resolveMarketTotal(payload, stateMarket.items);
    stateMarket.hasMore = Boolean(payload?.has_more);
    elements.marketCount.textContent = `Найдено: ${stateMarket.total}`;
    renderMarketPage({ append: true, items: freshItems });
    if (elements.marketMore) {
      elements.marketMore.style.display = stateMarket.hasMore ? "block" : "none";
    }
  } catch (error) {
    if (!isAbortError(error)) console.error("Failed to load more market listings:", error);
  } finally {
    if (marketMoreAbortController === controller) {
      marketMoreAbortController = null;
      stateMarket.loadingMore = false;
    }
  }
}

function renderMarketPage({ append = false, items = [] } = {}) {
  if (!append) {
    if (typeof resetMarketPreviewPipeline === "function") {
      resetMarketPreviewPipeline({ abortRequests: true });
    }
    // Replacing an already shown list (filter / «Купить»-«Продать» switch / refresh) must not replay the card fade-in:
    // every card started at opacity 0, which read as the background flashing dark. Only the first fill animates.
    elements.marketList.classList.toggle("no-card-anim", elements.marketList.childElementCount > 0);
    elements.marketList.innerHTML = "";
  }
  const favorites = getFavoritesSet();
  items.forEach((item) => {
    const card = buildMarketCard(item, favorites);
    elements.marketList.appendChild(card);
  });
}

function closeListingModerationMenu() {
  if (!elements.listingModerationMenu) return;
  const listingDetailCard = elements.listingModerationMenu.closest(".listing-detail");
  if (listingDetailCard) {
    listingDetailCard.classList.remove("menu-open");
  }
  elements.listingModerationMenu.classList.remove("show");
  elements.listingModerationMenu.hidden = true;
}

function toggleListingModerationMenu() {
  if (!elements.listingModerationMenu || elements.listingModerationMenuBtn?.hidden) return;
  const listingDetailCard = elements.listingModerationMenu.closest(".listing-detail");
  const opening = !elements.listingModerationMenu.classList.contains("show");
  if (opening) {
    if (listingDetailCard) {
      listingDetailCard.classList.add("menu-open");
    }
    elements.listingModerationMenu.hidden = false;
    requestAnimationFrame(() => elements.listingModerationMenu.classList.add("show"));
    return;
  }
  closeListingModerationMenu();
}

async function loadFavorites() {
  if (!elements.favoritesList || !elements.favoritesEmpty) return;
  elements.favoritesList.classList.add("market-listings", "market-listings--grid");
  elements.favoritesList.classList.remove("market-listings--list");
  const favorites = getFavoritesSet();
  stateCoins.favoritesCount = favorites.size;
  updateCoinsTileBadges();
  const countEl = document.getElementById("favoritesCount");
  elements.favoritesList.innerHTML = "";
  
  if (!favorites.size) {
    elements.favoritesEmpty.classList.add("show");
    if (countEl) countEl.textContent = "0 объявлений";
    return;
  }
  
  const listings = await apiRequest("/api/listings");
  const availableIds = new Set(listings.map((item) => Number(item.id)));
  const visible = listings.filter((item) => favorites.has(Number(item.id)));
  const cleaned = new Set(Array.from(favorites).filter((id) => availableIds.has(id)));
  
  if (cleaned.size !== favorites.size) {
    // Display filter only: do not push "removals" of inactive listings to the server.
    saveFavoritesSet(cleaned, { localOnly: true });
  }
  
  if (!visible.length) {
    elements.favoritesEmpty.classList.add("show");
    if (countEl) countEl.textContent = "0 объявлений";
    return;
  }
  
  elements.favoritesEmpty.classList.remove("show");
  if (countEl) {
    const count = visible.length;
    const word = count === 1 ? "объявление" : count < 5 ? "объявления" : "объявлений";
    countEl.textContent = `${count} ${word}`;
  }
  
  visible.forEach((item) => {
    const card = buildMarketCard(item, cleaned, (nextFavorites) => {
      if (!nextFavorites.has(Number(item.id))) {
        card.remove();
        const remaining = elements.favoritesList.children.length;
        if (!remaining) {
          elements.favoritesEmpty.classList.add("show");
        }
        if (countEl) {
          const word = remaining === 1 ? "объявление" : remaining < 5 ? "объявления" : "объявлений";
          countEl.textContent = `${remaining} ${word}`;
        }
      }
    });
    elements.favoritesList.appendChild(card);
  });
}

function normalizeLeaderboardMode(value) {
  const normalized = String(value || "").trim().toLowerCase();
  if (normalized === "captures" && !isCaptureUiEnabled()) return "mcoin";
  if (normalized === "captures" || normalized === "mcoin" || normalized === "deals") {
    return normalized;
  }
  return isCaptureUiEnabled() ? "captures" : "mcoin";
}

function getMskWeekRange(now = Date.now()) {
  const mskOffsetMs = 3 * 60 * 60 * 1000;
  const mskNow = new Date(now + mskOffsetMs);
  const weekDay = mskNow.getUTCDay();
  const daysSinceMonday = (weekDay + 6) % 7;
  const mskMidnightUtcMs = Date.UTC(mskNow.getUTCFullYear(), mskNow.getUTCMonth(), mskNow.getUTCDate());
  const startUtcMs = mskMidnightUtcMs - daysSinceMonday * 24 * 60 * 60 * 1000 - mskOffsetMs;
  const endUtcMs = startUtcMs + 7 * 24 * 60 * 60 * 1000 - 1;
  return { startUtcMs, endUtcMs };
}

function formatMskDateShort(ts) {
  const mskOffsetMs = 3 * 60 * 60 * 1000;
  const d = new Date(ts + mskOffsetMs);
  const day = String(d.getUTCDate()).padStart(2, "0");
  const month = String(d.getUTCMonth() + 1).padStart(2, "0");
  return `${day}.${month}`;
}

function formatCountdownRu(msLeft) {
  const total = Math.max(0, Math.floor(msLeft / 1000));
  const days = Math.floor(total / 86400);
  const hours = Math.floor((total % 86400) / 3600);
  const mins = Math.floor((total % 3600) / 60);
  if (days > 0) return `${days}д ${String(hours).padStart(2, "0")}ч ${String(mins).padStart(2, "0")}м`;
  return `${String(hours).padStart(2, "0")}ч ${String(mins).padStart(2, "0")}м`;
}

function renderLeaderboardModeUi() {
  const isTournamentView = state.page === "tournament";
  if (elements.leaderboardHeroTitle) {
    elements.leaderboardHeroTitle.textContent = isTournamentView ? "Рейтинг" : "Лидерборд";
  }
  if (isTournamentView) {
    const tournamentMode = String((stateRating.gameTournament || {}).mode || "solo").toLowerCase();
    if (elements.leaderboardModeHint) {
      elements.leaderboardModeHint.textContent = tournamentMode === "club"
        ? "Топ клубов по XP текущего турнира"
        : "Топ-100 по XP текущего турнира";
    }
    const switcher = document.getElementById("leaderboardModeSwitch");
    if (switcher) switcher.style.display = "none";
    return;
  }
  const mode = normalizeLeaderboardMode(stateRating.mode);
  const modeHintMap = {
    captures: "По успешным захватам",
    mcoin: "По текущему балансу M-Coin",
    deals: "По подтвержденным сделкам",
  };
  if (elements.leaderboardModeHint) {
    elements.leaderboardModeHint.textContent = modeHintMap[mode] || modeHintMap.captures;
  }
  const switcher = document.getElementById("leaderboardModeSwitch");
  if (switcher) switcher.style.display = "";
  const buttons = [
    { mode: "captures", el: elements.leaderboardModeCaptures },
    { mode: "mcoin", el: elements.leaderboardModeMcoin },
    { mode: "deals", el: elements.leaderboardModeDeals },
  ];
  buttons.forEach(({ mode: btnMode, el }) => {
    if (!el) return;
    const isActive = mode === btnMode;
    el.classList.toggle("active", isActive);
    el.setAttribute("aria-selected", isActive ? "true" : "false");
  });
}

function renderLeaderboardTimerUi() {
  if (!elements.leaderboardPeriodLine) return;
  const isTournamentView = state.page === "tournament";
  if (isTournamentView) {
    const tournament = stateRating.gameTournament || {};
    const rawStatus = String(tournament.status || "").toLowerCase();
    const endsAtMs = tournament.ends_at ? Date.parse(tournament.ends_at) : 0;
    const breakUntilMs = tournament.break_until_at ? Date.parse(tournament.break_until_at) : 0;
    const hasFutureEnd = Number.isFinite(endsAtMs) && endsAtMs > Date.now();
    const hasBreakWindow = Number.isFinite(breakUntilMs) && breakUntilMs > Date.now();
    const status = rawStatus === "active" || (rawStatus !== "break" && hasFutureEnd)
      ? "active"
      : (rawStatus === "break" || hasBreakWindow)
        ? "break"
        : rawStatus;
    const statusBadge = elements.leaderboardStatusBadge;
    const statusText = elements.leaderboardStatusText;
    const resultsTitle = elements.leaderboardResultsTitle;
    const taskCard = elements.leaderboardTournamentTask;
    if (statusBadge) {
      statusBadge.hidden = true;
      statusBadge.style.display = "none";
    }
    if (resultsTitle) resultsTitle.hidden = true;
    if (taskCard) taskCard.style.display = status === "active" ? "" : "none";
    if (status === "active") {
      elements.leaderboardPeriodLine.textContent = "Топ-100 по XP текущего турнира";
      if (elements.leaderboardTimerBadge) {
        elements.leaderboardTimerBadge.classList.remove("is-static");
      }
    } else if (status === "break") {
      const nextAt = tournament.break_until_at ? formatDateTimeMsk(tournament.break_until_at) : "—";
      elements.leaderboardPeriodLine.textContent = `Результаты зафиксированы • перерыв до ${nextAt}`;
      if (statusBadge && statusText) {
        statusText.textContent = "Завершён";
        statusBadge.hidden = false;
        statusBadge.style.display = "";
      }
      if (resultsTitle) {
        resultsTitle.hidden = false;
      }
    } else {
      elements.leaderboardPeriodLine.textContent = "Турнир пока не запущен";
    }
    if (elements.leaderboardTimerBadge && elements.leaderboardTimerLine) {
      const msLeft = Number.isFinite(endsAtMs) && endsAtMs > 0 ? endsAtMs - Date.now() : 0;
      if (status === "active" && msLeft > 0) {
        elements.leaderboardTimerLine.textContent = formatCountdownRu(msLeft);
        elements.leaderboardTimerBadge.classList.remove("is-static");
        elements.leaderboardTimerBadge.style.display = "";
      } else if (status === "break") {
        elements.leaderboardTimerLine.textContent = tournament.break_until_at
          ? `Перерыв до: ${formatDateTimeMsk(tournament.break_until_at)}`
          : "Турнир завершён";
        elements.leaderboardTimerBadge.classList.add("is-static");
        elements.leaderboardTimerBadge.style.display = "";
      } else {
        elements.leaderboardTimerBadge.classList.remove("is-static");
        elements.leaderboardTimerBadge.style.display = "none";
      }
    }
    if (elements.leaderboardPrizesChip) {
      elements.leaderboardPrizesChip.style.display = status === "active" ? "" : "none";
    }
    return;
  }
  const mode = normalizeLeaderboardMode(stateRating.mode);
  const periodMap = {
    captures: "Общий рейтинг по захватам",
    mcoin: "Общий рейтинг по M-Coin",
    deals: "Общий рейтинг по сделкам",
  };
  elements.leaderboardPeriodLine.textContent = periodMap[mode] || periodMap.captures;
  if (elements.leaderboardTimerBadge) {
    elements.leaderboardTimerBadge.style.display = "none";
  }
  if (elements.leaderboardPrizesChip) {
    elements.leaderboardPrizesChip.style.display = "none";
  }
}

function ensureLeaderboardTimer() {
  if (leaderboardTimer) {
    clearInterval(leaderboardTimer);
    leaderboardTimer = null;
  }
  if (state.page !== "tournament") return;
  const tick = () => {
    renderLeaderboardTimerUi();
    const tournament = stateRating.gameTournament || {};
    const status = String(tournament.status || "").toLowerCase();
    const endsAtMs = tournament.ends_at ? Date.parse(tournament.ends_at) : 0;
    if (status === "active" && Number.isFinite(endsAtMs) && endsAtMs > 0 && endsAtMs <= Date.now()) {
      ensureLeaderboardTimer();
      window.setTimeout(() => {
        if (state.page === "tournament") {
          loadTournamentPage();
        }
      }, 250);
    }
  };
  tick();
  if (String((stateRating.gameTournament || {}).status || "").toLowerCase() === "active") {
    leaderboardTimer = window.setInterval(tick, 1000);
  }
}

function setLeaderboardMode(mode, options = {}) {
  const nextMode = normalizeLeaderboardMode(mode);
  const shouldReload = Boolean(options.reload);
  if (stateRating.mode === nextMode && !shouldReload) {
    renderLeaderboardModeUi();
    renderLeaderboardTimerUi();
    return;
  }
  stateRating.mode = nextMode;
  localStorage.setItem(LEADERBOARD_MODE_KEY, nextMode);
  renderLeaderboardModeUi();
  renderLeaderboardTimerUi();
  if (shouldReload) {
    loadLeaderboardPage();
  }
}

async function openLeaderboardWithMode(mode) {
  setLeaderboardMode(mode, { reload: false });
  if (state.page !== "leaderboard") {
    navigateTo("leaderboard");
    return;
  }
  await loadLeaderboardPage();
}

function getRatingInitials(value) {
  const text = String(value || "").trim();
  if (!text) return "U";
  const letters = text.match(/[A-Za-zА-Яа-яЁё]/g);
  if (!letters || !letters.length) return "U";
  return letters.slice(0, 2).join("").toUpperCase();
}

function getLeaderboardProfileId(item) {
  if (!item || typeof item !== "object") return "";
  const direct =
    item.telegram_id ??
    item.user_id ??
    item.userId ??
    item.target_id ??
    item.tid ??
    item.id;
  if (direct === null || direct === undefined) return "";
  const value = String(direct).trim();
  return value && value !== "0" ? value : "";
}

function bindLeaderboardProfileOpen(target, userId, backPage) {
  if (!target || !userId) return;
  target.classList.add("is-clickable");
  target.setAttribute("role", "button");
  target.tabIndex = 0;
  target.addEventListener("click", () => {
    loadPublicProfile(userId, backPage);
  });
  target.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" && event.key !== " ") return;
    event.preventDefault();
    loadPublicProfile(userId, backPage);
  });
}

function buildRatingCard(item) {
  const card = document.createElement("div");
  card.className = "rating-row";
  const serverNum = Number(item.server_id || 0);
  const serverLabel = Number.isFinite(serverNum) && serverNum > 0 ? `Сервер ${serverNum}` : "Сервер —";
  const avatarSource = item.avatar_data || item.avatar_url || "";
  const fallbackName = getRatingInitials(item.display_name || "");
  const sellerName = item.display_name || "Пользователь";
  const score = Number(item.score || 0);
  const deals = Number(item.confirmed_deals || 0);

  card.innerHTML = `
    <div class="rating-rank">#${item.rank_position || "—"}</div>
    <div class="rating-avatar"></div>
    <div class="rating-main">
      <div class="rating-name"></div>
      <div class="rating-meta">
        <span>${serverLabel}</span>
        <span>Сделок: ${deals}</span>
      </div>
    </div>
    <div class="rating-score">${score}</div>
  `;
  const nameEl = card.querySelector(".rating-name");
  if (nameEl) {
    nameEl.textContent = sellerName;
    nameEl.title = sellerName;
  }
  const avatar = card.querySelector(".rating-avatar");
  if (avatar) {
    setAvatarPreview(avatar, avatarSource, fallbackName);
  }
  bindLeaderboardProfileOpen(card, getLeaderboardProfileId(item), "rating");
  return card;
}

