const MINE_CHARS = [
  { key: "shakter",  name: "Шахтер",  req: 0    },
  { key: "hasbik",   name: "Хазбик",  req: 500  },
  { key: "deadpool", name: "Дед Пул", req: 1000 },
  { key: "kuzmich",  name: "Кузьмич", req: 1500 },
];
const MINE_CHAR_ASSET_VERSION = "20260430j";

function getMiningChar() {
  return localStorage.getItem("mancini_mining_char") || "shakter";
}

function applyMiningChar(key) {
  const img = document.getElementById("mineCharImg");
  const bg  = document.getElementById("mineSceneBg");
  const selected = MINE_CHARS.some((item) => item.key === key) ? key : "shakter";
  if (img) {
    const nextSrc = `assets/characters/${selected}.png?v=${MINE_CHAR_ASSET_VERSION}`;
    img.onerror = () => {
      if (img.dataset.fallbackApplied === "1") return;
      img.dataset.fallbackApplied = "1";
      img.src = `assets/characters/shakter.jpg?v=${MINE_CHAR_ASSET_VERSION}`;
    };
    if (img.dataset.miningChar !== selected) {
      img.dataset.fallbackApplied = "0";
      img.dataset.miningChar = selected;
      img.src = nextSrc;
    }
  }
  if (bg)  bg.setAttribute("data-char", selected);
}

function updateWardrobeCards(energyBalance) {
  const current = getMiningChar();
  document.querySelectorAll(".mine-char-card").forEach((card) => {
    const req    = Number(card.dataset.energyReq || 0);
    const key    = String(card.dataset.char || "");
    const locked = energyBalance < req;
    card.classList.toggle("locked",   locked);
    card.classList.toggle("selected", key === current);
    card.disabled = locked;
  });
}
