function renderMiningHistory(items) {
  const historyList = document.getElementById("miningHistoryList");
  if (!historyList) return;
  historyList.innerHTML = "";
  if (!Array.isArray(items) || !items.length) {
    const empty = document.createElement("div");
    empty.className = "mine-history-empty";
    empty.id = "miningHistoryEmpty";
    empty.textContent = "Завершённых блоков пока нет.";
    historyList.appendChild(empty);
    return;
  }

  items.forEach((item) => {
    const card = document.createElement("article");
    card.className = "mine-history-card";

    // ── Top row: icon + title + status  |  reward pill
    const top = document.createElement("div");
    top.className = "mine-history-card-top";

    const head = document.createElement("div");
    head.className = "mine-history-card-head";

    const iconWrap = document.createElement("span");
    iconWrap.className = "mine-history-card-icon";
    iconWrap.innerHTML = MINE_HISTORY_ICONS.pickaxe;

    const titleBlock = document.createElement("div");
    titleBlock.className = "mine-history-card-titleblock";

    const label = document.createElement("div");
    label.className = "mine-history-card-label";
    const rawLabel = String(item?.label || "—");
    label.textContent = rawLabel.startsWith("#") ? `Блок ${rawLabel}` : `Блок #${rawLabel}`;

    const status = document.createElement("span");
    status.className = "mine-history-card-status";
    status.dataset.status = String(item?.status || "");
    status.textContent = String(item?.status_label || "Завершён").replace(" пользователем", "");

    titleBlock.append(label, status);
    head.append(iconWrap, titleBlock);

    const reward = document.createElement("div");
    reward.className = "mine-history-card-reward";
    const rewardLabel = document.createElement("span");
    rewardLabel.className = "mine-history-card-reward-label";
    rewardLabel.textContent = "Моя награда";
    const rewardValue = document.createElement("span");
    rewardValue.className = "mine-history-card-reward-value";
    rewardValue.textContent = `${Number(item?.points_earned || 0)} XP`;
    reward.append(rewardLabel, rewardValue);

    top.append(head, reward);

    // ── Meta row: start / energy / duration as small chip-cards
    const meta = document.createElement("div");
    meta.className = "mine-history-card-meta";
    [
      { icon: MINE_HISTORY_ICONS.clock, key: "Старт", value: formatMiningClock(item?.started_at) },
      { icon: MINE_HISTORY_ICONS.bolt, key: "Энергия", value: String(Number(item?.energy_spent || 0)) },
      { icon: MINE_HISTORY_ICONS.timer, key: "Майнинг", value: formatMiningDuration(item?.duration_minutes) },
    ].forEach(({ icon, key, value }) => {
      const chip = document.createElement("div");
      chip.className = "mine-history-meta-item";
      chip.innerHTML =
        `<span class="mine-history-meta-icon" aria-hidden="true">${icon}</span>` +
        `<span class="mine-history-meta-key">${key}</span>` +
        `<span class="mine-history-meta-value"></span>`;
      chip.querySelector(".mine-history-meta-value").textContent = value;
      meta.appendChild(chip);
    });

    card.append(top, meta);
    historyList.appendChild(card);
  });
}

function renderMiningState(statePayload) {
  if (!elements.ratingList || !elements.ratingEmpty) return;
  stateRating.gameState = statePayload || null;
  const player    = statePayload?.player     || {};
    const farm      = statePayload?.farm       || {};
    const tournament= statePayload?.tournament || {};
    const currentBlock = statePayload?.current_block || null;
    const historyBlocks = Array.isArray(statePayload?.history_blocks) ? statePayload.history_blocks : [];
    const energy    = player.energy            || {};
    const energyBal = Number(energy.balance || 0);
    const energyMax = Number(energy.max     || 5000);

    // XP balance
    if (elements.ratingMyScore) {
      elements.ratingMyScore.textContent = String(player.point || 0);
    }

    // Energy bar fill
    const fillPct = energyMax > 0 ? Math.min(100, (energyBal / energyMax) * 100) : 0;
    const energyFill = document.getElementById("mineEnergyFill");
    if (energyFill) energyFill.style.width = `${fillPct.toFixed(1)}%`;

    // Energy label
    if (elements.ratingMyRank) {
      elements.ratingMyRank.textContent = `${energyBal} / ${energyMax}`;
    }

    // Status
    if (elements.ratingMyDeals) {
      elements.ratingMyDeals.textContent = farm.active ? "ВКЛ" : "ВЫКЛ";
      elements.ratingMyDeals.classList.toggle("mine-status-badge--active", Boolean(farm.active));
    }

    // Current mining block
    const blockLabelEl   = document.getElementById("miningBlockLabel");
    const blockStatusEl  = document.getElementById("miningBlockStatus");
    const blockEmptyEl   = document.getElementById("miningBlockEmptyText");
    const blockGridEl    = document.getElementById("miningCurrentBlockGrid");
    const blockFarmersMirrorEl = document.getElementById("miningFarmersMirror");
    const blockTimeEl    = document.getElementById("miningBlockTimeLeft");
    const blockEnergyRateEl = document.getElementById("miningBlockEnergyRate");
    const blockPointsEl = document.getElementById("miningBlockPointsEarned");
    const activeMinersCount = Number(currentBlock?.active_miners_count || farm.active_miners_count || 0);
    const hasCurrentBlock = Boolean(currentBlock && farm.active);

    if (blockLabelEl) {
      blockLabelEl.textContent = hasCurrentBlock ? `${currentBlock.label || "—"}` : "—";
    }
    if (blockStatusEl) {
      blockStatusEl.textContent = hasCurrentBlock ? "ВКЛ" : "ВЫКЛ";
      blockStatusEl.classList.toggle("is-active", hasCurrentBlock);
    }
    if (blockEmptyEl) {
      blockEmptyEl.textContent = hasCurrentBlock
        ? ""
        : "Нажмите «Начать майнинг», чтобы создать новый блок.";
      blockEmptyEl.style.display = hasCurrentBlock ? "none" : "";
    }
    if (blockGridEl) {
      blockGridEl.classList.toggle("is-hidden", !hasCurrentBlock);
    }
    if (blockEnergyRateEl) {
      blockEnergyRateEl.textContent = `${Number(farm.energy_per_hour || 100)} / час`;
    }
    if (blockFarmersMirrorEl) {
      blockFarmersMirrorEl.textContent = hasCurrentBlock ? String(activeMinersCount) : "—";
    }
    if (blockTimeEl) {
      if (!hasCurrentBlock) {
        blockTimeEl.textContent = "—";
      } else if (Number(currentBlock?.seconds_until_end || 0) > 0) {
        blockTimeEl.textContent = formatCountdownRu(Number(currentBlock.seconds_until_end) * 1000);
      } else {
        blockTimeEl.textContent = "Без лимита";
      }
    }
    if (blockPointsEl) {
      blockPointsEl.textContent = `${Number(currentBlock?.points_earned || 0)} XP`;
    }

    renderMiningHistory(historyBlocks);

    // Tournament break banner
    const isBreak   = tournament.status === "break";
    const breakBanner  = document.getElementById("miningBreakBanner");
    const breakUntilEl = document.getElementById("miningBreakUntil");
    if (breakBanner) breakBanner.classList.toggle("hidden", !isBreak);
    if (breakUntilEl && isBreak) {
      breakUntilEl.textContent = tournament.break_until_at
        ? formatDateTimeMsk(tournament.break_until_at) : "—";
    }

    // Status footer
    if (elements.ratingUpdatedAt) {
      const statusText = tournament.status === "active"
        ? `Турнир до ${tournament.ends_at ? formatDateTimeMsk(tournament.ends_at) : "—"}`
        : isBreak
          ? `Перерыв до ${tournament.break_until_at ? formatDateTimeMsk(tournament.break_until_at) : "—"}`
          : "Ожидание следующего турнира";
      elements.ratingUpdatedAt.textContent = statusText;
    }

    // Toggle button
    const farmToggleBtn = document.getElementById("farmToggleBtn");
    if (farmToggleBtn) {
      const cantStart = !farm.active && !Boolean(farm.can_start);
      farmToggleBtn.textContent = farm.active ? "Остановить майнинг" : "Начать майнинг";
      farmToggleBtn.dataset.active = farm.active ? "1" : "0";
      farmToggleBtn.disabled = cantStart;
      farmToggleBtn.classList.toggle("mine-toggle-btn--stop", farm.active);
    }

    // Wardrobe: update lock states based on current energy
    updateWardrobeCards(energyBal);

    // Apply saved character
  applyMiningChar(getMiningChar());
}

async function loadRatingPage(options = {}) {
  if (!elements.ratingList || !elements.ratingEmpty) return null;
  const force = Boolean(options.force);
  const silent = Boolean(options.silent);
  const now = Date.now();
  if (stateRating.gameStateInFlight) return stateRating.gameStateInFlight;
  if (!force && stateRating.gameStateLoaded && now - Number(stateRating.gameStateLoadedAtMs || 0) < 5000) {
    setPageDataState("rating", "ready");
    return stateRating.gameState;
  }

  const isInitialLoad = !stateRating.gameStateLoaded;
  setPageDataState(
    "rating",
    isInitialLoad ? "loading" : "refreshing",
    "Загружаем майнинг…",
  );
  const requestSeq = Number(stateRating.gameStateRequestSeq || 0) + 1;
  stateRating.gameStateRequestSeq = requestSeq;
  const loadPromise = (async () => {
    const networkStartedAt = performance.now();
    try {
      const statePayload = await apiRequest(withAuth("/api/game/state"));
      recordFrontendPerf("PAGE mining network", networkStartedAt);
      if (requestSeq !== stateRating.gameStateRequestSeq) return stateRating.gameState;
      const renderStartedAt = performance.now();
      renderMiningState(statePayload);
      stateRating.gameStateLoaded = true;
      stateRating.gameStateLoadedAtMs = Date.now();
      setPageDataState("rating", "ready");
      recordFrontendPerf("PAGE mining render", renderStartedAt);
      return statePayload;
    } catch (error) {
      if (requestSeq === stateRating.gameStateRequestSeq) {
        if (stateRating.gameStateLoaded) {
          setPageDataState("rating", "ready");
        } else {
          setPageDataState("rating", "error", "Не удалось загрузить майнинг");
        }
      }
      if (!silent) console.warn("Mining page load failed:", error);
      return stateRating.gameState;
    }
  })();
  stateRating.gameStateInFlight = loadPromise;
  try {
    return await loadPromise;
  } finally {
    if (stateRating.gameStateInFlight === loadPromise) {
      stateRating.gameStateInFlight = null;
    }
  }
}

function getCaptureOwnerName(owner) {
  if (!owner) return "Нейтральная зона";
  const value = String(owner.display_name || owner.username || "").trim();
  if (!value) return "Без ника";
  if (/^\d+$/.test(value)) return "Без ника";
  return value;
}

function getCaptureInitials(value) {
  const text = String(value || "").trim();
  if (!text) return "RP";
  const parts = text.split(/\s+/).filter(Boolean).slice(0, 2);
  if (parts.length >= 2) return `${parts[0][0] || ""}${parts[1][0] || ""}`.toUpperCase();
  return text.slice(0, 2).toUpperCase();
}

function getAudioCtx() {
  const s = CAPTURE_AUDIO.state;
  if (s.ctx) {
    if (s.ctx.state === "suspended") s.ctx.resume().catch(() => {});
    return s.ctx;
  }
  const AC = window.AudioContext || window.webkitAudioContext;
  if (!AC) return null;
  s.ctx = new AC();
  if (s.ctx.state === "suspended") s.ctx.resume().catch(() => {});
  return s.ctx;
}

async function loadAudioBuffer(key) {
  const s = CAPTURE_AUDIO.state;
  if (s.buffers[key]) return s.buffers[key];
  if (!CAPTURE_AUDIO.src[key]) return null;
  const ctx = getAudioCtx();
  if (!ctx) return null;
  try {
    const resp = await fetch(CAPTURE_AUDIO.src[key]);
    const arrayBuf = await resp.arrayBuffer();
    const decoded = await ctx.decodeAudioData(arrayBuf);
    s.buffers[key] = decoded;
    return decoded;
  } catch {
    return null;
  }
}

async function unlockCaptureAudio() {
  const s = CAPTURE_AUDIO.state;
  if (s.unlocked) return;
  if (s.unlockInFlight) { await s.unlockInFlight; return; }
  s.unlockInFlight = (async () => {
    const ctx = getAudioCtx();
    if (!ctx) return;
    if (ctx.state === "suspended") {
      await ctx.resume().catch(() => {});
    }
    const silent = ctx.createBuffer(1, 1, ctx.sampleRate);
    const src = ctx.createBufferSource();
    src.buffer = silent;
    src.connect(ctx.destination);
    src.start(0);
    s.unlocked = ctx.state === "running";
  })();
  try { await s.unlockInFlight; } finally { s.unlockInFlight = null; }
}

function bindCaptureAudioUnlock() {
  const s = CAPTURE_AUDIO.state;
  if (s.unlockBound) return;
  s.unlockBound = true;
  const tryUnlock = async () => {
    await unlockCaptureAudio();
    if (CAPTURE_AUDIO.state.unlocked) {
      for (const ev of ["pointerdown", "touchstart", "touchend", "click", "keydown"]) {
        document.removeEventListener(ev, tryUnlock, true);
      }
    }
  };
  for (const ev of ["pointerdown", "touchstart", "touchend", "click", "keydown"]) {
    document.addEventListener(ev, tryUnlock, { capture: true, passive: true });
  }
}

function playCaptureSound(key, opts = {}) {
  const s = CAPTURE_AUDIO.state;
  const ctx = getAudioCtx();
  if (!ctx || !s.unlocked) return null;
  const buffer = s.buffers[key];
  if (!buffer) return null;
  if (opts.stopPrevious && s.sources[key]) {
    try { s.sources[key].stop(); } catch {}
    s.sources[key] = null;
  }
  const source = ctx.createBufferSource();
  source.buffer = buffer;
  source.loop = Boolean(opts.loop);
  const gain = ctx.createGain();
  gain.gain.value = opts.startVolume != null ? opts.startVolume : (CAPTURE_AUDIO.volume[key] || 0.2);
  source.connect(gain);
  gain.connect(ctx.destination);
  source.start(0, opts.offset || 0);
  s.sources[key] = source;
  s.gains[key] = gain;
  source.onended = () => {
    if (s.sources[key] === source) { s.sources[key] = null; s.gains[key] = null; }
  };
  return { source, gain };
}

function stopCaptureSound(key, fadeSec) {
  const s = CAPTURE_AUDIO.state;
  const ctx = getAudioCtx();
  const gain = s.gains[key];
  const source = s.sources[key];
  if (!source) return;
  if (ctx && gain && fadeSec > 0) {
    const now = ctx.currentTime;
    gain.gain.setValueAtTime(gain.gain.value, now);
    gain.gain.linearRampToValueAtTime(0, now + fadeSec);
    const ref = source;
    setTimeout(() => {
      try { ref.stop(); } catch {}
      if (s.sources[key] === ref) { s.sources[key] = null; s.gains[key] = null; }
    }, fadeSec * 1000 + 50);
  } else {
    try { source.stop(); } catch {}
    s.sources[key] = null;
    s.gains[key] = null;
  }
}

function startCaptureAmbience() {}
function stopCaptureAmbience() {}

function notifyCaptureScrollSound() {
  if (isAndroidLiteMode()) return;
  const s = CAPTURE_AUDIO.state;
  if (!s.unlocked) return;
  const now = performance.now();
  if (now < s.scrollThrottleUntil) return;
  s.scrollThrottleUntil = now + 300;
  if (!s.buffers.scroll) {
    loadAudioBuffer("scroll");
    return;
  }
  const buffer = s.buffers.scroll;
  const tailSec = 1.2;
  const offset = Math.max(0, buffer.duration - tailSec);
  if (s.scrollStopTimer) { clearTimeout(s.scrollStopTimer); s.scrollStopTimer = 0; }
  if (!s.sources.scroll) {
    playCaptureSound("scroll", { stopPrevious: true, startVolume: CAPTURE_AUDIO.volume.scroll, offset });
  }
  s.scrollStopTimer = window.setTimeout(() => {
    stopCaptureSound("scroll", 0.25);
    s.scrollStopTimer = 0;
  }, 500);
}

function stopCaptureScrollSound() {
  const s = CAPTURE_AUDIO.state;
  if (s.scrollStopTimer) { clearTimeout(s.scrollStopTimer); s.scrollStopTimer = 0; }
  stopCaptureSound("scroll", 0.15);
}

function playCaptureOneShotWithUnlock(key) {
  const s = CAPTURE_AUDIO.state;
  if (!s.unlocked) return;
  if (!s.buffers[key]) {
    loadAudioBuffer(key).then(() => {
      if (s.unlocked && s.buffers[key]) playCaptureSound(key, { stopPrevious: true });
    });
    return;
  }
  playCaptureSound(key, { stopPrevious: true });
}

function playCaptureSuccessSound() {
  playCaptureOneShotWithUnlock("captureSuccess");
}

function playCaptureDefeatSound() {
  playCaptureOneShotWithUnlock("captureDefeat");
}

function playCaptureDefenseBoostSound() {
  playCaptureOneShotWithUnlock("defenseBoost");
}

function stopCaptureTimer() {
  if (stateCapture.timerId) {
    clearInterval(stateCapture.timerId);
    stateCapture.timerId = null;
  }
}

function stopCaptureStateAutoRefresh() {
  if (captureStateRefreshTimer) {
    clearInterval(captureStateRefreshTimer);
    captureStateRefreshTimer = null;
  }
  captureStateRefreshInFlight = false;
}

function startCaptureStateAutoRefresh() {
  stopCaptureStateAutoRefresh();
  captureStateRefreshTimer = setInterval(() => {
    if (state.page !== "capture") {
      stopCaptureStateAutoRefresh();
      return;
    }
    if (document.hidden || stateCapture.attackInFlight || captureStateRefreshInFlight || stateCapture.loadInFlight) return;
    captureStateRefreshInFlight = true;
    Promise.resolve(loadCaptureState({ force: true, silent: true, skipTimerRestart: true }))
      .finally(() => {
        captureStateRefreshInFlight = false;
      });
  }, 10000);
}

function getCaptureNodeState(territory) {
  const liveBadge = String(territory?.live_event?.badge || "").trim().toLowerCase();
  if (liveBadge === "attack") return { icon: "⚔️", tone: "alert-attack", label: "Идёт атака" };
  if (liveBadge === "counter") return { icon: "🔥", tone: "alert-counter", label: "Можно перехватить сейчас" };
  if (liveBadge === "defend") return { icon: "🛡", tone: "alert-defend", label: "Твоя территория под атакой" };
  const cooldown = Math.max(0, Number(territory?.cooldown_seconds || 0));
  if (cooldown > 0) return { icon: "⌛", tone: "cooldown", label: `Кулдаун ${formatDurationCompact(cooldown)}` };
  if (Boolean(territory?.is_mine)) return { icon: "🛡", tone: "mine", label: "Ваша территория" };
  return { icon: "⚔", tone: "enemy", label: "Можно атаковать" };
}

function getCaptureActionWaitSeconds(ownerCooldown, playerCooldown, nightCooldown) {
  return Math.max(0, Math.ceil(Math.max(
    Number(ownerCooldown || 0),
    Number(playerCooldown || 0),
    Number(nightCooldown || 0),
  )));
}

function formatCaptureActionCooldown(seconds) {
  const value = Math.max(0, Math.ceil(Number(seconds || 0)));
  if (value >= 3600) return formatHhMmSs(value);
  return formatMmSs(value);
}

function shouldRenderCaptureNodeCooldownChip() {
  return isIOSClient() && !isAndroidClient();
}

function refreshCaptureNodeStatuses() {
  if (!elements.captureMap) return;
  const androidLite = isAndroidLiteMode();
  const showCooldownChip = shouldRenderCaptureNodeCooldownChip();
  elements.captureMap.querySelectorAll(".capture-node").forEach((node) => {
    const territoryId = Number(node.dataset.territoryId || 0);
    const territory = (stateCapture.territories || []).find((item) => Number(item.id) === territoryId);
    if (!territory) return;
    const cooldownBadge = node.querySelector(".capture-node-cooldown");
    if (cooldownBadge) {
      const cooldownSeconds = Math.max(0, Number(territory.cooldown_seconds || 0));
      const isVisible = showCooldownChip && cooldownSeconds > 0;
      cooldownBadge.textContent = isVisible ? `⌛ ${formatCaptureActionCooldown(cooldownSeconds)}` : "";
      cooldownBadge.classList.toggle("hidden", !isVisible);
    }
    const stateBadge = node.querySelector(".capture-node-state-badge");
    if (stateBadge) {
      const stateInfo = getCaptureNodeState(territory);
      const wantClass = `capture-node-state-badge is-${stateInfo.tone}`;
      if (stateBadge.textContent !== stateInfo.icon) stateBadge.textContent = stateInfo.icon;
      if (stateBadge.className !== wantClass) stateBadge.className = wantClass;
      if (!androidLite) {
        stateBadge.setAttribute("aria-label", stateInfo.label);
        stateBadge.setAttribute("title", stateInfo.label);
      }
    }
  });
  elements.captureMap.querySelectorAll(".capture-business-node").forEach((node) => {
    const business = getCaptureBusinessById(Number(node.dataset.territoryId || 0));
    if (!business) return;
    node.classList.toggle("is-mine", Boolean(business.is_mine));
    node.classList.toggle("is-neutral", !business.owner);
    node.title = `${business.name} • ${business.cityName}`;
    const stateBadge = node.querySelector(".capture-business-node-state");
    if (stateBadge) {
      const stateInfo = getCaptureNodeState(business);
      const wantClass = `capture-business-node-state is-${stateInfo.tone}`;
      if (stateBadge.textContent !== stateInfo.icon) stateBadge.textContent = stateInfo.icon;
      if (stateBadge.className !== wantClass) stateBadge.className = wantClass;
      if (!androidLite) stateBadge.title = stateInfo.label;
    }
    const ownerName = getCaptureOwnerName(business.owner);
    const ownerEl = node.querySelector(".capture-business-node-owner");
    if (ownerEl && ownerEl.textContent !== ownerName) {
      ownerEl.textContent = ownerName;
    }
    const avatarEl = node.querySelector(".capture-business-node-avatar");
    if (avatarEl) {
      setAvatarPreview(
        avatarEl,
        business.owner?.avatar_data || business.owner?.avatar_url || "",
        getCaptureInitials(ownerName || business.name),
      );
    }
  });
}

function updateCaptureHeaderTimers() {
  if (elements.captureActionStatus) {
    const playerCooldown = Math.max(0, Number(stateCapture.playerCooldownSeconds || 0));
    const nightCooldown = stateCapture.nightCooldownActive ? Math.max(0, Number(stateCapture.nightCooldownSeconds || 0)) : 0;
    const cooldown = Math.max(playerCooldown, nightCooldown);
    elements.captureActionStatus.textContent = nightCooldown > 0
      ? `Ночной кулдаун: ${formatHhMmSs(nightCooldown)}`
      : cooldown > 0
        ? `Кулдаун: ${formatDurationCompact(cooldown)}`
        : "Атака доступна";
    elements.captureActionStatus.classList.toggle("is-cooldown", cooldown > 0);
    elements.captureActionStatus.classList.toggle("is-ready", cooldown <= 0);
  }
  renderCaptureEnergyHud();
}

function formatMmSs(seconds) {
  const safe = Math.max(0, Number(seconds || 0));
  const mm = String(Math.floor(safe / 60)).padStart(2, "0");
  const ss = String(safe % 60).padStart(2, "0");
  return `${mm}:${ss}`;
}

function formatHhMmSs(seconds) {
  const safe = Math.max(0, Number(seconds || 0));
  const hh = String(Math.floor(safe / 3600)).padStart(2, "0");
  const mm = String(Math.floor((safe % 3600) / 60)).padStart(2, "0");
  const ss = String(safe % 60).padStart(2, "0");
  return `${hh}:${mm}:${ss}`;
}

function setCaptureEnergyPopoverOpen(nextOpen) {
  const open = Boolean(nextOpen);
  stateCapture.energyPopoverOpen = open;
  if (elements.captureEnergyPopover) {
    elements.captureEnergyPopover.classList.toggle("hidden", !open);
  }
}

function renderCaptureEnergyHud() {
  if (elements.captureCoinValue) {
    elements.captureCoinValue.textContent = formatPrice(Math.max(0, Number(state.mcoin || 0)));
  }
  const current = Math.max(0, Number(stateCapture.energyCurrent || 0));
  const max = Math.max(1, Number(stateCapture.energyMax || 5));
  const nextSeconds = Math.max(0, Number(stateCapture.energyNextRegenSeconds || 0));
  const valueText = `${current}/${max}`;
  if (elements.captureEnergyValue) {
    elements.captureEnergyValue.textContent = valueText;
  }
  if (elements.captureEnergyPopoverMain) {
    elements.captureEnergyPopoverMain.textContent = `Энергия: ${valueText}`;
  }
  if (elements.captureEnergyPopoverTimer) {
    elements.captureEnergyPopoverTimer.textContent = current >= max
      ? "Полная"
      : `+1 через ${formatMmSs(nextSeconds)}`;
  }
  const nightLine = "🌙 00:00–08:00 МСК\nАтаки запрещены, доход -50%.";
  if (elements.captureNightInline) {
    elements.captureNightInline.textContent = nightLine;
  }
  const liveAlert = stateCapture.liveAlert && typeof stateCapture.liveAlert === "object" ? stateCapture.liveAlert : null;
  if (elements.captureLiveInline) {
    if (liveAlert) {
      const badge = String(liveAlert.badge || "").trim().toLowerCase();
      const icon = badge === "defend" ? "🛡" : badge === "counter" ? "🔥" : "⚔️";
      const territoryName = String(liveAlert.territory_name || "").trim();
      const actionLabel = badge === "defend" ? "Защита" : "Атака";
      elements.captureLiveInline.textContent = territoryName
        ? `${icon} ${actionLabel} ${territoryName}`
        : `${icon} Идёт атака`;
      elements.captureLiveInline.style.display = "";
    } else {
      elements.captureLiveInline.textContent = "";
      elements.captureLiveInline.style.display = "none";
    }
  }
}

function isCaptureLbOpen() {
  return Boolean(elements.captureLbOverlay && !elements.captureLbOverlay.classList.contains("hidden"));
}

function stopCaptureLbRefresh() {
  if (captureLbRefreshTimer) {
    clearInterval(captureLbRefreshTimer);
    captureLbRefreshTimer = null;
  }
}

function getCaptureLeaderboardAvatarSource(telegramId) {
  const userId = Number(telegramId || 0);
  if (!userId) return "";
  const territory = (stateCapture.territories || []).find((item) => Number(item?.owner?.telegram_id || 0) === userId);
  return String(territory?.owner?.avatar_data || territory?.owner?.avatar_url || "");
}

function getCaptureLeaderboardFallbackRows() {
  const byOwner = new Map();
  (stateCapture.territories || []).forEach((territory) => {
    const owner = territory?.owner || null;
    const ownerId = Number(owner?.telegram_id || 0);
    if (!ownerId) return;
    if (!byOwner.has(ownerId)) {
      byOwner.set(ownerId, {
        telegram_id: ownerId,
        display_name: String(owner?.display_name || "Без ника"),
        territories: 0,
        balance: null,
      });
    }
    const entry = byOwner.get(ownerId);
    entry.territories += 1;
  });
  return Array.from(byOwner.values());
}

function renderCaptureLbModal() {
  if (!elements.captureLbRows || !elements.captureLbEmpty) return;
  const sourceRaw = Array.isArray(stateCapture.leaderboard) ? stateCapture.leaderboard : [];
  const source = sourceRaw.length ? sourceRaw : getCaptureLeaderboardFallbackRows();
  const rows = source
    .map((entry) => ({
      telegram_id: Number(
        entry?.telegram_id ??
          entry?.owner_id ??
          entry?.user_id ??
          entry?.userId ??
          entry?.id ??
          0,
      ),
      display_name: String(entry?.display_name || "Без ника"),
      territories: Math.max(0, Number(entry?.territories ?? entry?.territories_count ?? entry?.captures ?? 0)),
      balance: Number.isFinite(Number(entry?.balance ?? entry?.mcoin))
        ? Math.max(0, Number(entry?.balance ?? entry?.mcoin ?? 0))
        : null,
    }))
    .sort((a, b) => {
      if (b.territories !== a.territories) return b.territories - a.territories;
      if ((b.balance ?? -1) !== (a.balance ?? -1)) return (b.balance ?? -1) - (a.balance ?? -1);
      return a.display_name.localeCompare(b.display_name, "ru");
    })
    .slice(0, 10);

  elements.captureLbRows.innerHTML = "";
  if (!rows.length) {
    elements.captureLbEmpty.classList.remove("hidden");
    return;
  }
  elements.captureLbEmpty.classList.add("hidden");

  const frag = document.createDocumentFragment();
  rows.forEach((entry, index) => {
    const row = document.createElement("button");
    row.type = "button";
    row.className = `capture-lb-row${index < 3 ? ` is-top-${index + 1}` : ""}`;

    const rankEl = document.createElement("span");
    rankEl.className = "capture-lb-rank";
    rankEl.textContent = String(index + 1);

    const playerEl = document.createElement("span");
    playerEl.className = "capture-lb-player";
    const avatarEl = document.createElement("span");
    avatarEl.className = "capture-lb-avatar";
    setAvatarPreview(avatarEl, getCaptureLeaderboardAvatarSource(entry.telegram_id), getCaptureInitials(entry.display_name));
    const nameEl = document.createElement("span");
    nameEl.className = "capture-lb-name";
    nameEl.textContent = entry.display_name;
    playerEl.append(avatarEl, nameEl);

    const territoriesEl = document.createElement("span");
    territoriesEl.className = "capture-lb-cell";
    territoriesEl.textContent = String(entry.territories);

    const balanceEl = document.createElement("span");
    balanceEl.className = "capture-lb-cell";
    balanceEl.textContent = entry.balance === null ? "—" : formatPrice(entry.balance);

    row.append(rankEl, playerEl, territoriesEl, balanceEl);
    bindLeaderboardProfileOpen(row, entry.telegram_id, "capture");
    frag.appendChild(row);
  });
  elements.captureLbRows.appendChild(frag);
}

async function refreshCaptureLbData() {
  try {
    const payload = await apiRequest(withAuth("/api/capture/state?leaderboard=1&titles=0&online=0&coupon_preview=1"));
    stateCapture.territories = Array.isArray(payload?.territories) ? payload.territories : stateCapture.territories;
    stateCapture.leaderboard = Array.isArray(payload?.leaderboard) ? payload.leaderboard : [];
  } catch {
    // Keep previously loaded data; modal still renders fallback rows from territories.
  }
  renderCaptureLbModal();
}

async function openCaptureLbModal() {
  if (!elements.captureLbOverlay) return;
  elements.captureLbOverlay.classList.remove("hidden");
  renderCaptureLbModal();
  await refreshCaptureLbData();
  stopCaptureLbRefresh();
  captureLbRefreshTimer = setInterval(() => {
    if (state.page !== "capture" || !isCaptureLbOpen()) {
      stopCaptureLbRefresh();
      return;
    }
    refreshCaptureLbData();
  }, 8000);
}

function closeCaptureLbModal() {
  if (!elements.captureLbOverlay) return;
  elements.captureLbOverlay.classList.add("hidden");
  stopCaptureLbRefresh();
}

function startCaptureTimer() {
  stopCaptureTimer();
  updateCaptureHeaderTimers();
  stateCapture.timerId = setInterval(() => {
    if (state.page !== "capture") {
      stopCaptureTimer();
      return;
    }
    if (stateCapture.season && Number(stateCapture.season.seconds_left || 0) > 0) {
      stateCapture.season.seconds_left = Math.max(0, Number(stateCapture.season.seconds_left) - 1);
    }
    if (Number(stateCapture.playerCooldownSeconds || 0) > 0) {
      stateCapture.playerCooldownSeconds = Math.max(0, Number(stateCapture.playerCooldownSeconds) - 1);
    }
    if (stateCapture.nightCooldownActive) {
      if (Number(stateCapture.nightCooldownSeconds || 0) > 0) {
        stateCapture.nightCooldownSeconds = Math.max(0, Number(stateCapture.nightCooldownSeconds) - 1);
      }
      if (Number(stateCapture.nightCooldownSeconds || 0) <= 0) {
        stateCapture.nightCooldownActive = false;
      }
    }
    if (Number(stateCapture.energyCurrent || 0) < Number(stateCapture.energyMax || 5)) {
      if (Number(stateCapture.energyNextRegenSeconds || 0) > 0) {
        stateCapture.energyNextRegenSeconds = Math.max(0, Number(stateCapture.energyNextRegenSeconds) - 1);
      }
      if (Number(stateCapture.energyNextRegenSeconds || 0) <= 0) {
        stateCapture.energyCurrent = Math.min(
          Number(stateCapture.energyMax || 5),
          Number(stateCapture.energyCurrent || 0) + 1,
        );
        stateCapture.energyNextRegenSeconds = Number(stateCapture.energyCurrent || 0) >= Number(stateCapture.energyMax || 5)
          ? 0
          : 120;
      }
    }
    (stateCapture.territories || []).forEach((item) => {
      if (Number(item.cooldown_seconds || 0) > 0) {
        item.cooldown_seconds = Math.max(0, Number(item.cooldown_seconds) - 1);
      }
    });
    Object.entries(stateCapture.businessOverrides || {}).forEach(([id, raw]) => {
      if (!raw || typeof raw !== "object") return;
      const patch = {};
      if (Number(raw.cooldown_seconds || 0) > 0) {
        patch.cooldown_seconds = Math.max(0, Number(raw.cooldown_seconds) - 1);
      }
      if (Boolean(raw.is_mine) && Number(raw.income_per_hour || 0) > 0) {
        const prevIncomeTick = Math.max(0, Number(raw._income_tick_seconds || 0));
        const nextIncomeTick = prevIncomeTick + 1;
        const incomePerHour = Math.max(1, Number(raw.income_per_hour || 0));
        const gainStep = Math.max(1, Math.round(incomePerHour / 60));
        patch._income_tick_seconds = nextIncomeTick % 60;
        if (nextIncomeTick >= 60) {
          patch.income_unclaimed = Math.max(0, Number(raw.income_unclaimed || 0)) + gainStep;
        }
      }
      if (Object.keys(patch).length) {
        setCaptureBusinessOverridesEntry(Number(id), patch);
      }
    });
    updateCaptureHeaderTimers();
    refreshCaptureNodeStatuses();
    if (stateCapture.selectedTerritoryId) {
      updateCapturePanelLiveState();
    }
    if (stateCapture.season && Number(stateCapture.season.seconds_left || 0) === 0) {
      loadCaptureState({ force: true, silent: true });
    }
  }, isAndroidLiteMode() ? 2000 : 1000);
}

function selectCaptureTerritory(territoryId) {
  stateCapture.selectedTerritoryId = Number(territoryId || 0);
  if (elements.captureMap) {
    elements.captureMap.querySelectorAll("[data-territory-id]").forEach((node) => {
      node.classList.toggle("active", Number(node.dataset.territoryId || 0) === stateCapture.selectedTerritoryId);
    });
  }
  if (elements.captureMapHint) {
    const selectedBusiness = getCaptureBusinessById(stateCapture.selectedTerritoryId);
    const selectedCity = (stateCapture.territories || []).find((item) => Number(item.id) === Number(stateCapture.selectedTerritoryId));
    if (selectedBusiness) {
      elements.captureMapHint.textContent = `Выбрано: ${selectedBusiness.name} (${selectedBusiness.cityName})`;
    } else if (selectedCity) {
      elements.captureMapHint.textContent = `Выбрано: ${selectedCity.name || "Территория"}`;
    } else {
      elements.captureMapHint.textContent = "Нажми на территорию, чтобы атаковать или усилить";
    }
  }
  syncCapturePanel({ force: true });
  openCaptureModal();
}

function openCaptureModal() {
  const overlay = document.getElementById("captureModalOverlay");
  if (overlay) overlay.classList.remove("hidden");
  document.body.classList.add("capture-modal-open");
}

function closeCaptureModal() {
  const overlay = document.getElementById("captureModalOverlay");
  if (overlay) overlay.classList.add("hidden");
  document.body.classList.remove("capture-modal-open");
  stateCapture.selectedTerritoryId = 0;
  stateCapture.panelRenderKey = "";
  if (elements.captureMapHint) {
    elements.captureMapHint.textContent = "Нажми на территорию, чтобы атаковать или усилить";
  }
  if (elements.captureMap) {
    elements.captureMap.querySelectorAll("[data-territory-id]").forEach((node) => {
      node.classList.remove("active");
    });
  }
}

function getCaptureTutorialSeenKey() {
  const tid = Number(state.tid || 0);
  const suffix = tid > 0 ? String(tid) : "anon";
  return `mancini_capture_tutorial_seen_count_${CAPTURE_TUTORIAL_VERSION}_${suffix}`;
}

function getCaptureTutorialSeenCount() {
  try {
    const raw = localStorage.getItem(getCaptureTutorialSeenKey());
    const count = Number(raw || 0);
    return Number.isFinite(count) ? Math.max(0, Math.floor(count)) : 0;
  } catch {
    return 0;
  }
}

function isCaptureTutorialSeen() {
  return getCaptureTutorialSeenCount() >= CAPTURE_TUTORIAL_MAX_SHOWS;
}

function markCaptureTutorialSeen() {
  try {
    const nextCount = Math.min(CAPTURE_TUTORIAL_MAX_SHOWS, getCaptureTutorialSeenCount() + 1);
    localStorage.setItem(getCaptureTutorialSeenKey(), String(nextCount));
  } catch {
    // ignore
  }
}

function clearCaptureTutorialFocus() {
  if (!Array.isArray(stateCaptureTutorial.focusElements) || !stateCaptureTutorial.focusElements.length) return;
  stateCaptureTutorial.focusElements.forEach((node) => {
    node.classList.remove("capture-tutorial-focus", "capture-tutorial-focus--node");
  });
  stateCaptureTutorial.focusElements = [];
}

function scheduleCaptureTutorialLayout() {
  if (!stateCaptureTutorial.active) return;
  if (stateCaptureTutorial.layoutFrameId) return;
  stateCaptureTutorial.layoutFrameId = window.requestAnimationFrame(() => {
    stateCaptureTutorial.layoutFrameId = 0;
    const index = Math.max(0, Math.min(CAPTURE_TUTORIAL_STEPS.length - 1, Number(stateCaptureTutorial.stepIndex || 0)));
    const step = CAPTURE_TUTORIAL_STEPS[index] || CAPTURE_TUTORIAL_STEPS[0];
    applyCaptureTutorialFocus(step);
  });
}

function positionCaptureTutorialCard(focusElement, step) {
  if (!elements.captureTutorialModal) return;
  const card = elements.captureTutorialModal.querySelector(".capture-tutorial-card");
  if (!card) return;
  const viewportW = Math.max(320, Number(window.innerWidth || document.documentElement.clientWidth || 0));
  const viewportH = Math.max(320, Number(window.innerHeight || document.documentElement.clientHeight || 0));
  const rootStyles = window.getComputedStyle(document.documentElement);
  const readCssPxVar = (name) => {
    const rawValue = rootStyles.getPropertyValue(name);
    const parsed = Number.parseFloat(String(rawValue || "").trim());
    return Number.isFinite(parsed) ? parsed : 0;
  };
  const safeTopInset = Math.max(readCssPxVar("--tg-safe-top"), readCssPxVar("--tg-content-safe-top"), 0);
  const safeBottomInset = Math.max(readCssPxVar("--tg-safe-bottom"), readCssPxVar("--tg-content-safe-bottom"), 0);
  const overlayTopInset = Math.max(readCssPxVar("--tg-overlay-offset-top"), 0);
  const edgeX = 12;
  const edgeTop = Math.max(12, Math.round(safeTopInset + overlayTopInset + 12));
  const edgeBottom = Math.max(12, Math.round(safeBottomInset + 12));
  const gap = 12;

  const cardRect = card.getBoundingClientRect();
  const cardWidth = Math.max(220, Math.min(cardRect.width || 300, viewportW - edgeX * 2));
  const cardHeight = Math.max(120, cardRect.height || 180);
  const placement = String(step?.cardPlacement || "").toLowerCase();
  const cardOffsetY = Number.isFinite(Number(step?.cardOffsetY)) ? Number(step.cardOffsetY) : 0;

  let targetCenterX = viewportW / 2;
  let targetCenterY = viewportH * 0.4;
  let targetRx = 68;
  let targetRy = 52;
  let targetRadius = 24;

  if (focusElement) {
    const rect = focusElement.getBoundingClientRect();
    if (rect.width > 0 && rect.height > 0) {
      targetCenterX = rect.left + rect.width / 2;
      targetCenterY = rect.top + rect.height / 2;
      targetRx = Math.max(58, rect.width * 0.8);
      targetRy = Math.max(44, rect.height * 0.8);
      const isNodeLike = focusElement.classList.contains("capture-node-core")
        || focusElement.classList.contains("capture-node")
        || (rect.width <= 140 && rect.height <= 140 && Math.abs(rect.width - rect.height) <= 24);
      targetRadius = isNodeLike ? 999 : 22;
    }
  }

  let cardTop;
  let cardLeft;
  if (placement === "top") {
    cardTop = edgeTop;
    cardLeft = (viewportW - cardWidth) / 2;
  } else {
    const placeBelow = targetCenterY < viewportH * 0.52;
    cardTop = placeBelow
      ? targetCenterY + targetRy + gap
      : targetCenterY - targetRy - cardHeight - gap;
    cardLeft = targetCenterX - cardWidth / 2;
  }
  cardTop += cardOffsetY;

  cardTop = Math.max(edgeTop, Math.min(viewportH - cardHeight - edgeBottom, cardTop));
  cardLeft = Math.max(edgeX, Math.min(viewportW - cardWidth - edgeX, cardLeft));

  card.style.left = `${Math.round(cardLeft)}px`;
  card.style.top = `${Math.round(cardTop)}px`;

  elements.captureTutorialModal.style.setProperty("--capture-tutorial-target-x", `${Math.round(targetCenterX)}px`);
  elements.captureTutorialModal.style.setProperty("--capture-tutorial-target-y", `${Math.round(targetCenterY)}px`);
  elements.captureTutorialModal.style.setProperty("--capture-tutorial-target-rx", `${Math.round(targetRx)}px`);
  elements.captureTutorialModal.style.setProperty("--capture-tutorial-target-ry", `${Math.round(targetRy)}px`);
  elements.captureTutorialModal.style.setProperty("--capture-tutorial-target-radius", `${targetRadius}px`);
}

function resolveCaptureTutorialFocusElements(step) {
  const selector = typeof step?.focusSelector === "string" ? step.focusSelector.trim() : "";
  if (!selector) return [];
  const nodes = Array.from(document.querySelectorAll(selector));
  return nodes.filter((node) => node.getClientRects().length > 0);
}

function applyCaptureTutorialFocus(step) {
  clearCaptureTutorialFocus();
  const focusElements = resolveCaptureTutorialFocusElements(step);
  focusElements.forEach((focusElement) => {
    focusElement.classList.add("capture-tutorial-focus");
    if (focusElement.classList.contains("capture-node") || focusElement.classList.contains("capture-node-core")) {
      focusElement.classList.add("capture-tutorial-focus--node");
    }
  });
  stateCaptureTutorial.focusElements = focusElements;
  positionCaptureTutorialCard(focusElements[0] || null, step);
}

function prepareCaptureTutorialStep(index) {
  const safeIndex = Math.max(0, Number(index || 0));
  if (safeIndex === 1) {
    const selectedId = Number(stateCapture.selectedTerritoryId || 0);
    if (selectedId > 0) {
      const selectedTerritory = (stateCapture.territories || []).find((item) => Number(item?.id || 0) === selectedId);
      if (selectedTerritory && !Boolean(selectedTerritory.is_mine)) {
        selectCaptureTerritory(selectedId);
        return;
      }
    }
    const attackableTerritory = (stateCapture.territories || []).find((item) => Number(item?.id || 0) > 0 && !Boolean(item.is_mine));
    if (attackableTerritory) {
      selectCaptureTerritory(Number(attackableTerritory.id));
      return;
    }
    const fallbackTerritory = (stateCapture.territories || []).find((item) => Number(item?.id || 0) > 0);
    if (fallbackTerritory) {
      selectCaptureTerritory(Number(fallbackTerritory.id));
    }
    return;
  }
  if (safeIndex === 2) {
    closeCaptureModal();
  }
}

function renderCaptureTutorialStep() {
  if (!elements.captureTutorialTitle || !elements.captureTutorialText || !elements.captureTutorialStep || !elements.captureTutorialNext) return;
  const total = CAPTURE_TUTORIAL_STEPS.length;
  const index = Math.max(0, Math.min(total - 1, Number(stateCaptureTutorial.stepIndex || 0)));
  const step = CAPTURE_TUTORIAL_STEPS[index] || CAPTURE_TUTORIAL_STEPS[0];
  elements.captureTutorialStep.textContent = `${index + 1}/${total}`;
  elements.captureTutorialTitle.textContent = String(step?.title || "Захват территорий");
  elements.captureTutorialText.textContent = String(step?.text || "");
  elements.captureTutorialNext.textContent = index >= total - 1 ? "Понятно ✓" : "Далее →";
  applyCaptureTutorialFocus(step);
}

function closeCaptureTutorial({ markSeen = true } = {}) {
  if (!elements.captureTutorialModal) return;
  elements.captureTutorialModal.classList.remove("show");
  document.body.classList.remove("capture-tutorial-active");
  if (stateCaptureTutorial.layoutFrameId) {
    window.cancelAnimationFrame(stateCaptureTutorial.layoutFrameId);
    stateCaptureTutorial.layoutFrameId = 0;
  }
  elements.captureTutorialModal.style.removeProperty("--capture-tutorial-target-x");
  elements.captureTutorialModal.style.removeProperty("--capture-tutorial-target-y");
  elements.captureTutorialModal.style.removeProperty("--capture-tutorial-target-rx");
  elements.captureTutorialModal.style.removeProperty("--capture-tutorial-target-ry");
  elements.captureTutorialModal.style.removeProperty("--capture-tutorial-target-radius");
  clearCaptureTutorialFocus();
  stateCaptureTutorial.active = false;
  stateCaptureTutorial.openScheduled = false;
  if (markSeen) markCaptureTutorialSeen();
}

function openCaptureTutorial() {
  if (!elements.captureTutorialModal) return;
  if (state.page !== "capture") return;
  if (stateCaptureTutorial.active || isCaptureTutorialSeen()) return;
  stateCaptureTutorial.stepIndex = 0;
  stateCaptureTutorial.active = true;
  stateCaptureTutorial.openScheduled = false;
  document.body.classList.add("capture-tutorial-active");
  elements.captureTutorialModal.classList.add("show");
  prepareCaptureTutorialStep(0);
  renderCaptureTutorialStep();
  scheduleCaptureTutorialLayout();
}

function scheduleCaptureTutorialOpen() {
  if (stateCaptureTutorial.active || stateCaptureTutorial.openScheduled || isCaptureTutorialSeen()) return;
  stateCaptureTutorial.openScheduled = true;
  window.setTimeout(() => {
    if (state.page !== "capture") {
      stateCaptureTutorial.openScheduled = false;
      return;
    }
    openCaptureTutorial();
  }, 380);
}

function scheduleCaptureTrailsRender() {
  if (captureTrailsScheduled) return;
  captureTrailsScheduled = true;
  window.requestAnimationFrame(() => {
    captureTrailsScheduled = false;
    layoutCaptureBusinessEdges();
    renderCaptureTrails();
  });
}

function bindCaptureTrailsListeners() {
  if (captureTrailsListenersBound) return;
  if (isAndroidLiteMode()) return;
  captureTrailsListenersBound = true;
  window.addEventListener(
    "resize",
    () => {
      if (state.page !== "capture") return;
      scheduleCaptureTrailsRender();
    },
    { passive: true },
  );
}

function updateCaptureHudVisibility(scrollTop = 0) {
  const hud = document.querySelector(".capture-hud");
  if (!hud) return;
  const value = Math.max(0, Number(scrollTop || 0));
  const hideThreshold = 96;
  const showThreshold = 58;
  if (state.page !== "capture") {
    captureHudHiddenByScroll = false;
  } else if (!captureHudHiddenByScroll && value >= hideThreshold) {
    captureHudHiddenByScroll = true;
  } else if (captureHudHiddenByScroll && value <= showThreshold) {
    captureHudHiddenByScroll = false;
  }
  const hidden = state.page === "capture" && captureHudHiddenByScroll;
  hud.classList.toggle("is-hidden", hidden);
  document.body.classList.toggle("capture-online-scroll-hidden", hidden);
  if (elements.captureBottomTrophyBtn) {
    elements.captureBottomTrophyBtn.classList.toggle("is-hidden", hidden);
  }
}

function renderCaptureParallax() {
  if (!elements.captureMap || !elements.captureMapCard || state.page !== "capture") return;
  const scrollTop = Number(elements.captureMap.scrollTop || 0);
  updateCaptureHudVisibility(scrollTop);
  if (isAndroidLiteMode()) return; /* skip CSS var updates — static bg on Android */
  elements.captureMapCard.style.setProperty("--capture-star-shift-far", `${-scrollTop * 0.16}px`);
  elements.captureMapCard.style.setProperty("--capture-star-shift-mid", `${-scrollTop * 0.26}px`);
  elements.captureMapCard.style.setProperty("--capture-star-shift-near", `${-scrollTop * 0.38}px`);
  elements.captureMapCard.style.setProperty("--capture-planet-shift", `${-scrollTop * 0.1}px`);
}

function scheduleCaptureParallaxRender() {
  if (captureParallaxScheduled) return;
  captureParallaxScheduled = true;
  window.requestAnimationFrame(() => {
    captureParallaxScheduled = false;
    renderCaptureParallax();
  });
}

function bindCaptureParallaxListeners() {
  if (captureParallaxListenersBound || !elements.captureMap) return;
  captureParallaxListenersBound = true;
  elements.captureMap.addEventListener(
    "scroll",
    () => {
      if (state.page !== "capture") return;
      scheduleCaptureParallaxRender();
      scheduleCaptureTrailsRender();
      scheduleCaptureTutorialLayout();
      notifyCaptureScrollSound();
    },
    { passive: true },
  );
  window.addEventListener(
    "resize",
    () => {
      if (state.page !== "capture") return;
      scheduleCaptureParallaxRender();
      scheduleCaptureTutorialLayout();
    },
    { passive: true },
  );
}

function triggerCaptureVictoryFx() {
  hapticImpact("heavy");
  setTimeout(() => hapticImpact("medium"), 90);
  setTimeout(() => hapticImpact("heavy"), 190);
  try {
    window.Telegram?.WebApp?.HapticFeedback?.notificationOccurred?.("success");
  } catch {
    // ignore
  }
  try {
    if (typeof navigator !== "undefined" && typeof navigator.vibrate === "function") {
      navigator.vibrate([50, 38, 72, 30, 96]);
    }
  } catch {
    // ignore
  }
  const host = document.body;
  if (!host) return;
  const prev = host.querySelector(".capture-confetti-overlay");
  if (prev) prev.remove();
  const overlay = document.createElement("div");
  overlay.className = "capture-confetti-overlay";
  const confettiCount = isAndroidLiteMode() ? 12 : 48;
  for (let idx = 0; idx < confettiCount; idx += 1) {
    const piece = document.createElement("span");
    piece.className = "capture-confetti-piece";
    const drift = (Math.random() - 0.5) * 34;
    const peak = 34 + Math.random() * 34;
    piece.style.setProperty("--spawn-x", `${Math.random() * 100}%`);
    piece.style.setProperty("--drift", `${drift}vw`);
    piece.style.setProperty("--drift-end", `${drift * 1.35}vw`);
    piece.style.setProperty("--peak-neg", `-${peak}vh`);
    piece.style.setProperty("--rot", `${(Math.random() - 0.5) * 820}deg`);
    piece.style.setProperty("--delay", `${Math.random() * 0.22}s`);
    piece.style.setProperty("--dur", `${1.55 + Math.random() * 0.75}s`);
    piece.style.setProperty("--hue", String(Math.floor(Math.random() * 360)));
    if (idx % 5 === 0) piece.classList.add("is-star");
    if (idx % 7 === 0) piece.classList.add("is-line");
    overlay.appendChild(piece);
  }
  host.appendChild(overlay);
  window.setTimeout(() => {
    overlay.classList.add("fade-out");
  }, 1650);
  window.setTimeout(() => {
    overlay.remove();
  }, 2350);
}

function renderCaptureTrails() {
  if (!elements.captureMap || state.page !== "capture") return;
  let layer = elements.captureMap.querySelector(".capture-trails-layer");
  if (!layer) {
    layer = document.createElement("div");
    layer.className = "capture-trails-layer";
    elements.captureMap.prepend(layer);
  }
  layer.innerHTML = "";
  const nodes = Array.from(elements.captureMap.querySelectorAll(".capture-node"));
  if (nodes.length < 2) return;
  const mapRect = elements.captureMap.getBoundingClientRect();
  const scrollTop = Number(elements.captureMap.scrollTop || 0);
  const scrollLeft = Number(elements.captureMap.scrollLeft || 0);
  for (let idx = 0; idx < nodes.length - 1; idx += 1) {
    const fromCore = nodes[idx].querySelector(".capture-node-core") || nodes[idx];
    const toCore = nodes[idx + 1].querySelector(".capture-node-core") || nodes[idx + 1];
    const a = fromCore.getBoundingClientRect();
    const b = toCore.getBoundingClientRect();
    const x1 = a.left - mapRect.left + scrollLeft + a.width / 2;
    const y1 = a.top - mapRect.top + scrollTop + a.height / 2;
    const x2 = b.left - mapRect.left + scrollLeft + b.width / 2;
    const y2 = b.top - mapRect.top + scrollTop + b.height / 2;
    const dx = x2 - x1;
    const dy = y2 - y1;
    const length = Math.max(1, Math.hypot(dx, dy));
    const angle = Math.atan2(dy, dx) * (180 / Math.PI);
    const trail = document.createElement("span");
    trail.className = "capture-trail";
    trail.style.left = `${x1}px`;
    trail.style.top = `${y1}px`;
    trail.style.width = `${length}px`;
    trail.style.transform = `rotate(${angle}deg)`;
    trail.style.opacity = String(0.52 + (idx % 3) * 0.1);
    trail.style.animationDelay = `${idx * 0.22}s`;
    layer.appendChild(trail);
  }
}

function layoutCaptureBusinessEdges() {
  if (!elements.captureMap) return;
  const clusters = elements.captureMap.querySelectorAll(".capture-node-cluster");
  clusters.forEach((cluster) => {
    const edge = cluster.querySelector(".capture-business-edge");
    const cityCore = cluster.querySelector(".capture-node .capture-node-core");
    const businessCore = cluster.querySelector(".capture-business-node .capture-business-node-core");
    if (!edge || !cityCore || !businessCore) return;
    const clusterRect = cluster.getBoundingClientRect();
    const a = cityCore.getBoundingClientRect();
    const b = businessCore.getBoundingClientRect();
    const x1 = a.left - clusterRect.left + a.width / 2;
    const y1 = a.top - clusterRect.top + a.height / 2;
    const x2 = b.left - clusterRect.left + b.width / 2;
    const y2 = b.top - clusterRect.top + b.height / 2;
    const dx = x2 - x1;
    const dy = y2 - y1;
    const length = Math.max(1, Math.hypot(dx, dy));
    const angle = Math.atan2(dy, dx) * (180 / Math.PI);
    edge.style.left = `${x1}px`;
    edge.style.top = `${y1}px`;
    edge.style.width = `${length}px`;
    edge.style.transform = `rotate(${angle}deg)`;
  });
}

/* Build a lightweight fingerprint — only structural identity (IDs + count).
   Owner/state changes are handled by in-place update, no need to rebuild DOM. */
function _captureMapFingerprint(list) {
  return list.map((t) => t.id).join("|");
}
let _captureMapLastFingerprint = "";

const { CAPTURE_MAP_BUILDING_BY_SLUG, CAPTURE_BUSINESS_BY_CITY_SLUG } = (window.__miniappStaticCatalogs || {});

function getCaptureBusinessSourceTerritoryByBusinessId(businessId) {
  const target = Number(businessId || 0);
  if (target >= 0) return null;
  const cityId = Math.abs(target) - 1000;
  return (stateCapture.territories || []).find((item) => Number(item?.id || 0) === cityId) || null;
}

function getCaptureBusinessOverridesEntry(businessId) {
  const key = String(Number(businessId || 0));
  const map = stateCapture.businessOverrides && typeof stateCapture.businessOverrides === "object"
    ? stateCapture.businessOverrides
    : {};
  const value = map[key];
  return value && typeof value === "object" ? value : null;
}

function setCaptureBusinessOverridesEntry(businessId, patch = {}) {
  const key = String(Number(businessId || 0));
  if (!key || key === "0") return;
  const prev = getCaptureBusinessOverridesEntry(businessId) || {};
  stateCapture.businessOverrides = {
    ...(stateCapture.businessOverrides && typeof stateCapture.businessOverrides === "object" ? stateCapture.businessOverrides : {}),
    [key]: { ...prev, ...patch },
  };
}

function getCaptureCurrentOwnerStub() {
  const profile = stateProfile?.data && typeof stateProfile.data === "object" ? stateProfile.data : {};
  const telegramId = Number(profile.telegram_id || state.tid || 0);
  const displayName = String(profile.game_nick || profile.display_name || "Вы").trim() || "Вы";
  const ownedTerritory = (stateCapture.territories || []).find(
    (item) => Number(item?.owner?.telegram_id || 0) === telegramId,
  );
  const fallbackAvatarData = ownedTerritory?.owner?.avatar_data || "";
  const fallbackAvatarUrl = ownedTerritory?.owner?.avatar_url || "";
  return {
    telegram_id: telegramId || 0,
    display_name: displayName,
    avatar_data: profile.avatar_data || fallbackAvatarData || "",
    avatar_url: profile.avatar_url || fallbackAvatarUrl || "",
  };
}

function getCaptureBusinessAttackModes(sourceTerritory) {
  if (Array.isArray(sourceTerritory?.attack_modes) && sourceTerritory.attack_modes.length) {
    return sourceTerritory.attack_modes.map((mode) => ({ ...mode }));
  }
  return [{ key: "NORMAL", title: "Обычная", multiplier: 1 }];
}

function getCaptureBusinessForTerritory(territory) {
  if (!territory || !Number(territory.id || 0)) return null;
  const slug =
    resolveCaptureCitySlug(territory.code || "", CAPTURE_MAP_BUILDING_BY_SLUG)
    || resolveCaptureCitySlug(territory.name || "", CAPTURE_MAP_BUILDING_BY_SLUG);
  const preset = slug ? CAPTURE_BUSINESS_BY_CITY_SLUG[slug] : null;
  if (!preset) return null;
  const seed = Math.max(1, Number(territory.id || 0));
  const businessId = -(1000 + seed);
  const serverBusiness = Array.isArray(stateCapture.businesses)
    ? stateCapture.businesses.find((item) => Number(item?.id || 0) === businessId || Number(item?.city_id || 0) === Number(territory.id || 0))
    : null;
  if (serverBusiness && typeof serverBusiness === "object") {
    return {
      ...serverBusiness,
      id: Number(serverBusiness.id || businessId),
      cityId: Number(serverBusiness.city_id || territory.id || 0),
      cityName: String(serverBusiness.city_name || territory.name || "Город"),
      name: String(serverBusiness.name || preset.name || "Бизнес"),
      code: String(serverBusiness.code || `${String(territory.code || slug || "city")}_business`),
      business_key: String(serverBusiness.business_key || preset.key || ""),
      node_image: encodeURI(String(preset.nodeImage || "")),
      card_image: encodeURI(String(preset.cardImage || "")),
      is_business: true,
    };
  }
  const overrides = getCaptureBusinessOverridesEntry(businessId) || {};
  const owner = overrides.owner ?? null;
  const isMine = Boolean(overrides.is_mine);
  const cooldownSeconds = Math.max(0, Number(territory.cooldown_seconds || 0) - ((seed * 7) % 120));
  const attackModes = getCaptureBusinessAttackModes(territory);
  const attackBaseCost = 20 + ((seed * 11) % 55);
  const defenseLevel = seed % 3;
  const incomePerHour = 45 + ((seed * 19) % 170);
  const incomeUnclaimed = 10 + ((seed * 13) % 140);
  const baseBusiness = {
    id: businessId,
    cityId: Number(territory.id || 0),
    cityName: String(territory.name || "Город"),
    code: `${String(territory.code || slug || "city")}_business`,
    name: preset.name,
    owner,
    is_mine: isMine,
    cooldown_seconds: Math.max(0, Number(overrides.cooldown_seconds ?? cooldownSeconds)),
    defense_level: Math.max(0, Math.min(3, Number(overrides.defense_level ?? defenseLevel))),
    attack_base_cost: Math.max(1, Number(overrides.attack_base_cost ?? attackBaseCost)),
    defense_upgrade_cost_next: Math.max(
      1,
      Number(overrides.defense_upgrade_cost_next ?? overrides.attack_base_cost ?? attackBaseCost),
    ),
    income_per_hour: Math.max(1, Number(overrides.income_per_hour ?? incomePerHour)),
    income_unclaimed: Math.max(0, Number(overrides.income_unclaimed ?? incomeUnclaimed)),
    attack_modes: Array.isArray(overrides.attack_modes) && overrides.attack_modes.length ? overrides.attack_modes : attackModes,
    live_event: overrides.live_event && typeof overrides.live_event === "object" ? overrides.live_event : null,
    business_key: preset.key,
    node_image: encodeURI(String(preset.nodeImage || "")),
    card_image: encodeURI(String(preset.cardImage || "")),
    is_business: true,
  };
  return baseBusiness;
}

function getCaptureBusinessById(businessId) {
  const target = Number(businessId || 0);
  if (target >= 0) return null;
  const territories = Array.isArray(stateCapture.territories) ? stateCapture.territories : [];
  for (const territory of territories) {
    const business = getCaptureBusinessForTerritory(territory);
    if (business && Number(business.id || 0) === target) return business;
  }
  return null;
}

function getCaptureMapBuildingImage(territory) {
  const tryResolve = (value) => {
    const slug = resolveCaptureCitySlug(value, CAPTURE_MAP_BUILDING_BY_SLUG);
    return slug ? CAPTURE_MAP_BUILDING_BY_SLUG[slug] : "";
  };
  return tryResolve(territory.code || "") || tryResolve(territory.name || "") || "";
}

/* Stabilized online counter for capture page */
function renderCaptureOnline(raw1h) {
  if (!elements.captureOnlineBadge || !elements.captureOnlineText) return;
  const base = Math.max(0, Number(raw1h || 0));
  const display = Math.max(15, Math.round(base));
  const text = `${display} онлайн`;
  elements.captureOnlineText.textContent = text;
  elements.captureOnlineBadge.classList.remove("hidden");
}


// ── Бухгалтерия: confirmed deals of one month (bought / sold / balance + the list); months are paged left/right ──
const stateTradeReport = { month: "", firstMonth: "", cache: new Map(), token: 0, bound: false };
const REPORT_MONTHS = ["Январь", "Февраль", "Март", "Апрель", "Май", "Июнь", "Июль", "Август", "Сентябрь", "Октябрь", "Ноябрь", "Декабрь"];

function reportCurrentMonth() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
}

function reportShiftMonth(month, delta) {
  const [y, m] = month.split("-").map(Number);
  const d = new Date(y, m - 1 + delta, 1);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
}

function reportMonthLabel(month) {
  const [y, m] = month.split("-").map(Number);
  return `${REPORT_MONTHS[m - 1] || ""} ${y}`;
}

function reportMoney(value, signed = false) {
  const n = Number(value) || 0;
  const sign = signed ? (n > 0 ? "+" : n < 0 ? "−" : "") : "";
  return `${sign}${formatPrice(Math.abs(n))} ₽`;
}

function reportCanGo(delta) {
  const next = reportShiftMonth(stateTradeReport.month, delta);
  if (delta > 0) return next <= reportCurrentMonth();
  return !stateTradeReport.firstMonth || next >= stateTradeReport.firstMonth;
}

function renderTradeReport(data, direction = 0) {
  const box = document.getElementById("reportContent");
  const title = document.getElementById("reportMonthTitle");
  if (!box || !title) return;
  title.textContent = reportMonthLabel(stateTradeReport.month);
  document.getElementById("reportPrev")?.toggleAttribute("disabled", !reportCanGo(-1));
  document.getElementById("reportNext")?.toggleAttribute("disabled", !reportCanGo(1));
  if (!data) {
    box.innerHTML = '<div class="report-empty">Загрузка…</div>';
    return;
  }
  const rows = (data.deals || []).map((deal) => {
    const sell = deal.side === "sell";
    const day = String(deal.at || "").slice(8, 10) + "." + String(deal.at || "").slice(5, 7);
    const meta = [day, deal.category, deal.server_id ? `Сервер ${deal.server_id}` : ""].filter(Boolean).join(" • ");
    return `<div class="report-row">
      <span class="report-row-icon ${sell ? "is-sell" : "is-buy"}">${sell ? "↑" : "↓"}</span>
      <span class="report-row-body"><b>${escapeHtmlText(deal.title)}</b><small>${escapeHtmlText(sell ? "Продал" : "Купил")} • ${escapeHtmlText(meta)}</small></span>
      <span class="report-row-sum ${sell ? "is-sell" : "is-buy"}">${sell ? "+" : "−"}${formatPrice(deal.price)} ₽</span>
    </div>`;
  }).join("");
  const balance = Number(data.balance) || 0;
  box.innerHTML = `
    <div class="report-tiles">
      <div class="report-tile"><span>Продано</span><b class="is-sell">${reportMoney(data.sold)}</b><small>${data.sold_count} шт.</small></div>
      <div class="report-tile"><span>Куплено</span><b class="is-buy">${reportMoney(data.bought)}</b><small>${data.bought_count} шт.</small></div>
      <div class="report-tile report-tile--wide"><span>Итог за месяц</span><b class="${balance > 0 ? "is-sell" : balance < 0 ? "is-buy" : ""}">${reportMoney(balance, true)}</b></div>
    </div>
    <div class="report-list-title">Сделки · ${(data.deals || []).length}</div>
    ${rows || '<div class="report-empty">В этом месяце сделок не было</div>'}
    <div class="report-note">Суммы в игровых рублях. Месяц считается по дате подтверждения сделки.</div>`;
  if (direction) {
    box.animate([{ transform: `translateX(${direction * 40}px)`, opacity: 0 }, { transform: "none", opacity: 1 }], { duration: 220, easing: "ease-out" });
  }
}

async function loadTradeReport(direction = 0) {
  const month = stateTradeReport.month;
  const token = ++stateTradeReport.token;
  const cached = stateTradeReport.cache.get(month);
  if (cached) renderTradeReport(cached, direction);
  else renderTradeReport(null);
  try {
    const data = await apiRequest(withAuth(`/api/me/report?month=${encodeURIComponent(month)}`));
    if (data && data.first_month) stateTradeReport.firstMonth = data.first_month;
    stateTradeReport.cache.set(month, data);
    // the report opens on the current month; when it is empty but older deals exist, show the latest month with deals instead
    if (stateTradeReport.autoJump && token === stateTradeReport.token) {
      stateTradeReport.autoJump = false;
      if (!(data.deals || []).length && data.last_month && data.last_month < month) {
        stateTradeReport.month = data.last_month;
        loadTradeReport();
        return;
      }
    }
    if (token === stateTradeReport.token) renderTradeReport(data, cached ? 0 : direction);
  } catch {
    if (token === stateTradeReport.token && !cached) {
      const box = document.getElementById("reportContent");
      if (box) box.innerHTML = '<div class="report-empty">Не удалось загрузить отчёт. Попробуйте ещё раз.</div>';
    }
  }
}

function openTradeReport() {
  stateTradeReport.month = reportCurrentMonth();
  stateTradeReport.autoJump = true;
  stateTradeReport.cache.clear();
  loadTradeReport();
}

function shiftTradeReport(delta) {
  if (!reportCanGo(delta)) return;
  stateTradeReport.month = reportShiftMonth(stateTradeReport.month, delta);
  loadTradeReport(delta);
}

function bindTradeReport() {
  if (stateTradeReport.bound) return;
  stateTradeReport.bound = true;
  const entry = document.getElementById("profileReportEntry");
  const open = () => navigateTo("profile-report");
  entry?.addEventListener("click", open);
  entry?.addEventListener("keydown", (event) => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); open(); } });
  document.getElementById("reportPrev")?.addEventListener("click", () => shiftTradeReport(-1));
  document.getElementById("reportNext")?.addEventListener("click", () => shiftTradeReport(1));
  const pager = document.getElementById("reportPager");
  let start = null;
  pager?.addEventListener("touchstart", (event) => {
    const t = event.touches[0];
    start = event.touches.length === 1 ? { x: t.clientX, y: t.clientY, at: Date.now() } : null;
  }, { passive: true });
  pager?.addEventListener("touchend", (event) => {
    if (!start) return;
    const t = event.changedTouches[0];
    const dx = t.clientX - start.x;
    const dy = t.clientY - start.y;
    const quick = Date.now() - start.at < 700;
    start = null;
    if (quick && Math.abs(dx) > 50 && Math.abs(dx) > Math.abs(dy) * 1.6) shiftTradeReport(dx < 0 ? 1 : -1);  // swipe left = the next month
  }, { passive: true });
  document.addEventListener("keydown", (event) => {
    if (state.page !== "profile-report") return;
    if (event.key === "ArrowLeft") shiftTradeReport(-1);
    if (event.key === "ArrowRight") shiftTradeReport(1);
  });
}


// ── Справочники «Матрешка РП» (публичная база знаний): машины и бизнесы/АЗС, подсказки в названии объявления ──
// Lists: /data/catalog/vehicles.json and businesses.json (scripts/catalog/import_matrp_vehicles.py). Search ignores case, spaces and
// punctuation and works in both scripts: «вада 2101», «vada 2101», «ваз 2101», «запорожец», «442» all find the same car.
// The title is free text («Продаю Bmw M3 срочно, торг»): words that match nothing are ignored, the car words still find the car.
const catalogState = { entries: {}, loading: {}, picked: null };  // picked = { kind, item }
const CATALOG_FILES = { vehicle: "/data/catalog/vehicles.json", business: "/data/catalog/businesses.json", fuel: "/data/catalog/fuel.json", house: "/data/catalog/houses.json", garage: "/data/catalog/garages.json", skin: "/data/catalog/skins.json" };
const CATALOG_CATEGORY = { vehicle: "Автомобили", business: "Бизнес", fuel: "Бизнес", house: "Недвижимость", garage: "Недвижимость", skin: "Скины" };
const CATALOG_KINDS_BY_CATEGORY = { "Автомобили": ["vehicle"], "Бизнес": ["business", "fuel"], "Недвижимость": ["house", "garage"], "Скины": ["skin"] };
const CATALOG_TRANSLIT = { а: "a", б: "b", в: "v", г: "g", д: "d", е: "e", ё: "e", ж: "zh", з: "z", и: "i", й: "y", к: "k", л: "l", м: "m", н: "n", о: "o", п: "p", р: "r", с: "s", т: "t", у: "u", ф: "f", х: "h", ц: "c", ч: "ch", ш: "sh", щ: "sh", ъ: "", ы: "y", ь: "", э: "e", ю: "u", я: "ya" };
const CATALOG_FILLER = new Set(("продаю продам продается продаётся куплю отдам обмен меняю срочно торг недорого дорого цена за на в и с по не от до или моя мой моё мою " +
  "скин скины скина скину машина машину авто автомобиль тачка тачку тачки новая новый хороший хорошая идеал идеальная идеальное состояние сервер игровая игровой есть нужна нужен ищу бизнес бизнеса").split(" "));

function catalogNorm(text) {
  return String(text || "").toLowerCase().replace(/ё/g, "е").replace(/[^a-z0-9а-я]+/g, "");
}

function catalogTranslit(text) {
  return String(text || "").replace(/[а-я]/g, (ch) => CATALOG_TRANSLIT[ch] ?? ch);
}

function catalogKindsForCategory(category) {
  if (CATALOG_KINDS_BY_CATEGORY[category]) return CATALOG_KINDS_BY_CATEGORY[category];
  return category ? [] : ["vehicle", "business", "fuel", "house", "garage", "skin"];  // no category chosen yet: look in all lists
}

function loadCatalog(kind) {
  if (catalogState.entries[kind]) return Promise.resolve(catalogState.entries[kind]);
  if (!catalogState.loading[kind]) {
    catalogState.loading[kind] = fetch(CATALOG_FILES[kind], { cache: "no-cache" })  // revalidated every time (a 304 is cheap): a stale list once hid the new car photos
      .then((resp) => (resp.ok ? resp.json() : Promise.reject(new Error("catalog_http_" + resp.status))))
      .then((data) => {
        catalogState.entries[kind] = (data.items || []).map((item) => {
          if (kind === "skin") item.kind = "Скин";
          if (kind === "house" || kind === "garage") {  // the map knows them by number only
            item.kind = kind === "house" ? "Дом" : "Гараж";
            item.name = `${item.kind} #${item.id}`;
          }
          const keys = [catalogNorm(item.name), catalogNorm(item.real), String(item.id)];
          const words = `${item.name} ${item.real || ""} ${item.kind || ""}`.toLowerCase().replace(/ё/g, "е").split(/[^a-z0-9а-я]+/).filter(Boolean);
          return { kind, item, words: [...words, ...words.map(catalogTranslit)], hay: [...keys, ...keys.map(catalogTranslit)].join(" "), start: [keys[0], keys[1], catalogTranslit(keys[0]), catalogTranslit(keys[1])] };
        });
        return catalogState.entries[kind];
      })
      .catch(() => { delete catalogState.loading[kind]; return []; });  // the helper is optional: without the list the form works as before
  }
  return catalogState.loading[kind];
}

// «bmw m» finds «BMW M3 E36»: a token has to start a word of the name (any script); a token of 3+ letters may also sit inside a word.
function searchCatalog(query, kinds, limit = 40) {
  const tokens = String(query || "").toLowerCase().split(/[\s,.!?;:()"«»/+-]+/).filter((t) => t && !CATALOG_FILLER.has(t)).map(catalogNorm).filter(Boolean);
  if (!tokens.length) return [];
  const scored = [];
  for (const kind of kinds) {
    for (const entry of catalogState.entries[kind] || []) {
      let score = 0;
      let matched = 0;      // tokens that matched
      let strong = 0;       // matched tokens that are not a lone letter («m» alone must not make a car a result)
      for (const token of tokens) {
        const tr = catalogTranslit(token);
        let hit = 0;
        if (entry.words.some((w) => w.startsWith(token) || w.startsWith(tr))) hit = 3;
        else if (token.length >= 3 && (entry.hay.includes(token) || entry.hay.includes(tr))) hit = 1;
        else if (token.length >= 5) {  // endings differ («шаурма» / «Шаурменная»): compare the stem
          const stem = token.slice(0, -1);
          const stemTr = catalogTranslit(stem);
          if (entry.words.some((w) => w.startsWith(stem) || w.startsWith(stemTr))) hit = 2;
        }
        if (!hit) continue;
        score += hit;
        matched += 1;
        if (token.length > 1 || /\d/.test(token)) strong += 1;
      }
      if (!strong) continue;
      if (matched === tokens.length) score += 4;  // every word of the title is part of this entry
      if (tokens.includes(String(entry.item.id))) score += 5;  // «дом 145» / «145»: the exact number first
      const joined = tokens.join("");
      if (entry.start.some((k) => k && (k.startsWith(joined) || k.startsWith(catalogTranslit(joined))))) score += 2;  // the whole title starts like the name
      scored.push({ entry, score });
    }
  }
  scored.sort((a, b) => b.score - a.score || a.entry.item.name.localeCompare(b.entry.item.name));
  return scored.slice(0, limit).map((x) => ({ kind: x.entry.kind, item: x.entry.item }));
}

function catalogPriceText(item) {
  return item.price && item.price >= 1000 ? `${formatPrice(item.price)} ₽` : "";
}

// A listing without its own photo gets the picture of the catalog entry it points at (cars, skins): «vehicle:442» / «skin:18332».
// (the id below has no picture: photo=false in vehicles.json; catalog_import_smoke keeps this list in sync). Businesses and banks keep the plain category cover on purpose.
const CATALOG_CARS_WITHOUT_PHOTO = new Set(["17945"]);
function catalogPhotoUrl(ref) {
  const m = /^(vehicle|skin):(\d+)$/.exec(String(ref || ""));
  if (!m) return "";
  if (m[1] === "skin") return `/assets/skins/${m[2]}.webp`;
  return CATALOG_CARS_WITHOUT_PHOTO.has(m[2]) ? "" : `/assets/cars/${m[2]}.webp`;
}

// the images of the listing page: its own photos, else the catalog picture
function listingGalleryImages(data) {
  const own = Array.isArray(data?.images) ? data.images.filter(Boolean) : [];
  if (own.length) return own;
  const photo = catalogPhotoUrl(data?.catalog_item_id);
  return photo ? [photo] : [];
}

function catalogThumbUrl(kind, item) {
  if (kind === "skin") return `/assets/skins/${item.id}.webp`;
  if (kind === "vehicle" && item.photo) return `/assets/cars/${item.id}.webp`;
  return "";
}

function catalogSpecsText(kind, item) {
  if (kind === "skin") return `Скин · ID ${item.id}`;
  if (kind !== "vehicle") return [item.kind, kind === "house" || kind === "garage" ? "" : `ID ${item.id}`, catalogPriceText(item) ? `госцена ${catalogPriceText(item)}` : ""].filter(Boolean).join(" · ");
  const parts = [];
  if (catalogPriceText(item)) parts.push(`госцена ${catalogPriceText(item)}`);
  if (item.accel) parts.push(`0–100 за ${item.accel} с`);
  if (item.speed) parts.push(`${item.speed} км/ч`);
  return parts.join(" · ");
}

function bindCatalogSuggest() {
  const form = elements.createForm;
  const titleInput = form && form.elements.title;
  if (!titleInput || titleInput.dataset.catalogBound) return;
  titleInput.dataset.catalogBound = "1";
  titleInput.setAttribute("autocomplete", "off");
  const box = document.createElement("div");
  box.className = "catalog-suggest";
  box.hidden = true;
  const picked = document.createElement("div");
  picked.className = "catalog-picked";
  picked.hidden = true;
  titleInput.insertAdjacentElement("afterend", box);
  box.insertAdjacentElement("afterend", picked);

  const currentKinds = () => catalogKindsForCategory(String(elements.createCategoryInput?.value || ""));
  const hide = () => { box.hidden = true; box.innerHTML = ""; };
  const refreshPreview = () => { try { if (typeof renderCreatePreview === "function") renderCreatePreview(); } catch { /* the preview is cosmetic */ } };
  const clearPicked = () => { catalogState.picked = null; picked.hidden = true; picked.innerHTML = ""; refreshPreview(); };

  const showPicked = (kind, item) => {
    catalogState.picked = { kind, item };
    picked.hidden = false;
    picked.innerHTML = "";
    const pickedThumb = catalogThumbUrl(kind, item);
    if (pickedThumb) {
      const th = document.createElement("img");
      th.className = `catalog-picked-thumb${kind === "vehicle" ? " is-wide" : ""}`;
      th.src = pickedThumb;
      th.alt = "";
      picked.appendChild(th);
    }
    const text = document.createElement("div");
    text.className = "catalog-picked-text";
    const name = document.createElement("b");
    name.textContent = item.real ? `${item.name} · ${item.real}` : item.name;
    const specs = document.createElement("span");
    specs.textContent = catalogSpecsText(kind, item);
    text.append(name, specs);
    const close = document.createElement("button");
    close.type = "button";
    close.className = "catalog-picked-clear";
    close.setAttribute("aria-label", "Убрать подстановку");
    close.textContent = "×";
    close.addEventListener("click", clearPicked);
    picked.append(text, close);
  };

  // Picking an entry attaches the card only: the title stays exactly as the seller typed it.
  const apply = (kind, item) => {
    hide();
    if (!String(elements.createCategoryInput?.value || "")) {
      elements.createCategoryPills?.querySelector(`[data-value="${CATALOG_CATEGORY[kind]}"]`)?.click();
    }
    showPicked(kind, item);
    refreshPreview();  // the preview card takes the catalog picture while the seller has no own photo
  };

  const render = () => {
    const query = titleInput.value.trim();
    const kinds = currentKinds();
    if (catalogState.picked || query.length < 2 || !kinds.length) { hide(); return; }  // an entry is already attached: no more hints until it is removed
    const found = searchCatalog(query, kinds);
    if (!found.length) { hide(); return; }
    box.innerHTML = "";
    found.forEach(({ kind, item }) => {
      const row = document.createElement("button");
      row.type = "button";
      row.className = "catalog-suggest-row";
      const thumbUrl = catalogThumbUrl(kind, item);
      if (thumbUrl) {
        const th = document.createElement("img");
        th.className = `catalog-suggest-thumb${kind === "vehicle" ? " is-wide" : ""}`;
        th.src = thumbUrl;
        th.alt = "";
        th.loading = "lazy";
        row.appendChild(th);
      }
      const main = document.createElement("span");
      main.className = "catalog-suggest-main";
      const name = document.createElement("b");
      name.textContent = item.name;
      const sub = document.createElement("small");
      sub.textContent = kind === "vehicle"
        ? (item.real ? `${item.real} · ID ${item.id}` : `ID ${item.id}`)
        : (kind === "house" || kind === "garage" ? item.kind : kind === "skin" ? `ID ${item.id}` : [item.kind, `ID ${item.id}`].join(" · "));
      main.append(name, sub);
      const price = document.createElement("span");
      price.className = "catalog-suggest-price";
      price.textContent = catalogPriceText(item);
      row.append(main, price);
      row.addEventListener("pointerdown", (event) => event.preventDefault());  // keep the keyboard open
      row.addEventListener("mousedown", (event) => event.preventDefault());
      // Android: a tap first closes the keyboard, the page jumps down and the click then lands on whatever is under the finger (the bottom bar: «Активность»).
      // So a touch is handled on touchend (cancelling the click and the focus loss), the keyboard stays and nothing moves.
      let touchY = null;
      row.addEventListener("touchstart", (event) => { touchY = event.touches[0] ? event.touches[0].clientY : null; }, { passive: true });
      row.addEventListener("touchend", (event) => {
        const endY = event.changedTouches[0] ? event.changedTouches[0].clientY : touchY;
        const moved = touchY !== null && endY !== null && Math.abs(endY - touchY) > 10;
        touchY = null;
        if (moved || !event.cancelable) return;   // a scroll of the list, not a tap
        event.preventDefault();
        apply(kind, item);
      });
      row.addEventListener("click", () => apply(kind, item));
      box.appendChild(row);
    });
    box.hidden = false;
  };
  const loadAndRender = () => Promise.all(currentKinds().map(loadCatalog)).then(render);

  let blurTimer = null;  // a late blur must never hide a list that was shown after the field got focus again
  titleInput.addEventListener("focus", () => { clearTimeout(blurTimer); loadAndRender(); });
  titleInput.addEventListener("input", () => {
    clearTimeout(blurTimer);
    loadAndRender();
  });
  titleInput.addEventListener("blur", () => { clearTimeout(blurTimer); blurTimer = setTimeout(hide, 150); });
  document.addEventListener("rp-create-reset", () => { hide(); clearPicked(); });
}

// The ref of the entry picked from a catalog («vehicle:442», «business:azs-rublevka»), sent with the listing.
function currentCatalogItemId() {
  const picked = catalogState.picked;
  return picked ? `${picked.kind}:${picked.item.id}` : "";
}

// World coordinates -> a point on the full map picture (fractions 0..1); the same linear formula the official map uses.
const MAP_WORLD = { halfX: 3000, halfY: 2950, left: 0.055, right: 0.945, top: 0.063, bottom: 0.9365 };

function catalogMapPoint(item) {
  const fx = MAP_WORLD.left + ((item.x + MAP_WORLD.halfX) / (2 * MAP_WORLD.halfX)) * (MAP_WORLD.right - MAP_WORLD.left);
  const fy = MAP_WORLD.top + ((MAP_WORLD.halfY - item.y) / (2 * MAP_WORLD.halfY)) * (MAP_WORLD.bottom - MAP_WORLD.top);
  return { fx, fy };
}

// A small map with a marker: the full picture is zoomed (CSS only, no map library) so that the object sits in the centre.
function buildCatalogMiniMap(item) {
  const { fx, fy } = catalogMapPoint(item);
  const zoom = 6;  // the picture is `zoom` container widths wide; the container is 2:1
  const px = (0.5 - fx * zoom) / (1 - zoom);
  const py = (0.25 - fy * zoom) / (0.5 - zoom);
  const box = document.createElement("div");
  box.className = "lcc-map";
  box.style.backgroundSize = `${zoom * 100}% auto`;
  box.style.backgroundPosition = `${(px * 100).toFixed(3)}% ${(py * 100).toFixed(3)}%`;
  const pin = document.createElement("span");
  pin.className = "lcc-map-pin";
  box.appendChild(pin);
  const tag = document.createElement("span");
  tag.className = "lcc-map-tag";
  tag.textContent = "Расположение на карте";
  box.appendChild(tag);
  return box;
}

