function renderListingCatalogCard(listing) {
  const card = document.getElementById("listingCatalogCard");
  if (!card) return;
  card.hidden = true;
  card.innerHTML = "";
  const match = /^(vehicle|business|fuel|house|garage|skin):(\d+)$/.exec(String(listing?.catalog_item_id || ""));
  if (!match) return;
  const kind = match[1];
  loadCatalog(kind).then((entries) => {
    const entry = (entries || []).find((e) => String(e.item.id) === match[2]);
    if (!entry || document.getElementById("listingCatalogCard") !== card) return;
    const item = entry.item;
    const meta = CATALOG_CARD_META[kind];
    const cells = [];
    if (kind === "vehicle") {
      if (catalogPriceText(item)) cells.push(["Госцена", catalogPriceText(item)]);
      if (item.accel) cells.push(["Разгон 0–100", `${item.accel} сек`]);
      if (item.speed) cells.push(["Макс. скорость", `${item.speed} км/ч`]);
      cells.push(["Игровой ID", String(item.id)]);
    } else if (kind === "skin") {
      cells.push(["Название", item.name], ["Игровой ID", String(item.id)]);
    } else {
      if (kind === "business" || kind === "fuel") cells.push(["Название", item.name]);
      if (kind === "business") cells.push(["Тип", item.kind]);
      cells.push([kind === "house" || kind === "garage" ? "Номер" : "Игровой ID", String(item.id)]);
      if (catalogPriceText(item)) cells.push(["Госцена", catalogPriceText(item)]);
    }
    const head = document.createElement("div");
    head.className = "lcc-head";
    head.innerHTML = `<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${meta.icon}</svg>`;
    const titleEl = document.createElement("span");
    titleEl.textContent = meta.title;
    head.appendChild(titleEl);
    const grid = document.createElement("div");
    grid.className = "lcc-grid";
    cells.forEach(([label, value]) => {
      const cell = document.createElement("div");
      if (label === "Название") cell.className = "lcc-wide";
      const l = document.createElement("small");
      l.textContent = label;
      const v = document.createElement("b");
      v.textContent = value;
      cell.append(l, v);
      grid.appendChild(cell);
    });
    // the source sits behind a small «i» next to the title instead of a line under the numbers
    const info = document.createElement("button");
    info.type = "button";
    info.className = "lcc-info";
    info.setAttribute("aria-label", "Откуда данные");
    info.textContent = "i";
    const note = document.createElement("div");
    note.className = "lcc-note";
    note.hidden = true;
    note.textContent = "Данные из справочника и карты «Матрёшка RP»" + (item.real ? ` · ${item.real}` : "");
    info.addEventListener("click", () => { note.hidden = !note.hidden; });
    head.appendChild(info);
    if (kind === "skin") {
      const body = document.createElement("div");
      body.className = "lcc-skin";
      const pic = document.createElement("img");
      pic.src = catalogThumbUrl(kind, item);
      pic.alt = item.name;
      body.append(pic, grid);
      card.append(head, note, body);
    } else {
      card.append(head, note);
      if (kind === "vehicle" && item.photo) {  // the car's picture sits above its numbers
        const photo = document.createElement("img");
        photo.className = "lcc-photo";
        photo.src = catalogThumbUrl(kind, item);
        photo.alt = item.name;
        photo.loading = "lazy";
        card.appendChild(photo);
      }
      card.appendChild(grid);
    }
    if (typeof item.x === "number" && typeof item.y === "number") card.appendChild(buildCatalogMiniMap(item));
    card.hidden = false;
  });
}

// «Описание»: about three lines tall, grows while typing (and shrinks back on reset)
function bindCreateDescAutosize() {
  const area = elements.createForm && elements.createForm.elements.description;
  if (!area || area.dataset.autosize) return;
  area.dataset.autosize = "1";
  const fit = () => {
    area.style.height = "auto";
    area.style.height = `${Math.min(area.scrollHeight + 2, 260)}px`;
  };
  area.addEventListener("input", fit);
  document.addEventListener("rp-create-reset", () => { area.style.height = ""; });
  area.addEventListener("focus", fit);
}


// ── Рефералы: лестница наград за друзей, достигших 2 уровня ──
const REF_ICONS = {
  mcoin: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9" fill="#e2a92b"/><circle cx="12" cy="12" r="7.2" fill="none" stroke="#f9d46e" stroke-width="1.4"/><path d="M8.6 15.4v-6.8l3.4 4.2 3.4-4.2v6.8" fill="none" stroke="#7a4d00" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  vip_days: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3.5 8.5l4.6 4 3.9-7 3.9 7 4.6-4-1.7 10H5.2z" fill="#ffd25e" stroke="#e0a526" stroke-width="1.3" stroke-linejoin="round"/></svg>',
  promotions: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2c3.3 2 5 5.2 5 8.6 0 1.4-.4 2.7-1 3.9H8c-.6-1.2-1-2.5-1-3.9C7 7.2 8.700 4 12 2z" fill="#9a7cff" stroke="#c7b6ff" stroke-width="1.2" stroke-linejoin="round"/><circle cx="12" cy="9.5" r="1.9" fill="#fff"/><path d="M8 14.5L5.500 19l3.700-1.300M16 14.500l2.500 4.500-3.700-1.300M10.500 18l1.500 3.500 1.500-3.500" fill="#fbbf24" stroke="#fbbf24" stroke-width="1" stroke-linejoin="round"/></svg>',
  matreshka: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3l7.500 5.300L12 21 4.500 8.300z" fill="#a78bfa" stroke="#ddd0ff" stroke-width="1.200" stroke-linejoin="round"/><path d="M4.500 8.300h15M12 3l-3 5.300L12 21l3-12.700z" fill="none" stroke="#ddd0ff" stroke-width="1" stroke-linejoin="round" opacity=".8"/></svg>',
};
const REF_LOCK_SVG = '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5.500" y="10.500" width="13" height="9.500" rx="2.500" fill="currentColor" opacity=".9"/><path d="M8.500 10.500V8a3.500 3.500 0 0 1 7 0v2.500" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>';
const REF_CHECK_SVG = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12.500l4.500 4.500L19 7.500" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const stateRefRewards = { data: null, claiming: false };

function refFriendsWord(n) {
  const m10 = n % 10;
  const m100 = n % 100;
  if (m10 === 1 && m100 !== 11) return "друг";
  if (m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14)) return "друга";
  return "друзей";
}

function renderReferralLadder(data) {
  const ladder = document.getElementById("refLadder");
  if (!ladder) return;
  stateRefRewards.data = data;
  state.promoCredits = Number(data?.promotion_credits || 0);  // the «В ТОП» button stays enabled while free promotions are left
  const friends = Number(data?.friends || 0);
  const counter = document.getElementById("refFriendsCount");
  if (counter) counter.textContent = String(friends);
  const hint = document.getElementById("refLadderHint");
  const rewards = data?.rewards || [];
  if (hint) {
    const next = data?.next_milestone;
    const prize = rewards.find((r) => r.milestone === next);
    const anyOpen = rewards.some((r) => r.state === "available");
    const allTaken = rewards.length > 0 && rewards.every((r) => r.state === "claimed");
    hint.textContent = anyOpen ? "Есть награды, которые можно забрать" : next && prize ? `Ещё ${next - friends} ${refFriendsWord(next - friends)} до «${prize.title}»` : (allTaken ? "Все награды получены" : "");
  }
  // the five prizes as tiles in a row; an open prize is taken by tapping its tile
  ladder.innerHTML = "";
  rewards.forEach((reward) => {
    const st = reward.state || "locked";
    const tile = document.createElement("button");
    tile.type = "button";
    tile.className = `ref-step ref-tile is-${st}`;
    tile.dataset.milestone = String(reward.milestone);
    tile.disabled = st !== "available";
    const icon = document.createElement("span");
    icon.className = "ref-tile-icon";
    icon.innerHTML = st === "locked" ? REF_LOCK_SVG : (REF_ICONS[reward.kind] || "");
    const prize = document.createElement("span");
    prize.className = "ref-step-prize ref-tile-prize";
    // «25 M-Coin» -> a big number and a small label under it (the tiles are narrow)
    const parts = String(reward.title || "").match(/^(\d+)\s+(.*)$/);
    if (parts) {
      const num = document.createElement("b");
      num.className = "ref-tile-num";
      num.textContent = parts[1];
      const label = document.createElement("small");
      label.textContent = parts[2];
      if (parts[2].length > 9) label.classList.add("is-long");  // «продвижений»: a smaller type so it stays inside the tile
      prize.append(num, label);
    } else {
      prize.textContent = reward.title;
    }
    prize.title = reward.title;
    const stateEl = document.createElement("span");
    stateEl.className = "ref-tile-state";
    if (st === "available") {
      tile.addEventListener("click", () => claimReferralMilestone(reward.milestone, tile));  // an open prize is taken by tapping its tile or the button below
    } else if (st === "claimed") {
      stateEl.innerHTML = REF_CHECK_SVG;
      stateEl.classList.add("is-done");
    }
    const sr = document.createElement("span");
    sr.className = "ref-step-title";
    sr.hidden = true;  // (the milestone is also in the track below; kept for assistive tech and tests)
    sr.textContent = `${reward.milestone} ${refFriendsWord(reward.milestone)}`;
    tile.append(icon, prize, stateEl, sr);
    ladder.appendChild(tile);
  });
  // the progress track: a line with a node under every tile, filled up to the number of friends
  const track = document.getElementById("refTrack");
  if (track) {
    track.innerHTML = "";
    const n = rewards.length;
    if (n) {
      const centers = rewards.map((_, i) => ((i + 0.5) / n) * 100);
      const marks = rewards.map((r) => r.milestone);
      let fill = 0;
      if (friends >= marks[n - 1]) fill = centers[n - 1];
      else if (friends <= 0) fill = 0;
      else if (friends < marks[0]) fill = centers[0] * (friends / marks[0]);
      else {
        for (let i = 0; i < n - 1; i += 1) {
          if (friends >= marks[i] && friends < marks[i + 1]) {
            fill = centers[i] + (centers[i + 1] - centers[i]) * ((friends - marks[i]) / (marks[i + 1] - marks[i]));
            break;
          }
        }
      }
      const line = document.createElement("div");
      line.className = "ref-track-line";
      const bar = document.createElement("i");
      bar.style.width = `${fill.toFixed(2)}%`;
      line.appendChild(bar);
      track.appendChild(line);
      rewards.forEach((r, i) => {
        const node = document.createElement("span");
        node.className = `ref-track-node${friends >= r.milestone ? " is-reached" : ""}`;
        node.style.left = `${centers[i]}%`;
        const label = document.createElement("span");
        label.className = "ref-track-label";
        label.textContent = `${r.milestone} ${refFriendsWord(r.milestone)}`;
        label.style.left = `${centers[i]}%`;
        track.append(node, label);
      });
    }
  }
  // no button: an open prize glows and is taken by tapping it; one line says so
  const openHint = document.getElementById("refOpenHint");
  if (openHint) openHint.hidden = !rewards.some((r) => r.state === "available");
  const credits = document.getElementById("refCredits");
  if (credits) {
    const nCredits = Number(data?.promotion_credits || 0);
    credits.hidden = nCredits <= 0;
    credits.textContent = nCredits > 0 ? `У вас бесплатных продвижений: ${nCredits}. Они списываются, когда вы выбираете «В ТОП» на 2 часа.` : "";
  }
}

async function loadReferralRewards() {
  if (!document.getElementById("refLadder")) return;
  try {
    renderReferralLadder(await apiRequest(withAuth("/api/referrals/rewards")));
  } catch {
    renderReferralLadder({ friends: 0, rewards: [], next_milestone: null, promotion_credits: 0 });
  }
}

const REF_CLAIM_ERRORS = { not_reached: "Награда ещё не открыта.", not_ready: "Награды пока недоступны, попробуйте позже.", payout_failed: "Не удалось выдать награду, попробуйте ещё раз.", bad_milestone: "Такой награды нет." };

async function claimReferralMilestone(milestone, btn) {
  if (stateRefRewards.claiming) return;
  stateRefRewards.claiming = true;
  if (btn) btn.disabled = true;
  try {
    const result = await apiRequest(withAuth("/api/referrals/rewards/claim"), { method: "POST", body: JSON.stringify({ milestone }) });
    renderReferralLadder(result);
    const step = document.querySelector(`.ref-step[data-milestone="${milestone}"]`);
    if (step) step.classList.add("just-claimed");
    try { window.Telegram?.WebApp?.HapticFeedback?.notificationOccurred?.("success"); } catch { /* no haptics */ }
    if (result.claimed) showToast(`🎁 ${result.reward}`, "success");
    try { loadProfile({ force: true }); } catch { /* the balance refreshes on the next load */ }
  } catch (error) {
    const code = error?.payload?.error || "";
    showToast(REF_CLAIM_ERRORS[code] || "Не удалось забрать награду.", "danger");
    if (btn) btn.disabled = false;
  } finally {
    stateRefRewards.claiming = false;
  }
}
function renderCaptureMap() {
  if (!elements.captureMap) return;
  const list = Array.isArray(stateCapture.territories) ? [...stateCapture.territories] : [];
  const showCooldownChip = shouldRenderCaptureNodeCooldownChip();
  list.sort((a, b) => Number(a.map_order || 0) - Number(b.map_order || 0));

  if (!list.length) {
    _captureMapLastFingerprint = "";
    elements.captureMap.innerHTML = "<div class='empty-state' style='display:block'>Карта пока недоступна.</div>";
    return;
  }

  const fp = _captureMapFingerprint(list);
  const existingNodes = elements.captureMap.querySelectorAll(".capture-node");

  /* If structure unchanged and nodes exist, do in-place update (no avatar flash) */
  if (fp === _captureMapLastFingerprint && existingNodes.length === list.length) {
    _updateCaptureMapInPlace(list, existingNodes);
    return;
  }

  _captureMapLastFingerprint = fp;
  elements.captureMap.innerHTML = "";

  /* Stone-like path: irregular offsets/sizes so nodes don't feel like a straight list */
  const wavePattern = [-132, 104, -156, 122, -118, 146, -138, 96, -148];
  const risePattern = [0, 20, 34, 14, 40, 18, 30, 12, 36];
  const sizePattern = [92, 84, 98, 88, 94, 86, 100, 90, 96];
  const frag = document.createDocumentFragment();
  list.forEach((territory, index) => {
    const cluster = document.createElement("div");
    cluster.className = "capture-node-cluster";
    const node = document.createElement("button");
    node.type = "button";
    node.className = "capture-node";
    node.dataset.territoryId = String(territory.id);
    const wave = wavePattern[index % wavePattern.length];
    const rise = risePattern[index % risePattern.length];
    const nodeSize = sizePattern[index % sizePattern.length];
    cluster.style.setProperty("--capture-wave", `${wave}px`);
    cluster.style.setProperty("--capture-rise", `${rise}px`);
    node.style.setProperty("--capture-node-size", `${nodeSize}px`);
    if (Number(territory.id) === Number(stateCapture.selectedTerritoryId || 0)) {
      node.classList.add("active");
    }
    if (Boolean(territory.is_mine)) {
      node.classList.add("is-mine");
    }
    if (!territory.owner) {
      node.classList.add("is-neutral");
    }
    const ownerName = getCaptureOwnerName(territory.owner);
    const stateInfo = getCaptureNodeState(territory);
    const buildingSlug =
      resolveCaptureCitySlug(territory.code || "", CAPTURE_MAP_BUILDING_BY_SLUG)
      || resolveCaptureCitySlug(territory.name || "", CAPTURE_MAP_BUILDING_BY_SLUG);
    const buildingImg = buildingSlug ? CAPTURE_MAP_BUILDING_BY_SLUG[buildingSlug] : "";
    const buildingClass = buildingSlug ? ` capture-node-building--${buildingSlug}` : "";
    node.innerHTML = `
      ${buildingImg ? `<img class="capture-node-building${buildingClass}" src="${buildingImg}" alt="" draggable="false"/>` : `<span class="capture-node-ring" aria-hidden="true"></span>`}
      <span class="capture-node-core">
        <span class="capture-node-state-badge is-${stateInfo.tone}" aria-label="${stateInfo.label}" title="${stateInfo.label}">${stateInfo.icon}</span>
        <span class="capture-node-avatar"></span>
      </span>
      <span class="capture-node-name">${territory.name || "Территория"}</span>
      <span class="capture-node-owner">${ownerName}</span>
      ${showCooldownChip ? `<span class="capture-node-cooldown ${Number(territory.cooldown_seconds || 0) > 0 ? "" : "hidden"}">${Number(territory.cooldown_seconds || 0) > 0 ? `⌛ ${formatCaptureActionCooldown(Number(territory.cooldown_seconds || 0))}` : ""}</span>` : ""}
    `;
    const avatarEl = node.querySelector(".capture-node-avatar");
    if (avatarEl) {
      setAvatarPreview(
        avatarEl,
        territory.owner?.avatar_data || territory.owner?.avatar_url || "",
        getCaptureInitials(ownerName),
      );
    }
    node.addEventListener("click", () => selectCaptureTerritory(territory.id));
    cluster.appendChild(node);

    const business = getCaptureBusinessForTerritory(territory);
    if (business) {
      const businessState = getCaptureNodeState(business);
      const businessOwnerName = getCaptureOwnerName(business.owner);
      const edge = document.createElement("span");
      edge.className = "capture-business-edge";
      cluster.appendChild(edge);

      const businessNode = document.createElement("button");
      businessNode.type = "button";
      businessNode.className = "capture-business-node";
      const businessKeyClass = String(business.business_key || "")
        .toLowerCase()
        .replace(/[^a-z0-9_-]+/g, "-")
        .replace(/^-+|-+$/g, "");
      if (businessKeyClass) businessNode.classList.add(`capture-business-node--${businessKeyClass}`);
      businessNode.dataset.territoryId = String(business.id);
      if (Number(business.id) === Number(stateCapture.selectedTerritoryId || 0)) businessNode.classList.add("active");
      if (Boolean(business.is_mine)) businessNode.classList.add("is-mine");
      if (!business.owner) businessNode.classList.add("is-neutral");
      businessNode.title = `${business.name} • ${business.cityName}`;
      businessNode.innerHTML = `
        <img class="capture-business-node-img capture-node-building${businessKeyClass ? ` capture-business-node-img--${businessKeyClass}` : ""}" src="${business.node_image}" alt="" draggable="false">
        <span class="capture-business-node-core capture-node-core">
          <span class="capture-business-node-state capture-node-state-badge is-${businessState.tone}" title="${businessState.label}">${businessState.icon}</span>
          <span class="capture-business-node-avatar capture-node-avatar"></span>
        </span>
        <span class="capture-business-node-name">${business.name}</span>
        <span class="capture-business-node-owner">${businessOwnerName}</span>
      `;
      const businessAvatarEl = businessNode.querySelector(".capture-business-node-avatar");
      if (businessAvatarEl) {
        setAvatarPreview(
          businessAvatarEl,
          business.owner?.avatar_data || business.owner?.avatar_url || "",
          business.owner ? getCaptureInitials(businessOwnerName || business.name) : "•",
        );
      }
      businessNode.addEventListener("click", () => selectCaptureTerritory(business.id));
      cluster.appendChild(businessNode);
    }
    frag.appendChild(cluster);
  });
  elements.captureMap.appendChild(frag);
  refreshCaptureNodeStatuses();
  layoutCaptureBusinessEdges();
  bindCaptureTrailsListeners();
  bindCaptureParallaxListeners();
  bindCaptureTrailImageLoadListeners();
  scheduleCaptureParallaxRender();
  scheduleCaptureTrailsRender();
  window.requestAnimationFrame(() => {
    scheduleCaptureParallaxRender();
    scheduleCaptureTrailsRender();
  });
  if (stateCaptureTutorial.active) {
    const index = Math.max(0, Math.min(CAPTURE_TUTORIAL_STEPS.length - 1, Number(stateCaptureTutorial.stepIndex || 0)));
    applyCaptureTutorialFocus(CAPTURE_TUTORIAL_STEPS[index] || CAPTURE_TUTORIAL_STEPS[0]);
  }
}

/* Update existing DOM nodes without recreating them (preserves building images) */
function _updateCaptureMapInPlace(list, existingNodes) {
  const selectedId = Number(stateCapture.selectedTerritoryId || 0);
  list.forEach((territory, index) => {
    const node = existingNodes[index];
    if (!node) return;
    /* Update classes */
    node.classList.toggle("active", Number(territory.id) === selectedId);
    node.classList.toggle("is-mine", Boolean(territory.is_mine));
    node.classList.toggle("is-neutral", !territory.owner);
    /* Update owner name */
    const ownerName = getCaptureOwnerName(territory.owner);
    const ownerEl = node.querySelector(".capture-node-owner");
    if (ownerEl && ownerEl.textContent !== ownerName) ownerEl.textContent = ownerName;
    /* Update territory name */
    const nameEl = node.querySelector(".capture-node-name");
    const tName = territory.name || "Территория";
    if (nameEl && nameEl.textContent !== tName) nameEl.textContent = tName;
    /* Update avatar if owner changed */
    const avatarEl = node.querySelector(".capture-node-avatar");
    if (avatarEl) {
      setAvatarPreview(
        avatarEl,
        territory.owner?.avatar_data || territory.owner?.avatar_url || "",
        getCaptureInitials(ownerName),
      );
    }
    const cluster = node.closest(".capture-node-cluster");
    const businessNode = cluster ? cluster.querySelector(".capture-business-node") : null;
    const business = getCaptureBusinessForTerritory(territory);
    if (businessNode && business) {
      const nextBusinessKeyClass = String(business.business_key || "")
        .toLowerCase()
        .replace(/[^a-z0-9_-]+/g, "-")
        .replace(/^-+|-+$/g, "");
      Array.from(businessNode.classList)
        .filter((className) => className.startsWith("capture-business-node--"))
        .forEach((className) => businessNode.classList.remove(className));
      if (nextBusinessKeyClass) businessNode.classList.add(`capture-business-node--${nextBusinessKeyClass}`);
      businessNode.classList.toggle("active", Number(business.id) === selectedId);
      businessNode.classList.toggle("is-mine", Boolean(business.is_mine));
      businessNode.classList.toggle("is-neutral", !business.owner);
      businessNode.dataset.territoryId = String(business.id);
      businessNode.title = `${business.name} • ${business.cityName}`;
      const businessOwnerName = getCaptureOwnerName(business.owner);
      const businessAvatarEl = businessNode.querySelector(".capture-business-node-avatar");
      if (businessAvatarEl) {
        setAvatarPreview(
          businessAvatarEl,
          business.owner?.avatar_data || business.owner?.avatar_url || "",
          business.owner ? getCaptureInitials(businessOwnerName || business.name) : "•",
        );
      }
      const businessImgEl = businessNode.querySelector(".capture-business-node-img");
      if (businessImgEl) {
        businessImgEl.className = `capture-business-node-img capture-node-building${nextBusinessKeyClass ? ` capture-business-node-img--${nextBusinessKeyClass}` : ""}`;
      }
      const stateInfo = getCaptureNodeState(business);
      const badgeEl = businessNode.querySelector(".capture-business-node-state");
      if (badgeEl) {
        badgeEl.className = `capture-business-node-state is-${stateInfo.tone}`;
        badgeEl.textContent = stateInfo.icon;
        badgeEl.title = stateInfo.label;
      }
      const businessNameEl = businessNode.querySelector(".capture-business-node-name");
      if (businessNameEl && businessNameEl.textContent !== String(business.name || "Бизнес")) {
        businessNameEl.textContent = String(business.name || "Бизнес");
      }
      const businessOwnerEl = businessNode.querySelector(".capture-business-node-owner");
      if (businessOwnerEl && businessOwnerEl.textContent !== businessOwnerName) {
        businessOwnerEl.textContent = businessOwnerName;
      }
    }
  });
  refreshCaptureNodeStatuses();
  layoutCaptureBusinessEdges();
  bindCaptureTrailImageLoadListeners();
  scheduleCaptureTrailsRender();
  if (stateCaptureTutorial.active) {
    const index = Math.max(0, Math.min(CAPTURE_TUTORIAL_STEPS.length - 1, Number(stateCaptureTutorial.stepIndex || 0)));
    applyCaptureTutorialFocus(CAPTURE_TUTORIAL_STEPS[index] || CAPTURE_TUTORIAL_STEPS[0]);
  }
}

function bindCaptureTrailImageLoadListeners() {
  if (!elements.captureMap) return;
  const imageNodes = elements.captureMap.querySelectorAll(".capture-node-building, .capture-business-node-img");
  imageNodes.forEach((img) => {
    if (!(img instanceof HTMLImageElement)) return;
    if (img.dataset.captureTrailBound === "1") return;
    img.dataset.captureTrailBound = "1";
    if (img.complete) return;
    img.addEventListener(
      "load",
      () => {
        if (state.page !== "capture") return;
        scheduleCaptureTrailsRender();
      },
      { once: true },
    );
  });
}

function getCaptureModeCost(baseCost, multiplier, mode = null) {
  if (mode && Number.isFinite(Number(mode.preview_cost))) {
    return Math.max(1, Math.ceil(Number(mode.preview_cost)));
  }
  if (mode && Number.isFinite(Number(mode.cost))) {
    return Math.max(1, Math.ceil(Number(mode.cost)));
  }
  if (mode && Number.isFinite(Number(mode.base_cost))) {
    return Math.max(1, Math.ceil(Number(mode.base_cost)));
  }
  return Math.max(1, Math.ceil(Number(baseCost || 0) * Number(multiplier || 1)));
}

function getCaptureModeCostInfo(baseCost, multiplier, mode = null) {
  const base = (() => {
    if (mode && Number.isFinite(Number(mode.cost))) return Math.max(1, Math.ceil(Number(mode.cost)));
    if (mode && Number.isFinite(Number(mode.base_cost))) return Math.max(1, Math.ceil(Number(mode.base_cost)));
    return Math.max(1, Math.ceil(Number(baseCost || 0) * Number(multiplier || 1)));
  })();
  const final = Number.isFinite(Number(mode?.preview_cost))
    ? Math.max(1, Math.ceil(Number(mode.preview_cost)))
    : base;
  return { base, final, discounted: final < base };
}

function getCaptureCouponSummaryHtml(target) {
  const preview = target?.coupon_preview && typeof target.coupon_preview === "object" ? target.coupon_preview : null;
  if (!preview) return "";
  const chips = [];
  const attackDiscount = Math.max(0, Number(preview.attack_discount_pct || 0));
  const attackBonus = Math.max(0, Number(preview.attack_bonus_pct || 0));
  const breakDefense = Math.max(0, Number(preview.break_defense_pct || 0));
  const shield = Math.max(0, Number(preview.defender_shield_pct || 0));
  if (attackDiscount > 0) chips.push(`🎟 Скидка -${attackDiscount}%`);
  if (attackBonus > 0) chips.push(`⚡ Шанс +${attackBonus}%`);
  if (breakDefense > 0) chips.push(`🪓 Пробой ${breakDefense}%`);
  if (shield > 0) chips.push(`🛡 Щит врага +${shield}%`);
  if (preview.defender_no_tax) chips.push(`💸 Без налога`);
  if (!chips.length) return "";
  return `<div class="capture-help" id="captureCouponSummary">${chips.join(" • ")}</div>`;
}

function getCaptureAttackButtonHtml(costInfo) {
  if (costInfo && costInfo.discounted) {
    return `<span class="capture-attack-price-row"><span class="capture-attack-price-label">Атаковать за</span><span class="capture-old-price capture-old-price--cta">${formatPrice(costInfo.base)}</span><span class="capture-price-current">${formatPrice(costInfo.final)} M-COIN</span></span>`;
  }
  return `Атаковать за ${formatPrice(Number(costInfo?.final || costInfo?.base || 0))} M-COIN`;
}

function getCaptureActionStatusText(seconds) {
  const value = Math.max(0, Number(seconds || 0));
  return value > 0 ? "Действия: недоступны" : "Действия: доступны";
}

function bindCaptureFastPress(button, handler) {
  if (!button || typeof handler !== "function") return;
  let lastTriggerAt = 0;
  const invoke = (event) => {
    if (button.disabled || button.classList.contains("disabled")) return;
    const now = Date.now();
    if (now - lastTriggerAt < 220) {
      if (event) {
        event.preventDefault();
        event.stopPropagation();
      }
      return;
    }
    lastTriggerAt = now;
    if (event) {
      event.preventDefault();
      event.stopPropagation();
    }
    handler();
  };
  button.addEventListener("pointerup", invoke);
  button.addEventListener("click", invoke);
}

function setCaptureButtonTextIfChanged(button, nextText) {
  if (!button) return;
  const target = String(nextText || "");
  if (button.textContent !== target) {
    button.textContent = target;
  }
}

function setCaptureButtonHtmlIfChanged(button, nextHtml) {
  if (!button) return;
  const target = String(nextHtml || "");
  if (button.dataset.renderedHtml !== target) {
    button.innerHTML = target;
    button.dataset.renderedHtml = target;
  }
}

function getCaptureDefenseTier(level) {
  const numeric = Math.max(0, Math.min(3, Number(level || 0)));
  if (numeric >= 3) return "Максимальная";
  if (numeric >= 2) return "Высокая";
  if (numeric >= 1) return "Средняя";
  return "Базовая";
}

function getCaptureChanceInfo(chance) {
  const value = Math.max(0, Math.min(1, Number(chance || 0)));
  if (value >= 0.66) return { label: "Высокий", tone: "high" };
  if (value >= 0.4) return { label: "Средний", tone: "mid" };
  return { label: "Низкий", tone: "low" };
}

const CAPTURE_STRUCTURED_BASE_CHANCE_BY_CITY = {
  edovo: { 0: 0.50, 1: 0.45, 2: 0.35, 3: 0.25 },
  garel: { 0: 0.50, 1: 0.45, 2: 0.35, 3: 0.25 },
  gorel: { 0: 0.50, 1: 0.45, 2: 0.35, 3: 0.25 },
  lytkarino: { 0: 0.40, 1: 0.35, 2: 0.25, 3: 0.20 },
  litkarino: { 0: 0.40, 1: 0.35, 2: 0.25, 3: 0.20 },
  batyrevo: { 0: 0.40, 1: 0.35, 2: 0.25, 3: 0.20 },
  yuzhny: { 0: 0.30, 1: 0.25, 2: 0.20, 3: 0.15 },
  yujniy: { 0: 0.30, 1: 0.25, 2: 0.20, 3: 0.15 },
  yuzhniy: { 0: 0.30, 1: 0.25, 2: 0.20, 3: 0.15 },
  nikitino: { 0: 0.30, 1: 0.25, 2: 0.20, 3: 0.15 },
  arzamas: { 0: 0.30, 1: 0.25, 2: 0.20, 3: 0.15 },
};

const CAPTURE_ATTACK_MODE_CHANCE_BONUS = {
  NORMAL: 0,
  BOOST: 0.10,
  STORM: 0.20,
};

function getCaptureStructuredChance(mode, territory) {
  const code = String(territory?.code || "").trim().toLowerCase();
  const byLevel = CAPTURE_STRUCTURED_BASE_CHANCE_BY_CITY[code];
  if (!byLevel) return null;
  const level = Math.max(0, Math.min(3, Number(territory?.defense_level || 0)));
  const modeKey = String(mode?.key || "NORMAL").toUpperCase();
  const base = Number(byLevel[level]);
  const bonus = Number(CAPTURE_ATTACK_MODE_CHANCE_BONUS[modeKey] || 0);
  if (!Number.isFinite(base)) return null;
  return Math.max(0.05, Math.min(0.95, base + bonus));
}

function getCaptureModeChancePreview(mode, territory = null) {
  const preview = Number(mode?.preview_chance);
  const base = Number.isFinite(preview) ? preview : Number(mode?.chance_base);
  const min = Number(mode?.chance_min);
  const max = Number(mode?.chance_max);
  let baseChance = Number.isFinite(base) ? Math.max(0.05, Math.min(0.95, base)) : null;
  let minChance = Number.isFinite(min) ? Math.max(0.05, Math.min(0.95, min)) : null;
  let maxChance = Number.isFinite(max) ? Math.max(0.05, Math.min(0.95, max)) : null;

  if (!Number.isFinite(baseChance)) {
    const structured = getCaptureStructuredChance(mode, territory);
    if (Number.isFinite(structured)) {
      baseChance = structured;
      minChance = structured;
      maxChance = structured;
    } else {
      const stake = Math.max(1, Number(mode?.cost || mode?.base_cost || 1));
      const defensePower = Math.max(1, Number(territory?.defense_level || 0) + 1) * 18;
      baseChance = Math.max(0.05, Math.min(0.95, stake / Math.max(1, stake + defensePower)));
      minChance = Math.max(0.05, Math.min(0.95, baseChance - 0.08));
      maxChance = Math.max(0.05, Math.min(0.95, baseChance + 0.08));
    }
  } else {
    if (!Number.isFinite(minChance)) minChance = baseChance;
    if (!Number.isFinite(maxChance)) maxChance = baseChance;
  }

  const chanceInfo = getCaptureChanceInfo(baseChance);
  const basePct = Math.round(baseChance * 1000) / 10;
  return {
    tone: chanceInfo.tone,
    label: `${basePct}%`,
    value: baseChance,
  };
}

function resolveCaptureAttackModeAndCost(targetId, preferredModeKey = "NORMAL") {
  const targetNumericId = Number(targetId || 0);
  const target = targetNumericId < 0
    ? getCaptureBusinessById(targetNumericId)
    : (stateCapture.territories || []).find((item) => Number(item?.id || 0) === targetNumericId);
  if (!target) return null;
  const attackBaseCost = Math.max(1, Number(target?.attack_base_cost || 25));
  const attackModes = Array.isArray(target?.attack_modes) && target.attack_modes.length
    ? target.attack_modes
    : [{ key: "NORMAL", title: "Обычная", multiplier: 1 }];
  const normalizedPreferred = String(preferredModeKey || "NORMAL").toUpperCase();
  const selectedMode = attackModes.find((mode) => String(mode?.key || "").toUpperCase() === normalizedPreferred)
    || attackModes[0];
  const selectedMultiplier = Math.max(1, Number(selectedMode?.multiplier || 1));
  const selectedCostInfo = getCaptureModeCostInfo(attackBaseCost, selectedMultiplier, selectedMode);
  return {
    modeKey: String(selectedMode?.key || "NORMAL").toUpperCase(),
    stake: Number(selectedCostInfo?.final || selectedCostInfo?.base || 0),
  };
}

function getCaptureOutcomeFromResponse(response) {
  const result = String(response?.result || "").toLowerCase();
  const roll = Number(response?.roll_value || 0);
  const winChance = Number(response?.win_chance || 0);
  if (result === "win") {
    return roll <= Math.max(0.08, winChance * 0.42) ? "CRIT" : "WIN";
  }
  const missDistance = Math.abs(winChance - roll);
  return missDistance <= 0.08 ? "CLOSE" : "FAIL";
}

function openCaptureAttackCaseOverlay(payload) {
  return new Promise((resolve) => {
    const host = document.body;
    if (!host) {
      resolve();
      return;
    }
    const outcome = String(payload?.outcome || "FAIL").toUpperCase();
    const stake = Number(payload?.stake || 0);
    const burnAmount = Math.max(0, Number(payload?.burnAmount || 0));
    const taxAmount = Math.max(0, Number(payload?.taxAmount || 0));
    const winChance = Math.max(0, Math.min(1, Number(payload?.winChance || 0)));
    const rollValue = Math.max(0, Math.min(1, Number(payload?.rollValue || 0)));
    const chanceInfo = getCaptureChanceInfo(winChance);
    const chancePercent = Math.round(winChance * 1000) / 10;
    const resultMeta = {
      FAIL: { title: "ПРОВАЛ", text: `Вы потеряли ${formatPrice(burnAmount || stake)} M-COIN. Владелец получил ${formatPrice(taxAmount)} M-COIN.` },
      CLOSE: {
        title: "ПОЧТИ",
        text: `Почти получилось. Потеря ${formatPrice(Math.max(0, burnAmount || Math.round(stake * 0.2)))} M-COIN.`,
      },
      WIN: { title: "ЗАХВАТ!", text: "Территория успешно захвачена." },
      CRIT: { title: "КРИТ", text: "Мощный прорыв. Территория захвачена с преимуществом." },
    };
    const resultInfo = resultMeta[outcome] || resultMeta.FAIL;
    const paletteClass = `is-${String(outcome || "fail").toLowerCase()}`;
    const previous = host.querySelector(".capture-case-overlay");
    if (previous) previous.remove();
    const overlay = document.createElement("div");
    overlay.className = "capture-case-overlay";
    document.body.classList.add("capture-case-open");
    overlay.innerHTML = `
      <div class="capture-case-window">
        <div class="capture-case-title">Атака территории</div>
        <div class="capture-case-sub">Шанс успеха: ${chanceInfo.label} • ${chancePercent}% • зависит от защиты и ставки</div>
        <button class="capture-case-skip" id="captureCaseSkip" type="button">Пропустить</button>
        <div class="capture-case-wheel-wrap">
          <div class="capture-case-wheel" id="captureCaseWheel">
            <div class="capture-case-wheel-rail"></div>
            <div class="capture-case-wheel-orbit" id="captureCaseWheelOrbit"></div>
            <div class="capture-case-threshold-pointer" id="captureCaseThresholdPointer"></div>
            <div class="capture-case-roll-pointer" id="captureCaseRollPointer"></div>
            <div class="capture-case-wheel-core">
              <div class="capture-case-wheel-percent">${chancePercent}%</div>
              <div class="capture-case-wheel-note">шанс атаки</div>
            </div>
          </div>
        </div>
        <div class="capture-case-result hidden ${paletteClass}" id="captureCaseResult">
          <div class="capture-case-result-title">${resultInfo.title}</div>
          <div class="capture-case-result-text">${resultInfo.text}</div>
          <button class="action-btn primary capture-case-ok" id="captureCaseOk" type="button">ОК</button>
        </div>
      </div>
    `;
    host.appendChild(overlay);
    const wheelEl = overlay.querySelector("#captureCaseWheel");
    const windowEl = overlay.querySelector(".capture-case-window");
    const wheelOrbitEl = overlay.querySelector("#captureCaseWheelOrbit");
    const thresholdPointerEl = overlay.querySelector("#captureCaseThresholdPointer");
    const rollPointerEl = overlay.querySelector("#captureCaseRollPointer");
    const resultEl = overlay.querySelector("#captureCaseResult");
    const okBtn = overlay.querySelector("#captureCaseOk");
    const skipBtn = overlay.querySelector("#captureCaseSkip");
    if (!wheelEl || !wheelOrbitEl || !thresholdPointerEl || !rollPointerEl || !resultEl || !okBtn || !skipBtn) {
      overlay.remove();
      document.body.classList.remove("capture-case-open");
      resolve();
      return;
    }
    const successSpan = Math.max(0, Math.min(1, winChance)) * 360;
    const rollAngle = Math.max(0, Math.min(1, rollValue)) * 360;
    const isSuccessOutcome = outcome === "WIN" || outcome === "CRIT";
    wheelOrbitEl.style.setProperty("--capture-win-span", `${successSpan.toFixed(2)}deg`);
    // Hide threshold marker to avoid outcome spoilers in result modal.
    thresholdPointerEl.classList.remove("is-visible");
    thresholdPointerEl.style.transform = "rotate(0deg)";
    const spinTurns = 4 + Math.floor(Math.random() * 2);
    const finalRotation = (spinTurns * 360) + rollAngle;
    rollPointerEl.style.transform = "rotate(0deg) translateZ(0)";
    rollPointerEl.style.transition = "none";
    if (CAPTURE_AUDIO.state.unlocked && CAPTURE_AUDIO.state.buffers.scroll) {
      playCaptureSound("scroll", { stopPrevious: true, startVolume: CAPTURE_AUDIO.volume.scroll });
    }
    void rollPointerEl.offsetWidth;
    rollPointerEl.style.transition = "transform 2.8s cubic-bezier(0.14, 0.84, 0.18, 1)";
    rollPointerEl.style.transform = `rotate(${finalRotation.toFixed(2)}deg) translateZ(0)`;
    let revealed = false;
    let revealTimer = 0;
    const reveal = () => {
      if (revealed) return;
      revealed = true;
      stopCaptureSound("scroll", 0.3);
      if (isSuccessOutcome) {
        playCaptureSuccessSound();
      } else {
        playCaptureDefeatSound();
      }
      rollPointerEl.classList.add("is-finished");
      resultEl.classList.remove("hidden");
      skipBtn.classList.add("hidden");
      if (windowEl) {
        requestAnimationFrame(() => {
          try {
            windowEl.scrollTo({ top: windowEl.scrollHeight, behavior: "smooth" });
          } catch {
            windowEl.scrollTop = windowEl.scrollHeight;
          }
        });
      }
      if (revealTimer) {
        clearTimeout(revealTimer);
        revealTimer = 0;
      }
    };
    // Use setTimeout as primary trigger (transitionend can fire unpredictably)
    // Wait 3 seconds to ensure wheel animation completes and there's drama!
    revealTimer = window.setTimeout(reveal, 3000);
    skipBtn.addEventListener("click", () => {
      rollPointerEl.style.transition = "transform 220ms ease-out";
      rollPointerEl.style.transform = `rotate(${finalRotation.toFixed(2)}deg) translateZ(0)`;
      reveal();
    });
    okBtn.addEventListener("click", () => {
      overlay.classList.add("leaving");
      setTimeout(() => {
        overlay.remove();
        document.body.classList.remove("capture-case-open");
        resolve();
      }, 220);
    }, { once: true });
  });
}

const { CAPTURE_CITY_IMAGE_BY_SLUG, CAPTURE_CITY_DEFAULT_IMAGE, CAPTURE_CITY_NAME_ALIASES } = (window.__miniappStaticCatalogs || {});

function normalizeCaptureCityName(value) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/ё/g, "е")
    .replace(/[^a-zа-я0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function transliterateCityName(value) {
  const map = {
    а: "a", б: "b", в: "v", г: "g", д: "d", е: "e", ж: "zh", з: "z", и: "i", й: "y", к: "k", л: "l",
    м: "m", н: "n", о: "o", п: "p", р: "r", с: "s", т: "t", у: "u", ф: "f", х: "h", ц: "ts", ч: "ch",
    ш: "sh", щ: "sch", ъ: "", ы: "y", ь: "", э: "e", ю: "yu", я: "ya",
  };
  return normalizeCaptureCityName(value).split("").map((ch) => map[ch] ?? ch).join("").replace(/\s+/g, "");
}

function resolveCaptureCitySlug(rawValue, sourceBySlug) {
  const normalized = normalizeCaptureCityName(rawValue);
  if (!normalized || !sourceBySlug) return "";

  const directAlias = CAPTURE_CITY_NAME_ALIASES[normalized];
  if (directAlias && sourceBySlug[directAlias]) return directAlias;
  if (sourceBySlug[normalized]) return normalized;

  const transliterated = transliterateCityName(normalized);
  if (sourceBySlug[transliterated]) return transliterated;
  const transliteratedAlias = CAPTURE_CITY_NAME_ALIASES[transliterated];
  if (transliteratedAlias && sourceBySlug[transliteratedAlias]) return transliteratedAlias;

  for (const [alias, slug] of Object.entries(CAPTURE_CITY_NAME_ALIASES)) {
    if (!sourceBySlug[slug]) continue;
    if (normalized.includes(alias) || alias.includes(normalized)) return slug;
  }
  return "";
}

function getCaptureTerritoryCityImage(territory) {
  if (!territory) return "";

  const tryResolve = (rawValue) => {
    const slug = resolveCaptureCitySlug(rawValue, CAPTURE_CITY_IMAGE_BY_SLUG);
    return slug ? CAPTURE_CITY_IMAGE_BY_SLUG[slug] : "";
  };

  const byCode = tryResolve(territory.code || "");
  if (byCode) return byCode;

  const byName = tryResolve(territory.name || "");
  if (byName) return byName;
  return CAPTURE_CITY_DEFAULT_IMAGE;
}

