async function setCaptureTitleTerritory(territoryId) {
  if (stateCapture.titleSetInFlight || stateCapture.mutationInFlight) return;
  const targetId = Number(territoryId || 0);
  if (targetId <= 0) return;
  stateCapture.mutationInFlight = true;
  stateCapture.titleSetInFlight = true;
  syncCapturePanel({ force: true });
  try {
    const response = await apiRequest(withAuth("/api/capture/title/select"), {
      method: "POST",
      body: JSON.stringify({
        territory_id: targetId,
        operation_id: `capture_title_${Date.now()}_${Math.random().toString(16).slice(2)}`,
      }),
    });
    const statePayload = response && typeof response === "object" ? response.state : null;
    if (statePayload && typeof statePayload === "object") {
      stateCapture.season = statePayload.season || stateCapture.season;
      stateCapture.playerCooldownSeconds = Number(statePayload.player_cooldown_seconds || 0);
      stateCapture.nightCooldownActive = Boolean(statePayload?.night_cooldown?.active);
      stateCapture.nightCooldownSeconds = Math.max(0, Number(statePayload?.night_cooldown?.seconds_left || 0));
      stateCapture.liveAlert = statePayload?.live_alert && typeof statePayload.live_alert === "object" ? statePayload.live_alert : null;
      stateCapture.energyCurrent = Math.max(0, Number(statePayload?.energy?.current ?? stateCapture.energyCurrent ?? 5));
      stateCapture.energyMax = Math.max(1, Number(statePayload?.energy?.max ?? stateCapture.energyMax ?? 5));
      stateCapture.energyNextRegenSeconds = Math.max(0, Number(statePayload?.energy?.next_regen_seconds ?? 0));
      stateCapture.myTotalCaptures = Math.max(0, Number(statePayload.my_total_captures || 0));
      stateCapture.titleState = statePayload.title_state && typeof statePayload.title_state === "object"
        ? statePayload.title_state
        : stateCapture.titleState;
      stateCapture.territories = Array.isArray(statePayload.territories) ? statePayload.territories : stateCapture.territories;
      stateCapture.leaderboard = Array.isArray(statePayload.leaderboard) ? statePayload.leaderboard : stateCapture.leaderboard;
    } else {
      Promise.resolve(loadCaptureState({ force: true, silent: true })).catch(() => {});
    }
    renderCaptureMap();
    syncCapturePanel({ force: true });
    Promise.resolve(loadProfile({ force: true })).catch(() => {});
    if (state.page === "public-profile" && Number(statePublic.userId || 0) === Number(state.tid || 0)) {
      Promise.resolve(loadPublicProfile(Number(state.tid || 0), statePublic.backPage || "market")).catch(() => {});
    }
    showToast("Титул обновлен.", "success");
  } catch (error) {
    const code = String(error?.payload?.error || "");
    if (code === "not_owned_territory") {
      showToast("Можно выбрать только свою территорию.", "danger");
    } else {
      showToast("Не удалось обновить титул.", "danger");
    }
  } finally {
    stateCapture.titleSetInFlight = false;
    stateCapture.mutationInFlight = false;
    updateCapturePanelLiveState();
  }
}

function buildLeaderboardRow(item) {
  const row = document.createElement("div");
  row.className = "leaderboard-row";
  const rankRaw = Number(item.rank_position || 0);
  const rank = rankRaw > 0 ? rankRaw : "—";
  const isTournamentBoard = state.page === "tournament";
  const mode = isTournamentBoard ? "tournament" : normalizeLeaderboardMode(stateRating.mode);
  const scoreValueByMode = {
    deals: Number(item.score ?? 0),
    captures: Number(item.metric_value ?? item.captures_total ?? 0),
    mcoin: Number(item.metric_value ?? item.balance ?? 0),
    tournament: Number(item.score ?? item.point ?? 0),
  };
  const scoreRaw = scoreValueByMode[mode];
  const score = Number.isFinite(scoreRaw) ? scoreRaw : 0;
  const deals = Number(item.confirmed_deals || 0);
  const scoreLabelMap = {
    captures: "захваты",
    mcoin: "M-COIN",
    deals: "",
    tournament: "XP",
  };
  const metaLineMap = {
    captures: "",
    mcoin: "",
    deals: `Сделок: ${deals}`,
    tournament: "",
  };
  const serverNum = Number(item.server_id || 0);
  const serverLabel = isTournamentBoard
    ? ""
    : Number.isFinite(serverNum) && serverNum > 0
      ? `Сервер ${serverNum}`
      : "Сервер —";
  const avatarSource = item.avatar_data || item.avatar_url || "";
  const displayName = item.display_name || "Пользователь";

  if (isTournamentBoard) {
    const tournamentMode = String((stateRating.gameTournament || {}).mode || "solo").toLowerCase();
    // Tournament: place + avatar | name + XP under | coin reward icon.
    // 1st & 3rd → Matreshka-Coin, 2nd & 4-100 → Market-Coin, 100+ → no icon.
    const useMatreshka = rankRaw === 1 || rankRaw === 3;
    const showCoin = rankRaw >= 1 && rankRaw <= 100;
    const coinSrc = useMatreshka
      ? "assets/logo matreshka coin.png"
      : "assets/logo market coin.PNG";
    const coinAlt = useMatreshka ? "Matreshka-Coin" : "Market-Coin";
    const coinTier =
      rankRaw === 1
        ? "gold"
        : rankRaw === 2
          ? "silver"
          : rankRaw === 3
            ? "bronze"
            : "base";
    row.classList.add("leaderboard-row--tournament");

    row.innerHTML = `
      <div class="leaderboard-row-rank">#${rank}</div>
      <div class="leaderboard-row-avatar"></div>
      <div class="leaderboard-row-main">
        <div class="leaderboard-row-name"></div>
        <div class="leaderboard-row-xp">${score} XP${tournamentMode === "club" ? ` • ${Number(item.members_count || 0)} участ.` : ""}</div>
      </div>
      ${
        showCoin
          ? `<div class="leaderboard-row-coin leaderboard-row-coin--${coinTier}" title="${coinAlt}">
               <img src="${coinSrc}" alt="${coinAlt}" loading="lazy" decoding="async" />
             </div>`
          : ""
      }
    `;
  } else {
    row.innerHTML = `
      <div class="leaderboard-row-rank">#${rank}</div>
      <div class="leaderboard-row-avatar"></div>
      <div class="leaderboard-row-main">
        <div class="leaderboard-row-name"></div>
        <div class="leaderboard-row-meta">${metaLineMap[mode] ? `${metaLineMap[mode]} • ${serverLabel}` : serverLabel}</div>
      </div>
      <div class="leaderboard-row-score">${score}${scoreLabelMap[mode] ? `<small>${scoreLabelMap[mode]}</small>` : ""}</div>
    `;
  }
  if (rank === 1 || rank === 2 || rank === 3) {
    row.classList.add(`leaderboard-row--${rank}`);
  }
  if (item.is_vip) {
    row.classList.add("leaderboard-row--vip");
    if (item.vip_tier === "vip_ultimate") row.classList.add("leaderboard-row--vip-ultimate");
    // Galaxy stars scattered across the card
    const starCount = item.vip_tier === "vip_ultimate" ? 10 : 6;
    for (let i = 0; i < starCount; i++) {
      const star = document.createElement("span");
      const isCross = i % 3 === 0;
      star.className = "vip-star " + (isCross ? "vip-star--cross" : "vip-star--dot");
      const size = isCross ? 1 : (2 + Math.random() * 3);
      star.style.width = size + "px";
      star.style.height = size + "px";
      star.style.top = (8 + Math.random() * 80) + "%";
      star.style.left = (5 + Math.random() * 88) + "%";
      star.style.setProperty("--star-dur", (2.5 + Math.random() * 3) + "s");
      star.style.setProperty("--star-delay", (Math.random() * 4) + "s");
      row.appendChild(star);
    }
  }

  const nameEl = row.querySelector(".leaderboard-row-name");
  if (nameEl) {
    nameEl.textContent = displayName;
    nameEl.title = displayName;
  }

  const avatarEl = row.querySelector(".leaderboard-row-avatar");
  if (avatarEl) {
    setAvatarPreview(avatarEl, avatarSource, getRatingInitials(displayName));
  }
  if (!(isTournamentBoard && String(item.entity_type || "") === "club")) {
    bindLeaderboardProfileOpen(row, getLeaderboardProfileId(item), "leaderboard");
  }
  return row;
}

function buildLeaderboardMeCard(me) {
  const isTournamentBoard = state.page === "tournament";
  const mode = isTournamentBoard ? "tournament" : normalizeLeaderboardMode(stateRating.mode);
  const tournamentMode = String((stateRating.gameTournament || {}).mode || "solo").toLowerCase();
  const rank = Number(me.rank_position || 0);
  const scoreValueByMode = {
    deals: Number(me.score ?? 0),
    captures: Number(me.metric_value ?? me.captures_total ?? 0),
    mcoin: Number(me.metric_value ?? me.balance ?? 0),
    tournament: Number(me.score ?? me.point ?? 0),
  };
  const scoreRaw = scoreValueByMode[mode];
  const score = Number.isFinite(scoreRaw) ? scoreRaw : 0;
  const scoreLabelMap = { captures: "захваты", mcoin: "M-COIN", deals: "", tournament: "XP" };
  const totalUsers = Number(me.total_users || 0);

  // Get user info from me or stateProfile
  const profileData = stateProfile.data || {};
  const displayName = me.display_name || profileData.display_name || getSafeProfileName(profileData) || (tournamentMode === "club" ? "Без клуба" : "Вы");
  const avatarSource = me.avatar_data || me.avatar_url || profileData.avatar_data || profileData.avatar_url || "";
  const serverNum = Number(me.server_id || profileData.server_id || 0);
  const serverLabel = isTournamentBoard
    ? (tournamentMode === "club" ? `${Number(me.members_count || 0)} участников` : "Недельный сезон")
    : serverNum > 0 ? `Сервер ${serverNum}` : "";

  const card = document.createElement("div");
  card.className = "leaderboard-me-card";

  card.innerHTML = `
    <div class="leaderboard-me-rank">${rank > 0 ? `#${rank}` : "—"}</div>
    <div class="leaderboard-me-avatar"></div>
    <div class="leaderboard-me-main">
      <div class="leaderboard-me-name"></div>
      <div class="leaderboard-me-meta">${serverLabel}${totalUsers > 0 ? ` • из ${totalUsers}` : ""}</div>
    </div>
    <div class="leaderboard-me-score">${score}${scoreLabelMap[mode] ? `<small>${scoreLabelMap[mode]}</small>` : ""}</div>
  `;

  const nameEl = card.querySelector(".leaderboard-me-name");
  if (nameEl) { nameEl.textContent = displayName; nameEl.title = displayName; }

  const avatarEl = card.querySelector(".leaderboard-me-avatar");
  if (avatarEl) setAvatarPreview(avatarEl, avatarSource, getRatingInitials(displayName));

  // VIP effects for me card — use profile data as fallback for VIP status
  const meVipTier = me.vip_tier || getActiveVipTier(stateProfile.data || {});
  const meIsVip = me.is_vip || !!meVipTier;
  if (meIsVip) {
    card.classList.add("leaderboard-row--vip");
    if (meVipTier === "vip_ultimate") card.classList.add("leaderboard-row--vip-ultimate");
    const starCount = meVipTier === "vip_ultimate" ? 10 : 6;
    for (let i = 0; i < starCount; i++) {
      const star = document.createElement("span");
      const isCross = i % 3 === 0;
      star.className = "vip-star " + (isCross ? "vip-star--cross" : "vip-star--dot");
      const size = isCross ? 1 : (2 + Math.random() * 3);
      star.style.width = size + "px";
      star.style.height = size + "px";
      star.style.top = (8 + Math.random() * 80) + "%";
      star.style.left = (5 + Math.random() * 88) + "%";
      star.style.setProperty("--star-dur", (2.5 + Math.random() * 3) + "s");
      star.style.setProperty("--star-delay", (Math.random() * 4) + "s");
      card.appendChild(star);
    }
  }

  return card;
}

function buildLeaderboardPodCard(item, place) {
  const card = document.createElement("div");
  const tier = place === 1 ? "gold" : place === 2 ? "silver" : "bronze";
  card.className = `leaderboard-pod leaderboard-pod--${tier}`;

  const score = Number(item.score ?? item.point ?? item.metric_value ?? 0);
  const displayName = item.display_name || "Пользователь";
  const avatarSource = item.avatar_data || item.avatar_url || "";

  card.innerHTML = `
    <span class="leaderboard-pod-place">${place}</span>
    ${place === 1 ? '<span class="leaderboard-pod-crown" aria-hidden="true">👑</span>' : ""}
    <div class="leaderboard-pod-avatar"></div>
    <div class="leaderboard-pod-name"></div>
    <div class="leaderboard-pod-score leaderboard-pod-score--${tier}">${score}</div>
  `;

  const nameEl = card.querySelector(".leaderboard-pod-name");
  if (nameEl) {
    nameEl.textContent = displayName;
    nameEl.title = displayName;
  }
  const avatarEl = card.querySelector(".leaderboard-pod-avatar");
  if (avatarEl) {
    setAvatarPreview(avatarEl, avatarSource, getRatingInitials(displayName));
  }
  if (String(item.entity_type || "") !== "club") {
    bindLeaderboardProfileOpen(card, getLeaderboardProfileId(item), "leaderboard");
  }
  return card;
}

function renderLeaderboardPodium(top3) {
  if (!elements.leaderboardPodium) return;
  elements.leaderboardPodium.innerHTML = "";
  if (!top3.length) {
    elements.leaderboardPodium.style.display = "none";
    return;
  }
  // Visual order: silver (2) — gold (1) — bronze (3)
  const visualOrder = [top3[1], top3[0], top3[2]];
  const places = [2, 1, 3];
  visualOrder.forEach((item, idx) => {
    if (!item) return;
    const card = buildLeaderboardPodCard(item, places[idx]);
    elements.leaderboardPodium.appendChild(card);
  });
  elements.leaderboardPodium.style.display = "";
}

function renderLeaderboardPage(items) {
  if (!elements.leaderboardPodium || !elements.leaderboardList || !elements.leaderboardEmpty) return;
  elements.leaderboardPodium.innerHTML = "";
  elements.leaderboardPodium.style.display = "none";
  elements.leaderboardList.innerHTML = "";
  elements.leaderboardEmpty.classList.remove("show");

  const isTournamentView = state.page === "tournament";
  const tournamentMode = String((stateRating.gameTournament || {}).mode || "solo").toLowerCase();

  // Show "me" card at the top
  const me = stateRating.me;
  const myId = Number(state.tid || 0);
  const meRank = Number(me?.rank_position || 0);
  const isInList = meRank > 0 && items.some((item) => {
    if (isTournamentView && tournamentMode === "club") {
      return Number(item.club_id || 0) > 0 && Number(item.club_id || 0) === Number(me?.club_id || 0);
    }
    const itemId = Number(item.telegram_id || item.user_id || 0);
    return itemId === myId;
  });

  // Show "me" card if user is ranked but not in the first visible rows (top 5)
  const meVisibleOnScreen = isInList && meRank > 0 && meRank <= 5;
  if (me && meRank > 0 && !meVisibleOnScreen) {
    const meCard = buildLeaderboardMeCard(me);
    elements.leaderboardList.appendChild(meCard);
  }

  if (!items.length) {
    if (isTournamentView) {
      const tournamentStatus = String((stateRating.gameTournament || {}).status || "").toLowerCase();
      const tournamentMode = String((stateRating.gameTournament || {}).mode || "solo").toLowerCase();
      elements.leaderboardEmpty.textContent =
        tournamentStatus === "break"
          ? (tournamentMode === "club" ? "Итоговые результаты клубного турнира пока недоступны." : "Итоговые результаты турнира пока недоступны.")
          : tournamentStatus === "active"
            ? (tournamentMode === "club" ? "Пока нет клубов с XP для турнирной таблицы." : "Пока недостаточно данных для турнирной таблицы.")
            : "Турнир пока не запущен.";
    } else {
      elements.leaderboardEmpty.textContent = "Пока недостаточно данных для таблицы лидеров.";
    }
    elements.leaderboardEmpty.classList.add("show");
    return;
  }
  const sortedItems = [...items].sort((a, b) => Number(a.rank_position || 999) - Number(b.rank_position || 999));

  // Tournament view: split top-3 into the podium, rest into the list.
  let listSource = sortedItems;
  if (isTournamentView) {
    const top3 = sortedItems.slice(0, 3);
    renderLeaderboardPodium(top3);
    listSource = sortedItems.slice(3);
  }

  listSource.forEach((item) => {
    const itemId = Number(item.telegram_id || item.user_id || 0);
    // For own row, ensure VIP data from profile if API didn't include it
    if (itemId === myId && !item.is_vip) {
      const myVipTier = getActiveVipTier(stateProfile.data || {});
      if (myVipTier) {
        item = { ...item, is_vip: true, vip_tier: myVipTier };
      }
    }
    const row = buildLeaderboardRow(item);
    if ((isTournamentView && tournamentMode === "club" ? Number(item.club_id || 0) === Number(me?.club_id || 0) : itemId === myId) && isInList) {
      row.classList.add("leaderboard-row--me");
    }
    elements.leaderboardList.appendChild(row);
  });
}

function renderLeaderboardLoadingState() {
  if (!elements.leaderboardPodium || !elements.leaderboardList || !elements.leaderboardEmpty) return;
  elements.leaderboardPodium.innerHTML = "";
  elements.leaderboardPodium.style.display = "none";
  elements.leaderboardList.innerHTML = "";
  elements.leaderboardEmpty.classList.remove("show");

  const frag = document.createDocumentFragment();
  for (let i = 0; i < 5; i += 1) {
    const row = document.createElement("div");
    row.className = "leaderboard-row leaderboard-row--loading";
    row.innerHTML = `
      <div class="leaderboard-loading-rank shimmer"></div>
      <div class="leaderboard-loading-avatar shimmer"></div>
      <div class="leaderboard-loading-main">
        <div class="leaderboard-loading-line shimmer"></div>
        <div class="leaderboard-loading-line leaderboard-loading-line--meta shimmer"></div>
      </div>
      <div class="leaderboard-loading-score shimmer"></div>
    `;
    frag.appendChild(row);
  }
  elements.leaderboardList.appendChild(frag);
}

function mapCaptureLeaderboardToRatingItems(rawEntries) {
  const rows = (Array.isArray(rawEntries) ? rawEntries : [])
    .map((entry) => {
      const captures = Math.max(
        0,
        Number(entry?.territories ?? entry?.territories_count ?? entry?.captures ?? entry?.metric_value ?? 0),
      );
      return {
        rank_position: 0,
        metric_value: captures,
        captures_total: captures,
        confirmed_deals: Number(entry?.confirmed_deals || 0),
        server_id: Number(entry?.server_id || 0),
        display_name: String(entry?.display_name || "Без ника"),
        avatar_data: entry?.avatar_data || "",
        avatar_url: entry?.avatar_url || "",
        telegram_id: entry?.telegram_id ?? entry?.user_id ?? entry?.userId ?? entry?.id ?? 0,
      };
    })
    .sort((a, b) => {
      const diff = Number(b.metric_value || 0) - Number(a.metric_value || 0);
      if (diff !== 0) return diff;
      return String(a.display_name || "").localeCompare(String(b.display_name || ""), "ru");
    });
  rows.forEach((row, index) => {
    row.rank_position = index + 1;
  });
  return rows;
}

async function loadLeaderboardPage() {
  const mode = normalizeLeaderboardMode(stateRating.mode);
  renderLeaderboardModeUi();
  renderLeaderboardTimerUi();
  const cachedItems = Array.isArray(stateRating.itemsByMode?.[mode]) ? stateRating.itemsByMode[mode] : [];
  stateRating.items = cachedItems;
  stateRating.me = stateRating.meByMode?.[mode] || null;
  stateRating.updatedAt = stateRating.updatedAtByMode?.[mode] || "";
  stateRating.gameTournament = {};
  if (cachedItems.length) {
    renderLeaderboardPage(cachedItems);
  } else {
    renderLeaderboardLoadingState();
  }
  const requestId = ++leaderboardRequestSeq;
  try {
    const metricByMode = {
      deals: "score",
      captures: "captures",
      mcoin: "mcoin",
    };
    const metric = metricByMode[mode] || "score";
    const payload = await apiRequest(withAuth(`/api/rating/top?limit=50&metric=${metric}`));
    let items = Array.isArray(payload?.items) ? payload.items : [];
    if (mode === "captures" && !items.length) {
      try {
        const capturePayload = await apiRequest(withAuth("/api/capture/state?leaderboard=1&titles=0&online=0&coupon_preview=1"));
        stateCapture.territories = Array.isArray(capturePayload?.territories) ? capturePayload.territories : stateCapture.territories;
        stateCapture.leaderboard = Array.isArray(capturePayload?.leaderboard) ? capturePayload.leaderboard : [];
        const captureRawRows = stateCapture.leaderboard.length ? stateCapture.leaderboard : getCaptureLeaderboardFallbackRows();
        items = mapCaptureLeaderboardToRatingItems(captureRawRows);
      } catch {
        // keep primary API response
      }
    }
    if (stateRating.itemsByMode && Array.isArray(stateRating.itemsByMode[mode])) {
      stateRating.itemsByMode[mode] = items;
    }
    if (stateRating.meByMode && mode in stateRating.meByMode) {
      stateRating.meByMode[mode] = payload?.me || null;
    }
    if (stateRating.updatedAtByMode && mode in stateRating.updatedAtByMode) {
      stateRating.updatedAtByMode[mode] = payload?.updated_at || "";
    }
    if (requestId !== leaderboardRequestSeq || normalizeLeaderboardMode(stateRating.mode) !== mode || state.page !== "leaderboard") {
      return;
    }
    stateRating.items = items;
    stateRating.me = stateRating.meByMode[mode];
    stateRating.updatedAt = stateRating.updatedAtByMode[mode];
    renderLeaderboardPage(items);
  } catch {
    if (requestId !== leaderboardRequestSeq || normalizeLeaderboardMode(stateRating.mode) !== mode || state.page !== "leaderboard") {
      return;
    }
    renderLeaderboardPage(cachedItems);
  }
}

async function loadTournamentPage() {
  renderLeaderboardModeUi();
  renderLeaderboardLoadingState();
  try {
    const payload = await apiRequest(withAuth("/api/game/rating"));
    const items = Array.isArray(payload?.items) ? payload.items : [];
    const tournament = payload?.tournament || {};
    const me = payload?.me || {};
    stateRating.gameTournament = tournament;
    const tournamentMode = String(tournament.mode || "solo").toLowerCase();
    if (tournamentMode === "club") {
      stateRating.items = items.map((item) => ({
        club_id: item.club_id,
        display_name: item.club_name || "Клуб",
        avatar_url: item.club_avatar_url || "",
        score: Number(item.point || 0),
        rank_position: Number(item.rank || 0),
        members_count: Number(item.members_count || 0),
        entity_type: "club",
        reward: item.reward || {},
      }));
      stateRating.me = {
        display_name: me.display_name || "Без клуба",
        avatar_url: me.avatar_url || "",
        score: Number(me.point || 0),
        rank_position: Number(me.rank || 0),
        total_users: stateRating.items.length,
        members_count: Number(me.members_count || 0),
        entity_type: "club",
      };
    } else {
      stateRating.items = items.map((item) => ({
        telegram_id: item.telegram_id,
        display_name: item.game_nick || item.display_name || "Игрок",
        avatar_data: "",
        server_id: 0,
        score: Number(item.point || 0),
        confirmed_deals: Number(item.reward?.market_coin || 0),
        rank_position: Number(item.rank || 0),
        entity_type: "player",
      }));
      stateRating.me = {
        telegram_id: Number(state.tid || 0),
        display_name: me.game_nick || me.display_name || "Игрок",
        score: Number(me.point || 0),
        rank_position: Number(me.rank || 0),
        total_users: stateRating.items.length,
        server_id: 0,
        entity_type: "player",
      };
    }
    renderLeaderboardTimerUi();
    ensureLeaderboardTimer();
    renderLeaderboardPage(stateRating.items);
  } catch {
    stateRating.items = [];
    stateRating.me = null;
    stateRating.gameTournament = {};
    renderLeaderboardTimerUi();
    ensureLeaderboardTimer();
    renderLeaderboardPage([]);
  }
}

function clubRoleLabel(role) {
  if (role === "founder") return "Основатель";
  if (role === "deputy") return "Заместитель";
  return "Новичок";
}

const CLUB_ROLE_ORDER = ["founder", "deputy", "member"];
const CLUB_ROLE_ICONS = { founder: "👑", deputy: "⭐", member: "👤" };
const CLUB_ROLE_LABELS = { founder: "Основатель", deputy: "Заместитель", member: "Новичок" };

function getClubRoleLabels(roleLabels) {
  const source = roleLabels && typeof roleLabels === "object" ? roleLabels : {};
  return {
    founder: String(source.founder || CLUB_ROLE_LABELS.founder || "").trim() || CLUB_ROLE_LABELS.founder,
    deputy: String(source.deputy || CLUB_ROLE_LABELS.deputy || "").trim() || CLUB_ROLE_LABELS.deputy,
    member: String(source.member || CLUB_ROLE_LABELS.member || "").trim() || CLUB_ROLE_LABELS.member,
  };
}

function renderClubMembersGrouped(container, members, viewer, roleLabels) {
  container.innerHTML = "";
  const labels = getClubRoleLabels(roleLabels);
  const grouped = {};
  CLUB_ROLE_ORDER.forEach((r) => (grouped[r] = []));
  members.forEach((m) => {
    const r = CLUB_ROLE_ORDER.includes(m.role) ? m.role : "member";
    grouped[r].push(m);
  });

  CLUB_ROLE_ORDER.forEach((role) => {
    const list = grouped[role];
    if (!list.length) return;

    /* Role group header */
    const header = document.createElement("div");
    header.className = "club-role-header club-role-header--" + role;
    header.innerHTML = `<span class="club-role-icon">${CLUB_ROLE_ICONS[role]}</span><span class="club-role-label">${escapeClubHtml(labels[role])}</span><span class="club-role-count">${list.length}</span>`;
    container.appendChild(header);

    list.forEach((m) => {
      const card = document.createElement("div");
      card.className = "club-member-card-v2";

      const row = document.createElement("div");
      row.className = "club-member-row";

      const av = document.createElement("div");
      av.className = "club-avatar";
      setAvatarPreview(av, m.avatar_data || m.avatar_url || "", getRatingInitials(m.display_name || "U"));

      const info = document.createElement("div");
      info.className = "club-member-info";
      info.innerHTML = `
        <div class="club-member-name">${escapeClubHtml(m.display_name || `ID ${m.telegram_id}`)}</div>
        <div class="club-member-sub">⚡ ${Number(m.xp_current_tournament || 0)} XP турнира</div>
      `;
      row.append(av, info);
      card.appendChild(row);

      /* Admin actions */
      if (viewer.can_assign_deputy || viewer.can_remove_members) {
        const acts = document.createElement("div");
        acts.className = "club-member-btns";
        if (viewer.can_assign_deputy && m.role !== "founder" && m.role !== "deputy") {
          acts.innerHTML += `<button class="club-member-btn club-member-btn--promote" type="button" data-club-member-action="make_deputy" data-member-id="${m.telegram_id}">⭐ Заместитель</button>`;
        }
        if (viewer.can_assign_deputy && m.role === "deputy") {
          acts.innerHTML += `<button class="club-member-btn club-member-btn--demote" type="button" data-club-member-action="remove_deputy" data-member-id="${m.telegram_id}">↩︎ Снять</button>`;
        }
        if (viewer.can_remove_members && m.role !== "founder") {
          acts.innerHTML += `<button class="club-member-btn club-member-btn--remove" type="button" data-club-member-action="remove" data-member-id="${m.telegram_id}">Исключить</button>`;
        }
        if (acts.innerHTML) card.appendChild(acts);
      }

      container.appendChild(card);
    });
  });
}

function escapeClubHtml(value) {
  return String(value || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function formatClubMembersLabel(club = {}, members = null) {
  const rawLabel = String(club?.members_label || "0/0");
  const labelParts = rawLabel.split("/");
  const current = Array.isArray(members)
    ? members.length
    : Number((club?.members_count ?? labelParts[0]?.trim()) || 0);
  const limit = Number((club?.member_limit ?? labelParts[1]?.trim()) || 0);
  return `${Math.max(0, current)} / ${Math.max(0, limit)}`;
}

/* ── Club avatar from name initials ── */
const CLUB_AVATAR_PALETTES = [
  ["#7C5CFF", "#5B3FD4"], ["#FF6B6B", "#D44040"], ["#1FE6D1", "#12B09E"],
  ["#FFB347", "#E08A20"], ["#FF79C6", "#D44FA0"], ["#50FA7B", "#30C95A"],
  ["#6C9CFF", "#4070D4"], ["#FF5555", "#C03030"], ["#BD93F9", "#9060D0"],
  ["#F1FA8C", "#C8D050"],
];
function getClubAvatarHTML(name, size) {
  const sz = size || 44;
  const text = String(name || "?").trim();
  const initials = text.length <= 2 ? text.toUpperCase() : text.slice(0, 2).toUpperCase();
  let hash = 0;
  for (let i = 0; i < text.length; i++) hash = ((hash << 5) - hash + text.charCodeAt(i)) | 0;
  const pal = CLUB_AVATAR_PALETTES[Math.abs(hash) % CLUB_AVATAR_PALETTES.length];
  const fs = Math.round(sz * 0.38);
  return {
    initials,
    start: pal[0],
    end: pal[1],
    size: sz,
    fontSize: fs,
  };
}

function renderClubAvatarHtml(name, size, avatarUrl = "") {
  const meta = getClubAvatarHTML(name, size);
  return `<div class="club-avatar-gen" data-club-avatar-src="${escapeClubHtml(avatarUrl || "")}" data-club-avatar-fallback="${escapeClubHtml(meta.initials)}" data-club-avatar-start="${escapeClubHtml(meta.start)}" data-club-avatar-end="${escapeClubHtml(meta.end)}" style="width:${meta.size}px;height:${meta.size}px;background:linear-gradient(135deg,${meta.start},${meta.end});font-size:${meta.fontSize}px">${escapeClubHtml(meta.initials)}</div>`;
}

function hydrateClubAvatarNodes(root) {
  const scope = root && typeof root.querySelectorAll === "function" ? root : document;
  scope.querySelectorAll("[data-club-avatar-fallback]").forEach((node) => {
    const fallback = String(node.dataset.clubAvatarFallback || "КЛ").trim() || "КЛ";
    const start = String(node.dataset.clubAvatarStart || "#7C5CFF");
    const end = String(node.dataset.clubAvatarEnd || "#5B3FD4");
    const src = String(node.dataset.clubAvatarSrc || "").trim();
    node.style.background = `linear-gradient(135deg, ${start}, ${end})`;
    node.textContent = fallback;
    if (src) {
      setAvatarPreview(node, src, fallback);
    } else {
      node.classList.remove("avatar-photo");
      node.style.backgroundImage = "";
      node.style.background = `linear-gradient(135deg, ${start}, ${end})`;
      node.style.backgroundSize = "";
      node.style.backgroundPosition = "";
      node.textContent = fallback;
    }
  });
}

function renderClubFormAvatarPreview() {
  const preview = document.getElementById("clubAvatarPreview");
  if (!preview) return;
  const clubName = String(document.getElementById("clubNameInput")?.value || "").trim() || "Клуб";
  const meta = getClubAvatarHTML(clubName, 74);
  const src = String(stateClub.formAvatarData || stateClub.formAvatarUrl || "").trim();
  preview.style.width = `${meta.size}px`;
  preview.style.height = `${meta.size}px`;
  preview.style.fontSize = `${meta.fontSize}px`;
  preview.style.background = `linear-gradient(135deg, ${meta.start}, ${meta.end})`;
  preview.textContent = meta.initials;
  if (src) {
    setAvatarPreview(preview, src, meta.initials);
  } else {
    preview.classList.remove("avatar-photo");
    preview.style.backgroundImage = "";
    preview.style.background = `linear-gradient(135deg, ${meta.start}, ${meta.end})`;
    preview.style.backgroundSize = "";
    preview.style.backgroundPosition = "";
    preview.textContent = meta.initials;
  }
}

async function handleClubAvatarFile(file) {
  if (!file) return;
  try {
    const dataUrl = await compressImageForUpload(file, {
      maxDimension: 768,
      targetBytes: 180 * 1024,
      hardLimitBytes: 700 * 1024,
    });
    stateClub.formAvatarData = typeof dataUrl === "string" ? dataUrl : "";
    stateClub.formAvatarUrl = "";
    stateClub.formAvatarClear = false;
    renderClubFormAvatarPreview();
  } catch {
    showToast("Не удалось подготовить аватар клуба. Выбери другое изображение.", "danger");
  }
}

function setClubFormVisible(visible) {
  const panel = document.getElementById("clubCreatePanel");
  if (!panel) return;
  panel.classList.toggle("hidden", !visible);
}

function setClubRoleLabelInputsEnabled(enabled) {
  const next = Boolean(enabled);
  ["clubFounderRoleInput", "clubDeputyRoleInput", "clubMemberRoleInput"].forEach((id) => {
    const input = document.getElementById(id);
    if (!input) return;
    input.disabled = !next;
    input.classList.toggle("is-disabled", !next);
  });
}

function clubCanEditRoleLabels(club = null) {
  const formClubId = Number(club?.id || stateClub.editClubId || stateClub.openedClubId || 0);
  const detailClubId = Number(stateClub.detail?.club?.id || 0);
  if (formClubId > 0 && formClubId === detailClubId) {
    return Boolean(stateClub.detail?.viewer?.can_edit_role_labels || stateClub.detail?.club?.edit_access_enabled);
  }
  return Boolean(club?.edit_access_enabled || club?.can_edit_role_labels);
}

function bindClubAccordion(sectionIds, toggleMap) {
  const sections = sectionIds
    .map((id) => document.getElementById(id))
    .filter(Boolean);
  const openSection = (targetId) => {
    sections.forEach((section) => {
      section.classList.toggle("hidden", section.id !== targetId);
    });
  };
  Object.entries(toggleMap || {}).forEach(([buttonId, sectionId]) => {
    const button = document.getElementById(buttonId);
    const section = document.getElementById(sectionId);
    if (!button || !section) return;
    button.onclick = () => {
      const isHidden = section.classList.contains("hidden");
      if (!isHidden) {
        section.classList.add("hidden");
        return;
      }
      openSection(sectionId);
    };
  });
}

function setClubFormMode(mode, club = null) {
  stateClub.formMode = mode === "edit" ? "edit" : "create";
  stateClub.editClubId = stateClub.formMode === "edit" ? Number(club?.id || stateClub.openedClubId || 0) : 0;
  const title = document.getElementById("clubFormTitle");
  const submit = document.getElementById("clubSubmitBtn");
  const nameInput = document.getElementById("clubNameInput");
  const descInput = document.getElementById("clubDescriptionInput");
  const founderRoleInput = document.getElementById("clubFounderRoleInput");
  const deputyRoleInput = document.getElementById("clubDeputyRoleInput");
  const memberRoleInput = document.getElementById("clubMemberRoleInput");
  const labels = getClubRoleLabels(club?.role_labels);
  if (title) title.textContent = stateClub.formMode === "edit" ? "Редактировать клуб" : "Создать клуб";
  if (submit) submit.textContent = stateClub.formMode === "edit" ? "Сохранить изменения" : "Создать клуб";
  if (nameInput) nameInput.value = club?.name || "";
  if (descInput) descInput.value = club?.description || "";
  if (founderRoleInput) founderRoleInput.value = labels.founder;
  if (deputyRoleInput) deputyRoleInput.value = labels.deputy;
  if (memberRoleInput) memberRoleInput.value = labels.member;
  const canEditRoleLabels = stateClub.formMode === "create" ? false : clubCanEditRoleLabels(club);
  setClubRoleLabelInputsEnabled(canEditRoleLabels);
  stateClub.formAvatarData = "";
  stateClub.formAvatarUrl = String(club?.avatar_url || "").trim();
  stateClub.formAvatarClear = false;
  setClubFormVisible(true);
  renderClubFormAvatarPreview();
  if (nameInput) nameInput.focus();
}

function resetClubForm() {
  stateClub.formMode = "create";
  stateClub.editClubId = 0;
  const nameInput = document.getElementById("clubNameInput");
  const descInput = document.getElementById("clubDescriptionInput");
  const founderRoleInput = document.getElementById("clubFounderRoleInput");
  const deputyRoleInput = document.getElementById("clubDeputyRoleInput");
  const memberRoleInput = document.getElementById("clubMemberRoleInput");
  if (nameInput) nameInput.value = "";
  if (descInput) descInput.value = "";
  if (founderRoleInput) founderRoleInput.value = CLUB_ROLE_LABELS.founder;
  if (deputyRoleInput) deputyRoleInput.value = CLUB_ROLE_LABELS.deputy;
  if (memberRoleInput) memberRoleInput.value = CLUB_ROLE_LABELS.member;
  setClubRoleLabelInputsEnabled(false);
  stateClub.formAvatarData = "";
  stateClub.formAvatarUrl = "";
  stateClub.formAvatarClear = false;
  const avatarInput = document.getElementById("clubAvatarInput");
  if (avatarInput) avatarInput.value = "";
  setClubFormVisible(false);
}

function setClubMode(mode, options = {}) {
  const nextMode = ["mine", "all"].includes(String(mode || "")) ? String(mode) : "mine";
  stateClub.activeTab = nextMode;
  document.querySelectorAll("[data-club-mode]").forEach((button) => {
    const isActive = String(button.dataset.clubMode || "") === nextMode;
    button.classList.toggle("active", isActive);
    button.setAttribute("aria-selected", isActive ? "true" : "false");
  });
  const minePane = document.getElementById("clubPaneMine");
  const allPane = document.getElementById("clubPaneAll");
  if (minePane) minePane.classList.toggle("hidden", nextMode !== "mine");
  if (allPane) allPane.classList.toggle("hidden", nextMode !== "all");
  if (options.focusSearch && nextMode === "all") {
    const searchInput = document.getElementById("clubSearchInput");
    if (searchInput) searchInput.focus();
  }
}

async function requestClubUpgrade(club, kind = "member_limit") {
  const clubId = Number(club?.id || 0);
  if (!clubId) return;
  const upgradeKind = String(kind || "member_limit");
  const metaMap = {
    member_limit: {
      cost: Number(club?.member_upgrade_cost || 100),
      next: Number(club?.member_limit_next || ((Number(club?.member_limit || 20)) + Number(club?.member_upgrade_step || 10))),
      confirm: `Увеличить лимит участников клуба за ${Number(club?.member_upgrade_cost || 100)} Market-Coin?`,
      success: `Лимит клуба увеличен до ${Number(club?.member_limit_next || ((Number(club?.member_limit || 20)) + Number(club?.member_upgrade_step || 10)))}.`,
    },
    request_limit: {
      cost: Number(club?.request_upgrade_cost || 50),
      next: Number(club?.request_limit_next || ((Number(club?.request_limit || 10)) + Number(club?.request_upgrade_step || 10))),
      confirm: `Увеличить лимит ожидающих заявок за ${Number(club?.request_upgrade_cost || 50)} Market-Coin?`,
      success: `Лимит заявок увеличен до ${Number(club?.request_limit_next || ((Number(club?.request_limit || 10)) + Number(club?.request_upgrade_step || 10)))}.`,
    },
    edit_access: {
      cost: Number(club?.edit_access_cost || 200),
      confirm: `Открыть доступ к редактированию за ${Number(club?.edit_access_cost || 200)} Market-Coin?`,
      success: "Доступ к редактированию клуба открыт.",
    },
  };
  const meta = metaMap[upgradeKind] || metaMap.member_limit;
  if (!confirm(meta.confirm)) return;
  try {
    await apiRequest(withAuth("/api/game/clubs/upgrade"), {
      method: "POST",
      body: JSON.stringify({ club_id: clubId, kind: upgradeKind }),
    });
    if (stateClub.openedClubId && Number(stateClub.openedClubId) === clubId) {
      await Promise.all([loadClubPage(), openClubDetail(clubId)]);
    } else {
      await loadClubPage();
    }
    showToast(meta.success, "success");
  } catch (error) {
    const code = String(error?.payload?.error || "");
    if (code === "insufficient_mcoin") {
      showToast("Недостаточно Market-Coin для покупки.", "danger");
      return;
    }
    if (code === "forbidden") {
      showToast("Покупки клуба доступны только создателю.", "danger");
      return;
    }
    if (code === "edit_access_already_enabled") {
      showToast("Доступ к редактированию уже открыт.", "info");
      return;
    }
    if (code === "bad_upgrade_kind") {
      showToast("Не удалось определить тип улучшения.", "danger");
      return;
    }
    showToast("Не удалось провести покупку.", "danger");
  }
}

function getClubUpgradeStoreHtml(sectionIdPrefix, club) {
  const asset = window.__appendAssetVersion__ || ((path) => `${path}?v=${window.__APP_ASSET_VERSION__ || String(Date.now())}`);
  const requestsPrice = Number(club?.request_upgrade_cost || 50);
  const editPrice = Number(club?.edit_access_cost || 200);
  const requestsStep = Number(club?.request_upgrade_step || 10);
  const editEnabled = Boolean(club?.edit_access_enabled);
  return `
    <div class="club-dash-section hidden club-store-panel" id="${sectionIdPrefix}Store">
      <div class="club-store-list">
        <article class="club-store-card">
          <img class="club-store-art" src="${asset("assets/Mayning/club_upgrade_members.png")}" alt="" aria-hidden="true" decoding="async" />
          <div class="club-store-copy">
            <div class="club-store-title">Увеличить количество участников</div>
            <div class="club-store-price">100 Market-Coin</div>
            <div class="club-store-sub">Прибавляет +10 слотов в клубе</div>
          </div>
          <button class="club-store-buy" type="button" id="${sectionIdPrefix}StoreMembersBtn">
            <span class="club-store-buy-icon">🛒</span>
            <span>Купить</span>
          </button>
        </article>
        <article class="club-store-card">
          <img class="club-store-art" src="${asset("assets/Mayning/club_upgrade_requests.png")}" alt="" aria-hidden="true" decoding="async" />
          <div class="club-store-copy">
            <div class="club-store-title">Увеличить количество заявок</div>
            <div class="club-store-price">${requestsPrice} Market-Coin</div>
            <div class="club-store-sub">Прибавляет +${requestsStep} слотов для ожидающих заявок</div>
          </div>
          <button class="club-store-buy" type="button" id="${sectionIdPrefix}StoreRequestsBtn">
            <span class="club-store-buy-icon">🛒</span>
            <span>Купить</span>
          </button>
        </article>
        <article class="club-store-card">
          <img class="club-store-art" src="${asset("assets/Mayning/club_upgrade_edit.png")}" alt="" aria-hidden="true" decoding="async" />
          <div class="club-store-copy">
            <div class="club-store-title">Доступ к редактированию</div>
            <div class="club-store-price">${editPrice} Market-Coin</div>
            <div class="club-store-sub">Откроет кастомные названия рангов клуба</div>
          </div>
          <button class="club-store-buy ${editEnabled ? 'club-store-buy--ghost' : ''}" type="button" id="${sectionIdPrefix}StoreEditBtn">
            <span class="club-store-buy-icon">🛒</span>
            <span>${editEnabled ? 'Куплено' : 'Купить'}</span>
          </button>
        </article>
      </div>
    </div>
  `;
}

function wireClubUpgradeStore(sectionIdPrefix, club) {
  const membersBtn = document.getElementById(`${sectionIdPrefix}StoreMembersBtn`);
  if (membersBtn) {
    membersBtn.onclick = () => requestClubUpgrade(club);
  }
  const requestsBtn = document.getElementById(`${sectionIdPrefix}StoreRequestsBtn`);
  if (requestsBtn) {
    requestsBtn.onclick = () => requestClubUpgrade(club, "request_limit");
  }
  const editBtn = document.getElementById(`${sectionIdPrefix}StoreEditBtn`);
  if (editBtn) {
    editBtn.onclick = () => {
      if (club?.edit_access_enabled) {
        showToast("Доступ к редактированию уже открыт.", "info");
        return;
      }
      requestClubUpgrade(club, "edit_access");
    };
  }
}

function renderClubDashboard(detail) {
  const root = document.getElementById("clubMyCard");
  if (!root) return;
  const club = detail?.club || {};
  const viewer = detail?.viewer || {};
  const members = Array.isArray(detail?.members) ? detail.members : [];
  const requests = Array.isArray(detail?.requests) ? detail.requests : [];
  root.classList.remove("hidden");

  /* ── Header: avatar + name + stats ── */
  let html = `
    <div class="club-dash-header">
      <div class="club-dash-header-top">
        ${renderClubAvatarHtml(club.name, 56, club.avatar_url || "")}
        <div>
          <div class="club-dash-name">${escapeClubHtml(club.name || "—")}</div>
          <div class="club-dash-meta">Основатель: ${escapeClubHtml(club.founder_nickname || club.founder_display_name || "—")}</div>
        </div>
      </div>
      <div class="club-dash-stats">
        <div class="club-dash-stat">
          <div class="club-dash-stat-val">${formatClubMembersLabel(club, members)}</div>
          <div class="club-dash-stat-lbl">Участники</div>
        </div>
        <div class="club-dash-stat">
          <div class="club-dash-stat-val">${Number(club.xp_current_tournament || 0)}</div>
          <div class="club-dash-stat-lbl">XP турнира</div>
        </div>
        <div class="club-dash-stat">
          <div class="club-dash-stat-val">${Number(club.xp_total_all_time || 0)}</div>
          <div class="club-dash-stat-lbl">XP всего</div>
        </div>
        <div class="club-dash-stat">
          <div class="club-dash-stat-val">${Number(club.captures_total || 0)}</div>
          <div class="club-dash-stat-lbl">Захваты</div>
        </div>
      </div>
    </div>
  `;

  /* ── Description (if any) ── */
  if (club.description) {
    html += `<div class="club-dash-desc">${escapeClubHtml(club.description)}</div>`;
  }

  /* ── Quick actions grid ── */
  html += `<div class="club-dash-actions">`;
  if (viewer.can_edit) {
    html += `<button class="club-dash-action" type="button" id="clubDashEditBtn"><span class="club-dash-action-icon">✏️</span><span>Редактировать</span></button>`;
    html += `<button class="club-dash-action club-dash-action--upgrade" type="button" id="clubDashStoreBtn"><span class="club-dash-action-icon">🛒</span><span>Магазин</span></button>`;
  }
  if (club.id) {
    html += `<button class="club-dash-action" type="button" id="clubDashInviteBtn"><span class="club-dash-action-icon">🔗</span><span>Пригласить</span></button>`;
  }
  if (viewer.can_review_requests) {
    const reqCount = requests.length;
    html += `<button class="club-dash-action ${reqCount ? 'club-dash-action--accent' : ''}" type="button" id="clubDashRequestsToggle"><span class="club-dash-action-icon">📩</span><span>Заявки${reqCount ? ` (${reqCount})` : ''}</span></button>`;
  }
  html += `<button class="club-dash-action" type="button" id="clubDashMembersToggle"><span class="club-dash-action-icon">👥</span><span>Участники (${members.length})</span></button>`;
  if (viewer.can_leave) {
    const leaveDisabled = viewer.leave_blocked_reason === "founder_has_members" ? ' disabled title="Основатель не может выйти, пока в клубе есть участники"' : '';
    html += `<button class="club-dash-action club-dash-action--danger" type="button" id="clubDashLeaveBtn"${leaveDisabled}><span class="club-dash-action-icon">🚪</span><span>Выйти</span></button>`;
  }
  html += `</div>`;

  if (viewer.can_edit) {
    html += getClubUpgradeStoreHtml("clubDash", club);
  }

  /* ── Requests section (collapsed by default) ── */
  if (viewer.can_review_requests) {
    html += `<div class="club-dash-section hidden" id="clubDashRequests">`;
    html += `<div class="club-dash-section-title">Заявки</div>`;
    if (!requests.length) {
      html += `<div class="club-dash-empty">Новых заявок нет</div>`;
    }
    html += `<div class="club-dash-requests-list" id="clubDashRequestsList"></div>`;
    html += `</div>`;
  }

  /* ── Members section (collapsed by default) ── */
  html += `<div class="club-dash-section hidden" id="clubDashMembers">`;
  html += `<div class="club-dash-members-list" id="clubDashMembersList"></div>`;
  html += `</div>`;

  root.innerHTML = html;
  hydrateClubAvatarNodes(root);

  /* ── Render requests DOM ── */
  if (viewer.can_review_requests && requests.length) {
    const reqList = document.getElementById("clubDashRequestsList");
    if (reqList) {
      requests.forEach((r) => {
        const card = document.createElement("div");
        card.className = "club-member-card";
        const head = document.createElement("div");
        head.className = "club-member-title";
        const av = document.createElement("div");
        av.className = "club-avatar";
        setAvatarPreview(av, r.avatar_data || r.avatar_url || "", getRatingInitials(r.display_name || "U"));
        const txt = document.createElement("div");
        txt.innerHTML = `<div>${escapeClubHtml(r.display_name || `ID ${r.telegram_id}`)}</div><div class="club-member-meta">${r.created_at ? formatDateTimeMsk(r.created_at) : "Ожидает"}</div>`;
        head.append(av, txt);
        const acts = document.createElement("div");
        acts.className = "club-member-actions";
        acts.innerHTML = `
          <button class="action-btn primary" type="button" data-club-request-action="accept" data-request-id="${r.id}">Принять</button>
          <button class="action-btn" type="button" data-club-request-action="reject" data-request-id="${r.id}">Отклонить</button>
        `;
        card.append(head, acts);
        reqList.appendChild(card);
      });
    }
  }

  /* ── Render members DOM (grouped by role) ── */
  const memList = document.getElementById("clubDashMembersList");
  if (memList) renderClubMembersGrouped(memList, members, viewer, club.role_labels);

  /* ── Wire up toggle buttons ── */
  bindClubAccordion(
    ["clubDashStore", "clubDashRequests", "clubDashMembers"],
    {
      clubDashStoreBtn: "clubDashStore",
      clubDashRequestsToggle: "clubDashRequests",
      clubDashMembersToggle: "clubDashMembers",
    },
  );

  /* ── Edit button ── */
  const editBtn = document.getElementById("clubDashEditBtn");
  if (editBtn) {
    editBtn.onclick = () => {
      setClubFormMode("edit", club);
      window.scrollTo({ top: 0, behavior: "smooth" });
    };
  }
  const inviteBtn = document.getElementById("clubDashInviteBtn");
  if (inviteBtn) {
    inviteBtn.onclick = () => shareClubInviteLink(club);
  }

  if (viewer.can_edit) {
    wireClubUpgradeStore("clubDash", club);
  }

  /* ── Leave button ── */
  const leaveBtn = document.getElementById("clubDashLeaveBtn");
  if (leaveBtn && !leaveBtn.disabled) {
    leaveBtn.onclick = async () => {
      if (!confirm("Выйти из клуба?")) return;
      try {
        const result = await apiRequest(withAuth("/api/game/clubs/member/action"), {
          method: "POST",
          body: JSON.stringify({
            club_id: Number(club.id || 0),
            target_telegram_id: Number(state.tid || 0),
            action: "leave",
          }),
        });
        stateClub.detail = null;
        stateClub.openedClubId = 0;
        await loadClubPage();
        showToast(result?.club_deleted ? "Клуб удалён." : "Вы вышли из клуба.", "success");
      } catch (error) {
        const code = String(error?.payload?.error || "");
        showToast(code === "founder_has_members" ? "Основатель не может выйти, пока в клубе есть другие участники." : "Не удалось выйти из клуба.", "danger");
      }
    };
  }
}

function renderClubMyCard(item) {
  const root = document.getElementById("clubMyCard");
  if (!root) return;
  if (!item) {
    root.classList.add("hidden");
    root.innerHTML = "";
    return;
  }
  /* Show loading state while we fetch full detail */
  root.classList.remove("hidden");
  root.innerHTML = `
    <div class="club-dash-header">
      <div class="club-dash-header-top">
        ${renderClubAvatarHtml(item.name, 56, item.avatar_url || "")}
        <div>
          <div class="club-dash-name">${escapeClubHtml(item.name || "—")}</div>
          <div class="club-dash-meta">Загрузка...</div>
        </div>
      </div>
    </div>
  `;
}

async function renderClubMineState(payload) {
  const root = document.getElementById("clubMyCard");
  const empty = document.getElementById("clubMineEmptyState");
  if (!root || !empty) return;

  if (!payload?.my_club) {
    root.classList.add("hidden");
    root.innerHTML = "";
    empty.classList.remove("hidden");
    empty.innerHTML = `
      <div class="club-empty-title">Вы пока не в клубе</div>
      <div class="club-empty-subtitle">Создайте свой клуб или найдите существующий.</div>
      <div class="club-empty-actions club-detail-actions">
        <button class="action-btn primary" type="button" id="clubMineCreateBtn">Создать клуб</button>
        <button class="action-btn" type="button" id="clubMineFindBtn">Найти клуб</button>
      </div>
    `;
    const createBtn = document.getElementById("clubMineCreateBtn");
    const findBtn = document.getElementById("clubMineFindBtn");
    if (createBtn) createBtn.onclick = () => { setClubFormMode("create"); window.scrollTo({ top: 0, behavior: "smooth" }); };
    if (findBtn) findBtn.onclick = () => setClubMode("all", { focusSearch: true });
    return;
  }

  empty.classList.add("hidden");
  empty.innerHTML = "";
  renderClubMyCard(payload.my_club);

  /* Auto-fetch full club detail for dashboard */
  try {
    const detail = await apiRequest(withAuth(`/api/game/clubs/${payload.my_club.id}`));
    renderClubDashboard(detail);
  } catch {
    /* fallback: show basic info */
    root.innerHTML = `
      <div class="club-dash-header">
        <div class="club-dash-name">${escapeClubHtml(payload.my_club.name || "—")}</div>
        <div class="club-dash-meta">Не удалось загрузить подробности</div>
        <div class="club-dash-stats">
          <div class="club-dash-stat"><div class="club-dash-stat-val">${formatClubMembersLabel(payload.my_club)}</div><div class="club-dash-stat-lbl">Участники</div></div>
          <div class="club-dash-stat"><div class="club-dash-stat-val">${Number(payload.my_club.xp_current_tournament || 0)}</div><div class="club-dash-stat-lbl">XP турнира</div></div>
        </div>
      </div>
    `;
  }
}

function buildClubActionNode(item) {
  const actionWrap = document.createElement("div");
  actionWrap.className = "club-card-v2-actions";

  if (item.is_my_club) {
    const badge = document.createElement("div");
    badge.className = "club-badge club-badge--mine";
    badge.textContent = "Ваш клуб";
    actionWrap.appendChild(badge);
    const openBtn = document.createElement("button");
    openBtn.className = "club-btn-open";
    openBtn.type = "button";
    openBtn.dataset.clubOpen = String(item.id || 0);
    openBtn.textContent = "Открыть";
    actionWrap.appendChild(openBtn);
    return actionWrap;
  }

  if (item.application_status === "pending") {
    const badge = document.createElement("div");
    badge.className = "club-badge club-badge--pending";
    badge.textContent = "Заявка отправлена";
    actionWrap.appendChild(badge);
    return actionWrap;
  }

  if (item.is_full) {
    const badge = document.createElement("div");
    badge.className = "club-badge club-badge--full";
    badge.textContent = "Заполнен";
    actionWrap.appendChild(badge);
    return actionWrap;
  }

  const openBtn = document.createElement("button");
  openBtn.className = "club-btn-open";
  openBtn.type = "button";
  openBtn.dataset.clubOpen = String(item.id || 0);
  openBtn.textContent = "Подробнее";
  actionWrap.appendChild(openBtn);

  if (item.can_apply) {
    const applyBtn = document.createElement("button");
    applyBtn.className = "club-btn-apply";
    applyBtn.type = "button";
    applyBtn.dataset.clubApply = String(item.id || 0);
    applyBtn.textContent = "Вступить";
    actionWrap.appendChild(applyBtn);
  }

  return actionWrap;
}

function renderClubList(items) {
  const root = document.getElementById("clubList");
  if (!root) return;
  root.innerHTML = "";
  (Array.isArray(items) ? items : []).forEach((item) => {
    const card = document.createElement("article");
    card.className = "club-card-v2";
    const membersLabel = formatClubMembersLabel(item);
    const membersNum = String(membersLabel || "0/20").split("/")[0].trim();
    const membersMax = String(membersLabel || "0/20").split("/")[1]?.trim() || "20";
    const fillPct = Math.min(100, Math.round((Number(membersNum) / Number(membersMax)) * 100));
    card.innerHTML = `
      <div class="club-card-v2-top">
        ${renderClubAvatarHtml(item.name, 48, item.avatar_url || "")}
        <div class="club-card-v2-info">
          <div class="club-card-v2-name">${escapeClubHtml(item.name || "—")}</div>
          <div class="club-card-v2-founder">${item.founder_display_name ? escapeClubHtml(item.founder_display_name) : "—"}</div>
        </div>
      </div>
      <div class="club-card-v2-chips">
        <span class="club-chip">👥 ${membersLabel}</span>
        <span class="club-chip">⚡ ${Number(item.xp_current_tournament || 0)} XP</span>
        <span class="club-chip">Всего ${Number(item.xp_total_all_time || 0)} XP</span>
      </div>
      <div class="club-card-v2-bar-wrap">
        <div class="club-card-v2-bar" style="width:${fillPct}%"></div>
      </div>
    `;
    card.appendChild(buildClubActionNode(item));
    hydrateClubAvatarNodes(card);
    root.appendChild(card);
  });
}

function renderClubRatingList(items) {
  const root = document.getElementById("clubRatingList");
  const status = document.getElementById("clubRatingStatus");
  const empty = document.getElementById("clubRatingEmptyState");
  if (!root || !status || !empty) return;
  root.innerHTML = "";
  const rows = [...(Array.isArray(items) ? items : [])].sort((a, b) => {
    const xpDiff = Number(b.xp_current_tournament || 0) - Number(a.xp_current_tournament || 0);
    if (xpDiff !== 0) return xpDiff;
    const allDiff = Number(b.xp_total_all_time || 0) - Number(a.xp_total_all_time || 0);
    if (allDiff !== 0) return allDiff;
    return String(a.name || "").localeCompare(String(b.name || ""), "ru");
  });
  if (!rows.length) {
    status.textContent = "Пока пусто";
    empty.classList.remove("hidden");
    empty.innerHTML = `
      <div class="club-empty-title">Рейтинг пока пуст</div>
      <div class="club-empty-subtitle">Как только клубы начнут зарабатывать XP турнира, они появятся здесь.</div>
    `;
    return;
  }
  empty.classList.add("hidden");
  empty.innerHTML = "";
  status.textContent = `${rows.length} клубов`;
  rows.forEach((item, index) => {
    const card = document.createElement("article");
    card.className = "club-card";
    const membersLabel = formatClubMembersLabel(item);
    card.innerHTML = `
      <div class="club-rating-row">
        <div class="club-rating-rank">#${index + 1}</div>
        <div class="club-card-head">
          <div>
            <div class="club-card-name">${escapeClubHtml(item.name || "—")}</div>
            <div class="club-card-meta">${membersLabel} • XP всего: ${Number(item.xp_total_all_time || 0)}</div>
          </div>
        </div>
        <div class="club-rating-points">${Number(item.xp_current_tournament || 0)}<small>XP турнира</small></div>
      </div>
    `;
    const actions = document.createElement("div");
    actions.className = "club-card-actions";
    const openBtn = document.createElement("button");
    openBtn.className = "action-btn";
    openBtn.type = "button";
    openBtn.dataset.clubOpen = String(item.id || 0);
    openBtn.textContent = "Открыть";
    actions.appendChild(openBtn);
    card.appendChild(actions);
    root.appendChild(card);
  });
}

function renderClubPage(payload) {
  stateClub.list = payload || {};
  renderClubMineState(payload);
  renderClubList(payload?.clubs || []);

  const searchInput = document.getElementById("clubSearchInput");
  const searchStatus = document.getElementById("clubSearchStatus");
  if (searchInput) {
    searchInput.value = stateClub.search || "";
  }
  if (searchStatus) {
    if (payload?.empty_state === "not_found") {
      searchStatus.textContent = "Клуб не найден";
    } else if (payload?.empty_state === "no_clubs") {
      searchStatus.textContent = "Клубов пока нет";
    } else {
      searchStatus.textContent = `${Array.isArray(payload?.clubs) ? payload.clubs.length : 0} клубов`;
    }
  }

  const empty = document.getElementById("clubEmptyState");
  if (empty) {
    const emptyState = String(payload?.empty_state || "");
    if (!emptyState) {
      empty.classList.add("hidden");
      empty.innerHTML = "";
    } else {
      empty.classList.remove("hidden");
      empty.innerHTML = emptyState === "not_found"
        ? `<div class="club-empty-title">Клуб не найден</div><div class="club-empty-subtitle">Попробуйте изменить запрос и поискать по другому названию.</div>`
        : `<div class="club-empty-title">Клубов пока нет</div><div class="club-empty-subtitle">Станьте первым и создайте клуб.</div>`;
    }
  }

  const createToggle = document.getElementById("clubCreateToggle");
  if (createToggle) {
    createToggle.style.display = payload?.can_create ? "" : "none";
  }
  setClubMode(stateClub.activeTab || "mine");
}

function buildClubInviteLink(club) {
  const inviteUrl = String(club?.invite_url || "").trim();
  if (inviteUrl) return inviteUrl;
  const clubId = Number(club?.id || 0);
  if (!clubId) return "";
  const url = new URL(window.location.href);
  url.hash = "";
  url.searchParams.set("page", "club");
  url.searchParams.set("club_id", String(clubId));
  url.searchParams.delete("listing");
  url.searchParams.delete("chat");
  url.searchParams.delete("chat_id");
  url.searchParams.delete("tgWebAppData");
  url.searchParams.delete("tgWebAppVersion");
  url.searchParams.delete("tgWebAppPlatform");
  url.searchParams.delete("tgWebAppThemeParams");
  return url.toString();
}

async function shareClubInviteLink(club) {
  const link = buildClubInviteLink(club);
  if (!link) {
    showToast("Ссылка клуба пока недоступна.", "info");
    return;
  }
  const clubName = String(club?.name || "клуб").trim();
  const text = `Вступай в клуб «${clubName}» в RP Market`;
  const shareUrl = `https://t.me/share/url?url=${encodeURIComponent(link)}&text=${encodeURIComponent(text)}`;

  try {
    if (window.Telegram?.WebApp?.openTelegramLink) {
      window.Telegram.WebApp.openTelegramLink(shareUrl);
      return;
    }
  } catch {
    // ignore
  }

  try {
    if (navigator.share) {
      await navigator.share({ title: "RP Market Club", text, url: link });
      return;
    }
  } catch {
    // ignore
  }

  try {
    await navigator.clipboard.writeText(link);
    showToast("Ссылка-приглашение скопирована.", "success");
  } catch {
    prompt("Скопируйте ссылку клуба:", link);
  }
}

function setClubDetailTab(tab) {
  stateClub.detailTab = tab === "members" ? "members" : "info";
  document.querySelectorAll("[data-club-detail-tab]").forEach((button) => {
    const isActive = String(button.dataset.clubDetailTab || "") === stateClub.detailTab;
    button.classList.toggle("active", isActive);
    button.setAttribute("aria-selected", isActive ? "true" : "false");
  });
  const infoPane = document.getElementById("clubDetailInfoPane");
  const membersPane = document.getElementById("clubDetailMembersPane");
  if (infoPane) infoPane.classList.toggle("hidden", stateClub.detailTab !== "info");
  if (membersPane) membersPane.classList.toggle("hidden", stateClub.detailTab !== "members");
}

function renderClubDetailNew(payload) {
  stateClub.detail = payload || null;
  const detailView = document.getElementById("clubDetailView");
  const mainView = document.getElementById("clubMainView");
  const card = document.getElementById("clubDetailCard");
  if (!detailView || !mainView || !card) return;
  const club = payload?.club || {};
  const viewer = payload?.viewer || {};
  const members = Array.isArray(payload?.members) ? payload.members : [];
  const requests = Array.isArray(payload?.requests) ? payload.requests : [];
  detailView.classList.remove("hidden");
  mainView.classList.add("hidden");

  /* Hide old tabs — we render everything inline now */
  const oldTabs = document.querySelector(".club-detail-tabs");
  const infoPane = document.getElementById("clubDetailInfoPane");
  const membersPane = document.getElementById("clubDetailMembersPane");
  if (oldTabs) oldTabs.style.display = "none";
  if (infoPane) { infoPane.innerHTML = ""; infoPane.style.display = "none"; }
  if (membersPane) { membersPane.innerHTML = ""; membersPane.style.display = "none"; }

  /* ── Build dashboard-style HTML inside the detail card ── */
  let html = `
    <div class="club-dash-header">
      <div class="club-dash-header-top">
        ${renderClubAvatarHtml(club.name, 56, club.avatar_url || "")}
        <div>
          <div class="club-dash-name">${escapeClubHtml(club.name || "—")}</div>
          <div class="club-dash-meta">Основатель: ${escapeClubHtml(club.founder_nickname || club.founder_display_name || "—")}</div>
        </div>
      </div>
      <div class="club-dash-stats">
        <div class="club-dash-stat">
          <div class="club-dash-stat-val">${formatClubMembersLabel(club, members)}</div>
          <div class="club-dash-stat-lbl">Участники</div>
        </div>
        <div class="club-dash-stat">
          <div class="club-dash-stat-val">${Number(club.xp_current_tournament || 0)}</div>
          <div class="club-dash-stat-lbl">XP турнира</div>
        </div>
        <div class="club-dash-stat">
          <div class="club-dash-stat-val">${Number(club.xp_total_all_time || 0)}</div>
          <div class="club-dash-stat-lbl">XP всего</div>
        </div>
        <div class="club-dash-stat">
          <div class="club-dash-stat-val">${Number(club.captures_total || 0)}</div>
          <div class="club-dash-stat-lbl">Захваты</div>
        </div>
      </div>
    </div>
  `;

  if (club.description) {
    html += `<div class="club-dash-desc">${escapeClubHtml(club.description)}</div>`;
  }

  /* ── Actions ── */
  html += `<div class="club-dash-actions">`;
  if (viewer.can_edit) {
    html += `<button class="club-dash-action" type="button" id="clubDetailEditBtn"><span class="club-dash-action-icon">✏️</span><span>Редактировать</span></button>`;
    html += `<button class="club-dash-action club-dash-action--upgrade" type="button" id="clubDetailStoreBtn"><span class="club-dash-action-icon">🛒</span><span>Магазин</span></button>`;
  }
  if (club.id) {
    html += `<button class="club-dash-action" type="button" id="clubDetailInviteBtn"><span class="club-dash-action-icon">🔗</span><span>Пригласить</span></button>`;
  }
  if (viewer.can_review_requests) {
    const reqCount = requests.length;
    html += `<button class="club-dash-action ${reqCount ? 'club-dash-action--accent' : ''}" type="button" id="clubDetailRequestsToggle"><span class="club-dash-action-icon">📩</span><span>Заявки${reqCount ? ` (${reqCount})` : ''}</span></button>`;
  }
  html += `<button class="club-dash-action" type="button" id="clubDetailMembersToggle"><span class="club-dash-action-icon">👥</span><span>Участники (${members.length})</span></button>`;
  if (viewer.can_leave) {
    const leaveDisabled = viewer.leave_blocked_reason === "founder_has_members" ? ' disabled title="Основатель не может выйти, пока в клубе есть участники"' : '';
    html += `<button class="club-dash-action club-dash-action--danger" type="button" id="clubDetailLeaveBtn"${leaveDisabled}><span class="club-dash-action-icon">🚪</span><span>Выйти</span></button>`;
  }
  if (!viewer.can_edit && !viewer.can_leave && !viewer.can_review_requests) {
    /* Visitor — show apply button if available */
  }
  html += `</div>`;

  if (viewer.can_edit) {
    html += getClubUpgradeStoreHtml("clubDetail", club);
  }

  /* ── Requests section ── */
  if (viewer.can_review_requests) {
    html += `<div class="club-dash-section hidden" id="clubDetailRequests">`;
    html += `<div class="club-dash-section-title">Заявки</div>`;
    if (!requests.length) html += `<div class="club-dash-empty">Новых заявок нет</div>`;
    html += `<div class="club-dash-requests-list" id="clubDetailRequestsList"></div></div>`;
  }

  /* ── Members section ── */
  html += `<div class="club-dash-section hidden" id="clubDetailMembers">`;
  html += `<div class="club-dash-members-list" id="clubDetailMembersList"></div></div>`;

  card.innerHTML = html;
  hydrateClubAvatarNodes(card);

  /* ── Render requests DOM ── */
  if (viewer.can_review_requests && requests.length) {
    const reqList = document.getElementById("clubDetailRequestsList");
    if (reqList) {
      requests.forEach((r) => {
        const el = document.createElement("div");
        el.className = "club-member-card";
        const head = document.createElement("div");
        head.className = "club-member-title";
        const av = document.createElement("div");
        av.className = "club-avatar";
        setAvatarPreview(av, r.avatar_data || r.avatar_url || "", getRatingInitials(r.display_name || "U"));
        const txt = document.createElement("div");
        txt.innerHTML = `<div>${escapeClubHtml(r.display_name || `ID ${r.telegram_id}`)}</div><div class="club-member-meta">${r.created_at ? formatDateTimeMsk(r.created_at) : "Ожидает"}</div>`;
        head.append(av, txt);
        const acts = document.createElement("div");
        acts.className = "club-member-actions";
        acts.innerHTML = `
          <button class="action-btn primary" type="button" data-club-request-action="accept" data-request-id="${r.id}">Принять</button>
          <button class="action-btn" type="button" data-club-request-action="reject" data-request-id="${r.id}">Отклонить</button>
        `;
        el.append(head, acts);
        reqList.appendChild(el);
      });
    }
  }

  /* ── Render members DOM (grouped by role) ── */
  const memList = document.getElementById("clubDetailMembersList");
  if (memList) renderClubMembersGrouped(memList, members, viewer, club.role_labels);

  /* ── Wire toggles ── */
  bindClubAccordion(
    ["clubDetailStore", "clubDetailRequests", "clubDetailMembers"],
    {
      clubDetailStoreBtn: "clubDetailStore",
      clubDetailRequestsToggle: "clubDetailRequests",
      clubDetailMembersToggle: "clubDetailMembers",
    },
  );

  /* ── Edit button ── */
  const editBtn = document.getElementById("clubDetailEditBtn");
  if (editBtn) {
    editBtn.onclick = () => {
      setClubFormMode("edit", club);
      window.scrollTo({ top: 0, behavior: "smooth" });
    };
  }
  const inviteBtn = document.getElementById("clubDetailInviteBtn");
  if (inviteBtn) {
    inviteBtn.onclick = () => shareClubInviteLink(club);
  }

  if (viewer.can_edit) {
    wireClubUpgradeStore("clubDetail", club);
  }

  /* ── Leave button ── */
  const leaveBtn = document.getElementById("clubDetailLeaveBtn");
  if (leaveBtn && !leaveBtn.disabled) {
    leaveBtn.onclick = async () => {
      if (!confirm("Выйти из клуба?")) return;
      try {
        const result = await apiRequest(withAuth("/api/game/clubs/member/action"), {
          method: "POST",
          body: JSON.stringify({
            club_id: Number(club.id || 0),
            target_telegram_id: Number(state.tid || 0),
            action: "leave",
          }),
        });
        stateClub.detail = null;
        stateClub.openedClubId = 0;
        detailView.classList.add("hidden");
        mainView.classList.remove("hidden");
        await loadClubPage();
        showToast(result?.club_deleted ? "Клуб удалён." : "Вы вышли из клуба.", "success");
      } catch (error) {
        const code = String(error?.payload?.error || "");
        showToast(code === "founder_has_members" ? "Основатель не может выйти, пока в клубе есть другие участники." : "Не удалось выйти из клуба.", "danger");
      }
    };
  }
}

async function loadClubPage() {
  try {
    const payload = await apiRequest(withAuth(`/api/game/clubs?search=${encodeURIComponent(stateClub.search || "")}&limit=24`));
    renderClubPage(payload);
    const deepLinkClubId = Number(getClubParam() || 0);
    if (
      deepLinkClubId > 0 &&
      consumedClubStartTarget !== String(deepLinkClubId) &&
      Number(stateClub.openedClubId || 0) !== deepLinkClubId
    ) {
      consumedClubStartTarget = String(deepLinkClubId);
      await openClubDetail(deepLinkClubId);
    }
  } catch {
    renderClubPage({ my_club: null, clubs: [], can_create: true, empty_state: "no_clubs" });
  }
}

async function openClubDetail(clubId) {
  const nextClubId = Number(clubId || 0);
  if (!nextClubId) return;
  const detailView = document.getElementById("clubDetailView");
  const mainView = document.getElementById("clubMainView");
  const card = document.getElementById("clubDetailCard");
  if (!detailView || !mainView || !card) return;

  /* Show loading state */
  detailView.classList.remove("hidden");
  mainView.classList.add("hidden");
  card.innerHTML = `<div class="club-dash-header"><div class="club-dash-name">Загрузка...</div></div>`;

  try {
    const payload = await apiRequest(withAuth(`/api/game/clubs/${nextClubId}`));
    stateClub.openedClubId = nextClubId;
    renderClubDetailNew(payload);
  } catch {
    showToast("Не удалось открыть клуб.", "danger");
    detailView.classList.add("hidden");
    mainView.classList.remove("hidden");
  }
}

function renderPlaceholders() {
  const examples = [
    "Пример объявления",
    "Пока нет активных лотов",
    "Создайте первое объявление",
  ];
  examples.forEach((title) => {
    const card = document.createElement("div");
    card.className = "listing-item placeholder";
    card.innerHTML = `
      <div class="listing-main">
        <div class="listing-title">${title}</div>
        <div class="listing-meta">Сервер — • Категория — • Цена —</div>
      </div>
    `;
    elements.marketList.appendChild(card);
  });
}

// ---- Sharing a listing: short plain text (title / price · server / link), no ad copy ----
function buildListingShare(data) {
  const id = Number(data?.id || 0);
  const link = String(data?.share_url || "").trim() || `${window.location.origin}/?listing=${id}`;
  const title = String(data?.title || "Объявление").trim();
  const price = `${formatPrice(data?.price || 0)} ₽`;
  const server = Number(data?.server_id || 0) > 0 ? ` · Сервер ${data.server_id}` : "";
  const line2 = `${price}${server}`;
  return { link, title, line2, text: `${title}\n${line2}`, full: `${title}\n${line2}\n${link}` };
}

async function copyListingLink(link) {
  try {
    await navigator.clipboard.writeText(link);
    showToast("Ссылка скопирована", "success");
  } catch {
    prompt("Скопируйте ссылку:", link);
  }
}

// Telegram (Bot API 8.0+): the bot prepares a card (title, price, «Открыть в RP Market» button) and the Mini App hands it to
// the chat picker, so the recipient gets a button instead of a bare link. Returns true when the picker was opened.
async function shareListingAsCard(data) {
  const webApp = window.Telegram?.WebApp;
  if (!webApp || typeof webApp.shareMessage !== "function" || !webApp.initData) return false;
  try {
    if (typeof webApp.isVersionAtLeast === "function" && !webApp.isVersionAtLeast("8.0")) return false;
    const prepared = await apiRequest(withAuth(`/api/listings/${Number(data?.id || 0)}/share`), { method: "POST", timeoutMs: 6000, body: "{}" });
    const messageId = String(prepared?.message_id || "").trim();
    if (!messageId) return false;
    webApp.shareMessage(messageId, () => {});
    return true;
  } catch {
    return false;
  }
}

async function shareListing(data) {
  const share = buildListingShare(data);
  const inTelegram = Boolean(window.Telegram?.WebApp?.openTelegramLink && window.Telegram?.WebApp?.initData);
  if (inTelegram && (await shareListingAsCard(data))) return;
  if (!inTelegram && typeof navigator.share === "function") {
    try {
      await navigator.share({ title: share.title, text: share.text, url: share.link });
      return;
    } catch (error) {
      if (error && error.name === "AbortError") return;
    }
  }
  const sheet = document.getElementById("listingShareSheet");
  if (!sheet) {
    await copyListingLink(share.link);
    return;
  }
  document.getElementById("listingSharePreview").innerHTML =
    `<b>${escapeHtmlText(share.title)}</b><span>${escapeHtmlText(share.line2)}</span><small>${escapeHtmlText(share.link)}</small>`;
  const tgBtn = document.getElementById("listingShareTelegram");
  tgBtn.hidden = !inTelegram;
  tgBtn.onclick = () => {
    sheet.classList.remove("show");
    const shareUrl = `https://t.me/share/url?url=${encodeURIComponent(share.link)}&text=${encodeURIComponent(share.text)}`;
    try {
      window.Telegram.WebApp.openTelegramLink(shareUrl);
    } catch {
      copyListingLink(share.link);
    }
  };
  document.getElementById("listingShareCopy").onclick = async () => {
    sheet.classList.remove("show");
    await copyListingLink(share.link);
  };
  document.getElementById("listingShareCancel").onclick = () => sheet.classList.remove("show");
  sheet.onclick = (event) => {
    if (event.target === sheet) sheet.classList.remove("show");
  };
  sheet.classList.add("show");
}

async function loadListing(id, backPage = "market", prefill = null) {
  if (listingLoadAbortController) listingLoadAbortController.abort();
  if (listingImagesAbortController) listingImagesAbortController.abort();
  const controller = new AbortController();
  listingLoadAbortController = controller;
  const loadToken = ++listingLoadToken;
  const loadingToken = beginUiLoading("Открываем объявление...", "Загружаем карточку");
  const prefillHasImages =
    Array.isArray(prefill?.images) && prefill.images.length > 0
      ? true
      : Number(prefill?.has_image || 0) > 0;
  try {
  stateListing.backPage = backPage;
  const previousPage = state.page;
  const previousScrollY = window.scrollY || 0;
  if (state.page !== "listing") {
    navigateTo("listing");
    if (previousPage === "market" && navStack.length) {
      const last = navStack[navStack.length - 1];
      if (last && last.page === "market") {
        last.skipReload = true;
        last.restoreScrollY = previousScrollY;
      }
    }
  }
  if (elements.listingTitle) {
    elements.listingTitle.textContent = prefill?.title || "Загрузка...";
  }
  if (elements.listingPrice) {
    elements.listingPrice.innerHTML = prefill?.price ? formatPriceWithGame(prefill.price) : "—";
  }
  setListingTypeTag(prefill);
  if (elements.listingMeta) {
    if (prefill?.server_id && prefill?.category) {
      renderListingMeta(elements.listingMeta, prefill);
    } else {
      elements.listingMeta.textContent = "";
    }
  }
  if (elements.listingDesc) {
    elements.listingDesc.textContent = "Описание не указано.";
  }
  renderListingCatalogCard(null);
  if (elements.listingStatus) {
    elements.listingStatus.hidden = true;
  }
  if (elements.listingDeal) {
    elements.listingDeal.hidden = true;
  }
  if (elements.listingModerationMenuBtn) {
    elements.listingModerationMenuBtn.hidden = true;
  }
  if (elements.listingModerationMenu) {
    closeListingModerationMenu();
  }
  if (elements.listingOwnerMenuSection) {
    elements.listingOwnerMenuSection.hidden = true;
  }
  if (elements.listingOwnerDivider) {
    elements.listingOwnerDivider.hidden = true;
  }
  if (elements.listingModerationMenuSection) {
    elements.listingModerationMenuSection.hidden = true;
  }
  if (elements.listingOwnerRole) {
    elements.listingOwnerRole.className = "listing-mod-menu-role owner";
  }
  if (elements.listingOwnerMenuSold) {
    elements.listingOwnerMenuSold.hidden = true;
    elements.listingOwnerMenuSold.onclick = null;
  }
  if (elements.listingOwnerMenuHide) {
    elements.listingOwnerMenuHide.hidden = true;
    elements.listingOwnerMenuHide.onclick = null;
  }
  if (elements.listingOwnerMenuRestore) {
    elements.listingOwnerMenuRestore.hidden = true;
    elements.listingOwnerMenuRestore.onclick = null;
  }
  if (elements.listingOwnerMenuEdit) {
    elements.listingOwnerMenuEdit.hidden = true;
    elements.listingOwnerMenuEdit.onclick = null;
  }
  if (elements.listingModerationRole) {
    elements.listingModerationRole.className = "listing-mod-menu-role";
    elements.listingModerationRole.textContent = "Модерация";
  }
  if (elements.listingModerationMenuHide) {
    elements.listingModerationMenuHide.hidden = true;
    elements.listingModerationMenuHide.onclick = null;
  }
  if (elements.listingModerationMenuRestore) {
    elements.listingModerationMenuRestore.hidden = true;
    elements.listingModerationMenuRestore.onclick = null;
  }
  if (elements.listingModerationMenuEdit) {
    elements.listingModerationMenuEdit.hidden = true;
    elements.listingModerationMenuEdit.onclick = null;
  }
  if (elements.listingModerationMenuRestrict) {
    elements.listingModerationMenuRestrict.hidden = true;
    elements.listingModerationMenuRestrict.onclick = null;
  }
  if (elements.listingModerationMenuDelete) {
    elements.listingModerationMenuDelete.hidden = true;
    elements.listingModerationMenuDelete.onclick = null;
  }
  if (elements.sellerMessage) {
    elements.sellerMessage.textContent = "Написать продавцу";
    elements.sellerMessage.disabled = true;
    elements.sellerMessage.onclick = null;
    elements.sellerMessage.dataset.listingId = String(Number(id || 0) || "");
  }
  if (elements.sellerContactSecondary) {
    elements.sellerContactSecondary.classList.add("hidden");
    elements.sellerContactSecondary.onclick = null;
  }
  if (elements.sellerContactIcons) {
    elements.sellerContactIcons.style.display = "none";
    const contactWrap = elements.sellerContactIcons.closest(".seller-contact");
    if (contactWrap) {
      contactWrap.classList.add("solo");
    }
  }
  if (Array.isArray(prefill?.images) && prefill.images.length) {
    renderGallery(listingGalleryImages(prefill));
  } else if (prefill && !prefillHasImages) {
    renderGallery([]);
  } else {
    renderGalleryLoading();
  }
  const data = await apiRequest(withAuth(`/api/listings/${id}?images=0`), {
    signal: controller.signal,
  });
  if (loadToken !== listingLoadToken || controller.signal.aborted || state.page !== "listing") return;
  renderGallery(listingGalleryImages(data));
  const listingHasImages = Number(data?.has_image || 0) > 0;
  elements.listingTitle.textContent = data.title;
  elements.listingPrice.innerHTML = formatPriceWithGame(data.price);
  setListingTypeTag(data);
  const shareBtn = document.getElementById("listingShareBtn");
  if (shareBtn) {
    // only live listings are worth sharing; the link of a hidden/sold one would lead nowhere
    shareBtn.hidden = data.status !== "active";
    shareBtn.onclick = () => shareListing(data);
  }
  renderListingMeta(elements.listingMeta, data, { showId: backPage === "admin" });
  const isSeller = Boolean(data.is_owner) || String(data.seller.telegram_id) === String(state.tid || "");
  if (elements.listingStatus && elements.listingStatusTitle && elements.listingStatusText) {
    if (data.status === "pending") {
      elements.listingStatus.hidden = false;
      elements.listingStatusTitle.textContent = "🔍 Объявление на модерации";
      elements.listingStatusText.textContent = "Мы проверяем его перед публикацией. Обычно это занимает до 1–2 часов.";
    } else if (data.status === "rejected") {
      elements.listingStatus.hidden = false;
      elements.listingStatusTitle.textContent = "❌ Объявление отклонено модерацией";
      elements.listingStatusText.textContent = "Исправьте данные и отправьте на повторную проверку.";
    } else if (data.status === "awaiting_confirmation") {
      elements.listingStatus.hidden = false;
      if (isSeller) {
        elements.listingStatusTitle.textContent = "🕓 Ожидает подтверждения";
        elements.listingStatusText.textContent = "Покупатель должен подтвердить сделку.";
      } else {
        elements.listingStatusTitle.textContent = "🕓 Ожидает подтверждения";
        elements.listingStatusText.textContent = "Подтвердите, что сделка состоялась.";
      }
    } else if (data.status === "hidden") {
      elements.listingStatus.hidden = false;
      if (isModeratorRole(data.hidden_by_role)) {
        elements.listingStatusTitle.textContent = "🛡 Объявление скрыто модератором";
        elements.listingStatusText.textContent = "После проверки модератор может вернуть объявление на рынок.";
      } else {
        elements.listingStatusTitle.textContent = "🙈 Объявление скрыто";
        elements.listingStatusText.textContent = "Вы скрыли объявление. Его можно вернуть в активные в профиле.";
      }
    } else if (data.status === "expired") {
      elements.listingStatus.hidden = false;
      elements.listingStatusTitle.textContent = "Срок публикации истёк";
      elements.listingStatusText.textContent = "Объявление скрыто с рынка. Продлить его на 30 дней за 50 M‑Coin можно в профиле: Объявления → Скрытые.";
    } else {
      elements.listingStatus.hidden = true;
    }
  }
  if (elements.listingDeal) {
    if (data.status === "awaiting_confirmation" && data.deal && data.deal.is_buyer && data.deal.status === "waiting") {
      elements.listingDeal.hidden = false;
      if (elements.dealConfirm) {
        elements.dealConfirm.textContent = "Подтвердить сделку";
      }
      if (elements.dealReject) {
        elements.dealReject.hidden = false;
      }
      if (elements.dealConfirm) {
        elements.dealConfirm.onclick = async () => {
          try {
            const result = await apiRequest(withAuth(`/api/listings/${data.id}/deal/confirm`), {
              method: "POST",
              body: JSON.stringify({}),
            });
            showDealConfirmResultToast(result, "✅ Сделка завершена");
            await loadListing(data.id, stateListing.backPage || "market");
          } catch (error) {
            if (error?.payload?.error === "pair_limit") {
              showToast(pairLimitMessage(error), "danger");
              return;
            }
            showToast("Не удалось подтвердить сделку.", "danger");
          }
        };
      }
      if (elements.dealReject) {
        elements.dealReject.onclick = async () => {
          await apiRequest(withAuth(`/api/listings/${data.id}/deal/reject`), {
            method: "POST",
            body: JSON.stringify({}),
          });
          showToast("❌ Сделка отменена", "danger");
          await loadListing(data.id, stateListing.backPage || "market");
        };
      }
    } else {
      elements.listingDeal.hidden = true;
      if (elements.dealReject) {
        elements.dealReject.hidden = false;
      }
    }
  }
  const canModerate = isModeratorRole(stateAdmin.role);
  const sellerTelegramId = Number(data?.seller?.telegram_id || 0) || null;
  const sellerDisplayName = String(data?.seller?.display_name || "").trim() || "Пользователь";
  const canOwnerManage = isSeller && data.status !== "deleted" && data.status !== "expired" && data.status !== "sold";
  let hasOwnerActions = false;
  let hasModerationActions = false;

  if (canOwnerManage) {
    if (elements.listingOwnerMenuSection) {
      elements.listingOwnerMenuSection.hidden = false;
    }
    if (elements.listingOwnerMenuSold && data.status === "active") {
      hasOwnerActions = true;
      elements.listingOwnerMenuSold.hidden = false;
      elements.listingOwnerMenuSold.onclick = () => {
        stateDeal.listingId = data.id;
        if (elements.dealBuyerNick) {
          elements.dealBuyerNick.value = "";
        }
        hideDealNickSuggest();
        if (elements.dealModal) {
          elements.dealModal.classList.add("show");
        }
        closeListingModerationMenu();
      };
    }
    if (elements.listingOwnerMenuHide && data.status === "active") {
      hasOwnerActions = true;
      elements.listingOwnerMenuHide.hidden = false;
      elements.listingOwnerMenuHide.onclick = () => {
        stateMyListings.statusId = data.id;
        stateMyListings.statusValue = "hidden";
        if (elements.statusTitle) elements.statusTitle.textContent = "Скрыть объявление?";
        if (elements.statusText) elements.statusText.textContent = "Оно исчезнет из рынка, но останется в профиле.";
        if (elements.statusConfirm) elements.statusConfirm.textContent = "Скрыть";
        if (elements.statusModal) elements.statusModal.classList.add("show");
        closeListingModerationMenu();
      };
    }
    if (elements.listingOwnerMenuRestore && data.status === "hidden" && !isModeratorRole(data.hidden_by_role)) {
      hasOwnerActions = true;
      elements.listingOwnerMenuRestore.hidden = false;
      elements.listingOwnerMenuRestore.onclick = () => {
        stateMyListings.statusId = data.id;
        stateMyListings.statusValue = "active";
        if (elements.statusTitle) elements.statusTitle.textContent = "Вернуть объявление в активные?";
        if (elements.statusText) elements.statusText.textContent = "Оно снова появится в рынке.";
        if (elements.statusConfirm) elements.statusConfirm.textContent = "Вернуть";
        if (elements.statusModal) elements.statusModal.classList.add("show");
        closeListingModerationMenu();
      };
    }
    if (elements.listingOwnerMenuEdit && (data.status === "active" || data.status === "rejected")) {
      hasOwnerActions = true;
      elements.listingOwnerMenuEdit.hidden = false;
      elements.listingOwnerMenuEdit.onclick = () => {
        startEditListing(data);
        closeListingModerationMenu();
      };
    }
    if (!hasOwnerActions && elements.listingOwnerMenuSection) {
      elements.listingOwnerMenuSection.hidden = true;
    }
  }

  if (canModerate) {
    if (elements.listingModerationMenuSection) {
      elements.listingModerationMenuSection.hidden = false;
    }
    if (elements.listingModerationRole) {
      if (isDeveloperRole(stateAdmin.role)) {
        elements.listingModerationRole.textContent = "Разработчик";
        elements.listingModerationRole.classList.add("developer");
      } else if (isCofounderRole(stateAdmin.role)) {
        elements.listingModerationRole.textContent = "Сооснователь";
        elements.listingModerationRole.classList.add("developer");
      } else if (isHeadModeratorRole(stateAdmin.role)) {
        elements.listingModerationRole.textContent = "Администратор";
        elements.listingModerationRole.classList.add("moderator");
      } else {
        elements.listingModerationRole.textContent = "Модератор";
        elements.listingModerationRole.classList.add("moderator");
      }
    }
    if (elements.listingModerationMenuHide && data.status === "active") {
      hasModerationActions = true;
      elements.listingModerationMenuHide.hidden = false;
      elements.listingModerationMenuHide.onclick = async () => {
        try {
          await apiRequest(withAuth(`/api/listings/${data.id}/moderation`), {
            method: "POST",
            body: JSON.stringify({ action: "hide" }),
          });
          showToast("Объявление скрыто", "success");
          await loadListing(data.id, stateListing.backPage || "market");
        } catch {
          showToast("Не удалось скрыть объявление", "danger");
        } finally {
          elements.listingModerationMenu.classList.remove("show");
        }
      };
    }
    if (elements.listingModerationMenuRestore && data.status === "hidden") {
      hasModerationActions = true;
      elements.listingModerationMenuRestore.hidden = false;
      elements.listingModerationMenuRestore.onclick = async () => {
        try {
          await apiRequest(withAuth(`/api/listings/${data.id}/moderation`), {
            method: "POST",
            body: JSON.stringify({ action: "restore" }),
          });
          showToast("Объявление возвращено", "success");
          await loadListing(data.id, stateListing.backPage || "market");
        } catch {
          showToast("Не удалось вернуть объявление", "danger");
        } finally {
          elements.listingModerationMenu.classList.remove("show");
        }
      };
    }
    if (elements.listingModerationMenuEdit && ["active", "pending", "rejected", "hidden"].includes(String(data.status || "").toLowerCase())) {
      hasModerationActions = true;
      elements.listingModerationMenuEdit.hidden = false;
      elements.listingModerationMenuEdit.onclick = () => {
        startEditListing(data, { scope: "moderation" });
        closeListingModerationMenu();
      };
    }
    if (elements.listingModerationMenuDelete && isDeveloperRole(stateAdmin.role)) {
      hasModerationActions = true;
      elements.listingModerationMenuDelete.hidden = false;
      elements.listingModerationMenuDelete.onclick = async () => {
        try {
          await apiRequest(withAuth(`/api/listings/${data.id}/moderation`), {
            method: "POST",
            body: JSON.stringify({ action: "delete" }),
          });
          showToast("Объявление удалено", "success");
          if (stateListing.backPage === "admin") {
            navigateTo("admin");
            await loadAdminListings();
          } else {
            navigateTo("market");
            await loadMarket();
          }
        } catch {
          showToast("Не удалось удалить объявление", "danger");
        } finally {
          elements.listingModerationMenu.classList.remove("show");
        }
      };
    }
    if (elements.listingModerationMenuRestrict && sellerTelegramId) {
      hasModerationActions = true;
      elements.listingModerationMenuRestrict.hidden = false;
      elements.listingModerationMenuRestrict.onclick = () => {
        openAdminRestrictionModal(sellerTelegramId, sellerDisplayName);
        closeListingModerationMenu();
      };
    }
    if (!hasModerationActions && elements.listingModerationMenuSection) {
      elements.listingModerationMenuSection.hidden = true;
    }
  }

  if (elements.listingOwnerDivider) {
    elements.listingOwnerDivider.hidden = !(hasOwnerActions && hasModerationActions);
  }
  if (elements.listingModerationMenuBtn) {
    elements.listingModerationMenuBtn.hidden = !(hasOwnerActions || hasModerationActions);
  }
  elements.listingDesc.textContent = data.description || "Описание не указано.";
  renderListingCatalogCard(data);
  elements.sellerName.textContent = data.seller.display_name || "—";
  if (elements.sellerAvatar) {
    const avatarUrl = data.seller.avatar_data || data.seller.avatar_url || "";
    setAvatarPreview(elements.sellerAvatar, avatarUrl, getInitials(data.seller.display_name || "—"));
  }
  applyProfileFrame(elements.sellerAvatar?.closest(".seller-avatar-wrap"), data.seller.cosmetics?.profile_frame || "");
  updateStaffBadge(elements.sellerStaff, data.seller.staff_role);
  loadSellerLevelPin(data.seller.telegram_id);
  const sellerLabelOverride = getOwnerDevLabelOverrideByTelegramId(data.seller.telegram_id, data.seller?.cosmetics?.label) || {};
	  applyCosmeticsToDisplay({
	    nameEl: elements.sellerName,
	    labelEl: elements.sellerBadge,
	    badgeEl: elements.sellerCosmeticBadge,
	    sellerCardEl: elements.sellerCard,
	    cosmetics: data.seller.cosmetics,
	    fallbackLabel: data.seller.rank || "Новичок",
      forceLabelText: sellerLabelOverride.text || "",
      forceLabelStyle: sellerLabelOverride.style || "",
	  });
  renderBadgeSlotsForContext({
    profile: data.seller,
    cosmetics: data.seller.cosmetics,
    fallbackLabel: data.seller.rank || "Новичок",
    forceLabelText: sellerLabelOverride.text || "",
    forceLabelStyle: sellerLabelOverride.style || "",
    mainEl: elements.sellerBadge,
    secondaryEl: elements.sellerRoleInline,
    territoryEl: null,
    vipEl: null,
  });
  // Hide territory and VIP badges in seller card
  if (elements.sellerFamilyInline) elements.sellerFamilyInline.classList.add("hidden");
  if (elements.sellerVipInline) elements.sellerVipInline.classList.add("hidden");
  if (elements.sellerSince) {
    const sellerDeals = Number(data.seller.closed_listings || data.seller.closed_deals || 0);
    renderCompactReputation(elements.sellerSince, sellerDeals);
  }
  if (elements.sellerProfile) {
    elements.sellerProfile.onclick = () => {
      loadPublicProfile(data.seller.telegram_id, "listing");
    };
  }
  // The whole seller block opens the profile (the separate "Профиль" button is hidden by CSS).
  const sellerMain = document.querySelector("#sellerCardWrap .seller-card-main");
  if (sellerMain) {
    sellerMain.onclick = () => {
      loadPublicProfile(data.seller.telegram_id, "listing");
    };
  }
  // "Пожаловаться" убрано из карточки продавца (остаётся только в публичном профиле).
  if (elements.sellerMessage) {
    elements.sellerMessage.textContent = "Написать продавцу";
    elements.sellerMessage.disabled = false;
    elements.sellerMessage.dataset.listingId = String(Number(data.id || 0) || "");
    elements.sellerMessage.onclick = () => {
      const activeListingId = Number(elements.sellerMessage.dataset.listingId || 0);
      if (!activeListingId) return;
      openDealChat(activeListingId);
    };
    elements.sellerMessage.onmousedown = (event) => {
      event.stopPropagation();
    };
  }
  if (elements.sellerContactSecondary) {
    elements.sellerContactSecondary.classList.add("hidden");
    elements.sellerContactSecondary.onclick = null;
  }
  if (elements.sellerContactIcons) {
    elements.sellerContactIcons.style.display = "none";
    const contactWrap = elements.sellerContactIcons.closest(".seller-contact");
    if (contactWrap) {
      contactWrap.classList.add("solo");
    }
  }
  if (elements.sellerProfile) {
    elements.sellerProfile.addEventListener("click", (event) => {
      event.stopPropagation();
    });
  }
  if (elements.listingReport) {
    elements.listingReport.addEventListener("click", (event) => {
      event.stopPropagation();
    });
  }
  if (listingHasImages) {
    loadListingImages(id, loadToken);
  } else {
    renderGallery([]);
  }
  } catch (error) {
    if (isAbortError(error)) return;
    throw error;
  } finally {
    if (listingLoadAbortController === controller) listingLoadAbortController = null;
    endUiLoading(loadingToken);
  }
}

async function loadListingImages(id, loadToken = listingLoadToken) {
  if (listingImagesAbortController) listingImagesAbortController.abort();
  const controller = new AbortController();
  listingImagesAbortController = controller;
  try {
    const data = await apiRequest(withAuth(`/api/listings/${id}/images`), {
      signal: controller.signal,
    });
    if (loadToken !== listingLoadToken || controller.signal.aborted || state.page !== "listing") return;
    renderGallery(listingGalleryImages(data));
  } catch (error) {
    if (isAbortError(error) || loadToken !== listingLoadToken || controller.signal.aborted) return;
    renderGallery([]);
  } finally {
    if (listingImagesAbortController === controller) listingImagesAbortController = null;
  }
}

// "02.2026" (month the person joined) -> "8 мес." / "1 г. 9 мес." — readable at a glance; the exact month stays in the tooltip.
function formatMarketSinceRu(text, now = new Date()) {
  const match = String(text || "").trim().match(/^(\d{1,2})\.(\d{4})$/);
  if (!match) return String(text || "—");
  const month = Number(match[1]);
  const year = Number(match[2]);
  if (month < 1 || month > 12) return String(text);
  const months = (now.getFullYear() - year) * 12 + (now.getMonth() + 1 - month);
  if (months < 1) return "< 1 мес.";
  if (months < 12) return `${months} мес.`;
  const years = Math.floor(months / 12);
  const rest = months % 12;
  return rest ? `${years} г. ${rest} мес.` : `${years} г.`;
}

function marketSinceTitleRu(text) {
  const match = String(text || "").trim().match(/^(\d{1,2})\.(\d{4})$/);
  if (!match) return "";
  const names = ["января", "февраля", "марта", "апреля", "мая", "июня", "июля", "августа", "сентября", "октября", "ноября", "декабря"];
  const month = Number(match[1]);
  return month >= 1 && month <= 12 ? `На рынке с ${names[month - 1]} ${match[2]}` : "";
}

function setMarketSinceValue(el, text) {
  if (!el) return;
  el.textContent = formatMarketSinceRu(text);
  const title = marketSinceTitleRu(text);
  if (title) el.title = title; else el.removeAttribute("title");
}

function formatRelativeRu(value) {
  const date = parseApiDate(value);
  if (!date) return "";
  const diffSec = Math.max(0, Math.floor((Date.now() - date.getTime()) / 1000));
  const plural = (n, one, few, many) => {
    const m10 = n % 10;
    const m100 = n % 100;
    if (m10 === 1 && m100 !== 11) return one;
    if (m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14)) return few;
    return many;
  };
  if (diffSec < 60) return "только что";
  const min = Math.floor(diffSec / 60);
  if (min < 60) return `${min} ${plural(min, "минуту", "минуты", "минут")} назад`;
  const hours = Math.floor(min / 60);
  if (hours < 24) return `${hours} ${plural(hours, "час", "часа", "часов")} назад`;
  const days = Math.floor(hours / 24);
  if (days < 7) return `${days} ${plural(days, "день", "дня", "дней")} назад`;
  if (days < 30) {
    const weeks = Math.floor(days / 7);
    return `${weeks} ${plural(weeks, "неделю", "недели", "недель")} назад`;
  }
  const months = Math.floor(days / 30);
  if (months < 12) return `${months} ${plural(months, "месяц", "месяца", "месяцев")} назад`;
  return formatDateTimeMsk(value).slice(0, 10);
}

// Listing page meta: server + category as chips, publish time as one quiet line (exact date on tap/hover).
function renderListingMeta(target, listing, options = {}) {
  if (!target) return;
  const server = Number(listing?.server_id);
  const chips = [];
  if (Number.isFinite(server) && server > 0) chips.push(`Сервер ${server}`);
  if (listing?.category) chips.push(String(listing.category));
  const chipsHtml = chips.map((text) => `<span class="listing-chip">${escapeHtmlText(text)}</span>`).join("");
  const relative = listing?.created_at ? formatRelativeRu(listing.created_at) : "";
  const exact = listing?.created_at ? formatDateTimeMsk(listing.created_at) : "";
  const idPart = options.showId && listing?.id ? ` • ID ${escapeHtmlText(String(listing.id))}` : "";
  const dateHtml = relative || idPart
    ? `<div class="listing-date" title="${escapeHtmlText(exact)}">${relative ? `Опубликовано ${escapeHtmlText(relative)}` : ""}${idPart}</div>`
    : "";
  target.innerHTML = chipsHtml || dateHtml ? `<div class="listing-chips">${chipsHtml}</div>${dateHtml}` : "";
}

function setListingTypeTag(item) {
  const tag = elements.listingTypeTag;
  if (!tag) return;
  const type = item?.listing_type === "buy" ? "buy" : item?.listing_type === "sell" ? "sell" : "";
  tag.textContent = type === "buy" ? "Куплю" : type === "sell" ? "Продам" : "";
  tag.dataset.type = type;
}

// Day separators in the dialog ("Сегодня" / "Вчера" / "14 апреля"), Moscow time like the rest of the chat.
function dealChatDayKey(value) {
  const dt = parseApiDate(value);
  if (!dt) return "";
  return dt.toLocaleDateString("en-CA", { timeZone: "Europe/Moscow" });
}

function dealChatDayLabel(value) {
  const key = dealChatDayKey(value);
  if (!key) return "";
  if (key === dealChatDayKey(new Date().toISOString())) return "Сегодня";
  if (key === dealChatDayKey(new Date(Date.now() - 86400000).toISOString())) return "Вчера";
  const dt = parseApiDate(value);
  const sameYear = key.slice(0, 4) === dealChatDayKey(new Date().toISOString()).slice(0, 4);
  return dt.toLocaleDateString("ru-RU", {
    timeZone: "Europe/Moscow",
    day: "numeric",
    month: "long",
    ...(sameYear ? {} : { year: "numeric" }),
  });
}

function formatDealChatTime(value) {
  if (!value) return "";
  try {
    const dt = parseApiDate(value);
    if (dt) {
      return dt.toLocaleTimeString("ru-RU", {
        timeZone: "Europe/Moscow",
        hour: "2-digit",
        minute: "2-digit",
        hour12: false,
      });
    }
  } catch {
    // ignore
  }
  return "";
}

function formatSupportCaseStatus(status) {
  const normalized = String(status || "").toLowerCase();
  if (normalized === "in_review") return "На рассмотрении";
  if (normalized === "accepted") return "Принято";
  if (normalized === "rejected") return "Отклонено";
  return "Открыт";
}

function isSupportCaseFinalStatus(status) {
  const normalized = String(status || "").toLowerCase();
  return normalized === "accepted" || normalized === "rejected";
}

// Until the first answer arrives we do not know whether the player already has a request: showing the "new request" UI
// (topics, «Создать обращение», "choose a topic") for a moment and then swapping it was the abrupt flash on entering.
function isSupportFirstLoad() {
  return Boolean(stateDealChat.supportMode && stateDealChat.loading && !stateDealChat.chat);
}

function renderSupportTopics() {
  if (!elements.dealChatSupportTopics) return;
  // the topic is only chosen before the request exists; afterwards it is shown inside the thread
  const shouldShowTopics = stateDealChat.supportMode && !stateDealChat.adminView && !stateDealChat.supportActiveThread
    && !isSupportFirstLoad();
  elements.dealChatSupportTopics.classList.toggle("hidden", !shouldShowTopics);
  if (!stateDealChat.supportMode) return;
  if (stateDealChat.adminView) return;
  const selected = String(stateDealChat.supportSelectedReason || "Другое");
  elements.dealChatSupportTopics.querySelectorAll("[data-support-reason]").forEach((btn) => {
    const reason = String(btn.dataset.supportReason || "");
    btn.classList.toggle("active", reason === selected);
  });
}

function renderSupportCaseControls() {
  if (!elements.dealChatSupportStatusWrap || !stateDealChat.supportMode) {
    if (elements.dealChatSupportStatusWrap) elements.dealChatSupportStatusWrap.classList.add("hidden");
    return;
  }
  if (isSupportFirstLoad()) {
    elements.dealChatSupportStatusWrap.classList.add("hidden");
    return;
  }
  const activeThread = stateDealChat.supportActiveThread || null;
  const lastClosedThread = stateDealChat.supportLastClosedThread || null;
  const complaintStatus = String(stateDealChat.chat?.complaint_status || "");
  const statusForView = complaintStatus || String(activeThread?.status || lastClosedThread?.status || "");
  const isResolved = isSupportCaseFinalStatus(statusForView);
  const statusText = formatSupportCaseStatus(statusForView || activeThread?.status || "");

  elements.dealChatSupportStatusWrap.classList.remove("hidden");
  const stepsEl = document.getElementById("dealChatSupportSteps");
  if (stepsEl) {
    const normalizedStatus = String(statusForView || activeThread?.status || "").toLowerCase();
    const stepIndex = isResolved ? 2 : normalizedStatus === "in_review" ? 1 : 0;
    stepsEl.hidden = !activeThread && !lastClosedThread;
    stepsEl.querySelectorAll("[data-step]").forEach((el) => {
      const index = Number(el.dataset.step);
      el.classList.toggle("is-done", index < stepIndex || (isResolved && index === 2));
      el.classList.toggle("is-current", index === stepIndex && !isResolved);
    });
  }
  if (elements.dealChatSupportStatusLabel) {
    elements.dealChatSupportStatusLabel.textContent = statusText;
    elements.dealChatSupportStatusLabel.classList.toggle("is-resolved", isResolved);
  }
  if (elements.dealChatSupportStatusNote) {
    const note = String(
      stateDealChat.chat?.complaint_resolution_note ||
      lastClosedThread?.resolution_note ||
      ""
    ).trim();
    const showNote = isResolved && Boolean(note);
    elements.dealChatSupportStatusNote.classList.toggle("hidden", !showNote);
    elements.dealChatSupportStatusNote.textContent = showNote ? `Причина: ${note}` : "";
  }
  if (elements.dealChatSupportCreate) {
    const showCreate = !stateDealChat.adminView && !activeThread && !lastClosedThread;
    elements.dealChatSupportCreate.classList.toggle("hidden", !showCreate);
    elements.dealChatSupportCreate.disabled = false;
  }
  if (elements.dealChatSupportOpenNew) {
    const showOpenNew = !stateDealChat.adminView && Boolean(lastClosedThread) && !activeThread;
    elements.dealChatSupportOpenNew.classList.toggle("hidden", !showOpenNew);
    elements.dealChatSupportOpenNew.disabled = false;
  }
}

function isDealChatNearBottom(threshold = 96) {
  const wrap = elements.dealChatMessages;
  if (!wrap) return true;
  return wrap.scrollHeight - wrap.scrollTop - wrap.clientHeight <= threshold;
}

function updateDealChatJumpBtn() {
  const btn = elements.dealChatJumpBtn;
  const wrap = elements.dealChatMessages;
  if (!btn || !wrap) return;
  const near = isDealChatNearBottom(140);
  if (near) stateDealChat.unreadBelow = 0;
  const unread = Number(stateDealChat.unreadBelow || 0);
  const hasMessages = Boolean(wrap.querySelector(".deal-chat-msg-row"));
  const show = hasMessages && !near;
  btn.hidden = !show;
  btn.classList.toggle("is-visible", show);
  if (elements.dealChatJumpBadge) {
    elements.dealChatJumpBadge.hidden = !(show && unread > 0);
    elements.dealChatJumpBadge.textContent = unread > 99 ? "99+" : String(unread);
  }
}

function scrollDealChatToBottom() {
  const wrap = elements.dealChatMessages;
  if (!wrap) return;
  const syncToBottom = () => {
    wrap.scrollTop = wrap.scrollHeight;
  };
  syncToBottom();
  requestAnimationFrame(syncToBottom);
}

function resolveDealChatCounterpartyUserId() {
  const chat = stateDealChat.chat || {};
  const listing = stateDealChat.listing || {};
  const isSeller = Boolean(chat.is_seller);
  const sellerId = Number(chat.seller_id || listing.seller_id || 0);
  const buyerId = Number(
    chat.buyer_id ||
    chat.counterparty_id ||
    chat.counterpart_id ||
    chat.counterparty?.telegram_id ||
    0,
  );
  if (isSeller) return buyerId > 0 ? buyerId : 0;
  if (sellerId > 0) return sellerId;
  return buyerId > 0 ? buyerId : 0;
}

function resolveDealChatMessageUserId(item) {
  const directId = Number(item?.sender_id || item?.telegram_id || item?.user_id || item?.author_id || 0);
  if (directId > 0) return directId;
  if (item?.is_me) {
    const myId = Number(state.tid || 0);
    return myId > 0 ? myId : 0;
  }
  return resolveDealChatCounterpartyUserId();
}

function openDealChatPublicProfile(userId) {
  const targetId = Number(userId || 0);
  if (!targetId) return;
  loadPublicProfile(targetId, "deal-chat");
}

function applyDealChatPrefill(prefill) {
  if (!prefill || typeof prefill !== "object") return;
  if (prefill.listing && typeof prefill.listing === "object") {
    stateDealChat.listing = { ...(stateDealChat.listing || {}), ...prefill.listing };
  }
  if (prefill.chat && typeof prefill.chat === "object") {
    stateDealChat.chat = { ...(stateDealChat.chat || {}), ...prefill.chat };
  }
  if (Array.isArray(prefill.messages)) {
    stateDealChat.messages = prefill.messages.slice();
  }
}

function compactDealChatText(value, maxLen = 110) {
  const text = String(value || "").replace(/\s+/g, " ").trim();
  if (!text) return "—";
  if (text.length <= maxLen) return text;
  return `${text.slice(0, maxLen - 1)}…`;
}

let dealChatMenuCloseTimer = null;

function closeDealChatMessageMenu() {
  const menu = elements.dealChatMessageMenu;
  if (!menu) return;
  stateDealChat.messageMenuTarget = null;
  if (menu.classList.contains("hidden")) return;
  const backdrop = elements.dealChatMessageMenuBackdrop;
  menu.classList.remove("is-open");
  if (backdrop) backdrop.classList.remove("is-open");
  clearTimeout(dealChatMenuCloseTimer);
  dealChatMenuCloseTimer = setTimeout(() => {
    menu.classList.add("hidden");
    if (backdrop) backdrop.classList.add("hidden");
  }, 180);
}

function openDealChatMessageMenu(anchorX, anchorY, item) {
  const menu = elements.dealChatMessageMenu;
  if (!menu || !item || item.is_system) return;
  if (stateDealChat.supportMode || stateDealChat.systemMode) return;
  if (state.page !== "deal-chat") return;
  clearTimeout(dealChatMenuCloseTimer);
  // The chat page has a transform, which turns position:fixed into "relative to the page" and shoved the menu off screen:
  // overlays live directly in <body> so the coordinates of the finger / cursor are viewport coordinates.
  [elements.dealChatMessageMenuBackdrop, menu, elements.serverDrawerBackdrop, elements.serverDrawer].forEach((node) => {
    if (node && node.parentElement !== document.body) document.body.appendChild(node);
  });
  stateDealChat.messageMenuTarget = item;
  stateDealChat.menuOpenedAt = Date.now();
  const isServer = Boolean(stateDealChat.serverRoomMode);
  const hasId = Number(item.id) > 0;
  const toggle = (el, visible) => el && el.classList.toggle("hidden", !visible);
  toggle(elements.dealChatMessageReactions, isServer && hasId);
  toggle(elements.dealChatMessageReportBtn, isServer && !item.is_me && hasId);
  toggle(elements.dealChatMessageDeleteBtn, isServer && hasId && Boolean(stateDealChat.chat?.can_moderate));
  toggle(elements.dealChatMessageCopyBtn, Boolean(String(item.message || "").trim()));
  const mine = Number(item.reactions?.mine || 0);
  elements.dealChatMessageReactions?.querySelectorAll(".dcmm-react").forEach((btn) => {
    btn.classList.toggle("is-mine", Number(btn.dataset.reaction) === mine);
  });
  const backdrop = elements.dealChatMessageMenuBackdrop;
  if (backdrop) backdrop.classList.remove("hidden");
  // the finger that held the message is still down / just lifted: for a moment the menu ignores touches,
  // otherwise the release lands on the item under it (it used to hit «Удалить» straight away)
  menu.classList.add("is-unarmed");
  clearTimeout(stateDealChat.menuArmTimer);
  stateDealChat.menuArmTimer = setTimeout(() => menu.classList.remove("is-unarmed"), 450);
  menu.classList.remove("hidden", "is-open");
  const menuWidth = menu.offsetWidth;   // layout size: unaffected by the opening scale animation
  const menuHeight = menu.offsetHeight;
  const vw = document.documentElement.clientWidth || window.innerWidth || 0;
  const vh = window.innerHeight || document.documentElement.clientHeight || 0;
  const padding = 10;
  const x = Math.min(Math.max(anchorX - menuWidth / 2, padding), Math.max(padding, vw - menuWidth - padding));
  const below = anchorY + 10 + menuHeight <= vh - padding;
  const y = Math.min(Math.max(below ? anchorY + 10 : anchorY - menuHeight - 10, padding), Math.max(padding, vh - menuHeight - padding));
  menu.style.left = `${x}px`;
  menu.style.top = `${y}px`;
  menu.style.setProperty("--menu-origin", `${Math.round(anchorX - x)}px ${below ? "0" : "100%"}`);
  requestAnimationFrame(() => {
    if (stateDealChat.messageMenuTarget !== item) return;
    menu.classList.add("is-open");
    if (backdrop) backdrop.classList.add("is-open");
  });
  try {
    window.Telegram?.WebApp?.HapticFeedback?.impactOccurred?.("light");
  } catch {
    // no haptics outside Telegram
  }
}

async function copyTextToClipboard(text) {
  const value = String(text || "");
  try {
    await navigator.clipboard.writeText(value);
    return true;
  } catch {
    // WebView without clipboard permission: legacy path
  }
  try {
    const area = document.createElement("textarea");
    area.value = value;
    area.setAttribute("readonly", "");
    area.style.cssText = "position:fixed;left:-9999px;top:0;opacity:0";
    document.body.appendChild(area);
    area.select();
    const ok = document.execCommand("copy");
    area.remove();
    return Boolean(ok);
  } catch {
    return false;
  }
}

function applyReactionToLocalMessage(messageId, counters) {
  const list = Array.isArray(stateDealChat.messages) ? stateDealChat.messages : [];
  const target = list.find((m) => Number(m?.id) === Number(messageId));
  if (!target) return false;
  target.reactions = { up: Number(counters.up || 0), down: Number(counters.down || 0), mine: Number(counters.mine || 0) };
  return true;
}

function buildReactionChips(item) {
  const reactions = item && item.reactions;
  if (!reactions || (Number(reactions.up) <= 0 && Number(reactions.down) <= 0)) return null;
  const chips = document.createElement("div");
  chips.className = "deal-chat-msg-reactions";
  [["1", "👍", Number(reactions.up || 0)], ["-1", "👎", Number(reactions.down || 0)]].forEach(([value, emoji, count]) => {
    if (count <= 0) return;
    const chip = document.createElement("button");
    chip.type = "button";
    chip.className = `deal-chat-msg-reaction${Number(reactions.mine || 0) === Number(value) ? " is-mine" : ""}`;
    chip.dataset.reaction = value;
    chip.textContent = `${emoji} ${count >= 1000 ? `${(count / 1000).toFixed(count >= 10000 ? 0 : 1).replace(".0", "")}k` : count}`;
    chip.addEventListener("click", (event) => {
      event.stopPropagation();
      reactToServerMessage(item, Number(value));
    });
    chips.appendChild(chip);
  });
  return chips.childElementCount ? chips : null;
}

// Updates only the reaction line of one message (no rebuild of the whole chat): no flicker, no scroll jump, a soft pop
function updateReactionFooterInDom(messageId) {
  const wrap = elements.dealChatMessages;
  const item = (stateDealChat.messages || []).find((m) => Number(m?.id) === Number(messageId));
  const row = wrap && item ? wrap.querySelector(`.deal-chat-msg-row[data-message-id="${Number(messageId)}"]`) : null;
  const bubble = row ? row.querySelector(".deal-chat-msg") : null;
  const meta = bubble ? bubble.querySelector(".deal-chat-msg-meta") : null;
  if (!bubble || !meta) {
    renderDealChatMessages();
    return;
  }
  const wasNearBottom = isDealChatNearBottom(140);
  let footer = bubble.querySelector(".deal-chat-msg-footer");
  const chips = buildReactionChips(item);
  if (chips) {
    chips.classList.add("is-pop");
    if (!footer) {
      footer = document.createElement("div");
      footer.className = "deal-chat-msg-footer";
      bubble.insertBefore(footer, meta);
      footer.appendChild(meta);
    } else {
      footer.querySelector(".deal-chat-msg-reactions")?.remove();
    }
    footer.insertBefore(chips, footer.firstChild);
  } else if (footer) {
    bubble.insertBefore(meta, footer);
    footer.remove();
  }
  if (wasNearBottom) scrollDealChatToBottom();
  updateDealChatJumpBtn();
}

async function reactToServerMessage(item, reaction) {
  const id = Number(item?.id || 0);
  if (!id || !stateDealChat.serverRoomMode) return;
  const before = { up: 0, down: 0, mine: 0, ...(item.reactions || {}) };
  const after = { ...before };
  // optimistic: the same reaction takes itself back, the other one replaces it
  if (before.mine === reaction) {
    after.mine = 0;
    after[reaction > 0 ? "up" : "down"] = Math.max(0, after[reaction > 0 ? "up" : "down"] - 1);
  } else {
    if (before.mine) after[before.mine > 0 ? "up" : "down"] = Math.max(0, after[before.mine > 0 ? "up" : "down"] - 1);
    after.mine = reaction;
    after[reaction > 0 ? "up" : "down"] += 1;
  }
  applyReactionToLocalMessage(id, after);
  updateReactionFooterInDom(id);
  try {
    const data = await apiRequest(withAuth("/api/chats/server/react"), {
      method: "POST",
      body: JSON.stringify({ message_id: id, reaction }),
    });
    applyReactionToLocalMessage(id, data || after);
  } catch (error) {
    applyReactionToLocalMessage(id, before);
    const code = String(error?.payload?.error || "");
    const softFail = code === "not_ready" || code === "rate_limited";
    showToast(code === "not_ready" ? "Реакции скоро заработают." : code === "rate_limited" ? "Не так часто." : "Не удалось поставить реакцию.", softFail ? "info" : "danger");
  }
  updateReactionFooterInDom(id);
}

// window.confirm is unreliable inside the Telegram WebView (it may answer «yes» without asking): own dialog
function confirmDialog(title, text, okLabel) {
  return new Promise((resolve) => {
    const overlay = document.createElement("div");
    overlay.className = "rp-confirm-overlay";
    overlay.innerHTML = '<div class="rp-confirm" role="alertdialog"><div class="rp-confirm-title"></div><div class="rp-confirm-text"></div>' +
      '<div class="rp-confirm-actions"><button type="button" class="rp-confirm-cancel">Отмена</button><button type="button" class="rp-confirm-ok"></button></div></div>';
    overlay.querySelector(".rp-confirm-title").textContent = title;
    overlay.querySelector(".rp-confirm-text").textContent = text;
    overlay.querySelector(".rp-confirm-ok").textContent = okLabel;
    const done = (value) => {
      overlay.classList.remove("is-open");
      setTimeout(() => overlay.remove(), 180);
      resolve(value);
    };
    overlay.querySelector(".rp-confirm-cancel").addEventListener("click", () => done(false));
    overlay.querySelector(".rp-confirm-ok").addEventListener("click", () => done(true));
    overlay.addEventListener("click", (event) => {
      if (event.target === overlay) done(false);
    });
    document.body.appendChild(overlay);
    requestAnimationFrame(() => overlay.classList.add("is-open"));
  });
}

async function deleteServerMessage(item) {
  const id = Number(item?.id || 0);
  if (!id) return;
  const confirmed = await confirmDialog("Удалить сообщение?", "Оно исчезнет у всех в чате сервера.", "Удалить");
  if (!confirmed) return;
  try {
    await apiRequest(withAuth("/api/chats/server/delete"), { method: "POST", body: JSON.stringify({ message_id: id }) });
    stateDealChat.messages = (stateDealChat.messages || []).filter((m) => Number(m?.id) !== id);
    renderDealChatMessages();
  } catch (error) {
    showToast(String(error?.payload?.error || "") === "not_allowed" ? "Удалять могут только модераторы." : "Не удалось удалить сообщение.", "danger");
  }
}

function clearDealChatReplyTarget() {
  stateDealChat.replyTarget = null;
  if (elements.dealChatReplyBar) elements.dealChatReplyBar.classList.add("hidden");
  if (elements.dealChatReplyName) elements.dealChatReplyName.textContent = "Ответ";
  if (elements.dealChatReplyText) elements.dealChatReplyText.textContent = "—";
}

function setDealChatReplyTarget(item) {
  if (!item || item.is_system) return;
  stateDealChat.replyTarget = {
    id: Number(item.id || item.message_id || 0) || 0,
    sender_name: String(item.sender_name || (item.is_me ? "Вы" : "Пользователь") || "").trim() || "Пользователь",
    message: compactDealChatText(item.message || ""),
  };
  if (!stateDealChat.replyTarget.id) return;
  if (elements.dealChatReplyBar) elements.dealChatReplyBar.classList.remove("hidden");
  if (elements.dealChatReplyName) elements.dealChatReplyName.textContent = stateDealChat.replyTarget.sender_name;
  if (elements.dealChatReplyText) elements.dealChatReplyText.textContent = stateDealChat.replyTarget.message;
  elements.dealChatInput?.focus();
}

function cancelDealChatLongPress() {
  if (stateDealChat.longPressTimer) {
    clearTimeout(stateDealChat.longPressTimer);
    stateDealChat.longPressTimer = null;
  }
  stateDealChat.longPressTouchId = null;
}

function attachDealChatMessageReplyGesture(targetEl, item) {
  if (!targetEl || !item || item.is_system) return;
  let startX = 0;
  let startY = 0;
  targetEl.addEventListener("contextmenu", (event) => {
    event.preventDefault();
    openDealChatMessageMenu(event.clientX, event.clientY, item);
  });
  targetEl.addEventListener("touchstart", (event) => {
    if (!event.touches || event.touches.length !== 1) return;
    const touch = event.touches[0];
    startX = touch.clientX;
    startY = touch.clientY;
    stateDealChat.longPressTouchId = touch.identifier;
    cancelDealChatLongPress();
    stateDealChat.longPressTouchId = touch.identifier;
    stateDealChat.longPressTimer = setTimeout(() => {
      stateDealChat.longPressTimer = null;
      openDealChatMessageMenu(touch.clientX, touch.clientY, item);
    }, 420);
  }, { passive: true });
  targetEl.addEventListener("touchmove", (event) => {
    if (!stateDealChat.longPressTimer) return;
    const touch = Array.from(event.touches || []).find((t) => t.identifier === stateDealChat.longPressTouchId);
    if (!touch) {
      cancelDealChatLongPress();
      return;
    }
    if (Math.abs(touch.clientX - startX) > 8 || Math.abs(touch.clientY - startY) > 8) {
      cancelDealChatLongPress();
    }
  }, { passive: true });
  targetEl.addEventListener("touchend", cancelDealChatLongPress, { passive: true });
  targetEl.addEventListener("touchcancel", cancelDealChatLongPress, { passive: true });
  // desktop: press and hold with the mouse works like the long tap (right click is handled above)
  let mouseTimer = null;
  const cancelMouseHold = () => {
    if (mouseTimer) clearTimeout(mouseTimer);
    mouseTimer = null;
  };
  targetEl.addEventListener("mousedown", (event) => {
    if (event.button !== 0 || event.target.closest("a, button")) return;
    const downX = event.clientX;
    const downY = event.clientY;
    cancelMouseHold();
    mouseTimer = setTimeout(() => {
      mouseTimer = null;
      openDealChatMessageMenu(downX, downY, item);
      // the release after the hold must not count as a click on the name / link under the cursor
      const swallow = (clickEvent) => {
        clickEvent.stopPropagation();
        clickEvent.preventDefault();
      };
      window.addEventListener("click", swallow, { capture: true, once: true });
      setTimeout(() => window.removeEventListener("click", swallow, { capture: true }), 600);
    }, 450);
    const move = (moveEvent) => {
      if (Math.abs(moveEvent.clientX - downX) > 6 || Math.abs(moveEvent.clientY - downY) > 6) cancelMouseHold();
    };
    window.addEventListener("mousemove", move, { passive: true });
    window.addEventListener("mouseup", () => {
      cancelMouseHold();
      window.removeEventListener("mousemove", move);
    }, { once: true });
  });
}

function buildSystemInboxMessagesFromNotifications(items) {
  const rows = Array.isArray(items) ? items : [];
  if (!rows.length) return [];
  return rows
    .slice()
    .sort((a, b) => {
      const aTs = parseApiDate(a?.created_at || a?.updated_at)?.getTime() || 0;
      const bTs = parseApiDate(b?.created_at || b?.updated_at)?.getTime() || 0;
      return aTs - bTs;
    })
    .map((item, index) => ({
      id: Number(item?.id || 0) || index + 1,
      is_system: false,
      is_me: false,
      sender_name: "RP Market",
      message: formatSystemNotificationMessage(item),
      created_at: item?.created_at || item?.updated_at || null,
    }));
}

function renderDealChatMessages() {
  if (!elements.dealChatMessages) return;
  const shouldStickToBottom = stateDealChat.forceScrollToBottom || isDealChatNearBottom();
  const prevCount = elements.dealChatMessages.querySelectorAll(".deal-chat-msg-row").length;
  const prevScrollTop = elements.dealChatMessages.scrollTop;
  elements.dealChatMessages.innerHTML = "";
  const messages = Array.isArray(stateDealChat.messages) ? stateDealChat.messages : [];
  if (shouldStickToBottom) {
    stateDealChat.unreadBelow = 0;
  } else if (prevCount > 0 && messages.length > prevCount && !stateDealChat.prependingOlder) {
    const fresh = messages.slice(prevCount).filter((m) => m && !m.is_me && !m.is_system).length;
    stateDealChat.unreadBelow = Number(stateDealChat.unreadBelow || 0) + fresh;
  }
  // Only animate new messages (skip stagger for already-seen ones)
  const animateFrom = stateDealChat.prependingOlder ? messages.length : (prevCount > 0 ? prevCount : 0);
  if (!messages.length) {
    const empty = document.createElement("div");
    empty.className = "deal-chat-empty";
    if (stateDealChat.loading) {
      empty.textContent = "Загрузка сообщений...";
    } else if (stateDealChat.supportMode) {
      const hasThread = Boolean(Number(stateDealChat.supportComplaintId || stateDealChat.chat?.complaint_id || 0));
      empty.textContent = hasThread
        ? "Сообщений пока нет. Модератор ответит в этом диалоге."
        : "Выберите тему и создайте обращение. После этого сообщения появятся здесь.";
    } else if (stateDealChat.systemMode) {
      empty.textContent = "Пока нет системных сообщений от RP Market.";
    } else if (stateDealChat.serverRoomMode) {
      empty.textContent = "Пока пусто. Начните общение в серверной комнате.";
    } else {
      empty.textContent = "Пока нет сообщений. Начните диалог по сделке.";
    }
    elements.dealChatMessages.appendChild(empty);
    if (shouldStickToBottom) scrollDealChatToBottom();
    stateDealChat.forceScrollToBottom = false;
    updateDealChatJumpBtn();
    return;
  }
  let lastDayKey = "";
  messages.forEach((item, msgIndex) => {
    const dayKey = dealChatDayKey(item.created_at);
    if (dayKey && dayKey !== lastDayKey) {
      lastDayKey = dayKey;
      const dayEl = document.createElement("div");
      dayEl.className = "deal-chat-day";
      dayEl.textContent = dealChatDayLabel(item.created_at);
      elements.dealChatMessages.appendChild(dayEl);
    }
    const isSystem = Boolean(item.is_system);
    const isMe = !isSystem && Boolean(item.is_me);
    // last bubble of a same-sender run gets the "tail" (Telegram-style grouping)
    const nextItem = messages[msgIndex + 1];
    const isTail = !isSystem && !(
      nextItem &&
      !nextItem.is_system &&
      Boolean(nextItem.is_me) === isMe &&
      String(nextItem.sender_name || "") === String(item.sender_name || "") &&
      dealChatDayKey(nextItem.created_at) === dayKey
    );
    const showReadReceipt = isMe && !isSystem && !stateDealChat.supportMode && !stateDealChat.serverRoomMode && !stateDealChat.systemMode;

    // Row wrapper (controls left/right/center alignment)
    const row = document.createElement("div");
    row.className = `deal-chat-msg-row${isSystem ? " is-system" : isMe ? " is-me" : ""}${isTail ? " is-tail" : ""}`;
    if (Number(item.id) > 0) row.dataset.messageId = String(item.id);
    // Animate only genuinely new messages (not on polling re-render)
    if (msgIndex >= animateFrom && animateFrom < messages.length) {
      row.classList.add("anim-in");
      row.style.setProperty("--msg-i", String(msgIndex - animateFrom));
    }

    // Avatar for incoming messages (first letter fallback)
    if (!isMe && !isSystem) {
      const ava = document.createElement("div");
      ava.className = "deal-chat-msg-ava";
      const senderAvatar =
        String(item.sender_avatar_data || "").trim() ||
        String(item.sender_avatar_url || "").trim() ||
        "";
      if (stateDealChat.systemMode) {
        ava.classList.add("deal-chat-msg-ava--market");
      } else {
        setAvatarPreview(ava, senderAvatar, (item.sender_name || "?").charAt(0).toUpperCase());
      }
      const avatarUserId = resolveDealChatMessageUserId(item);
      if (avatarUserId > 0 && !stateDealChat.systemMode && !stateDealChat.supportMode) {
        // the avatar opens the profile, like the name above the message
        ava.classList.add("is-link");
        ava.setAttribute("role", "button");
        ava.setAttribute("tabindex", "0");
        ava.setAttribute("aria-label", `Профиль: ${item.sender_name || "пользователь"}`);
        ava.addEventListener("click", () => openDealChatPublicProfile(avatarUserId));
        ava.addEventListener("keydown", (event) => {
          if (event.key !== "Enter" && event.key !== " ") return;
          event.preventDefault();
          openDealChatPublicProfile(avatarUserId);
        });
      }
      if (stateDealChat.serverRoomMode) {
        // level on the avatar (a ::after, so the avatar loader replacing its content cannot wipe it)
        ava.classList.add("deal-chat-msg-ava--lg");
        const senderLevel = Number(item.sender_level || 0);
        if (senderLevel > 0) {
          ava.dataset.level = String(senderLevel);
          ava.dataset.tier = senderLevel >= 80 ? "gold" : senderLevel >= 50 ? "violet" : senderLevel >= 20 ? "teal" : "base";
        }
      }
      row.appendChild(ava);
    }

    // Bubble
    const bubble = document.createElement("div");
    bubble.className = `deal-chat-msg${isSystem ? " is-system" : isMe ? " is-me" : ""}${isTail ? " is-tail" : ""}`;

    // Sender name above bubble for incoming only; not in a 1:1 deal chat (the name is already in the header)
    const isDirectDealChat = !stateDealChat.supportMode && !stateDealChat.systemMode && !stateDealChat.serverRoomMode;
    if (!isMe && !isSystem && item.sender_name && !isDirectDealChat) {
      const sender = document.createElement("div");
      sender.className = "deal-chat-msg-sender";
      sender.textContent = item.sender_name;
      const staffLabel = stateDealChat.serverRoomMode ? getStaffRoleLabel(item.sender_staff_role) : "";
      if (staffLabel) {
        const staffChip = document.createElement("span");
        staffChip.className = "deal-chat-msg-staff";
        staffChip.dataset.role = normalizeStaffRoleKey(item.sender_staff_role);
        staffChip.textContent = staffLabel;
        sender.appendChild(staffChip);
      }
      const senderUserId = resolveDealChatMessageUserId(item);
      if (senderUserId > 0) {
        sender.classList.add("is-link");
        sender.setAttribute("role", "button");
        sender.setAttribute("tabindex", "0");
        sender.addEventListener("click", () => {
          openDealChatPublicProfile(senderUserId);
        });
        sender.addEventListener("keydown", (event) => {
          if (event.key !== "Enter" && event.key !== " ") return;
          event.preventDefault();
          openDealChatPublicProfile(senderUserId);
        });
      }
      bubble.appendChild(sender);
    }

    const replyItem = item?.reply_to_message && typeof item.reply_to_message === "object"
      ? item.reply_to_message
      : null;
    if (replyItem && !isSystem) {
      const replyWrap = document.createElement("div");
      replyWrap.className = "deal-chat-msg-reply";
      const replyName = document.createElement("div");
      replyName.className = "deal-chat-msg-reply-name";
      replyName.textContent = String(replyItem.sender_name || "Сообщение").trim() || "Сообщение";
      const replyText = document.createElement("div");
      replyText.className = "deal-chat-msg-reply-text";
      replyText.textContent = compactDealChatText(replyItem.message || "");
      replyWrap.append(replyName, replyText);
      bubble.appendChild(replyWrap);
    }

    const text = document.createElement("div");
    text.className = "deal-chat-msg-text";
    text.textContent = item.message || "";

    const meta = document.createElement("div");
    meta.className = "deal-chat-msg-meta";
    if (item.local_pending) {
      meta.textContent = "Отправка...";
    } else {
      const time = document.createElement("span");
      time.className = "deal-chat-msg-time";
      time.textContent = formatDealChatTime(item.created_at);
      meta.appendChild(time);
      if (showReadReceipt) {
        const status = document.createElement("span");
        const deliveryStatus = String(item.delivery_status || "sent").toLowerCase() === "read" ? "read" : "sent";
        status.className = `deal-chat-msg-status deal-chat-msg-status--${deliveryStatus}`;
        status.innerHTML = deliveryStatus === "read"
          ? '<svg viewBox="0 0 18 12" aria-hidden="true"><path d="M1 6.5l3.2 3.2L10.6 2.3M7.2 8.4l1.5 1.5L15.2 2.3" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>'
          : '<svg viewBox="0 0 18 12" aria-hidden="true"><path d="M3 6.5l3.2 3.2L12.6 2.3" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';
        status.setAttribute("aria-label", deliveryStatus === "read" ? "Прочитано" : "Отправлено");
        meta.appendChild(status);
      }
    }

    bubble.append(item.listing_card ? buildListingCardEl(item.listing_card) : item.duel_card ? buildDuelCardEl(item) : text);
    const reactionChips = stateDealChat.serverRoomMode ? buildReactionChips(item) : null;
    if (reactionChips) {
      // Telegram layout: reactions on the left, time on the right of the same line (no extra empty row)
      const footer = document.createElement("div");
      footer.className = "deal-chat-msg-footer";
      footer.append(reactionChips, meta);
      bubble.appendChild(footer);
    } else {
      bubble.appendChild(meta);
    }
    attachDealChatMessageReplyGesture(bubble, item);
    row.appendChild(bubble);
    elements.dealChatMessages.appendChild(row);
  });
  if (shouldStickToBottom) {
    scrollDealChatToBottom();
  } else {
    elements.dealChatMessages.scrollTop = prevScrollTop;
  }
  stateDealChat.forceScrollToBottom = false;
  updateDealChatJumpBtn();
}

function buildDealChatRenderKey(chat, messages, extra = "") {
  const rows = Array.isArray(messages) ? messages : [];
  const last = rows.length ? rows[rows.length - 1] : null;
  const lastId = Number(last?.id || last?.message_id || 0) || 0;
  const lastAt = String(last?.created_at || "");
  const lastText = String(last?.message || "").trim().slice(0, 80);
  const lastReplyId = Number(last?.reply_to_message?.id || last?.reply_to_message_id || 0) || 0;
  const peerLastReadId = Number(chat?.peer_last_read_message_id || 0) || 0;
  const status =
    String(
      chat?.complaint_status ||
      chat?.status ||
      ""
    ).toLowerCase();
  return [status, rows.length, lastId, lastAt, lastText, lastReplyId, peerLastReadId, extra].join("|");
}

function renderDealChatHeader() {
  const chat = stateDealChat.chat || {};
  const listing = stateDealChat.listing || {};
  const roomServerId = Number(chat.server_id || listing.server_id || 0);
  const roomTitle = String(chat.room_title || listing.title || "").trim();
  const roomLabel = roomTitle || "Общение";
  if (elements.dealChatCounterparty) elements.dealChatCounterparty.style.display = stateDealChat.serverRoomMode ? "none" : "";
  // server chat: Telegram-like header — avatar on the left, the name centred
  elements.dealChatAvatar?.closest(".deal-chat-header")?.classList.toggle("deal-chat-header--server", Boolean(stateDealChat.serverRoomMode));
  if (elements.dealChatServerSwitch) {
    const canSwitch = Boolean(stateDealChat.serverRoomMode && stateDealChat.chat?.can_moderate);
    elements.dealChatServerSwitch.classList.toggle("hidden", !canSwitch);
    if (canSwitch && elements.dealChatServerSwitchNum) {
      elements.dealChatServerSwitchNum.textContent = String(roomServerId || "").padStart(2, "0");
    }
  }
  const isSeller = Boolean(chat.is_seller);
  const sellerName = String(chat.seller_name || "").trim();
  const counterpartyName = String(chat.counterparty_name || "").trim();
  const displayName = isSeller ? counterpartyName : (sellerName || counterpartyName);
  const counterpartyOnline = Boolean(chat.counterparty_online);

  const setAvatarOnlineState = (isOnline) => {
    const avatar = elements.dealChatAvatar;
    if (!avatar) return;
    let dot = avatar.querySelector(".deal-chat-avatar-online-dot");
    if (!dot) {
      dot = document.createElement("span");
      dot.className = "deal-chat-avatar-online-dot";
      avatar.appendChild(dot);
    }
    avatar.classList.toggle("deal-chat-avatar--online", Boolean(isOnline));
    dot.classList.toggle("is-visible", Boolean(isOnline));
  };

  // Title: counterparty name (Telegram-style — shows who you're chatting with)
  if (elements.dealChatTitle) {
    if (stateDealChat.supportMode && stateDealChat.adminView) {
      elements.dealChatTitle.textContent = String(chat.counterparty_name || "Пользователь");
    } else if (stateDealChat.supportMode) {
      elements.dealChatTitle.textContent = "Поддержка RP Market";
    } else if (stateDealChat.systemMode) {
      elements.dealChatTitle.textContent = "RP Market";
    } else if (stateDealChat.serverRoomMode) {
      elements.dealChatTitle.textContent = roomLabel;
    } else {
      elements.dealChatTitle.textContent = displayName || (stateDealChat.loading ? "Загрузка..." : "—");
    }
    const titleTargetUserId = stateDealChat.supportMode && stateDealChat.adminView
      ? Number(chat.reporter_id || 0)
      : stateDealChat.supportMode || stateDealChat.systemMode || stateDealChat.serverRoomMode
        ? 0
        : resolveDealChatCounterpartyUserId();
    elements.dealChatTitle.classList.toggle("is-link", titleTargetUserId > 0);
    if (titleTargetUserId > 0) {
      elements.dealChatTitle.setAttribute("role", "button");
      elements.dealChatTitle.setAttribute("tabindex", "0");
      elements.dealChatTitle.onclick = () => {
        openDealChatPublicProfile(titleTargetUserId);
      };
      elements.dealChatTitle.onkeydown = (event) => {
        if (event.key !== "Enter" && event.key !== " ") return;
        event.preventDefault();
        openDealChatPublicProfile(titleTargetUserId);
      };
    } else {
      elements.dealChatTitle.removeAttribute("role");
      elements.dealChatTitle.removeAttribute("tabindex");
      elements.dealChatTitle.onclick = null;
      elements.dealChatTitle.onkeydown = null;
    }
  }

  // Subtitle: role
  if (elements.dealChatCounterparty) {
    if (stateDealChat.supportMode && stateDealChat.adminView) {
      const thread = stateDealChat.supportActiveThread || {};
      const reason = String(thread.reason || "").trim();
      elements.dealChatCounterparty.textContent = `Обращение #${Number(chat.complaint_id || thread.complaint_id || 0) || "—"}${reason ? ` · ${reason}` : ""}`;
    } else if (stateDealChat.supportMode) {
      elements.dealChatCounterparty.textContent = "служба поддержки";
    } else if (stateDealChat.systemMode) {
      elements.dealChatCounterparty.textContent = "официальный аккаунт";
    } else if (stateDealChat.serverRoomMode) {
      elements.dealChatCounterparty.textContent = "";  // the server number is on the cover; no extra line under the name
    } else {
      // Messages already on screen (cache / refresh): show the person's status, not "loading".
      const hasMessages = Array.isArray(stateDealChat.messages) && stateDealChat.messages.length > 0;
      elements.dealChatCounterparty.textContent = stateDealChat.loading && !hasMessages
        ? "загрузка диалога"
        : (counterpartyOnline ? "в сети" : "не в сети");
    }
    elements.dealChatCounterparty.classList.toggle(
      "deal-chat-counterparty--online",
      Boolean(counterpartyOnline) && !stateDealChat.supportMode && !stateDealChat.systemMode && !stateDealChat.serverRoomMode
    );
  }

  // Pinned listing info (dealChatMeta is now inside pinned block)
  if (elements.dealChatMeta) {
    if (stateDealChat.supportMode) {
      elements.dealChatMeta.textContent = "Жалобы • Ответы модерации";
    } else if (stateDealChat.systemMode) {
      elements.dealChatMeta.textContent = "Системные сообщения";
    } else if (stateDealChat.serverRoomMode) {
      const statusLabel = String(chat.member_role || "").toLowerCase() === "moderator" ? "Модерация" : "Общий чат";
      elements.dealChatMeta.textContent = roomServerId > 0
        ? `Сервер ${String(roomServerId).padStart(2, "0")} • ${statusLabel}`
        : "Серверная комната";
    } else {
      const title = listing.title || "—";
      const priceText = listing.price != null ? `${formatPrice(listing.price)} ₽` : "";
      elements.dealChatMeta.textContent = priceText ? `${title} • ${priceText}` : title;
    }
  }

  // Pinned block visibility (hide for support/system modes)
  const pinnedEl = document.getElementById("dealChatPinned");
  if (pinnedEl) {
    pinnedEl.classList.toggle("hidden", Boolean(stateDealChat.supportMode || stateDealChat.systemMode || stateDealChat.serverRoomMode));
  }

  // Avatar
  if (elements.dealChatAvatarImg && elements.dealChatAvatarFallback) {
    const isSupportLike = stateDealChat.supportMode || stateDealChat.systemMode || stateDealChat.serverRoomMode;
    if (!stateDealChat.serverRoomMode) {
      // the server-room icon used to stay in the avatar after leaving a server chat (only the plain-chat branch cleaned it up)
      elements.dealChatAvatar?.querySelector(".deal-chat-avatar-server-svg")?.remove();
      elements.dealChatAvatar?.classList.remove("deal-chat-avatar--server");
    }
    elements.dealChatAvatar?.classList.toggle("deal-chat-avatar--support", isSupportLike);
    elements.dealChatAvatar?.classList.toggle("deal-chat-avatar--market", Boolean(stateDealChat.systemMode));
    document.querySelector(".page-deal-chat")?.classList.toggle("deal-chat--support", Boolean(stateDealChat.supportMode));
    if (stateDealChat.supportMode && stateDealChat.adminView) {
      // the moderator talks to a player: show the player, not the support logo
      setAvatarOnlineState(false);
      const playerName = String(chat.counterparty_name || "Пользователь");
      elements.dealChatAvatar?.classList.remove("deal-chat-avatar--support");
      elements.dealChatAvatarImg.removeAttribute("src");
      elements.dealChatAvatarImg.hidden = true;
      elements.dealChatAvatarFallback.hidden = false;
      elements.dealChatAvatarFallback.textContent = (playerName.charAt(0) || "?").toUpperCase();
      if (elements.dealChatAvatar) elements.dealChatAvatar.style.backgroundColor = typeof _convAvatarColor === "function" ? _convAvatarColor(playerName) : "";
      return;
    }
    if (stateDealChat.supportMode) {
      setAvatarOnlineState(false);
      if (elements.dealChatAvatar) elements.dealChatAvatar.style.backgroundColor = "";
      elements.dealChatAvatarImg.src = "/assets/support-agent.svg";
      elements.dealChatAvatarImg.classList.remove("deal-chat-avatar-img--cover");
      elements.dealChatAvatarImg.hidden = false;
      elements.dealChatAvatarFallback.hidden = true;
      return;
    }
    if (stateDealChat.systemMode) {
      setAvatarOnlineState(false);
      elements.dealChatAvatarImg.src = "/assets/logo/market-cart.png";
      elements.dealChatAvatarImg.classList.add("deal-chat-avatar-img--cover");
      elements.dealChatAvatarImg.hidden = false;
      elements.dealChatAvatarFallback.hidden = true;
      return;
    }
    if (stateDealChat.serverRoomMode) {
      setAvatarOnlineState(false);
      elements.dealChatAvatarImg.removeAttribute("src");
      elements.dealChatAvatarImg.classList.remove("deal-chat-avatar-img--cover");
      elements.dealChatAvatarImg.hidden = true;
      elements.dealChatAvatarFallback.hidden = true;
      elements.dealChatAvatar.classList.add("deal-chat-avatar--server");
      // per-server cover (hue + number), rebuilt only when the server changes
      let coverEl = elements.dealChatAvatar.querySelector(".deal-chat-avatar-server-svg");
      if (!coverEl) {
        coverEl = document.createElement("span");
        coverEl.className = "deal-chat-avatar-server-svg";
        elements.dealChatAvatar.appendChild(coverEl);
      }
      if (coverEl.dataset.serverId !== String(roomServerId)) {
        coverEl.dataset.serverId = String(roomServerId);
        applyServerCover(coverEl, roomServerId);
        elements.dealChatAvatar.style.setProperty("--server-hue", String(serverCoverHue(roomServerId)));
      }
      return;
    }
    // Clean up server SVG if switching away from server mode
    const oldServerSvg = elements.dealChatAvatar?.querySelector(".deal-chat-avatar-server-svg");
    if (oldServerSvg) oldServerSvg.remove();
    elements.dealChatAvatar?.classList.remove("deal-chat-avatar--server");
    setAvatarOnlineState(counterpartyOnline);
    const dealAvatarSource =
      String(
        (
          isSeller
            ? (chat.counterparty_avatar_data || chat.counterparty_avatar_url || "")
            : (chat.seller_avatar_data || chat.seller_avatar_url || chat.counterparty_avatar_data || chat.counterparty_avatar_url || "")
        ) || ""
      ).trim();
    if (dealAvatarSource) {
      const isAndroidAvatarClient = String(window.Telegram?.WebApp?.platform || "").toLowerCase().includes("android")
        || String(navigator.userAgent || "").toLowerCase().includes("android");
      const resolvedDealAvatarSource = (
        isAndroidAvatarClient && /^https?:\/\//i.test(dealAvatarSource)
          ? `/api/avatar?url=${encodeURIComponent(dealAvatarSource)}`
          : dealAvatarSource
      );
      elements.dealChatAvatarImg.referrerPolicy = "no-referrer";
      elements.dealChatAvatarImg.src = resolvedDealAvatarSource;
      elements.dealChatAvatarImg.classList.remove("deal-chat-avatar-img--cover");
      elements.dealChatAvatarImg.hidden = false;
      elements.dealChatAvatarFallback.hidden = true;
      return;
    }
    // Deal mode fallback: show first letter of counterparty name
    elements.dealChatAvatarImg.removeAttribute("src");
    elements.dealChatAvatarImg.classList.remove("deal-chat-avatar-img--cover");
    elements.dealChatAvatarImg.hidden = true;
    elements.dealChatAvatarFallback.hidden = false;
    elements.dealChatAvatarFallback.textContent = (displayName || "?").charAt(0).toUpperCase();
  }
}

function setDealChatTypingState(isTyping) {
  const page = elements.dealChatModal?.querySelector(".deal-chat-page");
  if (!page) return;
  page.classList.toggle("deal-chat-page--typing", Boolean(isTyping));
}

async function ensureDealChatPreviewImage() {
  if (stateDealChat.supportMode || stateDealChat.systemMode || stateDealChat.serverRoomMode || !stateDealChat.listingId) {
    stateDealChat.previewImage = "";
    stateDealChat.previewImageListingId = 0;
    return;
  }
  const listingId = Number(stateDealChat.listingId || 0);
  if (!listingId) return;
  if (stateDealChat.previewImageListingId === listingId) return;
  stateDealChat.previewImage = "";
  stateDealChat.previewImageListingId = listingId;
  try {
    const data = await apiRequest(withAuth(`/api/listings/${listingId}/preview`));
    stateDealChat.previewImage = String(data?.image || "");
  } catch {
    stateDealChat.previewImage = "";
  }
}

function renderDealChatActions() {
  if (!stateDealChat.serverRoomMode) {
    elements.dealChatAttach?.classList.add("hidden");
    elements.dealChatInput?.closest(".deal-chat-compose")?.classList.remove("deal-chat-compose--attach");
  }
  const chat = stateDealChat.chat || {};
  const activeThread = stateDealChat.supportActiveThread || null;
  const interactionLocked = Boolean(stateDealChat.loading || stateDealChat.sending);
  const actionsWrap =
    (elements.dealChatAgree && elements.dealChatAgree.closest(".deal-chat-actions")) ||
    (elements.dealChatConfirm && elements.dealChatConfirm.closest(".deal-chat-actions")) ||
    (elements.dealChatCancel && elements.dealChatCancel.closest(".deal-chat-actions"));
  const isClosed = ["expired", "cancelled", "confirmed"].includes(String(chat.status || ""));
  const canAgree = Boolean(chat.can_agree) && !isClosed;
  const canConfirm = Boolean(chat.can_confirm) && !isClosed;
  const canCancel = Boolean(chat.can_cancel) && !isClosed;
  const isSeller = Boolean(chat.is_seller);
  const proposalById = Number(chat.proposal_by_id || 0);
  const sellerId = Number(chat.seller_id || 0);
  const proposalBySeller = proposalById > 0 && proposalById === sellerId;
  const setActionVisible = (element, visible) => {
    if (!element) return;
    element.classList.toggle("hidden", !visible);
    element.hidden = !visible;
  };

  if (!stateDealChat.supportMode) {
    const staleBar = document.getElementById("dealChatSupportAdminBar");
    const staleTemplates = document.getElementById("dealChatAdminTemplates");
    if (staleBar) staleBar.hidden = true;
    if (staleTemplates) staleTemplates.hidden = true;
  }
  if (stateDealChat.supportMode) {
    renderSupportTopics();
    renderSupportCaseControls();
    if (elements.dealChatAgree) setActionVisible(elements.dealChatAgree, false);
    if (elements.dealChatConfirm) setActionVisible(elements.dealChatConfirm, false);
    if (elements.dealChatCancel) setActionVisible(elements.dealChatCancel, false);
    if (elements.dealChatReport) setActionVisible(elements.dealChatReport, false);
    const supportThreadId = Number(
      stateDealChat.supportComplaintId || chat?.complaint_id || activeThread?.complaint_id || 0
    );
    const hasThread = Boolean(supportThreadId);
    const effectiveStatus = String(chat?.complaint_status || activeThread?.status || "");
    const canSendSupport = hasThread && !isSupportCaseFinalStatus(effectiveStatus);
    if (elements.dealChatInput) {
      elements.dealChatInput.disabled = !canSendSupport || interactionLocked;
      elements.dealChatInput.placeholder = isSupportFirstLoad()
        ? "Загрузка…"
        : canSendSupport
          ? (stateDealChat.adminView ? "Напишите ответ пользователю..." : "Напишите сообщение для модерации...")
          : "Выберите тему и нажмите «Создать обращение».";
    }
    if (elements.dealChatSend) {
      elements.dealChatSend.disabled = !canSendSupport || interactionLocked;
    }
    const adminBar = document.getElementById("dealChatSupportAdminBar");
    const adminTemplates = document.getElementById("dealChatAdminTemplates");
    const isAdminSupport = Boolean(stateDealChat.adminView);
    if (adminBar) {
      adminBar.hidden = !isAdminSupport || !hasThread;
      const resolveBtn = document.getElementById("dealChatAdminResolve");
      const rejectBtn = document.getElementById("dealChatAdminReject");
      const closed = isSupportCaseFinalStatus(effectiveStatus);
      if (resolveBtn) resolveBtn.disabled = closed || interactionLocked;
      if (rejectBtn) rejectBtn.disabled = closed || interactionLocked;
    }
    if (adminTemplates) {
      adminTemplates.hidden = !isAdminSupport || !canSendSupport;
      if (isAdminSupport && canSendSupport && !adminTemplates.childElementCount) {
        [
          ["Проверяем", "Спасибо за обращение, уже разбираемся. Ответим, как только будет результат."],
          ["Нужны детали", "Опишите, пожалуйста, подробнее, что произошло, и пришлите скриншоты, если есть."],
          ["Исправили", "Мы всё исправили. Проверьте, пожалуйста, и напишите, если что-то осталось."],
          ["Не наш случай", "К сожалению, мы не можем помочь с этим вопросом: он не относится к работе RP Market."],
        ].forEach(([label, text]) => {
          const chip = document.createElement("button");
          chip.type = "button";
          chip.className = "admin-reply-template";
          chip.textContent = label;
          chip.addEventListener("click", () => {
            if (!elements.dealChatInput) return;
            elements.dealChatInput.value = text;
            elements.dealChatInput.dispatchEvent(new Event("input", { bubbles: true }));
            elements.dealChatInput.focus();
          });
          adminTemplates.appendChild(chip);
        });
      }
    }
    if (!canSendSupport) clearDealChatReplyTarget();
    if (!canSendSupport) setDealChatTypingState(false);
    if (actionsWrap) {
      actionsWrap.style.gridTemplateColumns = "repeat(3, minmax(0, 1fr))";
    }
    return;
  }
  if (stateDealChat.systemMode) {
    clearDealChatReplyTarget();
    if (elements.dealChatSupportStatusWrap) elements.dealChatSupportStatusWrap.classList.add("hidden");
    if (elements.dealChatSupportTopics) elements.dealChatSupportTopics.classList.add("hidden");
    if (elements.dealChatSupportCreate) elements.dealChatSupportCreate.classList.add("hidden");
    if (elements.dealChatSupportOpenNew) elements.dealChatSupportOpenNew.classList.add("hidden");
    if (elements.dealChatReport) setActionVisible(elements.dealChatReport, false);
    if (elements.dealChatAgree) setActionVisible(elements.dealChatAgree, false);
    if (elements.dealChatConfirm) setActionVisible(elements.dealChatConfirm, false);
    if (elements.dealChatCancel) setActionVisible(elements.dealChatCancel, false);
    if (elements.dealChatInput) {
      elements.dealChatInput.disabled = true;
      elements.dealChatInput.placeholder = "Это системный диалог. Ответы недоступны.";
    }
    if (elements.dealChatSend) {
      elements.dealChatSend.disabled = true;
    }
    setDealChatTypingState(false);
    if (actionsWrap) {
      actionsWrap.style.gridTemplateColumns = "repeat(3, minmax(0, 1fr))";
    }
    return;
  }
  if (stateDealChat.serverRoomMode) {
    if (elements.dealChatSupportStatusWrap) elements.dealChatSupportStatusWrap.classList.add("hidden");
    if (elements.dealChatSupportTopics) elements.dealChatSupportTopics.classList.add("hidden");
    if (elements.dealChatSupportCreate) elements.dealChatSupportCreate.classList.add("hidden");
    if (elements.dealChatSupportOpenNew) elements.dealChatSupportOpenNew.classList.add("hidden");
    if (elements.dealChatReport) setActionVisible(elements.dealChatReport, false);
    if (elements.dealChatAgree) setActionVisible(elements.dealChatAgree, false);
    if (elements.dealChatConfirm) setActionVisible(elements.dealChatConfirm, false);
    if (elements.dealChatCancel) setActionVisible(elements.dealChatCancel, false);
    const canSendServerRoom = Boolean(chat.can_send);
    if (elements.dealChatInput) {
      elements.dealChatInput.disabled = !canSendServerRoom || interactionLocked;
      elements.dealChatInput.placeholder = canSendServerRoom
        ? (Number(chat.slowmode_sec) > 0 ? "1 уровень: раз в минуту" : "Сообщение")
        : "Отправка недоступна";
    }
    if (elements.dealChatSend) {
      elements.dealChatSend.disabled = !canSendServerRoom || interactionLocked;
    }
    if (elements.dealChatAttach) elements.dealChatAttach.classList.toggle("hidden", !canSendServerRoom);
    elements.dealChatInput?.closest(".deal-chat-compose")?.classList.add("deal-chat-compose--attach");
    if (!canSendServerRoom) clearDealChatReplyTarget();
    if (!canSendServerRoom) setDealChatTypingState(false);
    if (actionsWrap) {
      actionsWrap.style.gridTemplateColumns = "repeat(3, minmax(0, 1fr))";
    }
    return;
  }
  if (elements.dealChatSupportStatusWrap) elements.dealChatSupportStatusWrap.classList.add("hidden");
  if (elements.dealChatSupportTopics) elements.dealChatSupportTopics.classList.add("hidden");
  if (elements.dealChatReport) {
    setActionVisible(elements.dealChatReport, true);
    elements.dealChatReport.disabled = false;
  }

  if (elements.dealChatAgree) {
    setActionVisible(elements.dealChatAgree, canAgree);
    elements.dealChatAgree.disabled = !canAgree;
    elements.dealChatAgree.textContent = "🤝 Договорились";
  }
  if (elements.dealChatConfirm) {
    setActionVisible(elements.dealChatConfirm, canConfirm);
    elements.dealChatConfirm.disabled = !canConfirm;
    elements.dealChatConfirm.textContent = "✅ Подтвердить";
  }
  if (elements.dealChatCancel) {
    setActionVisible(elements.dealChatCancel, canCancel);
    elements.dealChatCancel.disabled = !canCancel;
    if (canCancel && !canConfirm && proposalById) {
      const amProposer = (isSeller && proposalBySeller) || (!isSeller && !proposalBySeller);
      elements.dealChatCancel.textContent = amProposer ? "✖️ Отменить предложение" : "✖️ Отменить";
    } else {
      elements.dealChatCancel.textContent = "✖️ Отменить";
    }
  }
  if (actionsWrap) {
    const visibleCount =
      Number(Boolean(elements.dealChatAgree && !elements.dealChatAgree.classList.contains("hidden"))) +
      Number(Boolean(elements.dealChatConfirm && !elements.dealChatConfirm.classList.contains("hidden"))) +
      Number(Boolean(elements.dealChatCancel && !elements.dealChatCancel.classList.contains("hidden")));
    if (visibleCount > 0) {
      actionsWrap.style.gridTemplateColumns = `repeat(${visibleCount}, minmax(0, 1fr))`;
    } else {
      actionsWrap.style.gridTemplateColumns = "repeat(3, minmax(0, 1fr))";
    }
  }
  if (elements.dealChatInput) {
    elements.dealChatInput.disabled = !chat.can_send || interactionLocked;
  }
  if (elements.dealChatSend) {
    elements.dealChatSend.disabled = !chat.can_send || interactionLocked;
  }
  if (elements.dealChatInput && !chat.can_send) {
    clearDealChatReplyTarget();
    setDealChatTypingState(false);
    if (chat.status === "expired") {
      elements.dealChatInput.placeholder = "Сделка просрочена.";
    } else if (chat.status === "cancelled") {
      elements.dealChatInput.placeholder = "Сделка отменена.";
    } else if (chat.status === "confirmed") {
      elements.dealChatInput.placeholder = "Сделка подтверждена.";
    } else {
      elements.dealChatInput.placeholder = "Ожидание доступа к чату...";
    }
  } else if (elements.dealChatInput) {
    elements.dealChatInput.placeholder = "Напишите сообщение...";
  }
}

async function refreshSystemInboxChat(options = {}) {
  const markRead = options.markRead !== false;
  // history = read messages too, so reading them doesn't make them vanish from the dialog
  const historyPayload = await apiRequest(withAuth("/api/notifications?history=1"));
  const items = Array.isArray(historyPayload) ? historyPayload : [];
  stateSystemInbox.latest = resolveSystemInboxLatestNotification(items) || stateSystemInbox.latest || null;
  stateDealChat.listing = null;
  stateDealChat.chat = { status: "system", can_send: false };
  stateDealChat.chatId = null;
  stateDealChat.listingId = null;
  stateDealChat.messages = buildSystemInboxMessagesFromNotifications(items);
  const unreadCount = getNotificationsUnreadCount(items);
  if (markRead && unreadCount > 0) {
    await resolveSystemInboxItems(items);
    await loadNotificationsCount();
  }
  await ensureDealChatPreviewImage();
  renderDealChatHeader();
  renderDealChatMessages();
  renderDealChatActions();
}

async function refreshDealChat() {
  if (stateDealChat.systemMode) {
    await refreshSystemInboxChat();
    return;
  }
  if (stateDealChat.supportMode) {
    const supportBaseEndpoint = stateDealChat.adminView ? "/api/admin/chats/support" : "/api/chats/support";
    let endpoint = stateDealChat.supportComplaintId
      ? withAuth(`${supportBaseEndpoint}?complaint_id=${encodeURIComponent(String(stateDealChat.supportComplaintId))}`)
      : withAuth(supportBaseEndpoint);
    const data = await apiRequest(endpoint);
    stateDealChat.listing = data?.listing || null;
    stateDealChat.chat = data?.chat || null;
    stateDealChat.chatId = Number(data?.chat?.id || 0) || null;
    stateDealChat.supportActiveThread = data?.active_thread || null;
    stateDealChat.supportLastClosedThread = data?.last_closed_thread || null;
    if (stateDealChat.supportActiveThread?.reason) {
      stateDealChat.supportSelectedReason = String(stateDealChat.supportActiveThread.reason);
    }
    stateDealChat.supportComplaintId =
      Number(
        data?.chat?.complaint_id ||
          data?.active_thread?.complaint_id ||
          stateDealChat.supportComplaintId ||
          0
      ) || null;
    const nextMessages = Array.isArray(data?.messages) ? data.messages : [];
    const nextSupportKey = buildDealChatRenderKey(
      data?.chat || {},
      nextMessages,
      `support:${Number(data?.chat?.complaint_id || data?.active_thread?.complaint_id || 0) || 0}:${String(data?.active_thread?.status || "")}:${String(data?.last_closed_thread?.status || "")}`
    );
    stateDealChat.messages = nextMessages;
    if (nextSupportKey !== stateDealChat.lastSupportRenderKey) {
      stateDealChat.lastSupportRenderKey = nextSupportKey;
      await ensureDealChatPreviewImage();
      renderDealChatHeader();
      renderDealChatMessages();
      renderDealChatActions();
    }
    updateSupportModeratorIndicatorFromPayload(data, { markSeen: false });
    return;
  }
  if (stateDealChat.serverRoomMode) {
    // Telegram-style: the first load brings the latest page, every poll afterwards asks only for messages newer than the last one we have
    const knownMessages = Array.isArray(stateDealChat.messages) ? stateDealChat.messages : [];
    const lastKnownId = knownMessages.reduce((max, m) => (m && !m.local_pending ? Math.max(max, Number(m.id) || 0) : max), 0);
    const roomQuery = stateDealChat.roomId ? `room_id=${encodeURIComponent(String(stateDealChat.roomId))}` : "";
    const cursorQuery = lastKnownId > 0 ? `after_id=${lastKnownId}` : "";
    const firstKnownId = knownMessages.reduce((min, m) => (m && Number(m.id) > 0 ? Math.min(min, Number(m.id)) : min), Infinity);
    const sinceQuery = lastKnownId > 0 && stateDealChat.serverSince
      ? `since=${encodeURIComponent(stateDealChat.serverSince)}&window_from=${Number.isFinite(firstKnownId) ? firstKnownId : 0}`
      : "";
    const queryString = [roomQuery, cursorQuery, sinceQuery].filter(Boolean).join("&");
    const requestSeq = stateDealChat.openSeq;
    const data = await apiRequest(withAuth(`/api/chats/server${queryString ? `?${queryString}` : ""}`));
    if (requestSeq !== stateDealChat.openSeq) return;  // the room was switched while this poll was in flight
    if (lastKnownId <= 0) stateDealChat.serverHasMore = Boolean(data?.has_more);
    stateDealChat.listing = data?.listing || null;
    stateDealChat.chat = data?.chat || null;
    stateDealChat.roomId = Number(data?.chat?.room_id || data?.chat?.id || stateDealChat.roomId || 0) || null;
    stateDealChat.chatId = null;
    stateDealChat.listingId = null;
    let nextMessages = lastKnownId > 0
      ? mergeServerRoomMessages(data?.messages)
      : (Array.isArray(data?.messages) ? data.messages : []);
    if (data?.server_time) stateDealChat.serverSince = String(data.server_time);
    // what changed in messages we already show: deletions by moderators and other people's reactions
    const deletedIds = new Set((Array.isArray(data?.deleted_ids) ? data.deleted_ids : []).map(Number));
    if (deletedIds.size) nextMessages = nextMessages.filter((m) => !deletedIds.has(Number(m?.id)));
    const reactionChanges = data?.reaction_changes && typeof data.reaction_changes === "object" ? data.reaction_changes : {};
    nextMessages.forEach((m) => {
      const changed = reactionChanges[String(m?.id)];
      if (changed) m.reactions = { up: Number(changed.up || 0), down: Number(changed.down || 0), mine: Number(changed.mine || 0) };
    });
    // dice duels that changed (accepted / finished / cancelled by somebody else): patch the cards that are on screen
    const duelUpdates = data?.duel_updates && typeof data.duel_updates === "object" ? data.duel_updates : {};
    const duelDirty = [];
    nextMessages.forEach((m) => {
      const fresh = m?.duel_card ? duelUpdates[String(m.duel_card.id)] : null;
      if (fresh && JSON.stringify(fresh) !== JSON.stringify(m.duel_card)) {
        const before = m.duel_card.status;
        m.duel_card = fresh;
        if (before === "open" && fresh.status === "finished") m._duelAnimate = true;
        duelDirty.push(m.id);
      }
    });
    const reactionSig = nextMessages.reduce((acc, m) => acc + Number(m?.reactions?.up || 0) * 3 + Number(m?.reactions?.down || 0) * 7 + Math.abs(Number(m?.reactions?.mine || 0)) * 11, 0);
    const nextServerKey = buildDealChatRenderKey(
      data?.chat || {},
      nextMessages,
      `server:${Number(data?.chat?.room_id || data?.chat?.id || stateDealChat.roomId || 0) || 0}:${String(data?.chat?.member_role || "")}:${Boolean(data?.chat?.can_send)}:${reactionSig}:${nextMessages.length}`
    );
    stateDealChat.messages = nextMessages;
    applyConversationReadStateLocally({
      chatType: "server_room",
      roomId: Number(data?.chat?.room_id || data?.chat?.id || stateDealChat.roomId || 0) || 0,
    });
    if (nextServerKey !== stateDealChat.lastServerRoomRenderKey && isDuelAnimating()) {
      // someone wrote while the dice are rolling: the chat is rebuilt after the landing (the key stays old, so the next poll does it)
    } else if (nextServerKey !== stateDealChat.lastServerRoomRenderKey) {
      const lastNextId = nextMessages.length ? Number(nextMessages[nextMessages.length - 1]?.id || 0) : 0;
      const reactionsOnly = lastKnownId > 0 && !deletedIds.size && nextMessages.length === knownMessages.length &&
        lastNextId === lastKnownId && Object.keys(reactionChanges).length > 0;
      stateDealChat.lastServerRoomRenderKey = nextServerKey;
      if (reactionsOnly) {
        Object.keys(reactionChanges).forEach((id) => updateReactionFooterInDom(Number(id)));  // someone reacted: only that line changes
        renderDealChatActions();
      } else {
        await ensureDealChatPreviewImage();
        renderDealChatHeader();
        renderDealChatMessages();
        renderDealChatActions();
      }
    }
    duelDirty.forEach((id) => updateDuelCardInDom(id));
    return;
  }
  if (!stateDealChat.listingId) return;
  const baseEndpoint = stateDealChat.adminView
    ? `/api/admin/listings/${stateDealChat.listingId}/chat`
    : `/api/listings/${stateDealChat.listingId}/chat`;
  const endpoint = stateDealChat.chatId
    ? `${baseEndpoint}?chat_id=${encodeURIComponent(String(stateDealChat.chatId))}`
    : baseEndpoint;
  const data = await apiRequest(withAuth(endpoint));
  stateDealChat.listing = data?.listing || null;
  stateDealChat.chat = data?.chat || null;
  stateDealChat.chatId = Number(data?.chat?.id || 0) || null;
  stateDealChat.messages = Array.isArray(data?.messages) ? data.messages : [];
  applyConversationReadStateLocally({
    chatType: "listing",
    listingId: Number(stateDealChat.listingId || data?.listing?.id || 0) || 0,
    chatId: Number(data?.chat?.id || stateDealChat.chatId || 0) || 0,
  });
  await ensureDealChatPreviewImage();
  renderDealChatHeader();
  // The 2 s poll must not rebuild an unchanged message list (every rebuild re-created the avatars and made them blink).
  const nextListingKey = buildDealChatRenderKey(data?.chat || {}, stateDealChat.messages, `listing:${Number(data?.chat?.id || 0)}`);
  if (nextListingKey !== stateDealChat.lastListingRenderKey || stateDealChat.forceScrollToBottom) {
    stateDealChat.lastListingRenderKey = nextListingKey;
    renderDealChatMessages();
  }
  renderDealChatActions();
}

function mergeServerRoomMessages(incoming) {
  const byId = new Map();
  const add = (m) => {
    const id = Number(m?.id || 0);
    if (id > 0 && !m.local_pending) byId.set(id, m);
  };
  (Array.isArray(stateDealChat.messages) ? stateDealChat.messages : []).forEach(add);
  (Array.isArray(incoming) ? incoming : []).forEach(add);
  return [...byId.values()].sort((a, b) => Number(a.id) - Number(b.id));
}

async function loadOlderServerRoomMessages() {
  if (!stateDealChat.serverRoomMode || !stateDealChat.serverHasMore || stateDealChat.serverOlderLoading) return;
  const wrap = elements.dealChatMessages;
  const firstId = (Array.isArray(stateDealChat.messages) ? stateDealChat.messages : [])
    .reduce((min, m) => (m && Number(m.id) > 0 ? Math.min(min, Number(m.id)) : min), Infinity);
  if (!wrap || !Number.isFinite(firstId)) return;
  const openSeq = stateDealChat.openSeq;
  stateDealChat.serverOlderLoading = true;
  try {
    const roomQuery = stateDealChat.roomId ? `room_id=${encodeURIComponent(String(stateDealChat.roomId))}&` : "";
    const data = await apiRequest(withAuth(`/api/chats/server?${roomQuery}before_id=${firstId}`));
    if (openSeq !== stateDealChat.openSeq || !stateDealChat.serverRoomMode) return;
    const older = Array.isArray(data?.messages) ? data.messages : [];
    stateDealChat.serverHasMore = Boolean(data?.has_more);
    if (!older.length) return;
    const prevHeight = wrap.scrollHeight;
    const prevTop = wrap.scrollTop;
    stateDealChat.messages = mergeServerRoomMessages(older);
    stateDealChat.prependingOlder = true;
    try {
      renderDealChatMessages();
    } finally {
      stateDealChat.prependingOlder = false;
    }
    wrap.scrollTop = prevTop + (wrap.scrollHeight - prevHeight);
  } catch {
    // transient: the next scroll to the top retries
  } finally {
    stateDealChat.serverOlderLoading = false;
  }
}

function stopDealChatPolling() {
  if (stateDealChat.pollTimer) {
    clearTimeout(stateDealChat.pollTimer);
    stateDealChat.pollTimer = null;
  }
}

function releaseDealChatUiLoading() {
  const token = stateDealChat.uiLoadingToken;
  if (!token) return;
  endUiLoading(token);
  stateDealChat.uiLoadingToken = null;
}

function resetDealChatTransientState() {
  stateDealChat.openSeq += 1;
  if (typeof closeServerDrawer === "function") closeServerDrawer();
  stopDealChatPolling();
  stateDealChat.opening = false;
  stateDealChat.loading = false;
  stateDealChat.sending = false;
  cancelDealChatLongPress();
  closeDealChatMessageMenu();
  clearDealChatReplyTarget();
  stateDealChat.lastSupportRenderKey = "";
  stateDealChat.lastServerRoomRenderKey = "";
  stateDealChat.lastListingRenderKey = "";
  releaseDealChatUiLoading();
}

function scheduleDealChatPolling() {
  stopDealChatPolling();
  if (state.page !== "deal-chat") return;
  if (!stateDealChat.supportMode && !stateDealChat.systemMode && !stateDealChat.serverRoomMode && !stateDealChat.listingId) return;
  stateDealChat.pollTimer = setTimeout(async () => {
    try {
      if (stateDealChat.loading || stateDealChat.sending || stateDealChat.opening) return;
      await refreshDealChat();
    } catch {
      // ignore transient issues
    } finally {
      scheduleDealChatPolling();
    }
  }, 2000);
}

async function withTimeout(promise, ms = 9000) {
  let timer = null;
  try {
    return await Promise.race([
      promise,
      new Promise((_, reject) => {
        timer = setTimeout(() => reject(new Error("timeout")), ms);
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}

async function openDealChat(listingId, options = {}) {
  if (stateDealChat.opening && state.page !== "deal-chat") {
    resetDealChatTransientState();
  }
  if (stateDealChat.opening) return false;
  const openSeq = ++stateDealChat.openSeq;
  stateDealChat.backPage = state.page || "market";
  stateDealChat.listingId = Number(listingId || 0) || null;
  stateDealChat.chatId = Number(options && options.chatId ? options.chatId : 0) || null;
  stateDealChat.listing = null;
  stateDealChat.chat = null;
  stateDealChat.messages = [];
  stateDealChat.previewImage = "";
  stateDealChat.previewImageListingId = 0;
  stateDealChat.supportComplaintId = null;
  stateDealChat.supportFreshView = false;
  stateDealChat.supportActiveThread = null;
  stateDealChat.supportLastClosedThread = null;
  stateDealChat.forceScrollToBottom = true;
  stateDealChat.adminView = Boolean(options && options.adminView);
  stateDealChat.supportMode = false;
  stateDealChat.systemMode = false;
  stateDealChat.serverRoomMode = false;
  stateDealChat.lastSupportRenderKey = "";
  stateDealChat.lastServerRoomRenderKey = "";
  stateDealChat.lastListingRenderKey = "";
  stateDealChat.roomId = null;
  if (!stateDealChat.listingId) return false;
  stateDealChat.opening = true;
  stateDealChat.loading = true;
  let refreshedOnce = false;
  applyDealChatPrefill(options && options.prefill ? options.prefill : null);
  const loadingToken = beginUiLoading("Загружаем диалог...", "Синхронизируем сообщения");
  stateDealChat.uiLoadingToken = loadingToken;
  navigateTo("deal-chat");
  // Trigger entrance animation once
  const chatPageEl = document.querySelector(".page-deal-chat");
  if (chatPageEl) {
    chatPageEl.classList.remove("anim-enter");
    void chatPageEl.offsetWidth; // reflow to restart animation
    chatPageEl.classList.add("anim-enter");
  }
  try {
    window.scrollTo({ top: 0, behavior: "auto" });
    if (document.documentElement) document.documentElement.scrollTop = 0;
    if (document.body) document.body.scrollTop = 0;
  } catch {
    // ignore
  }
  requestAnimationFrame(() => {
    try {
      window.scrollTo({ top: 0, behavior: "auto" });
      if (document.documentElement) document.documentElement.scrollTop = 0;
      if (document.body) document.body.scrollTop = 0;
    } catch {
      // ignore
    }
  });
  renderDealChatHeader();
  renderDealChatMessages();
  renderDealChatActions();
  try {
    await withTimeout(refreshDealChat(), 9000);
    if (openSeq !== stateDealChat.openSeq) return false;
    refreshedOnce = true;
    scheduleDealChatPolling();
    return true;
  } catch (error) {
    if (openSeq !== stateDealChat.openSeq) return false;
    const code = String(error?.payload?.error || "");
    stopDealChatPolling();
    stateDealChat.messages = [];
    if (code === "chat_busy") {
      showToast("По этому объявлению уже открыт диалог с другим покупателем.", "danger");
    } else if (code === "not_allowed") {
      showToast("У вас нет доступа к этому диалогу.", "danger");
    } else if (code === "not_found") {
      showToast("Диалог недоступен.", "danger");
    } else if (error?.status === 401 || code === "unauthorized") {
      showToast("Сессия истекла. Перезапустите мини-приложение.", "danger");
    } else {
      showToast("Не удалось загрузить диалог. Попробуйте ещё раз.", "danger");
    }
    if (state.page === "deal-chat") closeDealChat();
    return false;
  } finally {
    if (openSeq === stateDealChat.openSeq) {
      stateDealChat.loading = false;
      stateDealChat.opening = false;
      endUiLoading(loadingToken);
      if (stateDealChat.uiLoadingToken === loadingToken) {
        stateDealChat.uiLoadingToken = null;
      }
      if (!refreshedOnce) {
        renderDealChatHeader();
        renderDealChatMessages();
        renderDealChatActions();
      } else {
        // the data render ran while "loading" was still true, which left the input and buttons disabled
        renderDealChatActions();
      }
    }
  }
}

