  if (elements.editProfileSave) {
    elements.editProfileSave.addEventListener("click", async () => {
      if (stateEditProfile.saving) return;
      if (!elements.editNickInput) return;
      const nickValue = elements.editNickInput.value.trim();
      const selectedServerId = parseServerId(elements.editServerInput?.value) || state.serverId || null;
      if (!nickValue || !stateEditProfile.nickValid) {
        alert("Проверьте никнейм.");
        return;
      }
      if (!selectedServerId) {
        alert("Выберите сервер.");
        return;
      }
      const payload = {
        game_nick: nickValue,
        contact_type: "telegram",
        contact_ingame: "",
        contact_secondary_enabled: false,
      };
      const avatarPayload = typeof stateEditProfile.avatarData === "string" ? stateEditProfile.avatarData.trim() : "";
      if (stateEditProfile.avatarClear || avatarPayload.startsWith("data:image/")) {
        payload.avatar_clear = stateEditProfile.avatarClear;
        payload.avatar_data = avatarPayload;
      }
      stateEditProfile.saving = true;
      const prevLabel = elements.editProfileSave.textContent;
      elements.editProfileSave.disabled = true;
      elements.editProfileSave.textContent = "Сохраняю...";
      try {
        if (Number(state.serverId || 0) !== Number(selectedServerId || 0)) {
          await apiRequest(withAuth("/api/server"), {
            method: "POST",
            body: JSON.stringify({ server_id: selectedServerId }),
          });
          state.serverId = selectedServerId;
          setMarketServerFilter(selectedServerId);
          updateCreateServerPicker();
          updateNicknameServerPicker();
          updateEditProfileServerPicker();
          updateFilterServerButtons();
          updateFiltersBar();
          updateServerButton();
        }
        await apiRequest(withAuth("/api/profile/update"), {
          method: "POST",
          body: JSON.stringify(payload),
        });
        const c1 = elements.profileColor1Input ? elements.profileColor1Input.value : "#7c5cff";
        const c2 = elements.profileColor2Input ? elements.profileColor2Input.value : "#1fe6d1";
        saveProfileColors(c1, c2);
        await loadProfile();
        goBack();
        showToast("✅ Профиль обновлён", "success");
      } catch (error) {
        const code = error && error.payload ? error.payload.error : null;
        if (code === "nick_taken" || code === "nick_reserved" || code === "invalid_nick") {
          alert(nickErrorText(code));
          return;
        }
        if (code === "nick_change_limit") {
          const nextAt = error && error.payload ? error.payload.next_change_at : "";
          const label = nextAt ? formatDateTime(nextAt) : "";
          const message = label
            ? `Ник можно менять раз в 7 дней. Следующая смена: ${label}`
            : "Ник можно менять раз в 7 дней.";
          alert(message);
          return;
        }
        if (code === "temporary_unavailable" || code === "server_error") {
          alert("Сервер профиля временно занят. Повтори через 10–20 секунд.");
          return;
        }
        if (code === "bad_contact_value") {
          alert("Проверьте контакт");
          return;
        }
        if (code === "secondary_missing") {
          alert("Заполните дополнительный контакт или выключите его показ");
          return;
        }
        if (code === "avatar_too_large") {
          alert("Аватар слишком большой (максимум 1 МБ)");
          return;
        }
        if (code === "bad_avatar") {
          alert("Некорректный формат аватара. Выберите изображение заново.");
          return;
        }
        alert("Не удалось обновить профиль");
      } finally {
        stateEditProfile.saving = false;
        elements.editProfileSave.disabled = false;
        elements.editProfileSave.textContent = prevLabel || "Сохранить";
      }
    });
  }

