  // ── Helpers: sync body class with open mining modals ──
  function syncMineModalBodyClass() {
    const anyOpen =
      (miningWardrobeOverlay && !miningWardrobeOverlay.classList.contains("hidden")) ||
      (document.getElementById("miningRulesOverlay") && !document.getElementById("miningRulesOverlay").classList.contains("hidden"));
    document.body.classList.toggle("mine-modal-open", Boolean(anyOpen));
  }
  function openMineOverlay(overlay) {
    if (!overlay) return;
    overlay.classList.remove("hidden");
    syncMineModalBodyClass();
  }
  function closeMineOverlay(overlay) {
    if (!overlay) return;
    overlay.classList.add("hidden");
    syncMineModalBodyClass();
  }

  if (miningWardrobeBtn && miningWardrobeOverlay) {
    miningWardrobeBtn.addEventListener("click", () => openMineOverlay(miningWardrobeOverlay));
  }
