  const enforceCoinsActivityCardOrder = () => {
    const grid = document.querySelector(".mcoin-grid");
    if (!grid) return;
    const desiredOrder = ["shop", "vip", "tasks", "chests", "inventory", "favorites", "promotion", "referrals"];
    const cards = Array.from(grid.querySelectorAll(".mcoin-card[data-coins-pane]"));
    if (!cards.length) return;
    cards
      .sort((a, b) => {
        const aPane = String(a.getAttribute("data-coins-pane") || "");
        const bPane = String(b.getAttribute("data-coins-pane") || "");
        const aIdx = desiredOrder.indexOf(aPane);
        const bIdx = desiredOrder.indexOf(bPane);
        const aOrder = aIdx === -1 ? Number.MAX_SAFE_INTEGER : aIdx;
        const bOrder = bIdx === -1 ? Number.MAX_SAFE_INTEGER : bIdx;
        return aOrder - bOrder;
      })
      .forEach((card) => grid.appendChild(card));
  };

